window.QUESTIONS = [{"id":1,"type":"single","cat":"操纵与飞行技术","stem":"以下哪一种情景容易引起飞行员产生飞机比实际位置偏高的错觉（）。","A":"向上带斜坡的地形","B":"向下带斜坡的地形","C":"常规跑道","D":"以上均不正确","answer":"A","exp":"向上延伸的斜坡地形会抬高飞行员的目视参考基准，容易把飞机看成比实际位置偏高，进而可能过度压低高度；向下斜坡地形正好相反，会造成偏低的错觉，常规跑道基本不引发此类错觉。"},{"id":2,"type":"single","cat":"操纵与飞行技术","stem":"X型四轴逆时针偏航时，其1、2号电机的动作应该是（）。","A":"减速、加速","B":"减速、减速","C":"加速、减速","D":"加速、加速","answer":"A","exp":"多旋翼偏航依靠各旋翼反扭矩的不平衡：逆时针偏航时需将1、2号电机减速、3、4号加速，两组转速差形成的反扭矩差推动机身逆时针转动；悬停时四电机转速相等、扭矩相互抵消，若误将1、2号加速，机身会向顺时针偏转。"},{"id":3,"type":"single","cat":"基础概念","stem":"固定翼无人机的副翼负责完成无人机的（）动作。","A":"横滚","B":"俯仰","C":"偏航","D":"以上均不正确","answer":"A","exp":"副翼位于左右机翼后缘外侧，两侧反向偏转使翼面升力一增一减，形成滚转力矩实现横滚；俯仰由升降舵或全动平尾控制，偏航由方向舵控制，三种舵面各司其职，把副翼与升降舵功能混淆是最常见错误。"},{"id":4,"type":"single","cat":"操纵与飞行技术","stem":"X模式4轴飞行器从悬停转换到前进，那两个轴需要加速（）。","A":"右侧两轴","B":"左侧两轴","C":"后方两轴","D":"以上均不正确","answer":"C","exp":"前飞靠机体前倾使旋翼拉力产生向前的分量：后方两轴电机加速，升力大于前侧，机体绕横轴前倾推动前飞；若加速前侧两轴则机体后仰变为后退，加速左右两轴会引起侧移或横滚，方向搞反姿态就完全相反。"},{"id":5,"type":"single","cat":"电力巡检","stem":"输电线路状态巡视，对防护区内人口稠密区、交跨公路等易受外力损伤、破坏的区段巡视周期为（）至少一次。","A":"每月","B":"每季度","C":"每半年","D":"每年","answer":"A","exp":"输电线路运行规程要求，人口稠密区、交跨公路等易受外力破坏的防护区段环境复杂、隐患变化快，须每月至少巡视一次，及时发现吊车碰线、异物悬挂等险情；季度及更长周期适用于外部环境相对稳定的普通区段。"},{"id":6,"type":"single","cat":"领航与任务规划","stem":"信号线和电源线分开走线，飞机中信号线有电子调速器（电调）控制线、接收机线、全球导航卫星系统（GNSS）线、（）、无线图像传输（无线图传）系统线。","A":"无线数据传输（无线数传）系统线","B":"电流计线","C":"电池平衡充线","D":"电机线","answer":"A","exp":"无线数传系统传输遥测与控制数据，属典型小信号线路，应与强电分开布置；电流计串接在动力电源回路、电机线为三相动力线、平衡充线属地面充电设备，均为电源侧走线，与电调控制线、接收机、GNSS、图传等信号线性质不同。"},{"id":7,"type":"single","cat":"电力巡检","stem":"故障巡检、特殊巡检等非计划巡检也应办理（）。","A":"工作票","B":"工作任务单","C":"工作许可手续","D":"作业控制卡","answer":"C","exp":"故障巡检、特殊巡检虽属临时安排、不涉及停电作业，无需签发工作票，但巡检人员接近带电设备前仍须履行工作许可手续，经许可并明确安全范围后方可开始；把巡视任务的派单凭据与现场安全许可混为一谈是常见错误。"},{"id":8,"type":"single","cat":"基础概念","stem":"低空无人机任务高度一般在（）之间。","A":"0～100m","B":"100～1000m","C":"1000～7000m","D":"以上均不正确","answer":"B","exp":"按任务高度划分：超低空为0～100m，低空为100～1000m，中空约1000～7000m，更高属高空。低空无人机多数航测、巡查任务正是在一百至一千米高度进行，0～100m属超低空，勿将其与低空的通俗叫法混淆。"},{"id":9,"type":"single","cat":"领航与任务规划","stem":"空速明显大于地速的原因是（）。","A":"逆风","B":"顺风","C":"无风","D":"以上均不正确","answer":"A","exp":"空速是飞机相对空气的速度，地速是相对地面的速度。逆风飞行时风迎面而来，抵消部分空速，地速等于空速减去风速，故空速明显大于地速；顺风时地速等于空速加风速，两者关系正好相反，无风时二者相等。"},{"id":10,"type":"single","cat":"基础概念","stem":"固定翼无人机航程的提升措施，下列选项正确的是（）。","A":"增大电池容量","B":"增加飞机起飞重量","C":"减小迎角","D":"逆风飞行","answer":"A","exp":"航程取决于携带的能量与巡航气动效率，增大电池容量直接延长可飞距离。增加起飞重量会加大诱导阻力、抬高巡航功率，反而缩短航程；迎角应保持在有利升阻比附近而非一味减小；逆风飞行地速降低，同样能量下航程变短。"},{"id":11,"type":"single","cat":"设备与维护","stem":"关于遥控器天线，下面描述错误的是？（）","A":"每次飞行时，都应展开天线","B":"远离摇杆的天线尖端朝向，不应指向飞行器","C":"天线展开后应平行于飞行器","D":"远离摇杆的天线尖端朝向，应指向飞行器","answer":"D","exp":"天线辐射能量集中在与杆身垂直的侧面方向，杆轴两端方向最弱，远离摇杆的天线尖端若指向飞行器，恰处信号最弱区，极易造成失控，该说法错误；正确做法是每次飞行展开天线，并用天线侧面朝向飞行器，避免机身遮挡。"},{"id":12,"type":"single","cat":"航空气象","stem":"无人机链路影响因素有自由空间损耗、大气衰减、雨雾衰减以及（）等。","A":"地形地貌衰减","B":"距离衰减","C":"多径效应","D":"以上均不正确","answer":"C","exp":"无线链路除自由空间损耗、大气吸收与雨雾衰减外，信号还会经地面、水面和建筑物多次反射，反射波与直射波叠加造成信号忽强忽弱的衰落，即多径效应，是影响链路质量的又一主要因素；距离增大已含在自由空间损耗之内。"},{"id":13,"type":"single","cat":"领航与任务规划","stem":"无人机地面控制站是整个无人机系统非常重要的组成部分，它包括任务规划，任务回放，实时监测，数字地图，通信数据链在内的集控制，通信，数据处理于一体的综合能力，是整个无人机系统的（）。","A":"指挥终端","B":"指挥控制中心","C":"数据统计中心","D":"显示服务端","answer":"B","exp":"地面控制站集任务规划、实时监测、数字地图、链路通信与任务回放于一体，对飞行器实施指挥控制并处理回传数据，是整个无人机系统的指挥控制中心；指挥终端、显示服务端只反映其部分功能，数据统计中心以偏概全。"},{"id":14,"type":"single","cat":"领航与任务规划","stem":"直线变高菱形航线飞行训练科目中，由H点起飞，控制好油门，操控无人机匀速垂直上升至（）m高度。","A":"1","B":"1.5","C":"3","D":"7","answer":"B","exp":"该科目规定由H点起飞后保持油门平稳，匀速垂直上升至1.5米高度，以固定低高度建立目视基准，便于观察姿态、保持航迹稳定，再沿菱形航线各边按要求变换高度；上升过猛或高度偏差都会破坏航线形状并偏离考核标准。"},{"id":15,"type":"single","cat":"领航与任务规划","stem":"在多轴飞行任务中，触发失控返航时，应如何打断飞控当前任务，取回手动控制权（）。","A":"云台状态切换","B":"航向锁定切换","C":"GPS手动模式切换","D":"以上均不正确","answer":"C","exp":"失控返航是飞控自动任务，要中断它须将飞行模式切换至GPS手动模式，飞控随即退出自动逻辑，操纵杆重新直接控制机体，即可人工接管改出；云台切换只影响相机轴，航向锁定仅改变保持的航向参考，都无法打断自动任务。"},{"id":16,"type":"single","cat":"设备与维护","stem":"以大疆产品为例，假设飞行器处于操作员正上方，当前飞行高度为250米，距离为5米，DJIGO提示“遥控器信号微弱”时，操作员应如何处理（）。","A":"无需理会，飞行器可自行修复信号","B":"继续上升飞行器，高度越高信号越好","C":"原地悬停飞行器，重启遥控器","D":"操作员将遥控器天线摆放至平行于地面","answer":"D","exp":"天线侧面方向辐射最强，杆轴方向最弱。飞行器位于正上方时，竖立的天线恰以轴向对着飞机，信号必然微弱，应将天线放平、使其侧面朝上正对飞行器；原地重启遥控器会造成短暂失控，继续升高更会超出有效通信范围。"},{"id":17,"type":"single","cat":"操纵与飞行技术","stem":"六轴飞行器安装有（）。","A":"6个顺时针旋转螺旋桨","B":"3个顺时针旋转螺旋桨，3个逆时针旋转螺旋桨","C":"4个顺时针旋转螺旋桨，2个逆时针旋转螺旋桨","D":"以上均不正确","answer":"B","exp":"多旋翼要稳定悬停，各旋翼反扭矩必须互相抵消，因此顺、逆时针螺旋桨各占一半，六轴即三个顺时针、三个逆时针，相邻桨反转布置；偏航也靠两组转速差实现。若全部同向旋转，机身会持续反向自转，根本无法悬停。"},{"id":18,"type":"single","cat":"领航与任务规划","stem":"起落航线的重要组成部分应急航线相关内容不包括（）。","A":"检查飞行平台、发动机、机上设备的故障状态、油量、电量","B":"决定着陆场或迫降场","C":"任务执行情况","D":"以上均不正确","answer":"C","exp":"应急航线围绕安全返场落地组织：先检查飞行平台、动力与机载设备的故障状态及剩余油量电量，判断能否继续飞行，再选定着陆场或迫降场并规划应急返场路径；任务执行情况属于正常飞行管理内容，与应急处置无关。"},{"id":19,"type":"single","cat":"基础概念","stem":"多旋翼飞行器上的电信号传播顺序一般为（）。","A":"飞控——机载遥控接收机——电机——电调","B":"机载遥控接收机——飞控——电调——电机","C":"飞控——电调——机载遥控接收机——电机","D":"以上均不正确","answer":"B","exp":"操纵指令由地面遥控器发出，机载接收机接收后送入飞控，飞控结合姿态传感器数据解算，输出控制信号给各电调，电调把直流电逆变为三相电流驱动电机增减转速，链路为接收机—飞控—电调—电机，顺序不能颠倒。"},{"id":20,"type":"single","cat":"设备与维护","stem":"垂起固定翼无人机零部件的定期维护保养，下列选项错误的是（）。","A":"检查电池有无破损，鼓包胀气","B":"保持机身框架完好无裂纹","C":"检查电机安装是否紧固，有无松动等现象","D":"及时清理油污、碎屑，保持各部位清洁","answer":"D","exp":"定期保养核心是状态检查与紧固确认：电池有无破损鼓包、机身框架有无裂纹、电机安装是否松动都是必查项。垂起固定翼普遍采用电动力，没有滑油系统，正常运行不产生油污，把清理油污列为该机型的定期保养内容与实际不符。"},{"id":21,"type":"single","cat":"基础概念","stem":"飞机纵向阻尼力矩的产生主要（）。","A":"由后掠机翼产生的","B":"由垂直尾翼产生的","C":"由水平尾翼产生的","D":"以上均不正确","answer":"C","exp":"纵向阻尼力矩抑制飞机的俯仰姿态变化，主要由水平尾翼产生：飞机受扰转动时，尾翼随重心上下运动使迎角改变，产生与俯仰方向相反的附加升力形成阻尼；垂直尾翼提供方向阻尼，后掠机翼影响横向，都不是纵向俯仰阻尼的主要来源。"},{"id":22,"type":"single","cat":"设备与维护","stem":"电机在焊接插头时，应该先对线头和插头分别（），然后再焊接。","A":"上锡","B":"清洗","C":"预热","D":"上助焊剂","answer":"A","exp":"焊接插头前应先给线头和插头分别上锡，让焊锡预先润湿各自的金属表面，再对合施焊，这样结合牢固、导电可靠、不易虚焊；两表面若直接对接，氧化层和散热会使焊料无法充分浸润，容易形成假焊，接触电阻大且易松脱。"},{"id":23,"type":"single","cat":"领航与任务规划","stem":"航迹规划需要充分考虑（）的选取、标绘，航线预先规划以及在线调整时机。","A":"电子地图","B":"飞行航迹","C":"地理位置","D":"以上均不正确","answer":"A","exp":"航迹规划以电子地图为基础：先在地图上选取并标绘航点航线，标明禁飞区与障碍物，再进行航线预先规划，飞行中还要依据地图判断在线调整时机；电子地图承载地理位置信息，是标绘与规划的载体，飞行航迹只是规划产生的结果。"},{"id":24,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机平飞转弯后段（）。","A":"当飞机轨迹方向离目标方向10度-15度时，注视地平仪，根据接近目标方向的快慢，逐渐回杆","B":"当飞机轨迹方向到达目标方向时，注视地平仪，逐渐回杆","C":"当飞机轨迹方向超过目标方向10度-15度时，注视地平仪，逐渐回杆","D":"以上均不正确","answer":"A","exp":"转弯后段应提前改出：当飞机轨迹方向距目标方向还有10°～15°时，注视地平仪，根据接近目标的快慢逐渐回杆回舵，使飞机恰好在新航向改平；等到轨迹方向已到达或超过目标再回杆，坡度消除需要过程，飞机会转过目标航向，改出偏晚。"},{"id":25,"type":"single","cat":"电力巡检","stem":"相同巡检作业时，航线规划应优先调用已经实际飞行的（）。","A":"历史航线","B":"起落航线","C":"安全航线","D":"应急航线","answer":"A","exp":"相同巡检作业应优先调用已实际飞行的历史航线：它经过实践验证，航点、高度和避障参数可靠，复用既提高规划效率又降低风险；起落航线是机场起降专用航线，安全、应急航线是针对特定情况的预案，都不是日常巡检的常规规划基础。"},{"id":26,"type":"single","cat":"设备与维护","stem":"以大疆产品为例，操作员打开遥控器时，遥控器发出警告提示音及指示灯为红灯慢闪时，提示的是？（）","A":"遥控器天线未打开","B":"飞行器未于飞行器连接","C":"遥控器需进行摇杆校准","D":"遥控未开启","answer":"C","exp":"以大疆产品为例，遥控器开机发出警告音且指示灯红灯慢闪，提示遥控器需进行摇杆校准，应按提示完成校准后再用，否则摇杆行程与实际输出不对应，影响操控精度；天线未打开、未连接飞行器等状态各有不同的灯语和提示方式。"},{"id":27,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，如果飞机处于顺侧风时（）。","A":"地速增大，收油门下滑和四转弯时机均应适当提前","B":"地速减小，收油门下滑和四转弯时机均应适当延后","C":"地速增大，收油门下滑和四转弯时机均应适当延后","D":"以上均不正确","answer":"A","exp":"顺侧风含顺风分量使地速增大，飞过相同地面距离所需时间缩短，下滑进近和四转弯若按无风时机进行会飞过预定位置，收油门、下滑和四转弯时机均应适当提前；侧风分量还需另行修正航迹，但决定提前量的主要是地速增大。"},{"id":28,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，下列哪种情况，收油门的时机应适当提前，收油门的动作适当加快？（）","A":"实际下滑点与预定下滑点吻合","B":"实际下滑点在预定下滑点后面","C":"实际下滑点在预定下滑点前面","D":"以上均不正确","answer":"C","exp":"实际下滑点落在预定下滑点前面，说明飞机有飞过预定接地点的趋势，应提前收油门并加快收油门动作，迅速减小拉力使下滑角增大、下滑点后移回预定位置；若下滑点在预定位置后面则飞得太近太陡，应适当补油门，处置方向正好相反。"},{"id":29,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，俯仰角偏高时，下列正确的操纵是（）。","A":"应柔和地向右扭舵","B":"应柔和地向后带杆","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"C","exp":"姿态遥控模式爬升中俯仰角偏高，说明机头上仰过多、爬升角过陡，应柔和向前顶杆减小俯仰角，使爬升回到预定状态；向后带杆会进一步增大俯仰角、损失速度，扭舵用于方向修正，与俯仰角大小无直接关系。"},{"id":30,"type":"single","cat":"电力巡检","stem":"小型无人直升机巡检飞行速度不宜大于（）。","A":"10m/s","B":"15m/s","C":"20m/s","D":"25m/s","answer":"A","exp":"电力巡检要求仔细观察杆塔和导线细节，小型无人直升机巡检飞行速度不宜大于10m/s：速度过高会缩短有效观察时间、降低影像质量，还增大近距离绕塔飞行的碰撞风险；速度也不宜过低，否则直升机悬停抗风稳定性变差。"},{"id":31,"type":"single","cat":"设备与维护","stem":"位置传感器用于感受无人机的位置，是飞行轨迹控制的必要前提（）是典型的位置传感器。","A":"角速率传感器","B":"加速度传感器","C":"GPS卫星导航接收机","D":"以上均不正确","answer":"C","exp":"位置传感器感受无人机位置，是轨迹控制的前提，GPS卫星导航接收机是典型的位置传感器，直接输出经纬度等位置信息；角速率传感器测角速度、加速度传感器测加速度，属惯性传感器，积分推算位置误差随时间累积，非直接位置测量器件。"},{"id":32,"type":"single","cat":"基础概念","stem":"（）升降舵、方向舵的舵量标准没有绝对的规定，在调整过程中应注意不能一次调整到位，而是每次调整一个小数量，一般要经过几次调整后才能达到理想状态。","A":"电子调速器（电调）","B":"遥控器","C":"舵机","D":"副翼","answer":"D","exp":"副翼与升降舵、方向舵的舵量没有绝对统一的标准，应结合机型和飞行感受调整，且每次只调小量、分几次逐步到位，一次调过头易造成操纵过量、飞机难以控制；电调、遥控器、舵机各有确定的参数与校准方式，不属于这种经验性舵量调整对象。"},{"id":33,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机带右坡度时，下列正确的操纵是（）。","A":"应柔和地向右压杆","B":"应柔和地回杆或向左压杆","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"B","exp":"姿态模式爬升中出现右坡度，说明飞机正带坡度侧倾，应柔和回杆或向左压杆消除坡度，恢复机翼水平后再继续爬升；继续向右压杆会加大坡度，向前顶杆只改变俯仰姿态，都纠正不了右倾斜。"},{"id":34,"type":"single","cat":"设备与维护","stem":"需要灵活操控性能的飞机，选用（）电机。","A":"高直径","B":"高转速","C":"高扭矩","D":"以上均不正确","answer":"B","exp":"需要灵活操控性能的飞机应选用高转速电机：高KV高转速电机响应快、加速迅猛，配小桨可获得灵敏的动态响应，适合竞速穿越等追求机动性的机型；高扭矩电机配大桨偏重载重和效率，不是灵活性机型的首选。"},{"id":35,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机要求实现悬停中向右偏航，不同螺旋桨应如何变化？（）","A":"逆时针桨减速，顺时针桨加速","B":"机体轴左边螺旋桨加速，右边螺旋桨减速","C":"逆时针桨加速，顺时针桨减速","D":"以上均不正确","answer":"C","exp":"悬停中向右偏航靠改变反扭矩实现：逆时针桨加速、顺时针桨减速后，机身受到的反扭矩合力指向顺时针方向，机头即向右偏转；反向调整会使机头左偏，仅增减机体左右两侧桨的转速产生的是滚转，都无法实现原地右偏航。"},{"id":36,"type":"single","cat":"操纵与飞行技术","stem":"X型四轴前进时，其1、3号电机的动作应该是（）。","A":"加速、加速","B":"减速、减速","C":"加速、减速","D":"减速、加速","answer":"D","exp":"X型四轴前进需先让机体前倾：按该机型的电机编号，位于前侧的1号电机减速、后侧的3号电机加速，前后拉力差形成低头力矩，机头下俯后升力的向前分量推动飞机前飞；若前后桨同步增减只能改变高度，搭配相反则机体后仰。"},{"id":37,"type":"single","cat":"基础概念","stem":"以下操作符合安全规范的是（）。","A":"在无人机旋转的旋翼下方吹风乘凉","B":"初次飞行时，在空旷地区操作无人机，并且保持安全距离","C":"用手触摸高速旋转中的螺旋桨","D":"在密集人群上方飞行","answer":"B","exp":"初次飞行应选空旷场地并保持安全距离：远离人群、建筑和障碍物，操作失误时也有修正和缓冲空间；在旋转的旋翼下方吹风、触摸高速旋转的螺旋桨极易被割伤，在密集人群上方飞行一旦坠机会伤及地面人员，均严重违反安全规范。"},{"id":38,"type":"single","cat":"基础概念","stem":"可能需要执行的应急程序不包括（）。","A":"动力装置重启操作","B":"备份系统切换操作","C":"导航系统重启操作","D":"以上均不正确","answer":"C","exp":"应急程序针对危及飞行安全的突发情况，包括动力装置失效或异常时的动力装置重启操作、主系统故障时的备份系统切换操作等；导航系统重启不属于应急程序范畴，重启期间导航输出中断，一般由地面排查处理而非飞行中的应急处置手段。"},{"id":39,"type":"single","cat":"操纵与飞行技术","stem":"无人机定速遥控飞行时收起襟翼，驾驶员需（）。","A":"增加油门以保持空速","B":"针对此情况，无需做相关动作","C":"减小油门以保持空速","D":"以上均不正确","answer":"C","exp":"定速飞行中收起襟翼，机翼阻力明显减小，油门不动时空速会增大，为保持空速应适当减小油门；收襟翼同时升力系数下降，需稍带杆保持高度，但就维持空速而言，正确处置是减油门而非加油门。"},{"id":40,"type":"single","cat":"设备与维护","stem":"下面属于使用遥控器时日常维护保养要素的是（）。","A":"保证电源工作正常","B":"定期打磨天线避免生锈","C":"对摇杆灵敏度进行检查","D":"定期拆解遥控器进行除尘","answer":"A","exp":"保证电源工作正常是遥控器日常维护保养的基本要素：每次使用前检查电池电量和电压，及时充电更换，防止飞行中遥控器断电导致失控；打磨天线会破坏镀层影响信号收发，遥控器是精密设备不宜随意拆解脱尘，摇杆灵敏度异常时应校准解决。"},{"id":41,"type":"single","cat":"基础概念","stem":"飞行器在执行兴趣点环绕最低高度是？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A","exp":"以大疆产品为例，兴趣点环绕的最低飞行高度为5米：高度设置过低易受地面障碍物、旋翼气流扬起杂物的影响，环绕安全性差，也难以获得稳定的拍摄画面；使用中还应同时满足环绕半径和避障要求，不能只贴着最低高度飞行。"},{"id":42,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，下列哪种情况需要复飞（）。","A":"飞机油料不足","B":"跑道上有飞机或其它障碍物影响着陆安全时","C":"飞机稍稍偏离期望下滑线","D":"以上均不正确","answer":"B","exp":"着陆时发现跑道上有飞机或其他障碍物影响着陆安全，必须果断复飞，加油门爬升重新建立着陆航线，防止相撞；油料不足应在地面充分准备避免，飞机稍稍偏离下滑线属于正常偏差范围，可以修正着陆，无需复飞。"},{"id":43,"type":"single","cat":"基础概念","stem":"未按照国家有关规定经特别批准，（）航空器不得飞入空中禁区和临时空中禁区。","A":"军用","B":"民用","C":"临时","D":"任何","answer":"D","exp":"空中禁区为国家安全等特殊需要划定，未经国家有关规定特别批准，任何航空器都不得飞入，无论军用、民用还是临时任务需要；按机型区分准入资格的说法不成立，禁区的限制对象是所有航空器，例外只能通过特别批准程序获得。"},{"id":44,"type":"single","cat":"基础概念","stem":"第一人称视角（FPV）穿越机在穿越障碍时发生剧烈碰撞，此时第一人称视角（FPV）眼镜再也无法看清影像，此时应首先检修（）。","A":"摄像头","B":"电机","C":"电子调速器（电调）","D":"螺旋桨","answer":"A","exp":"穿越障碍发生剧烈碰撞后FPV眼镜完全看不到影像，说明图传画面信号源中断，应首先检修摄像头：摄像头位于机首最前方，最易在碰撞中受损，损坏或排线松脱即无图输出；电机、电调故障只影响动力不影响画面，螺旋桨断裂时画面仍能传输。"},{"id":45,"type":"single","cat":"基础概念","stem":"下列正确的是（）。","A":"飞机的升阻比越大，飞机的空气动力特性越差","B":"飞机的升阻比越小，飞机的空气动力特性越好","C":"飞机的升阻比越大，飞机的空气动力特性越好","D":"以上均不正确","answer":"C","exp":"升阻比是同一迎角下升力与阻力之比，是衡量飞机空气动力特性的重要指标：升阻比越大，产生同样升力所需克服的阻力越小，巡航经济性和滑翔性能越好，空气动力特性越好；说升阻比越小气动特性越好，把两者的关系弄反了。"},{"id":46,"type":"single","cat":"操纵与飞行技术","stem":"撞网回收系统是常用的无人机起飞着陆系统，当该起飞着陆系统出现故障时，我们可能需要维修下面这些装置：拦阻网装置、吸能缓冲装置和（）。","A":"末端引导装置","B":"遥控装置","C":"发射装置","D":"飞行控制系统（自驾仪）装置","answer":"A","exp":"撞网回收系统由拦阻网装置、吸能缓冲装置和末端引导装置组成：拦阻网兜住飞机，吸能缓冲装置吸收剩余动能使其减速停止，末端引导装置引导无人机精确对准撞网；发射装置用于起飞，遥控和飞控不属于该回收系统的组成装置。"},{"id":47,"type":"single","cat":"基础概念","stem":"多旋翼无人机的特点是（）。","A":"机动灵活","B":"使用成本低","C":"结构简单","D":"其他全是","answer":"D","exp":"多旋翼无人机靠多个对称分布的旋翼差动控制姿态，无需复杂的倾斜盘和活动舵面，结构简单、维护方便；能垂直起降、原地悬停、低速灵活机动；电机动力系统购置和使用成本低，因此机动灵活、使用成本低、结构简单都是其特点，需全面概括。"},{"id":48,"type":"single","cat":"基础概念","stem":"在对无人机电动系统组装时，参照电路的稳定电流，并根据整机的重量要求选择合适的（）。","A":"电池","B":"电动机","C":"电调","D":"飞控","answer":"A","exp":"组装电动系统时，参照电路的稳定电流并结合整机重量要求选择合适的电池：电池放电能力须满足电路稳定工作电流，容量与重量又直接影响续航和起飞重量，需综合权衡；电机、电调、飞控的选择依据各不相同，不是按这两项直接选取的对象。"},{"id":49,"type":"single","cat":"领航与任务规划","stem":"（）是在无人机执行任务前，由地面控制站制定的，主要是综合任务要求、地理环境和无人机任务载荷等因素进行规划，其特点是约束和飞行环境给定，规划的主要目的是通过选用合适的算法谋求（）飞行航迹。","A":"预先规划，全局最优","B":"实时规划，航程最短","C":"航迹规划，航时最短","D":"以上均不正确","answer":"A","exp":"任务执行前由地面控制站制定的规划属预先规划：此时约束和飞行环境已经给定，综合任务要求、地理环境和任务载荷等因素，选用合适算法谋求全局最优的飞行航迹；实时规划是飞行中的在线调整，追求快速响应而非全局最优。"},{"id":50,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机定高平飞时，下列操纵正确的是（）。","A":"如航迹方向偏离目标超过5°，应协调地压杆扭舵，使飞机对正目标，然后改平坡度","B":"如航迹方向偏离目标超过5°，应柔和地向偏转的方向适当扭舵杆","C":"如航迹方向偏离目标超过5°，应缓慢地向偏转的反方向适当扭舵杆","D":"以上均不正确","answer":"A","exp":"定高平飞中航迹方向偏离目标超过5°时，应协调地压杆并扭舵，使飞机对正目标方向后改平坡度，杆舵一致的操纵转弯圆滑、高度与坡度易控制；只扭舵不压杆会产生侧滑、转弯迟缓，向偏转反方向扭舵则使偏离进一步加大。"},{"id":51,"type":"single","cat":"设备与维护","stem":"BEC电子调速器（电调）有分流供电能力，可将动力电池电压变为（）电压给飞行控制系统（自驾仪）供电，多旋翼无人机的多个电子调速器（电调）都给飞行控制系统（自驾仪）供电，就容易混乱，所以我们一般只会保留一个电子调速器（电调）供电。","A":"24V","B":"12V","C":"5V","D":"36V","answer":"C","exp":"BEC电调具有分流供电能力，将动力电池电压变换为5V电压为飞控、接收机等设备供电；多旋翼有多个电调，若都向飞控供电会造成供电混乱，一般只保留一个电调供电；24V、12V、36V远高于飞控电子设备的适用电压。"},{"id":52,"type":"single","cat":"基础概念","stem":"遥控直升机在动力停滞状态，靠旋翼与空气相互作用维持直升机保持飞行的过程，称为（）飞行。","A":"维持","B":"自旋","C":"滑行","D":"以上均不正确","answer":"B","exp":"直升机动力停滞时靠旋翼与空气相互作用保持飞行称为自旋飞行：下降相对气流驱动旋翼继续旋转产生升力，驾驶员利用总距控制下降率并在接地前拉平增稳，是动力失效后的重要应急手段；维持、滑行都不是描述这一状态的专业术语。"},{"id":53,"type":"single","cat":"领航与任务规划","stem":"GPS的3个主要功能是（）。","A":"高度速度经纬度","B":"高度速度（地速）位置","C":"高度速度（空速）位置","D":"以上均不正确","answer":"B","exp":"GPS的三个主要功能是提供位置、高度和速度：速度由多普勒频移或位置差分测得，属于相对地面的地速而非空速；空速反映飞机相对空气的运动，须由空速管测量动压获得，GPS无法感知气流，故含空速的表述不准确。"},{"id":54,"type":"single","cat":"电力巡检","stem":"使用固定翼无人机巡检系统巡检作业时，使用（）方式时，应防止橡皮筋断裂伤人。","A":"滑翔起飞","B":"弹射起飞","C":"增稳起飞","D":"垂直起飞","answer":"B","exp":"弹射起飞依靠橡筋束等弹性装置积蓄弹力将固定翼加速抛出，橡筋处于高张力状态，一旦断裂会高速回弹伤人，作业时应检查橡筋状态并让人员站到安全位置；滑翔、垂直起飞不使用橡筋弹射装置，增稳也不是一种起飞方式，无此类风险。"},{"id":55,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，关于大逆风着陆描述正确的是（）。","A":"第三转弯后，适当提前下滑时机，进入第四转弯的高度应比正常风速时略低","B":"第三转弯后，适当延迟下滑时机，进入第四转弯的高度应比正常风速时略高","C":"第三转弯后，适当提前下滑时机，进入第四转弯的高度应比正常风速时略高","D":"以上均不正确","answer":"B","exp":"大逆风着陆时地速小、飞机容易被顶得飞不到预定位置，第三转弯后应适当延迟下滑时机，并以比正常风速略高的高度进入第四转弯，为下滑留足距离和能量；提前下滑且高度偏低，逆风会进一步削弱前进距离，导致到不了预定下滑点。"},{"id":56,"type":"single","cat":"法规与空域","stem":"空域是航空器运行的环境，也是宝贵的国家资源国务院中央军委十分重视我国民用航空交通管制的建设工作，目前正在推进空城管理改革预计划分三类空城为（）。","A":"管制空域、监视空城和报告空域","B":"管制空城、非管制空域和特殊空域","C":"营制空域、非管制空域和报告空域","D":"监视空域、非监视空域和报告空域","answer":"A","exp":"我国空域管理改革将空域划分为管制空域、监视空域和报告空域三类：管制空域内飞行须接受空管管制并事先获批，监视空域飞行须接受监视并报告，报告空域飞行按要求报告后即可实施；非管制、特殊等划分不属于该三类空域方案。"},{"id":57,"type":"single","cat":"领航与任务规划","stem":"无人机物理限制对飞行航迹有以下限制（），最小航迹段较长度，最低安全飞行高度。","A":"最大转弯半径，最小俯仰角","B":"最小转弯半径，最小俯仰角","C":"最小转弯半径，最大俯仰角","D":"以上均不正确","answer":"C","exp":"无人机物理性能对航迹的约束包括最小转弯半径、最大俯仰角，还有最小航迹段长度和最低安全飞行高度：机体机动能力决定了转弯半径不能小于最小值，俯仰角受失速特性和动力限制只能有上限，说存在最小俯仰角限制不符合飞行实际。"},{"id":58,"type":"single","cat":"操纵与飞行技术","stem":"无人机的发射方式可归纳为手抛发射、零长发射、弹射发射、起落架滑跑起飞、母机、空中发射、容器式发射装置发射和垂直起飞等类型下列说法正确的是（）。","A":"在地面发射时，无人机使用较为广泛的发射方式是母机空中发射与零长发射","B":"无人机安装在轨道式发射装置上，在压缩空气、橡筋或液压等弹射装置作用下起飞，无人机飞离发射装置后，在辅助发动机作用下完成飞行任务","C":"容器式发射装置是一种封闭式发射装置，兼备发射与贮存无人机功能它有单室式和多室式两种类型","D":"以上均不正确","answer":"C","exp":"容器式发射装置是封闭式发射装置，兼具发射与贮存无人机功能，分单室式和多室式两种类型；地面发射广泛采用滑跑、弹射、零长发射等方式，母机空中发射并非地面最常用方式；弹射起飞的无人机离轨后靠自身发动机飞行，无需辅助发动机。"},{"id":59,"type":"single","cat":"操纵与飞行技术","stem":"以大疆精灵4飞行器为例，起飞前未移除云台扣会造成什么后果（）。","A":"损坏云台电机","B":"画面清晰无影响","C":"云台正常自检","D":"飞行器进入FPV模式","answer":"A","exp":"大疆精灵4起飞前未取下云台扣，云台自检和增稳动作被卡阻，云台电机强行运转容易过载损坏，造成云台电机损伤；未移除云台扣还可能引发自检报错、画面异常，绝非毫无影响，起飞前应按检查单将其取下。"},{"id":60,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机机动飞行时平飞速度的提升措施，下列选项正确的是（）。","A":"减小飞机载重量","B":"增大迎角","C":"增大机翼面积","D":"减小翼型厚度","answer":"D","exp":"平飞最大速度由推力与阻力平衡决定，减小翼型厚度可直接减小翼型阻力，是提升平飞速度的有效气动措施；增大迎角会使诱导阻力增大而掉速度，增大机翼面积同样加大阻力；减小载重量主要改善起飞爬升性能，非提升平飞速度的直接手段。"},{"id":61,"type":"single","cat":"操纵与飞行技术","stem":"多轴飞行器悬停时的平衡不包括（）。","A":"方向平衡","B":"俯仰平衡","C":"前飞废阻力平衡","D":"以上均不正确","answer":"C","exp":"多轴飞行器悬停时的平衡包括俯仰平衡、滚转平衡和方向平衡，即各旋翼拉力对重心形成的俯仰、滚转力矩相互抵消，各反扭矩相互抵消，姿态与位置保持稳定；前飞废阻力平衡不是悬停平衡的组成部分，悬停没有前飞运动，不存在这种平衡。"},{"id":62,"type":"single","cat":"基础概念","stem":"垂直起降固定翼无人机尾翼由安定面和（）构成。","A":"舵面","B":"外翼段","C":"中翼段","D":"尾翼","answer":"A","exp":"垂直起降固定翼无人机的尾翼由安定面和舵面构成：安定面提供纵向和方向静稳定性，舵面（升降舵、方向舵）偏转产生操纵力矩，实现俯仰和方向控制；外翼段、中翼段属于机翼结构，不是尾翼的组成部分。"},{"id":63,"type":"single","cat":"设备与维护","stem":"遥控器、图传、地面站与飞行器之间数据链路分别是（）。","A":"上行链路、下行链路、上行链路","B":"上行链路、下行链路、上下行链路并存","C":"下行链路、下行链路、上行链路","D":"以上均不正确","answer":"B","exp":"遥控器向飞行器发送操纵指令，属上行链路；图传将机载相机画面回传地面，属下行链路；地面站既向飞行器下发任务和指令，又接收遥测状态信息，上下行链路并存；把地面站说成单纯上行或下行，会遗漏指令下发或遥测回传之一。"},{"id":64,"type":"single","cat":"基础概念","stem":"在管制机场附近的所有航空器，以及在地面的航空器都应服从（）的指令。","A":"管制员","B":"机务人员","C":"机长","D":"副机长","answer":"A","exp":"在管制机场附近运行的所有航空器，包括地面滑行和起降中的航空器，都应服从管制员的指令：管制员统一调配机场及周边空域的交通秩序，保证安全间隔；机务人员负责飞机维护，机长也必须执行管制许可，二者均不能代替管制指令。"},{"id":65,"type":"single","cat":"操纵与飞行技术","stem":"无人机重新起飞测试时，出现某台或多台电动机起动微调级时起动不一致的情况，此时首先需要（），直到所有电动机能够同步起动和停止。","A":"更换飞控","B":"重新校准油门行程","C":"更换接收机","D":"拆卸螺旋桨","answer":"B","exp":"多台电机起动不一致、不能同步起停，通常是各电调油门行程标定不一致，应首先重新校准油门行程，使所有电调在同一信号范围内动作，实现同步起停；更换飞控或接收机是排查硬件故障，拆螺旋桨只是安全防护，解决不了标定问题。"},{"id":66,"type":"single","cat":"设备与维护","stem":"小型多旋翼无人机续航时间测试步骤，第一步是将多旋翼无人机放置在环境气候实验室中；第二步是调节所述环境气候实验室室内的压强P.温度T.（），模拟真实环境；第三步，启动电池电量饱和的多旋翼无人机，开始记录时间。","A":"湿度φ","B":"密度ρ","C":"高度H","D":"风速V","answer":"D","exp":"续航测试在环境气候实验室中调节压强、温度和风速模拟真实环境：气压温度决定空气密度，影响旋翼拉力和电机功率，风速模拟风场，三者共同决定真实耗电；湿度影响次要，密度、高度由气压温度推算，不是独立调节的变量。"},{"id":67,"type":"single","cat":"法规与空域","stem":"起飞前，操作人员应逐项开展设备检查、系统自检、（）确保无人机处于适航状态。","A":"天气检查","B":"航线检查","C":"地面检查","D":"空域检查","answer":"B","exp":"起飞前应逐项开展设备检查、系统自检和航线检查，确保无人机适航：设备检查确认机体与动力正常，系统自检确认飞控和链路状态，航线检查核对航线、空域与障碍物；天气和空域属于飞行条件评估，不与这三项检查并列。"},{"id":68,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器姿态数据中，“V.S”代表什么？","A":"飞行器与起飞点之间的相对高度","B":"飞行器与起飞点之间的水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平运动的飞行速度","answer":"C","exp":"大疆飞行器姿态数据中V.S即Vertical Speed，表示飞行器沿垂直方向的上升、下降速度，正值爬升、负值下降；与起飞点的相对高度显示为D，水平距离由H.N、H.E等分量表示，它们反映位置而不是速度。"},{"id":69,"type":"single","cat":"领航与任务规划","stem":"就任务规划系统具备的功能而言，任务规划可包含航迹规划、任务分配规划、数据链路规划和系统保障与应急预案规划等，其中（）是任务规划的主体和核心。","A":"数据链路规划","B":"任务分配规划","C":"航迹规划","D":"以上均不正确","answer":"C","exp":"任务规划包含航迹规划、任务分配规划、数据链路规划和系统保障与应急预案规划等，其中航迹规划是主体和核心：飞行器如何从起点安全到达任务区并返回由航迹决定，其余规划围绕航迹展开并提供支撑，数据链路和任务分配只是配套环节。"},{"id":70,"type":"single","cat":"操纵与飞行技术","stem":"旋翼无人机最主要的操纵面是（）。","A":"尾桨","B":"副翼","C":"方向舵","D":"旋翼","answer":"D","exp":"旋翼无人机最主要的操纵面是旋翼：通过周期变距使桨盘倾斜实现俯仰、滚转操纵，通过总距改变升力大小控制升降，通过改变各旋翼或尾桨的转速与桨距调节反扭矩实现方向操纵；尾桨只是单旋翼机的部件，副翼、方向舵是固定翼操纵面。"},{"id":71,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机爬升率过小时，下列正确的操纵是（）。","A":"柔和减小俯仰角","B":"柔和增大俯仰角","C":"迅速停止爬升","D":"以上均不正确","answer":"B","exp":"姿态模式下爬升率过小说明俯仰角偏小、上升能力不足，应柔和增大俯仰角，使爬升角加大、爬升率恢复到预定值；柔和减小俯仰角会让爬升率更低，迅速停止爬升则完全脱离爬升状态，都不符合恢复爬升率的要求。"},{"id":72,"type":"single","cat":"基础概念","stem":"下列属于多旋翼无人机性能优化主要措施的是（）。","A":"功能改造，如任务载荷系统改造","B":"检修维保，如故障检修、维护保养等","C":"美观改造，如颜色、LOG等改造","D":"结构改造，如机体结构、减振、减噪等改造","answer":"D","exp":"多旋翼无人机性能优化的主要措施是结构改造，如改进机体结构、减振、减噪等，能直接提升飞行稳定性、可靠性和任务品质；功能改造属于扩展用途，检修维保属于日常维护，美观改造只改善外观，都不属于性能优化措施。"},{"id":73,"type":"single","cat":"设备与维护","stem":"固定翼无人机方向舵和升降舵并排安装在舵机层板架上舵机配有减震用的橡胶垫，内有一个空心铆钉用螺钉固定时，空心铆钉起（）的作用。","A":"减小振幅","B":"平衡重心","C":"限制高度","D":"确定安装位置","answer":"C","exp":"舵机经减震橡胶垫安装在舵机层板架上，橡胶垫内的空心铆钉在螺钉固定时起定位作用，确定舵机的安装位置，保证安装对正、受力均匀；减振功能由橡胶垫的弹性实现，金属铆钉不承担减振，也不涉及重心平衡或高度限制。"},{"id":74,"type":"single","cat":"领航与任务规划","stem":"一般常见的组合导航系统以（）为主。","A":"天文导航和惯性导航","B":"图像匹配导航和卫星导航","C":"卫星导航和天文导航","D":"多卫星","answer":"D","exp":"常见组合导航系统以多卫星组合为主，如同时接收GPS、北斗等多套卫星导航系统信号，互相补充校验，提高定位精度与可靠性；天文导航依赖天体观测、图像匹配依赖地形特征，设备复杂且易受环境限制，一般不作常规组合导航的主体。"},{"id":75,"type":"single","cat":"电力巡检","stem":"无人机巡检作业人员应具有（）年以上高压输电线路运行维护经验。","A":"1","B":"2","C":"3","D":"4","answer":"B","exp":"无人机巡检作业人员应具有2年以上高压输电线路运行维护经验：熟悉线路结构、杆塔型式和运行状况，才能正确把握巡检重点、判断缺陷部位，保证巡检质量与作业安全；经验不足难以独立承担高压线路巡检任务。"},{"id":76,"type":"single","cat":"航空气象","stem":"气温的变化，会严重影响电动无人机的哪项性能？","A":"速度性能","B":"续航性能","C":"载荷性能","D":"以上均不正确","answer":"B","exp":"气温变化严重影响电动无人机的续航性能：低温下锂电池活性下降、可用容量和放电能力明显降低，高温加速电池老化并限制散热，都直接缩短续航时间；速度和载荷性能主要取决于气动布局与动力配置，受气温直接影响相对较小。"},{"id":77,"type":"single","cat":"操纵与飞行技术","stem":"四轴飞行器为什么相邻的桨旋转方向不同？（）","A":"增加升力","B":"抵消反扭矩","C":"更加灵活","D":"以上均不正确","answer":"B","exp":"四轴飞行器相邻螺旋桨旋转方向相反是为了抵消反扭矩：每个桨旋转时空气给它一个反向扭矩，相邻桨反向布置使反扭矩相互平衡，机体不会持续自转，改变各桨转速即可实现偏航操纵；升力取决于各桨升力之和，与转向安排无关。"},{"id":78,"type":"single","cat":"操纵与飞行技术","stem":"无人机定速遥控飞行时收起起落架，驾驶员需（）。","A":"增加油门以保持空速","B":"减小油门以保持空速","C":"针对此情况，无需做相关动作","D":"以上均不正确","answer":"B","exp":"定速飞行中收起起落架，飞机阻力明显减小，油门不动时空速会增大，为保持空速应适当减小油门；起落架收放对升力影响很小，关键在于按阻力变化调整油门，加油门会使空速进一步偏大，不动作则无法保持原空速。"},{"id":79,"type":"single","cat":"飞行原理","stem":"实际升力和洗流方向是（）。","A":"平行的","B":"交叉的","C":"垂直的","D":"根据迎角变化","answer":"C","exp":"存在下洗时，实际升力定义为垂直于当地相对气流即洗流方向的空气动力分力，因此实际升力与洗流方向垂直；下洗使实际升力相对未受下洗的理想升力后倾，其水平分量构成诱导阻力的一部分，这一垂直关系由气动力定义确定，不随迎角变化。"},{"id":80,"type":"single","cat":"设备与维护","stem":"一般电源适配器的最大输出功率要比充电器的最大最出功率大（）倍。","A":"1.2-1.5","B":"2-3","C":"2.5-3","D":"3-5","answer":"A","exp":"电源适配器的最大输出功率应比充电器最大输出功率大1.2～1.5倍：留出适当功率裕量，保证充电器满载工作时适配器不过载、不过热，输出稳定并延长寿命；裕量过小适配器长期满载易损坏，裕量过大则造成成本浪费。"},{"id":81,"type":"single","cat":"领航与任务规划","stem":"下面哪项功能与GPS指南针模块无关（）。","A":"精准定位悬停","B":"定高","C":"保持飞行稳定","D":"失控返航","answer":"B","exp":"GPS指南针模块提供位置和航向信息，支撑精准定位悬停、保持飞行稳定的位置航向闭环，以及失控返航时按返航点坐标导航；定高依靠气压计等高度传感器实现，与GPS指南针无关，故定高是与该模块无关的功能。"},{"id":82,"type":"single","cat":"操纵与飞行技术","stem":"是否装有（）也是无人驾驶航空器区别于普通航空模型的重要标志。","A":"定位系统","B":"飞控系统","C":"电力系统","D":"动力系统","answer":"B","exp":"无人驾驶航空器区别于普通航空模型的重要标志是装有飞控系统：飞控自动完成姿态稳定、导航定位与航线飞行，可自主执行任务，航模靠飞手实时遥控，不具备自主飞行控制能力；定位、动力、电力系统航模同样可以具备，不构成本质区别。"},{"id":83,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机动力装置安装时，对于油动发动机，油箱出油口与发动机连接，油箱进气管与消声器、增压嘴连接利用（）给油箱增压、加压，保证无人机在任何飞行姿态供油压力稳定。","A":"飞行惯性产生的压力","B":"空气流动产生的压力","C":"油料挥发产生的压力","D":"发动机的排气压力","answer":"D","exp":"油动发动机供油系统利用发动机的排气压力给油箱增压：消声器上的增压嘴接油箱进气管，将部分排气引入油箱建立正压，使燃油在任何飞行姿态下都以稳定压力供向化油器，防止俯冲、滚转时断油；惯性、气流或油料挥发产生的压力均不可靠。"},{"id":84,"type":"single","cat":"设备与维护","stem":"电调是多旋翼无人机最重要的部件之一，不属于飞行器电调功能的是（）。","A":"变压供电","B":"电机调速","C":"实时电机反转","D":"以上均不正确","answer":"C","exp":"电调的基本功能是把直流电变成驱动无刷电机的三相电并按指令调速，还可通过BEC变压供电为飞控等设备供电；实时电机反转不属于其常规功能，电机转向一般在地面调试时设定，飞行中实时反转会导致拉力方向突变，带来失控风险。"},{"id":85,"type":"single","cat":"设备与维护","stem":"翼载荷（），飞行速度（），无人机的机动性较差，但飞行阻力小，抗风性和穿透性较好。","A":"小，慢","B":"小，快","C":"大，慢","D":"大，快","answer":"D","exp":"翼载荷大、飞行速度快的无人机，单位机翼面积承受的重量大，转弯半径和可用过载受限，机动性较差；但高速飞行受阵风扰动影响小、能顶风保持航迹，抗风性和穿透性较好，阻力占比也小；翼载荷小速度慢的机型相反，机动灵活但抗风差。"},{"id":86,"type":"single","cat":"操纵与飞行技术","stem":"无人机装配报告中桨叶安装复检包括（）、正反桨位置检查、螺旋桨安装牢固、垂起桨和平飞桨区分安装。","A":"桨叶动平衡检查","B":"桨叶静平衡检查","C":"桨叶效率检查","D":"桨叶无损检查","answer":"D","exp":"桨叶安装复检包括桨叶无损检查、正反桨位置检查、螺旋桨安装牢固以及垂起桨和平飞桨区分安装：无损检查在不拆解的情况下发现裂纹、缺损等隐患；动平衡、静平衡属于专门的平衡试验项目，效率检查也不属于安装复检内容。"},{"id":87,"type":"single","cat":"领航与任务规划","stem":"以大疆产品为例，关于飞行器返航点描述正确的是？（）","A":"返航点可在飞行中刷新","B":"返航点不可在飞行中刷新","C":"室内飞行时可刷新返航点","D":"GPS信号弱时可刷新返航点","answer":"A","exp":"返航点可在飞行中刷新：大疆飞行器支持手动刷新返航点，也可按设定在定位良好时自动更新，使返航点跟随操作者当前位置；室内或GPS信号弱时定位不可靠，刷新会导致返航点偏差，不宜刷新，返航点并非固定不可改变。"},{"id":88,"type":"single","cat":"基础概念","stem":"新出厂或组装后首次投入飞行的旋翼飞机，应在正式飞行之前进行（）。","A":"有桨调试","B":"无桨调试","C":"充电","D":"放电","answer":"B","exp":"新出厂或组装后首次投入飞行的旋翼飞机，正式飞行前应先做无桨调试：卸下螺旋桨通电，检查电机转向、电调响应、飞控自检与遥控链路，排除装配错误，避免带桨试车时桨叶伤人；有桨调试须在无桨调试通过后进行，充放电只是电池维护。"},{"id":89,"type":"single","cat":"基础概念","stem":"现场禁止使用可能对无人机造成干扰的（）。","A":"遥控系统","B":"图传系统","C":"任务设备","D":"电子设备","answer":"D","exp":"无人机靠无线电链路和卫星导航工作，现场禁止使用可能对其造成干扰的电子设备：大功率电台、无线发射装置等会产生同频或宽带干扰，导致遥控失灵、图传中断或导航漂移；遥控、图传和任务设备是无人机系统的组成部分，规范使用不受禁止。"},{"id":90,"type":"single","cat":"基础概念","stem":"以下那一项是无人飞行器的英文缩写（）。","A":"UAU","B":"ATC","C":"AUV","D":"UAV","answer":"D","exp":"无人飞行器的英文缩写是UAV，即Unmanned Aerial Vehicle，指无人驾驶、由遥控或自控系统操纵的航空器；AUV一般指自主水下航行器，ATC是空中交通管制，UAU不是航空领域的标准缩写。"},{"id":91,"type":"single","cat":"设备与维护","stem":"无刷电机动平衡性能对飞行器性能的影响，下面不包括的是（）。","A":"降低电调寿命","B":"影响飞行器飞行性能","C":"飞机振动","D":"影响电机寿命","answer":"A","exp":"无刷电机动平衡不良会产生高频振动，使飞机振动加剧、飞行性能下降，并加速电机轴承磨损、影响电机寿命；电调主要受电流和发热影响，动平衡好坏并不直接决定电调寿命，因此降低电调寿命不属于动平衡性能的影响范围。"},{"id":92,"type":"single","cat":"领航与任务规划","stem":"起落航线（五边航线）组成内容不包括（）。","A":"着陆目测、着陆","B":"任务飞行","C":"起飞、建立航线","D":"以上均不正确","answer":"B","exp":"起落航线即五边航线，围绕机场供起飞着陆训练和进出机场使用，包括起飞爬升、建立航线、沿各边飞行、着陆目测和着陆等阶段；任务飞行是执行侦察、巡检等作业的飞行，发生在任务空域，不属于起落航线的组成内容。"},{"id":93,"type":"single","cat":"操纵与飞行技术","stem":"擦地着陆回收是通过无人机与地面摩擦阻力实现速度缓冲与能量吸收的着陆方式，擦地着陆不受地形条件和机型大小限制，成功着陆率高，但容易造成（）损伤，需要更换与维修。","A":"机体","B":"全球定位系统（GPS）模块","C":"电机","D":"接收机","answer":"A","exp":"擦地着陆靠机体与地面摩擦滑跑消耗速度和能量，成功率高且不受地形条件和机型大小限制，但机体直接触地摩擦，蒙皮、起落结构等机体部分容易磨损划伤，着陆后需更换维修；GPS模块、电机、接收机位于机体内部，一般不直接受擦地损伤。"},{"id":94,"type":"single","cat":"基础概念","stem":"如果多轴飞行器安装的螺旋桨与电动机不匹配，桨尺寸过大，会带来的坏处不包括（）。","A":"飞控电流过大，造成损坏","B":"电机电流过大，造成损坏","C":"电调电流过大，造成损坏","D":"以上均不正确","answer":"A","exp":"螺旋桨尺寸过大，电机需输出更大扭矩，电机电流和电调电流都会过大，长期满负荷工作易烧坏电机和电调，也可能超出电池放电能力；飞控是信号控制单元，工作电流很小，不因桨大而增大，飞控电流过大损坏不属于桨过大的坏处。"},{"id":95,"type":"single","cat":"设备与维护","stem":"电调是通过改变什么来控制电机转速的？（）","A":"电流","B":"电压","C":"功率","D":"以上均不正确","answer":"B","exp":"电调通过改变加在电机上的有效电压来控制转速：电调以PWM方式调节输出占空比，等效改变电机端电压，电压升高转速上升、降低则减速，从而实现油门对转速的控制；电流和功率是电压变化带来的结果，不是直接的控制量。"},{"id":96,"type":"single","cat":"设备与维护","stem":"下面那一部分不属于电调的组成部分（）。","A":"插头","B":"漆包线","C":"硅胶线","D":"信号线","answer":"B","exp":"电调由外壳、功率管和控制电路板以及各连接线组成：输入电源线（硅胶线）、输出到电机的三相线、插头和接接收机的信号线都是其组成部分；漆包线用于绕制电机定子线圈，不作为电调的结构部件出现。"},{"id":97,"type":"single","cat":"电力巡检","stem":"设备运维单位提前建立各型无人机巡检系统正常以及备选起飞和（），由工作许可人在地图上进行标注，并及时更新。","A":"线路资料信息","B":"设备信息","C":"起飞区档案","D":"降落区档案","answer":"D","exp":"设备运维单位应提前建立各型巡检系统正常及备选的起飞和降落区档案，由工作许可人在地图标注并及时更新：起降区档案明确各作业点的起降场地与备选方案，便于快速组织起降和应急转移；线路资料、设备信息是运维资料，不是起降场地档案。"},{"id":98,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器飞行过程中，红色三角形位于姿态球左上方，三角形尖端朝向姿态球中心，请问飞行器处于操作者哪个位置，机头朝向如何？","A":"飞行器处于操作者左前方，机头朝向操作者自己","B":"飞行器处于操作者左后方，机头朝向操作者自己","C":"飞行器处于操作者右后方，机头朝向操作者前方","D":"飞行器处于操作者右前方，机头朝向操作者后方","answer":"A","exp":"姿态球以操作者位置为参照：红色三角形位于球的左上方，表示飞行器处于操作者左前方，上方对应前方、左侧对应左方；三角形尖端朝向球心，表示机头朝向操作者自己，其余方位组合与姿态球的映射关系不符。"},{"id":99,"type":"single","cat":"设备与维护","stem":"多轴飞行器飞控板上一般会安装（）。","A":"6个角速率陀螺","B":"1个角速率陀螺","C":"3个角速率陀螺","D":"以上均不正确","answer":"A","exp":"多轴飞行器飞控板上一般安装6个角速率陀螺，即两组三轴陀螺，分别敏感俯仰、滚转、偏航三个轴的角速率并互为备份，一组异常时另一组仍能提供姿态角速率信息，保证飞控可靠工作；1个或3个陀螺没有冗余，单点失效就会丧失姿态测量。"},{"id":100,"type":"single","cat":"领航与任务规划","stem":"无人机任务规划需要考虑的因素有（）、无人机物理限制、实时性要求。","A":"飞行任务范围，飞行安全限制","B":"飞行安全限制，飞行任务要求","C":"飞行环境限制，飞行任务要求","D":"以上均不正确","answer":"C","exp":"无人机任务规划需要考虑飞行环境限制、飞行任务要求、无人机物理限制和实时性要求等因素：环境限制涵盖地形、障碍物和禁飞区，任务要求决定目标点与优先级，综合权衡才能生成安全可行的航迹；单讲安全限制或任务范围都概括不全。"},{"id":101,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，为加强架空输电线路无人机巡检现场管理，规范各类工作人员的行为，保证（）安全，应遵循国家有关法律、法规，并结合电力生产的实际，开展架空输电线路无人机巡检作业。","A":"人身","B":"电网","C":"设备","D":"设施","answer":"ABC","exp":"《架空输电线路无人机巡检作业安全工作规程》以保证人身、电网、设备安全为目标：人身安全要求防止无人机伤人和触电事故，电网安全要求巡检不得危及输电线路正常供电，设备安全要求保护无人机与线路设备不受损伤；规程规范的安全对象就是这三项，设施未被单独列入。"},{"id":102,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统应按要求定期（），确保状态良好。","A":"检查","B":"保养","C":"维修","D":"试验","answer":"BCD","exp":"按巡检作业规程要求，无人直升机巡检系统应定期保养、维修和试验：保养维持各系统性能状态，维修排除使用中出现的故障，试验验证整机功能与安全裕度，三者共同确保设备状态良好；检查属于作业前后的日常例行环节，不属于与保养、维修并列的定期项目。"},{"id":103,"type":"multi","cat":"基础概念","stem":"固定翼无人机性能升级的主要目标（）。","A":"提升航时","B":"改变焦点位置","C":"提高抗风性","D":"提高抗雨性","answer":"ACD","exp":"固定翼无人机性能升级的主要目标是提升航时、提高抗风性和提高抗雨性：航时越长任务覆盖能力越强，抗风性提高可扩大可用气象条件范围，抗雨性提高减少天气对任务的影响；改变焦点位置属于气动布局与重心调配的设计内容，不是性能升级的目标。"},{"id":104,"type":"multi","cat":"电力巡检","stem":"使用小型无人直升机巡检系统的巡检作业，操控手应在巡检作业前一个工作日（）。","A":"完成所用无人直升机巡检系统的检查","B":"确认状态正常","C":"准备好现场作业工器具","D":"备品备件等物资","answer":"ABCD","exp":"操控手应在巡检作业前一个工作日完成所用无人直升机巡检系统的检查并确认状态正常，同时准备好现场作业工器具和备品备件等物资：提前检查确认可防止次日带故障起飞，工器具与备件预先到位能保证现场作业连续进行、出现故障时及时更换，四个环节都不可缺。"},{"id":105,"type":"multi","cat":"操纵与飞行技术","stem":"旋翼无人机按起飞重量可分为以下几种类型（）。","A":"微型旋翼无人机","B":"轻型旋翼无人机","C":"小型无人旋翼机","D":"大旋无人旋翼机","answer":"ABCD","exp":"旋翼无人机按起飞重量通常分为微型、轻型、小型和大型：微型体积重量最小，适合近距练习和室内场景；轻型、小型承担航拍、巡检等常规任务；大型起飞重量大，可挂载更重的任务载荷执行复杂任务；四个等级按重量递进划分，构成完整的类型体系。"},{"id":106,"type":"multi","cat":"基础概念","stem":"图元标注主要包括以下三个方面信息（）。","A":"航迹标注","B":"场地标注","C":"警示标注","D":"任务区域标注","answer":"BCD","exp":"图元标注主要包括场地标注、警示标注和任务区域标注三个方面：场地标注标明起降点和作业场地位置，警示标注提示禁飞区、高压线等危险信息，任务区域标注圈定本次作业的范围；航迹是飞行路径规划的成果，属于航线要素，不在图元标注的三个方面之内。"},{"id":107,"type":"multi","cat":"领航与任务规划","stem":"（）时，作业人员应与无人直升机始终保持足够安全距离，避开起降航线。","A":"起飞","B":"巡视","C":"拍照","D":"降落","answer":"AD","exp":"无人直升机起飞和降落阶段风险最高：旋翼下洗气流强、姿态和高度变化快，作业人员应与其始终保持足够安全距离并避开起降航线，防止被桨叶或被气流吹起的异物伤害；巡视、拍照阶段航线和速度相对平稳，按正常作业距离即可，无需专门避开。"},{"id":108,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，民用无人机可以分为（）。","A":"巡查/监视无人机","B":"农用无人机","C":"通信中继无人机","D":"勘探无人机","answer":"ABD","exp":"按《架空输电线路无人机巡检技术》的分类，民用无人机可分为巡查/监视无人机、农用无人机和勘探无人机：巡查/监视类用于线路巡视与安防监控，农用类承担植保喷洒作业，勘探类用于测绘与勘察；通信中继无人机是空中通信平台，不属于该分类。"},{"id":109,"type":"single","cat":"基础概念","stem":"下列（）属于电动无人机的缺点。","A":"续航能力差","B":"系统稳定性差","C":"环境适应能力差","D":"震动大","answer":"A","exp":"电动无人机的缺点是续航能力差：受电池能量密度限制，续航时间明显短于油动飞机，难以胜任长航时任务；电动机运转平稳、振动小，动力系统简单可靠，环境适应性和系统稳定性并不差，这些是电动力相对油动的优点而非缺点。"},{"id":110,"type":"single","cat":"设备与维护","stem":"飞机飞行时感受到气流的冲击力量，即动压，与空气静止时的压力相比，从而转换出飞机空速需要用到的传感器是（）。","A":"姿态传感器","B":"高度传感器","C":"空速传感器","D":"位置传感器","answer":"C","exp":"动压是气流冲击产生的压力，空速传感器（空速管/皮托管）测量全压与静压之差得到动压，按动压与空速的换算关系解算出空速；姿态传感器测姿态角，高度传感器测气压高度，位置传感器定位坐标，都不测量气流冲击压力、给不出空速。"},{"id":111,"type":"single","cat":"设备与维护","stem":"关于多轴飞行器机桨与电机匹配描述错误的是（）。","A":"2S电池下，KV1300-1500左右用9050浆","B":"3S电池下，KV900-1000的电机配1060或1047桨","C":"3S电池下，KV1200-1400配3寸桨","D":"以上均不正确","answer":"C","exp":"机桨匹配按电压和电机KV值选桨：2S配KV1300-1500用9050桨、3S配KV900-1000用1060桨是常见搭配；同电压KV越高桨应越小，KV1200-1400应配中等尺寸桨，说配3寸桨不符常规，描述错误。"},{"id":112,"type":"single","cat":"基础概念","stem":"抵达现场，应报告（），履行飞行许可手续，获得许可后方可开展作业。","A":"机长","B":"空管部门","C":"工作负责人","D":"工作许可人","answer":"B","exp":"抵达现场应向空管部门报告并履行飞行许可手续，获得许可后方可开展作业：空域和飞行活动由空管统一管理，飞行前报批是法规要求的必经程序，未经许可不得起飞；机长、工作负责人、工作许可人是作业团队内部分工，不能代替空管审批。"},{"id":113,"type":"single","cat":"基础概念","stem":"在目视范围内，操控手应密切观察无人直升机（）及周围环境变化，异常情况下，操控手可手动接管控制无人直升机。","A":"机架","B":"脚架","C":"光电吊舱","D":"飞行姿态","answer":"D","exp":"目视飞行范围内，操控手应密切观察无人直升机的飞行姿态及周围环境变化：姿态异常如抖动、漂移、姿态角突变往往是故障先兆，操控手可及时手动接管控制，防止事态扩大；机架、脚架和光电吊舱只是局部结构或设备，无法综合反映飞行状态。"},{"id":114,"type":"single","cat":"设备与维护","stem":"属于无人机飞控子系统的是（）。","A":"无人机姿态稳定与控制","B":"无人机任务设备管理与控制","C":"信息收集与传递","D":"以上均不正确","answer":"A","exp":"无人机飞控子系统的核心是姿态稳定与控制：飞控实时解算姿态并输出舵面或电机控制量，保持飞机稳定并执行机动指令；任务设备管理与控制属于任务载荷分系统，信息收集与传递由数据链路等系统承担，均与飞控协同但非飞控组成部分。"},{"id":115,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，DJIGO界面中，姿态球上绿色范围表示的是。","A":"飞行器云台朝向","B":"遥控器朝向","C":"移动设备朝向","D":"操作员朝向","answer":"A","exp":"DJI GO姿态球上的绿色范围表示飞行器云台的朝向，帮助操作员直观掌握相机镜头指向与机头方向的偏差；遥控器、移动设备或操作员的朝向在界面中另有图标表示，不要与绿色范围混淆。"},{"id":116,"type":"single","cat":"飞行原理","stem":"下列属于无人驾驶航空器产生升力的主要部件是（）。","A":"机翼","B":"尾翼","C":"燃料系统","D":"动力装置","answer":"A","exp":"无人驾驶航空器的升力主要由机翼产生：气流流过机翼上下表面存在速度差，形成上下压力差即升力。尾翼只负责配平与稳定，动力装置提供拉力，燃料系统储存能源，都不承担产生升力的功能。"},{"id":117,"type":"single","cat":"基础概念","stem":"无人机配平的主要考虑是重心沿（）的前后位置。","A":"纵轴","B":"横轴","C":"立轴","D":"以上均不正确","answer":"A","exp":"配平主要关心俯仰平衡，俯仰力矩取决于重心沿纵轴（机头至机尾方向）的前后位置，重心偏前偏后都会改变俯仰姿态；横轴、立轴方向的位置变化对应滚转和偏航，不是配平的主要考虑方向。"},{"id":118,"type":"single","cat":"基础概念","stem":"固定翼无人机配平主要考虑的是（）沿纵轴的前后位置。","A":"气动焦点","B":"发动机","C":"重心","D":"以上均不正确","answer":"C","exp":"固定翼俯仰配平的核心对象是重心，重心沿纵轴的前后位置决定俯仰力矩能否平衡以及纵向静稳定性；气动焦点只是分析纵向稳定性的参考点，配平调整的是重心位置而不是焦点。"},{"id":119,"type":"single","cat":"基础概念","stem":"多旋翼无人机以下哪个下降速度较为合理（）。","A":"2m/s","B":"5m/s","C":"8m/s","D":"以上均不正确","answer":"A","exp":"多旋翼下降速度应控制在2m/s左右：下降过快会进入自身旋翼的下洗气流甚至涡环状态，升力骤减容易失控坠落；5m/s、8m/s的下沉速度已明显超出安全范围，不可取。"},{"id":120,"type":"single","cat":"基础概念","stem":"无识别标志的航空器因特殊情况需要飞行的（）。","A":"必须经相关管制单位批准","B":"必须经中国人民解放军空军批准","C":"必须经由国务院﹑中央军委空中交通管制委员会批准","D":"必须经民航局批准","answer":"B","exp":"按航空管制规定，无识别标志的航空器因特殊情况需要飞行时，必须经中国人民解放军空军批准；管制单位、民航局都无权批准这类特殊飞行，由空军统一审批是为了严格管控身份不明航空器的飞行活动。"},{"id":121,"type":"single","cat":"基础概念","stem":"民用无人机在条件允许的情况下，一般要（）。","A":"顺风起飞","B":"左侧风起飞","C":"逆风起飞","D":"以上均不正确","answer":"C","exp":"民用无人机条件允许时应逆风起飞：逆风增大相对空速，同样地速下升力更大，可缩短滑跑或爬升距离，且舵面、旋翼的操纵效能更好；顺风起飞会拉长起飞距离并降低操纵效率，侧风则易使机体偏转。"},{"id":122,"type":"single","cat":"基础概念","stem":"要想飞机飞行更稳定，负载应（）。","A":"靠近重心安装","B":"尽量向下远离重心位置安装","C":"尽量向上远离重心位置安装","D":"以上均不正确","answer":"A","exp":"负载应靠近重心安装：质量集中在重心附近，转动惯量小，姿态改变时产生的惯性力矩小，飞行更平稳、操纵响应更灵敏；远离重心安装会放大惯性与配平负担，机动时姿态剧烈，稳定性变差。"},{"id":123,"type":"single","cat":"操纵与飞行技术","stem":"地面控制站功能主要包括以下几个方面：飞行状态的监测与控制、（）、飞行数据的记录与回放、模拟飞行。","A":"地图导航","B":"任务规划","C":"飞行控制","D":"地图导航与任务规划","answer":"D","exp":"无人机地面控制站的基本功能包括飞行状态监测与控制、地图导航与任务规划、飞行数据记录回放和模拟飞行；地图导航与任务规划必须并列构成完整功能，单选任何一项都不全面。"},{"id":124,"type":"single","cat":"基础概念","stem":"固定翼无人机练习启动时，可用（）的螺旋桨，既容易启动，又不易反转和打手。","A":"直径较大和较重","B":"直径较小和较重","C":"直径较小和较轻","D":"直径较大和较轻","answer":"A","exp":"直径较大、较重的螺旋桨转动惯量大，启动后靠惯性维持稳定旋转，既容易启动又不易反转打手，适合练习启动使用；直径小而轻的桨惯性小，转速波动大，反扭时容易回弹伤手。"},{"id":125,"type":"single","cat":"航空气象","stem":"飞控系统主要由陀螺仪、加速度计、角速度计、气压计、GPS模块、指南针和控制电路等组成，主要功能是计算并调试无人机（）。","A":"飞行时间","B":"飞行姿态","C":"飞行距离","D":"飞行系统","answer":"B","exp":"飞控系统通过陀螺仪、加速度计、气压计、GPS、指南针等传感器实时测量机体状态，解算并调整无人机的飞行姿态，实现稳定飞行；飞行时间、距离只是附带记录显示的信息，不是飞控的核心功能。"},{"id":126,"type":"single","cat":"操纵与飞行技术","stem":"飞机起飞时后缘襟翼放下的角度小于着陆时放下的角度是因为（）。","A":"后缘襟翼放下角度比较小时，机翼的升力系数增加，阻力系数不增加","B":"后缘襟翼放下角度比较大时，机翼的阻力系数增加，升力系数不增加","C":"后缘襟翼放下角度比较小时，机翼的升力系数增加的效果大于阻力系数增加的效果","D":"以上均不正确","answer":"C","exp":"起飞用小角度襟翼，是因为小角度放下时升力系数增加的效果明显大于阻力系数增加的效果，既能缩短滑跑距离又不致阻力过大；着陆时用大角度襟翼靠大阻力缩短滑跑。认为襟翼只增升不增阻或只增阻不增升，都不符合气动规律。"},{"id":127,"type":"single","cat":"操纵与飞行技术","stem":"无人机在遥控下降中，速度过大时，驾驶员应（）。","A":"适当减小带杆量，增大下滑角","B":"适当增加带杆量，减小下滑角","C":"顺其自然，让其自动恢复状态","D":"以上均不正确","answer":"B","exp":"遥控下降中速度过大，说明下滑角偏大，应适当增加带杆量减小下滑角，使升力与重力的平衡恢复、速度回落；减小带杆量会使下滑角进一步增大、速度更快，飞行状态一般不会自动恢复。"},{"id":128,"type":"single","cat":"飞行原理","stem":"根据机翼产生升力的特性，飞行速度越快机翼产生的升力越大，为了保持无人机运动的水平，发动机还会有一定的（）。","A":"左拉角度","B":"右拉角度","C":"上拉角度","D":"下拉角度","answer":"D","exp":"飞行速度越快机翼升力越大，机头会出现上仰趋势；把发动机轴线设计成相对机身水平线有一定下拉角度，使拉力线产生相应的配平力矩抵消这一趋势，飞机才能保持水平运动。左拉、右拉角用于平衡螺旋桨反扭矩引起的偏航。"},{"id":129,"type":"single","cat":"操纵与飞行技术","stem":"多轴飞行器悬停转向和以10km/h速度前飞转向中（）。","A":"横滚角不同","B":"横滚角不确定","C":"横滚角相同","D":"以上均不正确","answer":"A","exp":"悬停转向时机身不前倾，只有绕立轴的偏航运动，横滚角基本为零；以10km/h前飞时机身需倾斜使旋翼拉力产生水平分量，转弯时还伴随横滚倾侧，两种状态的横滚角不同。"},{"id":130,"type":"single","cat":"基础概念","stem":"多旋翼无人机螺旋桨静平衡测试中，有孔位分配法削、减法和（）。","A":"增重法","B":"剪切法","C":"更换法","D":"打磨法","answer":"A","exp":"螺旋桨静平衡校正常用孔位分配法、削减法和增重法：在较轻一侧增重或削减较重一侧材料，使桨叶重量分布一致、旋转平稳；剪切法、更换法、打磨法不是静平衡校正的规范方法。"},{"id":131,"type":"single","cat":"设备与维护","stem":"多旋翼在测试电机转动方向最重要的安全措施是（）。","A":"拆卸螺旋桨","B":"拆卸机臂","C":"拆卸电机","D":"以上均不正确","answer":"A","exp":"测试电机转动方向前必须先拆卸螺旋桨：通电试转一旦意外高速启动，带桨旋转极易造成严重伤人和设备损坏；拆机臂或电机没有必要，反而破坏安装状态，卸桨是最重要的安全措施。"},{"id":132,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员舵面遥控操纵飞机时（）。","A":"拉杆飞机转入下降","B":"推油门飞机转入下降","C":"推杆飞机转入下降","D":"以上均不正确","answer":"C","exp":"推杆使升降舵下偏、尾部上抬产生低头力矩，机头下俯，飞机转入下降；拉杆则抬头进入爬升，油门主要控制速度与高度变化，与转入下降无直接关系，故舵面操纵中下降靠推杆。"},{"id":133,"type":"single","cat":"基础概念","stem":"高压线路的电线覆冰首先在（）生长，如风向不发生大的变化，迎风面上覆冰厚度会继续增加。","A":"导线两端","B":"导线下方","C":"迎风面上","D":"背风面上","answer":"C","exp":"导线覆冰是过冷水滴撞在导线上冻结形成的，首先在迎风面上生长；风向不变时水滴持续撞击迎风面，冰层不断加厚，导线两端、下方和背风面都不是覆冰最先集中生长的部位。"},{"id":134,"type":"single","cat":"基础概念","stem":"4轴飞行器飞行运动中有（）。","A":"6个自由度，沿3轴移动，绕3轴转动","B":"4个自由度，绕4个轴转动","C":"4个自由度，沿3个轴移动","D":"以上均不正确","answer":"A","exp":"四轴飞行器作为空间自由刚体具有6个自由度：沿纵轴、横轴、立轴三个方向的移动，加绕这三轴的转动（俯仰、横滚、偏航）；4个旋翼只是控制通道数，自由度不由旋翼数量决定。"},{"id":135,"type":"single","cat":"基础概念","stem":"（）是指无人机发动机推力/拉力与无人机飞行重力之比该参数是衡量动力系统乃至整机性能的重要参数，很大程度上影响飞行性能。","A":"展弦比","B":"冗余度","C":"推重比","D":"以上均不正确","answer":"C","exp":"推重比是发动机推力（拉力）与无人机飞行重力之比，是衡量动力系统乃至整机性能的重要参数，推重比越大爬升与机动能力越强；展弦比是机翼平面形状参数，冗余度描述系统可靠性，均与推力无关。"},{"id":136,"type":"single","cat":"操纵与飞行技术","stem":"固定翼常规无人机飞行主操纵面有（）。","A":"副翼、升降舵、方向舵、调整片","B":"副翼、升降舵(或全动平尾)、方向舵","C":"副翼","D":"以上均不正确","answer":"B","exp":"固定翼常规布局的主操纵面是副翼、升降舵（或全动平尾）和方向舵，分别控制滚转、俯仰、偏航三个姿态通道；调整片属于辅助操纵面，用于配平减轻杆力，不属于主操纵面。"},{"id":137,"type":"single","cat":"操纵与飞行技术","stem":"下面关于悬停操纵说法错误的是（）。","A":"悬停时的姿态是各气动力和力矩以及重量、重心配平的结果，是唯一的","B":"在悬停中，要保持直升机没有前后移位，必须使纵向力和俯仰力矩平衡","C":"悬停时气动力自动保持平衡，无需频繁操纵","D":"以上均不正确","answer":"C","exp":"悬停是直升机的不稳定平衡状态，稍有扰动就会破坏平衡，必须频繁操纵修正才能保持位置姿态，气动力自动保持平衡、无需频繁操纵的说法错误；悬停姿态是气动力、力矩与重量重心配平的唯一结果，保持无前后移位需纵向力和俯仰力矩平衡。"},{"id":138,"type":"single","cat":"操纵与飞行技术","stem":"X模式4轴飞行器从悬停转换到向右平移，哪两个轴需要减速（）。","A":"横轴右侧","B":"横轴左侧","C":"纵轴右侧","D":"以上均不正确","answer":"C","exp":"X构型四轴从悬停转入向右平移时，需纵轴右侧的两个旋翼减速、左侧两个加速，机身向右倾斜，旋翼合力产生向右的水平分力；横轴两侧电机的转速差对应俯仰，与向右平移无关。"},{"id":139,"type":"single","cat":"操纵与飞行技术","stem":"（）的主要功能是监控无人驾驶航空器的飞行过程以及任务执行情况，它是一个实时采集并分析遥测数据、不定时发送控制指令、显示飞行状态等功能结合于一体的综合监控系统。","A":"地面控制站","B":"飞控系统","C":"动力系统","D":"电力系统","answer":"A","exp":"地面控制站实时采集分析遥测数据、不定时发送控制指令并显示飞行状态，对无人机的飞行过程和任务执行情况进行监控；飞控系统在机载端负责姿态控制，动力、电力系统不承担监控职能。"},{"id":140,"type":"single","cat":"航空气象","stem":"同一架无人机于某日中午和傍晚进行两次GPS高度200米的飞行，地面基准气压相同的前提下（）。","A":"中午的气压高度高","B":"傍晚的气压高度高","C":"中午和傍晚的气压高度一样高","D":"以上均不正确","answer":"A","exp":"中午气温高，空气密度小，气压随高度递减变慢，同一真实高度处的气压值比傍晚低；气压高度按标准大气换算，气压越低对应显示高度越高，所以中午飞行的气压高度更高。GPS定位的真实高度两次相同。"},{"id":141,"type":"single","cat":"航空气象","stem":"下列选项中，关于气温影响飞机滑跑距离说法正确的是（）。","A":"气温高时，空气密度小，飞机增速慢，飞机的离地速度增大，起飞滑跑距离要长","B":"气温低时，空气密度小，飞机增速快，飞机升力减小，起飞滑跑距离要长","C":"气温高时，空气密度大，飞机增速快，飞机升力增大，起飞滑跑距离要短","D":"气温低时，空气密度大，飞机升力减小，起飞滑跑距离增加。","answer":"A","exp":"气温高时空气密度小，发动机功率和螺旋桨拉力下降，飞机增速慢，且同样表速对应的离地真空速更大，起飞滑跑距离加长；气温低时空气密度大、升力和拉力足，滑跑距离反而短，把气温与密度关系说反的说法都不成立。"},{"id":142,"type":"single","cat":"基础概念","stem":"以下哪个不是在系统菜单设置里的功能？（）","A":"Sound","B":"UserName","C":"function","D":"以上均不正确","answer":"C","exp":"地面站软件的系统菜单提供Sound声音、UserName用户名等系统级设置项；function（功能）是软件的功能模块名称，不属于系统菜单中的设置项，声音和用户名设置才是系统菜单内容。"},{"id":143,"type":"single","cat":"操纵与飞行技术","stem":"四轴飞行器和八轴飞行器的区别是（）。","A":"四轴飞行时间短，效率高八轴更稳","B":"四轴飞行时间久，效率高八轴更稳","C":"八轴飞行时间久，效率高四轴更稳","D":"以上均不正确","answer":"B","exp":"四轴旋翼数量少，电机与电调的功率损耗小，能量利用效率高，续航时间相对更久；八轴电机多、自重和功耗大，效率较低，但动力冗余多、抗风性和稳定性更好，所以四轴效率高、八轴更稳。"},{"id":144,"type":"single","cat":"领航与任务规划","stem":"共轴式无人机的航向操纵多是如何实现的（）。","A":"通过操纵上下旋翼的自动倾斜器","B":"通过分别改变上下的旋翼的总距","C":"通过自动倾斜器和总距的联合操纵","D":"以上均不正确","answer":"B","exp":"共轴式无人机的上下两副旋翼反转旋转，正常飞行时反扭矩相互抵消；分别改变上、下旋翼的总距，使两副旋翼的反扭矩出现差值，即可实现航向操纵，无需单独的方向舵或尾桨。"},{"id":145,"type":"single","cat":"基础概念","stem":"无人直升机飞行过程中应避免进行超出其（）的飞行。","A":"飞行高度","B":"飞行距离","C":"性能指标","D":"遥控信号","answer":"C","exp":"无人直升机应避免超出其性能指标的飞行，如超载重、超风速、超高度飞行会接近动力与操纵极限，容易失控；飞行距离、高度和信号只是外部条件，性能包线才是安全的根本边界。"},{"id":146,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员姿态遥控模式下操纵无人机下降时，下列正确的操纵是（）。","A":"如俯角过小，应柔和地向后带杆","B":"如俯角过小，应柔和地向左压杆","C":"如俯角过小，应柔和地向前顶杆","D":"以上均不正确","answer":"C","exp":"姿态模式操纵下降时，俯角过小说明机头下俯不够、下降航迹平缓、下降速度不足，应柔和地向前顶杆增大俯角、加大下降速度；向后带杆会使机头上仰，压杆向左只会改变坡度，均不能改善下降。"},{"id":147,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机地面滑行时，下列描述正确的是（）。","A":"主要通过控制方向舵杆量操纵","B":"主要通过控制副翼杆量操纵","C":"主要通过控制升降舵杆量操纵","D":"以上均不正确","answer":"A","exp":"无人机地面滑行时速度低，副翼、升降舵几乎没有气动效果，方向主要靠前轮（或尾轮）转向控制，因此应主要通过方向舵杆量操纵滑行方向，同时用油门控制滑行速度。"},{"id":148,"type":"single","cat":"设备与维护","stem":"下列关于使用遥控器注意事项错误的是（）。","A":"电源检査及充电","B":"做好日常保养","C":"拉距离试验","D":"有桨开机试验","answer":"D","exp":"使用遥控器应做好电源检查及充电、日常保养和拉距离试验，这些是正常维护项目；有桨开机试验危险，开机试转必须在卸桨状态下进行，防止电机意外启动高速桨叶伤人，不属于正确的使用注意事项。"},{"id":149,"type":"single","cat":"操纵与飞行技术","stem":"垂直起降固定翼无人机外翼段主要为无人机提供（），外翼段上装有副翼，控制无人机的滚转运动。","A":"起降动力","B":"升力","C":"重力","D":"推力","answer":"B","exp":"垂直起降固定翼巡航时由外翼段（常规机翼部分）产生主要升力，外翼段上的副翼差动偏转改变两翼升力差实现滚转控制；起降动力由旋翼提供，推力来自发动机，与外翼段功能无关。"},{"id":150,"type":"single","cat":"设备与维护","stem":"电池、电子调速器（电调）和电机三者之前的关系（）。","A":"电池输出电流≥电子调速器（电调）最大电流≥电动机最高承载电流","B":"电池输出电流≥电子调速器（电调）最高大电流≤电动机最高随载电流","C":"电池输出电流≤电子调速器（电调）最大电流≤电动机最高承载电流","D":"电池输出电流≤电子调速器（电调）最大电流≥电动机最高承载电流","answer":"A","exp":"动力系统电流匹配要求：电池最大输出电流≥电调最大电流≥电机最高承载电流，逐级保证供电能力，避免大油门时电调或电机过载烧毁；若电池输出小于电调需求，长时间满负荷会掉电甚至炸机。"},{"id":151,"type":"single","cat":"操纵与飞行技术","stem":"固定翼90度转弯风力对飞机影响（）。","A":"顺风大","B":"逆风大","C":"一样","D":"以上均不正确","answer":"C","exp":"飞机在空气中飞行，风不改变相对空速和操纵特性；90度转弯过程中顺、逆风分量各占一半航程，完成往返闭合航线时地速变化相互抵消，风力对飞机的总影响一样，不存在顺风或逆风更大的差别。"},{"id":152,"type":"single","cat":"设备与维护","stem":"巡航阶段地面站上显示的重要飞行信息不包括（）。","A":"电池电压","B":"飞行速度","C":"飞行控制系统状态","D":"位置","answer":"C","exp":"巡航阶段地面站重点显示电池电压、飞行速度、位置等动态飞行参数，用于监控飞行状态；飞行控制系统状态属于设备自检与内部状态信息，不属于巡航监控的重要飞行信息范畴。"},{"id":153,"type":"single","cat":"电力巡检","stem":"设备运维单位提前建立各型无人机巡检系统正常以及备选起飞和降落区档案，由（）在地图上进行标注，并及时更新。","A":"工作负责人","B":"工作许可人","C":"程控手","D":"操控手","answer":"B","exp":"按电力巡检作业组织规定，各型无人机巡检系统的正常及备选起降区档案由工作许可人在地图上标注并及时更新；工作负责人组织现场作业，程控手、操控手执行飞行操作，均不承担该档案标注职责。"},{"id":154,"type":"single","cat":"基础概念","stem":"机场上空高度较低的云会直接影响飞机的起降其中，危害最大的云是（）。","A":"对流云","B":"卷状云","C":"层状云","D":"层积云","answer":"A","exp":"机场上空低云中对流云危害最大，尤其积雨云内部升降气流强烈，伴随颠簸、雷电、下击暴流和低能见度，严重威胁起降安全；层状云、层积云主要影响云底高和能见度，危害相对较小。"},{"id":155,"type":"single","cat":"操纵与飞行技术","stem":"用下滑有利速度下滑，飞机的（）。","A":"升阻比最大","B":"升力最大","C":"下滑角最大","D":"以上均不正确","answer":"A","exp":"下滑有利速度对应最大升阻比，此时升力与阻力的比值最优，下滑角最小、下滑距离最远，是安全下滑的首选速度；速度偏大偏小都会使升阻比下降，升力最大不代表下滑性能最好。"},{"id":156,"type":"single","cat":"设备与维护","stem":"一般民用无人机所使用遥控器的频率是（）。","A":"2.4ZHZ","B":"2.4GHZ","C":"2.4WHZ","D":"以上均不正确","answer":"B","exp":"民用无人机遥控器普遍使用2.4GHz频段，波长短、天线小巧、带宽大且抗干扰能力较好；2.4ZHZ、2.4WHZ是单位写法错误，频率单位只有GHz（吉赫兹）。"},{"id":157,"type":"single","cat":"领航与任务规划","stem":"（）与任务规划是无人机地面站的主要功能。","A":"指挥控制","B":"导航","C":"飞行视角显示","D":"以上均不正确","answer":"A","exp":"无人机地面站的主要功能是指挥控制与任务规划：指挥控制负责飞行监控与指令下达，任务规划完成航线设计与任务装订；导航由机载设备完成，视角显示只是辅助界面功能。"},{"id":158,"type":"single","cat":"基础概念","stem":"活塞式发动机是将燃料在发动机气缸内部燃烧，将燃烧的化学能转变（）。","A":"动能","B":"热能","C":"机械能","D":"势能","answer":"B","exp":"活塞式发动机在气缸内部燃烧燃料，首先把燃料的化学能转变为燃气的热能，随后经活塞、曲柄连杆机构再把热能转化为机械能输出；化学能不是直接变成机械能或动能。"},{"id":159,"type":"single","cat":"基础概念","stem":"据统计，无人机系统事故60%以上发生在（）。","A":"滑跑阶段","B":"起降阶段","C":"巡航阶段","D":"以上均不正确","answer":"B","exp":"统计表明无人机系统60%以上的事故发生在起降阶段：起飞着陆时速度低、高度低，留给故障处置的时间最短、余地最小，任何动力或操纵异常都难以及时挽回，风险远高于平稳的巡航阶段。"},{"id":160,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操纵无人转弯时，下列描述正确的操纵方式是（）。","A":"机头过低时，应向转弯一侧的斜后方适当拉杆并稍回舵","B":"机头过低时，应向转弯一侧的斜前方适当推杆并稍扭舵","C":"机头过低时，应向转弯一侧的斜前方适当拉杆并稍扭舵","D":"以上均不正确","answer":"A","exp":"转弯中机头过低说明俯角过大、速度在增大，应向转弯一侧的斜后方适当带杆减小俯角，并稍回舵防止坡度继续加大；向斜前方推杆会加剧俯冲使速度更大，不符合改出要领。"},{"id":161,"type":"single","cat":"基础概念","stem":"以下哪种闪灯情况，可判定为指南针异常（）。","A":"飞行器LED紫黄灯交替快闪","B":"飞行器LED黄红灯交替慢闪","C":"飞行器LED黄灯快闪","D":"飞行器LED红灯常亮","answer":"B","exp":"按DJI飞行器灯语定义，LED黄红灯交替慢闪表示指南针异常或受磁场干扰，须重新校准指南针后方可起飞；黄灯快闪通常表示GPS信号不足进入姿态模式，红灯常亮为严重故障告警，含义各不相同。"},{"id":162,"type":"single","cat":"基础概念","stem":"在温暖的天气飞行中，在较低高度有时会遇上湍流空气，以下描述正确的是（）。","A":"很可能在路面和荒地上空发生上升气流","B":"在类似成片树林的广阔植被区域发生上升气流","C":"在大片水体区域发生上升气流","D":"在路面和荒地遇到下沉气流","answer":"A","exp":"温暖天气里深色路面、荒地吸热快，近地面空气被加热后上升，形成热气流湍流，在这些区域上空最可能遇到上升气流；大片水体和成片植被升温慢，空气下沉，更可能出现平稳或下沉气流。"},{"id":163,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机转弯时产生偏差的主要原因不包括（）。","A":"进入和退出转弯时，动作不协调，产生侧滑","B":"天气状况不佳","C":"转弯中，未保持好机头与天地线的关系位置，以致速度增大或减小","D":"以上均不正确","answer":"B","exp":"转弯偏差主要源于操纵本身：进入退出转弯动作不协调产生侧滑，转弯中未保持机头与天地线的关系位置导致速度增减；天气状况不佳是外部环境因素，不属于转弯操纵偏差的原因。"},{"id":164,"type":"single","cat":"设备与维护","stem":"关于无刷电机下列说法正确的是（）。","A":"定子是线圈，转子是磁极","B":"用直流电直接可以驱动","C":"有碳刷","D":"寿命较短","answer":"A","exp":"无刷电机定子绕线圈、转子为磁极，靠电调电子换相驱动，直流电不能直接驱动它；无碳刷结构消除了电刷磨损，效率高寿命长，有碳刷、寿命较短的说法与无刷电机特点正好相反。"},{"id":165,"type":"single","cat":"领航与任务规划","stem":"（）主要指执行任务过程中实现动作的时间点、方式和方法，设定航点的时间节点，飞行高度、航速、飞行姿态以及配合载荷设备的工作状态和模式，当无人机到达该航点时实施航拍、盘旋等飞行任务。","A":"任务分配","B":"载荷规划","C":"目标分配","D":"以上均不正确","answer":"C","exp":"目标分配规定执行任务过程中动作实现的时间点、方式和方法，包括设定航点的时间节点、飞行高度、航速、飞行姿态以及载荷设备工作状态的配合，到达航点即实施航拍、盘旋等任务；任务分配侧重任务整体下达，载荷规划只针对载荷参数设置。"},{"id":166,"type":"single","cat":"基础概念","stem":"六旋翼无人机，其六个螺旋桨旋转方向分别为（）。","A":"全部顺时针或逆时针","B":"三个顺时针三个逆时针","C":"两个顺时针两个逆时针，另外两个方向无所谓","D":"螺旋桨旋转方向可随意设置","answer":"B","exp":"六旋翼无人机采用三桨顺时针、三桨逆时针相间布置，反扭矩相互抵消才能实现平衡悬停；通过独立调节各桨转速即可控制姿态与航向。全部同向旋转时机身会被反扭矩带动持续偏转，无法稳定飞行。"},{"id":167,"type":"single","cat":"设备与维护","stem":"（）主要是制定无人机飞行任务、完成无人机载荷数据的处理和应用，指挥中心/数据处理中心一般都是通过无人机控制站等间接地实现对无人机的控制和数据接收。","A":"无人机控制站","B":"指挥处理中心","C":"载荷控制站","D":"以上均不正确","answer":"B","exp":"指挥处理中心负责制定无人机飞行任务、完成载荷数据的处理和应用，一般通过无人机控制站等间接实现对无人机的控制和数据接收；控制站执行直接飞行操控，载荷控制站只管任务设备。"},{"id":168,"type":"single","cat":"基础概念","stem":"以下不属于航空器的是（）。","A":"直升机","B":"飞艇","C":"卫星","D":"以上均不正确","answer":"C","exp":"航空器指在大气层内依靠空气反作用力飞行的机器，直升机靠旋翼、飞艇靠空气浮力，都属于航空器；卫星在稠密大气层之外的太空靠天体引力运行，属于航天器，不是航空器。"},{"id":169,"type":"single","cat":"电力巡检","stem":"用计算机生成或打印的工作票应使用统一的票面格式由（）审核无误，手工或电子签名后方可执行。","A":"工作票签发人","B":"工作许可人","C":"工作负责人","D":"专责监护人","answer":"A","exp":"用计算机生成或打印的工作票必须使用统一的票面格式，经工作票签发人审核无误、手工或电子签名后方可执行；工作许可人、工作负责人和专责监护人都在执行环节履职，无签发审核权限。"},{"id":170,"type":"single","cat":"设备与维护","stem":"无人机航时长短除了与电池性能有关以外，还有一些外在的因素也会对无人机的续航能力有影响，比如天气原因、飞行的方式、（）。","A":"信号距离","B":"飞机的重量","C":"飞行模式","D":"驾驶员操作技术","answer":"B","exp":"无人机航时长短除电池性能外，还受天气、飞行方式和飞机重量等外在因素影响：起飞重量越大，维持升力所需的电机功率和电流越大，耗电越快，续航相应缩短；信号距离、飞行模式、操作技术只是间接因素。"},{"id":171,"type":"single","cat":"设备与维护","stem":"djipc地面站实时建图最大的优点是什么（）。","A":"可以实时建图","B":"能编辑航线","C":"能添加航点","D":"能控制云台","answer":"A","exp":"DJI PC地面站实时建图的最大优点是边飞行边生成测区正射影像图，飞行中即可掌握覆盖范围与影像质量，发现漏拍及时补飞，大幅提高外业效率；编辑航线、添加航点、控制云台是各类地面站的常规功能。"},{"id":172,"type":"single","cat":"航空气象","stem":"气压传感器测的是以下哪个高度？（）","A":"相对高度","B":"海拔高度","C":"无线电高度","D":"以上均不正确","answer":"B","exp":"气压传感器利用气压随高度升高而降低的规律，以海平面气压为基准换算出气压高度，反映的是近似海拔高度；相对高度是人机之间的垂直距离，无线电高度靠电波测距获得，都不是气压传感器直接测量的对象。"},{"id":173,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的标称电压是（）。","A":"1.2V","B":"4.2V","C":"3.7V","D":"以上均不正确","answer":"C","exp":"锂聚合物电池单体的标称电压为3.7V，满充电压为4.2V；1.2V是镍镉、镍氢电池的标称电压，两者不能混淆。使用时应按单体3.7V计算总电压，充电终止以4.2V为限。"},{"id":174,"type":"single","cat":"基础概念","stem":"旋翼机可以用（）的飞行代替滑行。","A":"1米至5米高度","B":"1米至10米高度","C":"1米至15米高度","D":"以上均不正确","answer":"B","exp":"旋翼机具备垂直起降和低速悬停能力，可以用高度1米至10米的低空飞行代替地面滑行，既能越过地面障碍又能缩短地面滑行时间；超过该高度的飞行不属于代替滑行的范畴。"},{"id":175,"type":"single","cat":"航空气象","stem":"影响飞行的三大气象要素为（）。","A":"气温、气压和空气湿度","B":"气温、风和云","C":"风、云和降水","D":"气温、风向、降水","answer":"A","exp":"影响飞行安全的三大基本气象要素是气温、气压和空气湿度：三者共同决定空气密度，直接影响旋翼或机翼产生的升力、拉力及发动机功率；风、云和降水属于天气现象，不是决定空气性质的基本要素。"},{"id":176,"type":"single","cat":"设备与维护","stem":"飞行控制系统（自驾仪）安装水平面应与（）。","A":"机翼平面平行","B":"水平尾翼平面平行","C":"机身水平面平行","D":"随意安装","answer":"C","exp":"自驾仪依靠内部传感器感知机体姿态，安装水平面必须与机身水平基准面平行，否则姿态解算存在固定偏差，飞行中会出现持续的姿态漂移和配平误差；机翼有安装角，不能作为安装基准。"},{"id":177,"type":"single","cat":"设备与维护","stem":"线圈匝数越多的电机，kv值（）。","A":"越高","B":"无关","C":"越低","D":"以上均不正确","answer":"C","exp":"电机线圈匝数越多，绕线电感越大，同样电压下转速越低，Kv值（每伏特电压对应的空载转速）就越低；低Kv电机配大桨可获得大扭矩，高Kv电机匝数少转速高，两者相反。"},{"id":178,"type":"single","cat":"设备与维护","stem":"安装无人机的惯性测量单元（IMU）时要求靠近飞行器的（），并有一定的减震和指向要求。","A":"中心","B":"压力中心","C":"焦点","D":"重心","answer":"D","exp":"IMU通过测量机体角速度和加速度解算姿态，安装时应靠近飞行器的重心并按规定的指向固定，同时采取减振措施，以减小机体旋转和振动引起的测量误差；压力中心、焦点是气动概念，与传感器安装无关。"},{"id":179,"type":"single","cat":"操纵与飞行技术","stem":"相当于无人驾驶航空器大脑的是（）。","A":"定位系统","B":"飞控系统","C":"电力系统","D":"动力系统","answer":"B","exp":"飞控系统实时解算机体姿态并通过闭环控制调整电机转速和舵面，相当于无人机的大脑；定位系统只提供位置信息，动力系统输出拉力，电力系统提供能源，都不具备感知与决策控制功能。"},{"id":180,"type":"single","cat":"设备与维护","stem":"聚合物锂电池单体充满电后的电压一般为（）。","A":"3.7V","B":"4.2V","C":"3.3V","D":"以上均不正确","answer":"B","exp":"聚合物锂电池单体充满电后电压一般为4.2V，标称电压3.7V；充电超过4.2V会损伤电池、缩短寿命甚至引发鼓包起火，使用中应以4.2V为满充上限并避免过放。"},{"id":181,"type":"single","cat":"基础概念","stem":"（）与无人机控制站的功能类似，但只能控制无人机的机载任务设备，不能进行无人机的飞行控制。","A":"指挥处理中心","B":"无人机控制站","C":"载荷控制站","D":"飞控子系统","answer":"C","exp":"载荷控制站的功能与无人机控制站类似，但它只能控制云台相机等机载任务设备并接收任务数据，无权进行飞行控制；飞行控制权始终由无人机控制站掌握，两者分工明确。"},{"id":182,"type":"single","cat":"设备与维护","stem":"维护保养人员应按要求（）按时开展日常维护、零件维修更换、大修保养和试验等工作。","A":"使用经验","B":"使用说明书","C":"飞行手册","D":"维护保养手册","answer":"D","exp":"维护保养人员应按要求按维护保养手册规定的周期和项目，开展日常维护、零件维修更换、大修保养和试验等工作；依靠个人使用经验或随意参照飞行手册保养，容易漏项错项，不符合规范要求。"},{"id":183,"type":"single","cat":"电力巡检","stem":"设备运维单位应建立（），包括：线路走向和走势、交叉跨越情况、杆塔坐标、周边地形地貌等，并核实无误。","A":"线路资料信息","B":"设备信息","C":"起飞区档案","D":"降落区档案","answer":"A","exp":"电力巡检应建立线路资料信息，内容包括线路走向和走势、交叉跨越情况、杆塔坐标、周边地形地貌等，并逐一核实无误，作为航线规划、巡视安排和安全评估的基础；起降区档案、设备信息仅是其中局部内容。"},{"id":184,"type":"single","cat":"基础概念","stem":"多旋翼无人机飞行后的检查，下列选项错误的是（）。","A":"检查电子罗盘、IMU等的指向是否和多旋翼无人机机头指向一致","B":"飞行结束后按清单清点设备、材料和工具","C":"飞行结束后及时检查无人机完好情况，发现有缺陷的要及时更换修复","D":"飞行结束后，及时检查飞行附属设备，如云台、工具、材料、电脑等使用状况","answer":"A","exp":"电子罗盘、IMU与机头指向一致性的校核属于飞行前的安装检查项目，不属于飞行后检查内容；飞行后应按清单清点设备材料工具，及时检查机体完好情况并更换修复缺陷件，同时检查云台、工具、电脑等附属设备使用状况。"},{"id":185,"type":"single","cat":"基础概念","stem":"多旋翼飞行器通常装有（）具以上旋翼。","A":"四","B":"三","C":"二","D":"一","answer":"B","exp":"多旋翼飞行器通常指装有三具及以上旋翼的飞行器，常见为四、六、八旋翼，依靠多副旋翼正反旋转平衡反扭矩，实现悬停与姿态控制；两具以下难以平衡反扭矩，不属于多旋翼范畴。"},{"id":186,"type":"single","cat":"基础概念","stem":"（）航空器平台结构通常包括机翼、机身、尾翼和起落架等。","A":"单旋翼","B":"多旋翼","C":"固定翼","D":"以上均不正确","answer":"C","exp":"固定翼航空器平台结构通常包括机翼、机身、尾翼和起落架等，靠机翼产生升力、尾翼保证稳定与配平；单旋翼和多旋翼平台以旋翼系统为核心结构，不属于这一布局形式。"},{"id":187,"type":"single","cat":"基础概念","stem":"下列说法错误的是（没有提到的条件则为相同）（）。","A":"旋翼直径越大则拉力越大","B":"旋翼直径越大则悬停诱导速度越大","C":"旋翼直接越大则桨盘载荷越小标准","D":"以上均不正确","answer":"B","exp":"旋翼直径越大，桨盘面积越大，桨盘载荷越小，悬停时的诱导速度反而越小、效率越高；该说法错误在于把直径与诱导速度的关系说反。直径越大拉力越大、桨盘载荷越小这两条均成立。"},{"id":188,"type":"single","cat":"操纵与飞行技术","stem":"无人机系统中，起降驾驶员一般不参与哪个阶段控制（）。","A":"降落阶段","B":"巡航阶段","C":"起飞阶段","D":"以上均不正确","answer":"B","exp":"起降驾驶员专责无人机的起飞和降落等关键阶段操控，这些阶段风险最高需要人工精细操纵；巡航阶段飞行状态平稳，通常由自动驾驶或地面站监控完成，起降驾驶员一般不参与该阶段的直接控制。"},{"id":189,"type":"single","cat":"飞行原理","stem":"利用增大机翼弯度来提高机翼的升力系数，会导致（）。","A":"机翼上表面最低压力点前移，减小临界迎角","B":"机翼上表面最低压力点后移，减小临界迎角","C":"机翼上表面最低压力点前移，加大临界迎角","D":"以上均不正确","answer":"A","exp":"增大机翼弯度后，上表面气流加速更强、低压区更显著，最低压力点前移；同时气流在大迎角下更早分离，临界迎角减小，虽然升力系数提高，但失速裕度变小，这是高升力翼型付出的代价。"},{"id":190,"type":"single","cat":"基础概念","stem":"下列哪一项是飞行重规划要考虑的内容（）。","A":"已知威胁区域","B":"未知威胁区域","C":"无人机自身约束条件","D":"以上均不正确","answer":"B","exp":"飞行重规划针对飞行过程中出现的新情况，主要考虑未知威胁区域，如临时禁飞、突发恶劣天气或新的障碍；已知威胁区域和无人机自身约束条件在起飞前的预规划中已经处理完毕。"},{"id":191,"type":"single","cat":"操纵与飞行技术","stem":"多轴左右平移时，飞机姿态是绕哪根轴发生变化？（）","A":"纵轴","B":"横轴","C":"立轴","D":"以上均不正确","answer":"A","exp":"多轴左右平移靠机身向侧方横滚倾斜产生水平分力，是绕纵轴的滚转运动；绕横轴的俯仰变化对应前后平移，绕立轴的偏航变化对应转向，三条轴线控制的运动方向各不相同。"},{"id":192,"type":"single","cat":"基础概念","stem":"在中华人民共和国境内飞行的航空器必须遵守统一的飞行规则，该飞行规则应当由（）制定。","A":"中国民用航空局和中共中央军事委员会","B":"中共中央军事委员会 \"","C":"中华人民共和国国务院和中共中央军事委员会\"","D":"中华人民共和国民用航空局","answer":"C","exp":"《中华人民共和国飞行基本规则》规定，境内飞行必须遵守统一的飞行规则，该规则由国务院和中央军事委员会制定发布；民航局只承担行业管理职能，无权单独制定全国统一的飞行基本规则。"},{"id":193,"type":"single","cat":"操纵与飞行技术","stem":"视距内飞行定义中的高度，一般是指人、机相对高度不超过起飞点（）米。","A":"100米","B":"120米","C":"500米","D":"1000米","answer":"B","exp":"视距内飞行指驾驶员或观察员目视无人机进行的飞行，一般要求以起飞点为基准的相对高度不超过120米，且保持在视距范围内；500米、1000米高度已超出视距内运行的界定。"},{"id":194,"type":"single","cat":"设备与维护","stem":"关于部分多轴飞行器，机臂上反角设计描述正确的是（）。","A":"提高稳定性","B":"提高机动性","C":"减少电力损耗","D":"以上均不正确","answer":"A","exp":"多轴机臂设计上反角后，机体重心位置相对桨盘平面更低，形成摆锤效应，机体受扰倾斜时重心产生回正力矩，显著提高悬停稳定性；提高机动性和减少电力损耗都不是上反角的设计目的。"},{"id":195,"type":"single","cat":"领航与任务规划","stem":"姿态遥控模式下操纵无人机爬升，飞机航向向左偏离时，下列正确的操纵是（）。","A":"应柔和地向右扭舵","B":"应柔和地向左扭舵","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"A","exp":"姿态遥控模式爬升中航向向左偏离，说明机头偏左，应柔和地向右扭舵，用方向舵产生的偏航力矩把机头修正回原航向；向前顶杆只改变俯仰姿态，向左扭舵会加大偏差。"},{"id":196,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检系统配置导则》中：小型无人直升机巡检和固定翼无人机巡检工作班成员至少应包括（）。","A":"指挥手","B":"操控手","C":"程控手","D":"任务手","answer":"BC","exp":"《架空输电线路无人机巡检系统配置导则》规定，小型无人直升机和固定翼无人机巡检的工作班成员至少应包括操控手和程控手：操控手负责遥控操纵飞行，程控手负责地面站航线程序控制与监控；指挥手、任务手不属于导则规定的最低必配岗位，可按需要增设。"},{"id":197,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中：以下对中型无人机的巡线效果说法正确的是（）。","A":"飞行准备时间长。","B":"可定点悬停","C":"机动灵活率高","D":"发现隐蔽缺陷能力强","answer":"BCD","exp":"中型无人机巡线兼具旋翼与固定翼的优点：可定点悬停对杆塔部位细查，机动灵活率高；载荷较大、传感器先进，发现隐蔽缺陷能力强，这三项说法正确；其飞行准备时间相对较短，飞行准备时间长的说法错误。"},{"id":198,"type":"multi","cat":"基础概念","stem":"在《输变电工程无人机航空摄影测量技术应用导则》中，输变电工程中应积极稳妥地采用无人机航空摄影测量技术，辅助优化输变电工程的（）和（）。","A":"可行性研究报告","B":"施工方案","C":"初步设计","D":"施工图设计","answer":"CD","exp":"《输变电工程无人机航空摄影测量技术应用导则》要求积极稳妥采用无人机航测技术，辅助优化输变电工程的初步设计和施工图设计：航测提供的精确地形数据可优化线路路径、塔位布置与设计图纸；可行性研究报告和施工方案不属于导则指明的辅助优化对象。"},{"id":199,"type":"multi","cat":"基础概念","stem":"一般白平衡的模式包括（）。","A":"自动模式","B":"RAW模式","C":"阴天模式","D":"自定义模式","answer":"ACD","exp":"白平衡用于校正不同光源下的色彩还原，常见模式包括自动模式、阴天模式等预设场景模式和自定义模式，按拍摄环境光线选择；RAW是相机图像的存储格式，决定数据记录方式，与白平衡分属不同设置类别，不属于白平衡模式。"},{"id":200,"type":"multi","cat":"设备与维护","stem":"动力系统维护，做法正确的是（）。","A":"定时用手旋转电机，看是否顺畅","B":"桨叶有缺口继续使用","C":"作业期间定期清理电机农药残留","D":"桨叶上下表面应定时清理农药残留","answer":"ACD","exp":"动力系统维护的正确做法：定时用手旋转电机检查转动是否顺畅、有无卡滞异响，作业期间定期清理电机内外的农药残留，桨叶上下表面也要定时清理防止积垢影响平衡；桨叶有缺口时强度受损，必须立即更换，继续使用极易空中断裂造成事故。"},{"id":201,"type":"multi","cat":"基础概念","stem":"无人机平台外观质量需满足以下技术要求（）。","A":"外观结构。整机外观美观整洁、结构坚固、无裸露导线。","B":"外壳材料。外壳为绝缘复合材料，外壳包覆完全。","C":"连接紧固性。部件间连接紧固，紧固件、连接件有防松措施。","D":"设备表面。","answer":"ABCD","exp":"无人机平台外观质量的四项技术要求均须满足：整机外观美观整洁、结构坚固、无裸露导线；外壳采用绝缘复合材料并包覆完全；部件间连接紧固，紧固件、连接件有防松措施；设备表面完好无损伤。任何一项不达标都可能埋下飞行安全隐患。"},{"id":202,"type":"multi","cat":"电力巡检","stem":"操控手是利用遥控器以（）或（）模式控制无人机巡检系统飞行的工作人员。","A":"手动","B":"增稳","C":"全自主","D":"半自主","answer":"AB","exp":"操控手是利用遥控器控制无人机巡检飞行的人员，只能在手动或增稳两种模式下操控：手动模式完全由人的操纵决定姿态，增稳模式下飞控自动稳定姿态、人负责修正，两者都以遥控器为控制手段；全自主、半自主飞行由地面站程序控制，不属于操控手的遥控模式。"},{"id":203,"type":"single","cat":"法规与空域","stem":"根据中国民航局分类标准，重量为2.5kg的无人机属于（）。","A":"微型无人机","B":"轻型无人机","C":"小型无人机","D":"大型无人机","answer":"B","exp":"注：微型≤0.25kg，轻型0.254kg，小型420kg，大型＞20kg"},{"id":204,"type":"single","cat":"基础概念","stem":"无人机视距内飞行的最大高度限制（真高）为（）。","A":"50米","B":"120米","C":"300米","D":"500米","answer":"B","exp":"依据《无人驾驶航空器飞行管理暂行条例》，视距内真高不超过120米"},{"id":205,"type":"single","cat":"飞行原理","stem":"多旋翼无人机悬停时，升力主要由（）提供。","A":"机翼","B":"螺旋桨旋转产生的反作用力","C":"尾翼","D":"空气浮力","answer":"B","exp":"多旋翼依靠螺旋桨旋转产生升力"},{"id":206,"type":"single","cat":"设备与维护","stem":"无人机遥控器常用的2.4GHz频段属于（）。","A":"长波","B":"中波","C":"短波","D":"微波","answer":"D","exp":"2.4GHz为微波频段，用于短距离无线通信"},{"id":207,"type":"single","cat":"领航与任务规划","stem":"GPS模式下，无人机的定位精度通常为（）。","A":"0.10.5米","B":"15米","C":"1020米","D":"50100米","answer":"B","exp":"民用GPS定位精度一般为25米，RTK差分可提升至厘米级"},{"id":208,"type":"single","cat":"设备与维护","stem":"锂聚合物电池（LiPo）的标称电压为（）。","A":"3.7V/节","B":"1.2V/节","C":"1.5V/节","D":"4.2V/节","answer":"A","exp":"LiPo单节标称电压3.7V，满电4.2V"},{"id":209,"type":"single","cat":"基础概念","stem":"无人机避障系统中，激光雷达（LiDAR）的主要优势是（）。","A":"成本低","B":"抗干扰性强","C":"探测精度高","D":"适应雨雾环境","answer":"C","exp":"激光雷达通过激光测距，精度可达厘米级"},{"id":210,"type":"single","cat":"操纵与飞行技术","stem":"当飞行环境风速超过（）时，多旋翼无人机需谨慎起飞。","A":"3m/s","B":"6m/s","C":"10m/s","D":"15m/s","answer":"B","exp":"多旋翼抗风能力一般为56级风，即813.8m/s，但6m/s为安全临界值"},{"id":211,"type":"single","cat":"法规与空域","stem":"我国管制空域分为（）类。","A":"3","B":"5","C":"7","D":"9","answer":"C","exp":"A、B、C、D、E、F、G七类，其中G类为非管制空域"},{"id":212,"type":"single","cat":"操纵与飞行技术","stem":"起飞前检查中，无需确认的项目是（）。","A":"电池电量","B":"飞控校准状态","C":"周边电磁环境","D":"无人机颜色","answer":"D","exp":"颜色不影响飞行安全"},{"id":213,"type":"single","cat":"领航与任务规划","stem":"无人机飞行日志中，GPS卫星数显示为4颗时，通常（）。","A":"可正常定位","B":"仅能2D定位","C":"无法定位","D":"进入姿态模式","answer":"B","exp":"3颗卫星2D定位，4颗及以上3D定位"},{"id":214,"type":"single","cat":"基础概念","stem":"农业植保无人机的喷头流量调节主要影响（）。","A":"飞行速度","B":"药液覆盖密度","C":"电池续航","D":"避障精度","answer":"B","exp":"流量越大，单位面积药液量越多"},{"id":215,"type":"single","cat":"基础概念","stem":"无人机在海拔1000米以上高原飞行时，需调整的参数是（）。","A":"最大速度","B":"起飞重量","C":"气压计校准","D":"图传频率","answer":"C","exp":"高原气压低，需重新校准气压计以确保高度计准确"},{"id":216,"type":"single","cat":"基础概念","stem":"反制无人机的电子围栏技术主要通过（）实现。","A":"物理拦截","B":"信号干扰","C":"激光摧毁","D":"网捕","answer":"B","exp":"电子围栏通过发射同频干扰信号限制无人机进入"},{"id":217,"type":"single","cat":"基础概念","stem":"无人机飞行中出现磁罗盘干扰警告时，正确操作是（）。","A":"继续飞行并记录数据","B":"立即降落并重新校准","C":"加速飞离当前区域","D":"切换至手动模式","answer":"B","exp":"磁罗盘干扰会导致航向错误，需降落校准"},{"id":218,"type":"single","cat":"基础概念","stem":"多旋翼无人机的轴距指（）。","A":"螺旋桨直径","B":"电机中心到中心的对角线距离","C":"机身长度","D":"桨叶尖端间距","answer":"B","exp":"轴距是多旋翼电机安装位置的对角线距离"},{"id":219,"type":"single","cat":"设备与维护","stem":"无人机图传系统的延迟应控制在（）以内以保证操作安全。","A":"50ms","B":"200ms","C":"500ms","D":"1000ms","answer":"B","exp":"延迟超过200ms可能导致操作滞后，影响避障"},{"id":220,"type":"single","cat":"航空气象","stem":"以下气象条件中，最适合无人机飞行的是（）。","A":"小雨，能见度5km","B":"晴，风速4m/s，湿度60%","C":"雾，能见度1km","D":"雷暴，风速12m/s","answer":"B","exp":"晴、低风速、适宜湿度为理想条件"},{"id":221,"type":"single","cat":"领航与任务规划","stem":"无人机失控返航功能的触发条件不包括（）。","A":"遥控器信号丢失","B":"电池电量低于阈值","C":"GPS信号丢失","D":"飞手主动触发","answer":"C","exp":"GPS丢失时可能切换至姿态模式，不一定触发返航"},{"id":222,"type":"single","cat":"基础概念","stem":"物流无人机的最大载重通常指（）。","A":"电池重量","B":"机身重量+载重","C":"除去机身重量的有效载重","D":"起飞总重量","answer":"C","exp":"最大载重为有效载荷，不包括机身和电池"},{"id":223,"type":"single","cat":"设备与维护","stem":"无人机桨叶动平衡不良会导致（）。","A":"续航增加","B":"电机发热异常","C":"图传信号增强","D":"飞控校准成功","answer":"B","exp":"动平衡差会导致电机负载不均，发热加剧"},{"id":224,"type":"single","cat":"法规与空域","stem":"以下属于特殊空域的是（）。","A":"居民区上空","B":"机场净空区","C":"农田上方","D":"公园广场","answer":"B","exp":"机场净空区、军事管理区等为特殊空域，需专项申请"},{"id":225,"type":"single","cat":"基础概念","stem":"无人机飞行高度的参考基准通常是（）。","A":"平均海平面","B":"起飞点地面","C":"最近建筑物顶部","D":"当地海拔","answer":"B","exp":"无人机高度一般指相对于起飞点的相对高度，或真高"},{"id":226,"type":"single","cat":"基础概念","stem":"农业植保无人机的喷幅指（）。","A":"单次飞行覆盖的宽度","B":"喷头数量","C":"药液容量","D":"飞行速度","answer":"A","exp":"喷幅是药液喷洒的横向覆盖宽度"},{"id":227,"type":"single","cat":"设备与维护","stem":"无人机电池循环寿命指（）。","A":"充满电的次数","B":"放电至0%的次数","C":"充放电至80%容量的次数","D":"存放时间","answer":"C","exp":"循环寿命一般定义为容量降至初始80%时的充放电次数"},{"id":228,"type":"single","cat":"操纵与飞行技术","stem":"无人机手动模式下，飞手需完全控制（）。","A":"油门、俯仰、横滚、航向","B":"仅油门","C":"自动返航","D":"避障","answer":"A","exp":"手动模式无飞控辅助，需手动控制所有动作"},{"id":229,"type":"single","cat":"基础概念","stem":"以下不属于黑飞行为的是（）。","A":"在机场5km内飞行","B":"未申请空域飞行","C":"按计划在非管制空域飞行","D":"超过高度限制飞行","answer":"C","exp":"合法申请并在批准范围内飞行不属于黑飞"},{"id":230,"type":"single","cat":"基础概念","stem":"无人机视觉定位系统在（）环境下失效。","A":"室内无GPS","B":"纯色地面（如雪地）","C":"光照充足","D":"纹理丰富地面","answer":"B","exp":"视觉定位依赖地面纹理，纯色地面无法识别"},{"id":231,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停功耗主要受（）影响最大。","A":"螺旋桨直径","B":"电池容量","C":"飞控型号","D":"环境温度","answer":"A","exp":"桨径越大，产生相同升力所需转速越低，功耗越小"},{"id":232,"type":"single","cat":"设备与维护","stem":"无人机抗风等级标注为6级，对应的风速范围是（）。","A":"3.4~5.4m/s","B":"5.5~7.9m/s","C":"8.0~10.7m/s","D":"10.8~13.8m/s","answer":"C","exp":"6级风为8.0~10.7m/s，对应强风"},{"id":233,"type":"multi","cat":"操纵与飞行技术","stem":"无人机起飞前需检查的项目包括（）。","A":"电池电量是否达标","B":"螺旋桨安装是否牢固","C":"飞控IMU校准状态","D":"周边是否有电磁干扰源","answer":"ABCD","exp":"所有选项均为安全飞行必要检查"},{"id":234,"type":"multi","cat":"法规与空域","stem":"以下属于无人机禁飞区的有（）。","A":"军事管理区上空","B":"核电站周边5km","C":"大型运动会场馆","D":"普通居民小区","answer":"ABC","exp":"居民区非禁飞区，但需遵守高度限制"},{"id":235,"type":"multi","cat":"基础概念","stem":"多旋翼无人机的系统组成包括（）。","A":"飞控系统","B":"动力系统","C":"图传系统","D":"导航系统","answer":"ABCD","exp":"多旋翼由飞控、动力、图传、导航等子系统组成"},{"id":236,"type":"multi","cat":"基础概念","stem":"影响无人机续航时间的因素有（）。","A":"飞行速度","B":"环境温度","C":"载重重量","D":"电池老化程度","answer":"ABCD","exp":"速度越快、温度越低、载重越大、电池老化，续航越短"},{"id":237,"type":"multi","cat":"设备与维护","stem":"无人机飞行中出现电机异常发热可能的原因是（）。","A":"桨叶动平衡差","B":"电机进水","C":"飞控参数错误","D":"电池电压过高","answer":"ABC","exp":"电池电压过高会导致过流，但正常电压下发热多因机械或参数问题"},{"id":238,"type":"multi","cat":"基础概念","stem":"视距内飞行（VLOS）的要求包括（）。","A":"驾驶员肉眼可见无人机","B":"飞行高度≤120米","C":"无需额外通信设备","D":"需持有驾驶员执照","answer":"ABC","exp":"视距内飞行对执照的要求根据无人机重量而定，微型无人机可无执照"},{"id":239,"type":"multi","cat":"基础概念","stem":"无人机电磁干扰的可能来源有（）。","A":"高压输电线","B":"手机信号塔","C":"汽车火花塞","D":"无人机自身电机","answer":"ABCD","exp":"强电磁源及设备内部电磁辐射均可能干扰"},{"id":240,"type":"multi","cat":"设备与维护","stem":"锂聚合物电池的安全操作包括（）。","A":"充电电流不超过1C","B":"存放电压3.8~3.9V/节","C":"避免过放（＜3.0V/节）","D":"高温环境下充电","answer":"ABC","exp":"高温充电易引发电池膨胀甚至起火"},{"id":241,"type":"multi","cat":"领航与任务规划","stem":"无人机航线规划的原则包括（）。","A":"避开禁飞区","B":"预留安全高度","C":"减少急转动作","D":"优先逆风飞行","answer":"ABC","exp":"逆风飞行会增加功耗，通常优先顺风或侧风"},{"id":242,"type":"multi","cat":"设备与维护","stem":"无人机飞行日志中需记录的关键数据有（）。","A":"GPS坐标","B":"电池电压/电流","C":"飞控温度","D":"遥控器信号强度","answer":"ABCD","exp":"所有选项均为故障分析的关键数据"},{"id":243,"type":"single","cat":"法规与空域","stem":"民用无人机系统的机长是指（）。","A":"操控无人机的人","B":"负责整个飞行任务安全和运行的人","C":"协助操控无人机的人","D":"仅负责地面监控的人员","answer":"B","exp":"无人机系统机长是指经授权负责整个飞行任务安全和运行的人员，对飞行活动全过程的安全与运行负责；具体操纵无人机的是驾驶员（操控手），协助操控的是副驾驶或观察员，仅负责地面监控的人员也不承担机长职责。"},{"id":244,"type":"single","cat":"设备与维护","stem":"无人机飞行前，检查电池时不需要检查的是（）。","A":"电池电量","B":"电池外观有无破损","C":"电池品牌","D":"电池连接是否牢固","answer":"C","exp":"飞行前电池检查内容包括电量是否充足、外观有无破损鼓包、连接是否牢固可靠；电池品牌不是飞行安全检查的必查项，同一架飞机按规定使用匹配电池即可，无需在飞前核对品牌。"},{"id":245,"type":"single","cat":"基础概念","stem":"以下哪种天气条件最不适合无人机飞行（）。","A":"晴天微风","B":"小雨","C":"阴天少云","D":"风速2~3米/秒","answer":"B","exp":"小雨天气最不适合无人机飞行：雨水可能侵入机体电路和电机造成短路失控，多数消费级无人机不具备防水能力，且雨天能见度差、云层低；晴天微风、阴天少云和2~3米/秒的风速都属于可飞条件。"},{"id":246,"type":"single","cat":"基础概念","stem":"无人机在海拔较高地区飞行时，空气密度降低，会导致（）。","A":"升力增加","B":"升力减小","C":"飞行速度加快","D":"电机效率提高","answer":"B","exp":"海拔升高空气密度降低，同样速度下机翼或旋翼产生的升力减小，发动机进气量减少功率也下降，无人机性能明显衰减；升力与空气密度成正比，密度减小只会使升力变小、效率变差。"},{"id":247,"type":"single","cat":"领航与任务规划","stem":"无人机的GPS定位模式下，通常能实现（）。","A":"自主悬停","B":"高速飞行","C":"倒飞","D":"自动避障","answer":"A","exp":"GPS定位模式下，飞控依据卫星定位数据进行位置和速度闭环控制，可实现自主悬停，定点误差小、操纵简单；高速飞行、倒飞取决于机型性能，自动避障需要视觉等避障传感器支持，都不是GPS模式本身的功能。"},{"id":248,"type":"single","cat":"设备与维护","stem":"无人机飞行中，出现炸机现象通常是指（）。","A":"无人机正常降落","B":"无人机在空中平稳飞行","C":"无人机坠毁","D":"无人机失去信号","answer":"C","exp":"炸机是无人机行业对飞行事故的俗称，指无人机因失控、碰撞或故障而坠毁损毁；正常降落、平稳飞行与炸机含义相反，失去信号若最终安全返航也不算炸机，炸机的核心特征是坠毁。"},{"id":249,"type":"single","cat":"操纵与飞行技术","stem":"无人机的最大起飞重量是指（）。","A":"无人机自身重量","B":"无人机可携带的最大载荷重量","C":"无人机自身重量与最大载荷重量之和","D":"无人机空机重量","answer":"C","exp":"最大起飞重量指无人机允许起飞的最大总重量，即空机重量（含燃油等必备项）与最大任务载荷之和，是衡量运载能力、确定登记和运行要求的基础参数；只取自身重量或只取载荷，都只是其中的一部分。"},{"id":250,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的桨叶通常采用（）设计。","A":"对称翼型","B":"非对称翼型","C":"平板翼型","D":"三角翼型","answer":"B","exp":"多旋翼桨叶追求悬停与巡航的高效率，通常采用上表面弧度较大的非对称弯度翼型，相同转速下升力更大、诱导功率损失更小；对称翼型升力特性上下对称，多用于需要正倒飞的特技机或舵面，用作主升力桨效率偏低。"},{"id":251,"type":"single","cat":"设备与维护","stem":"无人机飞行中，若遥控器信号丢失，以下做法正确的是（）。","A":"立即切断电源","B":"等待信号自动恢复","C":"打开无人机的自动返航功能","D":"尝试手动操作返回","answer":"C","exp":"遥控信号丢失后最稳妥的做法是触发预设的失控保护，即自动返航：飞控依靠记录的返航点自主爬升、返回并降落，避免人工盲操越飞越偏。立即断电会彻底失去控制，被动等待信号恢复则可能电量耗尽坠机。"},{"id":252,"type":"single","cat":"法规与空域","stem":"以下关于无人机保险的说法，错误的是（）。","A":"可以保障无人机在飞行中因意外事故造成的损失","B":"购买保险后可以随意飞行","C":"不同的保险条款保障范围不同","D":"保险可以降低飞行风险带来的经济损失","answer":"B","exp":"无人机保险的作用是在意外造成机损或第三者人身财产损失时按条款赔付，只能转移经济损失，不同险种的保障范围与免责条款各不相同；投保并不能免除空域申请、禁飞区限制等合规义务，买了保险仍须依法依规飞行，随意飞行照样违法。"},{"id":253,"type":"single","cat":"基础概念","stem":"无人机飞行高度一般以（）为基准进行测量。","A":"当地地面","B":"海平面","C":"建筑物顶部","D":"树木顶部","answer":"B","exp":"飞行高度一般指海拔高度，以平均海平面为基准面测量，这样与空域划分、航图和管制指令的高度标准保持一致，便于统一空域管理；以当地地面为基准的是相对高度（真高），两者含义和用途不同，不能混为一谈。"},{"id":254,"type":"single","cat":"操纵与飞行技术","stem":"无人机的飞行姿态主要由（）传感器测量。","A":"气压计","B":"陀螺仪","C":"加速度计","D":"以上都是","answer":"D","exp":"姿态感知依靠多传感器融合：陀螺仪测量角速度，感知俯仰横滚的转动速率；加速度计感受重力方向，用于解算倾角；气压计提供高度基准辅助定高。多源数据互补融合才能输出准确的姿态与状态信息，任何单一传感器都有局限。"},{"id":255,"type":"single","cat":"基础概念","stem":"无人机飞行时，遇到强风，应该（）。","A":"继续保持原高度飞行","B":"降低飞行高度","C":"增加飞行高度","D":"加速飞行","answer":"B","exp":"近地面受地物摩擦影响，风速一般随高度增加而增大，遇到强风时适当降低飞行高度可进入风较小的空域，减小漂移和受风面，降低失控风险；盲目加速或爬升只会进入更强的风场，稳妥做法还包括尽早返航降落。"},{"id":256,"type":"single","cat":"基础概念","stem":"无人机的飞行限制区域不包括（）。","A":"机场净空保护区","B":"军事管理区","C":"人口密集区","D":"空旷农田","answer":"D","exp":"无人机限制飞行区域主要包括机场净空保护区、军事管理区等涉密敏感区域、人口稠密区上空，以及监管部门划设的禁飞范围；空旷农田远离人群和重要设施，通常属于可飞区域，不在限制之列。"},{"id":257,"type":"single","cat":"设备与维护","stem":"以下哪种电池适合用于无人机（）。","A":"碱性电池","B":"镍氢电池","C":"锂电池","D":"铅酸电池","answer":"C","exp":"无人机要求动力电池重量轻、能量密度高、放电倍率大，锂电池尤其是锂聚合物电池恰好兼具这些优点，能瞬间释放大电流满足电机的功率需求；碱性电池、铅酸电池能量密度低且笨重，镍氢电池放电能力也远逊于锂电池。"},{"id":258,"type":"single","cat":"基础概念","stem":"无人机在飞行中突然出现抖动，可能的原因是（）。","A":"电池电量充足","B":"桨叶安装不平衡","C":"飞行高度过低","D":"遥控器信号强","answer":"B","exp":"飞行中突然抖动最常见的原因是桨叶安装不平衡、变形或破损，高速旋转时产生周期性不平衡振动并传遍整机，还会加剧电机轴承磨损，应立即降落检查更换；电量充足、信号强都与振动无关，高度低也不直接引发抖动。"},{"id":259,"type":"single","cat":"基础概念","stem":"无人机的飞行记录可以帮助（）。","A":"分析飞行问题和改进飞行技术","B":"增加飞行速度","C":"提高电池续航能力","D":"改变无人机外观","answer":"A","exp":"飞控自动记录的飞行数据涵盖姿态、高度、速度、电量、卫星数和操纵输入等，事后复盘可以查找故障原因、分析操纵问题、改进飞行技术，也是事故追溯的重要依据；它是数据资料，不会直接改变速度、续航或外观。"},{"id":260,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的电机转速增加时，（）。","A":"升力减小","B":"升力增加","C":"飞行速度降低","D":"电池消耗减慢","answer":"B","exp":"螺旋桨升力近似与转速的平方成正比，电机转速提高时桨盘气流加快，升力随之增大，飞机便爬升或加速，同时电流和功耗明显上升、续航缩短；油门正是通过调节转速来控制升力和飞行状态，而非使升力减小或耗电变慢。"},{"id":261,"type":"single","cat":"设备与维护","stem":"无人机飞行前，对遥控器的检查不包括（）。","A":"遥控器电量","B":"遥控器天线是否完好","C":"遥控器的颜色","D":"遥控器的功能按键是否正常","answer":"C","exp":"遥控器飞行前检查的项目包括电量充足、天线完好无松动、各摇杆与按键功能正常、与接收机对频正常等，这些都直接关系操控可靠性；外观颜色纯属个人偏好，与飞行安全无关，不属于检查内容。"},{"id":262,"type":"single","cat":"法规与空域","stem":"以下关于无人机实名登记的说法，正确的是（）。","A":"不需要进行实名登记","B":"只有大型无人机需要实名登记","C":"所有民用无人机都需要实名登记","D":"只有商业用途的无人机需要实名登记","answer":"C","exp":"依据《无人驾驶航空器飞行管理暂行条例》，民用无人驾驶航空器的所有者都应当依法实名登记，微型、轻型同样适用，登记信息变更还须及时更新；实名登记是空域管理和事故追溯的基础，并非只有大机或商业用途才需要办理。"},{"id":263,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，需要（）。","A":"关闭灯光","B":"打开警示灯","C":"仅依靠GPS定位","D":"高速飞行","answer":"B","exp":"夜间飞行必须打开警示灯（航行灯），使其他飞行器和地面人员能及时发现识别无人机，避免相撞，也帮助飞手在昏暗环境中目视确认机体位置与姿态；关闭灯光或仅靠GPS定位都无法替代目视观察，高速夜飞更易失控。"},{"id":264,"type":"single","cat":"基础概念","stem":"无人机的飞行范围受到（）限制。","A":"电池续航能力","B":"遥控器信号范围","C":"法律法规","D":"以上都是","answer":"D","exp":"无人机能飞多远是多重约束共同作用的结果：电池续航决定滞空时间，遥控与图传链路的可靠通信距离限制远离范围，空域法规又划定了允许飞行的区域和高度，三者任何一项都会构成边界，因此飞行范围受这些因素共同限制。"},{"id":265,"type":"single","cat":"基础概念","stem":"无人机的水平尾翼主要作用是（）。","A":"增加飞行速度","B":"控制俯仰姿态","C":"增加升力","D":"减少阻力","answer":"B","exp":"固定翼的水平尾翼（含升降舵）位于机身后部，通过改变尾翼升力对重心形成俯仰力矩，用来保持纵向静稳定、控制俯仰姿态，让飞机平稳抬头或低头；增加升力主要靠机翼，减阻增速也不是平尾的功能定位。"},{"id":266,"type":"single","cat":"基础概念","stem":"无人机飞行中，若遇到电磁干扰，可能会导致（）。","A":"飞行速度加快","B":"飞行姿态失控","C":"电池电量增加","D":"桨叶转速加快","answer":"B","exp":"强电磁干扰会扰乱磁罗盘、惯性器件与导航接收机的正常工作，使飞控收到的姿态和位置数据失真，轻则悬停漂移、仪表告警，重则姿态失控甚至坠机；飞行应远离高压线、雷达站和大功率发射源，干扰不会让速度变快或电量变多。"},{"id":267,"type":"single","cat":"领航与任务规划","stem":"以下关于无人机航点规划的说法，错误的是（）。","A":"可以实现无人机的自动飞行","B":"航点规划需要考虑地形和障碍物","C":"航点规划完成后不能修改","D":"合理的航点规划可以提高飞行效率","answer":"C","exp":"航点规划让无人机按预设航点自动飞行，规划时必须结合地形高程与障碍物留足安全高度，合理的航线能明显提高作业效率；但航线并非一次定型，作业中完全可以根据现场情况暂停、调整或重编航点，说完成后不能修改与实际软件功能不符。"},{"id":268,"type":"single","cat":"基础概念","stem":"无人机的动力系统不包括（）。","A":"电机","B":"桨叶","C":"电池","D":"飞控系统","answer":"D","exp":"无人机的动力系统由电池、电子调速器、电机和螺旋桨组成，负责产生并调节拉力或推力；飞控系统属于导航控制部分，承担姿态解算与飞行控制，本身不产生动力，因此不在动力系统组成之列，电机、桨叶、电池才是动力成员。"},{"id":269,"type":"single","cat":"设备与维护","stem":"无人机在飞行中，若出现电机过热，应该（）。","A":"继续飞行","B":"立即增加电机转速","C":"降低飞行高度","D":"降落检查","answer":"D","exp":"电机过热说明电流异常偏大或散热不畅，继续飞行可能烧毁绕组、磁钢退磁甚至空中停车，正确处置是尽快降落检查，排除桨叶过载、异物缠绕、电调故障后再决定能否复飞；加大转速只会更热，降低高度也无济于事。"},{"id":270,"type":"single","cat":"基础概念","stem":"以下关于无人机避障系统的说法，正确的是（）。","A":"所有无人机都有避障系统","B":"避障系统能完全避免碰撞","C":"避障系统可以检测前方和下方障碍物","D":"避障系统不需要维护","answer":"C","exp":"避障系统依靠视觉、红外或激光等传感器探测前方和下方等方向的障碍物，发现后减速、绕行或刹停，是重要的辅助安全手段；但受探测距离、光照与目标材质限制，它不能完全避免碰撞，也并非所有机型都配备，传感器同样需要清洁校准维护。"},{"id":271,"type":"single","cat":"基础概念","stem":"无人机飞行时，若遇到大雨，应该（）。","A":"继续飞行完成任务","B":"降低飞行速度","C":"尽快降落","D":"升高飞行高度","answer":"C","exp":"雨水会打湿机体和电路造成短路，打在桨叶上破坏气动平衡，还常伴随低能见度和下沉气流，大雨中继续飞行极易失控，正确做法是尽快安全降落，事后彻底干燥检查再使用；减速或爬升都消除不了进水短路的风险。"},{"id":272,"type":"single","cat":"法规与空域","stem":"无人机的飞行执照分为（）。","A":"一种","B":"两种","C":"三种","D":"四种","answer":"C","exp":"民航部门颁发的操控员执照按运行能力分为视距内驾驶员、超视距驾驶员（机长）和教员三类：视距内只能目视范围内操作，超视距可依仪表和链路运行，教员另可承担培训教学，分类分级使操控资质与运行风险相匹配。"},{"id":273,"type":"multi","cat":"基础概念","stem":"以下属于无人机飞行前准备工作的有（）。","A":"检查无人机外观","B":"校准飞控系统","C":"规划飞行路线","D":"检查电池电量","answer":"ABCD","exp":"飞行前准备是完整流程：检查机体外观有无裂纹损伤；校准飞控的指南针、IMU等传感器，保证控制基准准确；规划飞行路线，避开障碍物和禁飞区；检查电池电量，确保有返航余量。四项环环相扣，任何疏漏都可能埋下事故隐患。"},{"id":274,"type":"multi","cat":"基础概念","stem":"影响无人机飞行安全的因素有（）。","A":"天气条件","B":"飞行环境","C":"操作人员技能","D":"无人机设备状况","answer":"ABCD","exp":"天气条件如大风、降雨、低能见度直接影响飞行稳定与操控；飞行环境中的障碍物、电磁干扰、人群密度构成外部风险；操作人员的技能和应急处置水平决定操纵质量；设备状况包括电池健康、桨叶完好、传感器精度等。四方面共同决定一次飞行是否安全。"},{"id":275,"type":"multi","cat":"基础概念","stem":"无人机的飞行模式通常有（）。","A":"GPS定位模式","B":"手动模式","C":"姿态模式","D":"自动返航模式","answer":"ABCD","exp":"常见飞行模式包括GPS定位模式，依靠卫星实现定点定高，适合大多数作业；姿态模式不依赖定位，用杆量直接控制姿态，用于卫星信号不佳的场合；手动模式完全由飞手操纵；自动返航模式在失控或一键触发时自主返回起飞点。各模式适用于不同环境与熟练程度。"},{"id":276,"type":"multi","cat":"基础概念","stem":"多旋翼无人机的优点有（）。","A":"垂直起降","B":"空中悬停","C":"结构简单","D":"续航时间长","answer":"ABC","exp":"多旋翼依靠多个旋翼的差动转速控制，可垂直起降，无需跑道；能够空中悬停，便于定点观测和作业；机械结构相对简单，维护方便、可靠性高。但悬停时能量几乎全部用于抵消重力，功耗大、续航时间短恰恰是它的明显短板，并非优点。"},{"id":277,"type":"multi","cat":"设备与维护","stem":"无人机的飞控系统可以（）。","A":"控制飞行姿态","B":"记录飞行数据","C":"实现自动飞行","D":"调节电机转速","answer":"ABCD","exp":"飞控系统是无人机的中枢：实时解算传感器数据，控制飞行姿态保持稳定；记录飞行数据日志，供事后复盘分析；执行预设航线任务，实现自动飞行；输出控制量给电调，调节各电机转速或舵面偏转，完成各种机动。四项都是飞控的基本功能。"},{"id":278,"type":"multi","cat":"基础概念","stem":"以下哪些地方不适合无人机飞行（）。","A":"核电站附近","B":"野生动物保护区","C":"体育赛事现场","D":"公园开阔草地","answer":"ABC","exp":"核电站属于重点防护目标，上空禁飞且周边电磁环境复杂；野生动物保护区内飞行会惊扰动物、破坏栖息环境；体育赛事现场人员密集，坠落或闯入都可能造成伤害、扰乱赛事。公园开阔草地只要遵守当地规定、不扰民，一般是允许的休闲飞行场所。"},{"id":279,"type":"multi","cat":"设备与维护","stem":"无人机电池使用时的注意事项有（）。","A":"避免过充","B":"避免过放","C":"定期检查电池外观","D":"存放时保持适当电量","answer":"ABCD","exp":"锂电池使用要点：过充会导致鼓包甚至起火，须用配套充电器并有人看护；过放会损伤电芯容量与寿命，电压接近保护值就应停用；定期检查外观有无鼓包、破损、漏液；长期存放应保持约一半电量的储存电压并阴凉放置。四项做法都能延长寿命、保障安全。"},{"id":280,"type":"multi","cat":"领航与任务规划","stem":"无人机的导航方式有（）。","A":"GPS导航","B":"视觉导航","C":"惯性导航","D":"磁力导航","answer":"ABCD","exp":"卫星导航（GPS、北斗）提供绝对位置基准；视觉导航利用摄像头识别环境特征定位，适合室内或卫星信号拒止环境；惯性导航靠陀螺仪和加速度计推算位姿，短时精度高但误差随时间累积；磁力导航借助地磁传感器提供航向参考。多源融合互补是主流做法。"},{"id":281,"type":"multi","cat":"基础概念","stem":"无人机在飞行中出现异常情况，应该（）。","A":"保持冷静","B":"尝试判断原因","C":"采取相应措施","D":"立即切断电源","answer":"ABC","exp":"飞行中出现异常，首先要保持冷静，避免慌乱误操作；随后结合姿态表现、告警信息和环境条件判断可能原因；再采取针对性措施，如降低高度、切回可控模式或就近降落。空中绝不能立即切断电源，那会让动力瞬间丧失直接坠机，断电只在落地排故时进行。"},{"id":282,"type":"multi","cat":"法规与空域","stem":"以下关于无人机的法律法规，说法正确的有（）。","A":"需要遵守当地的飞行规定","B":"飞行前可能需要申请飞行许可","C":"不得在禁飞区飞行","D":"可以随意拍摄他人隐私","answer":"ABC","exp":"无人机活动必须遵守当地飞行管理规定；在管制空域飞行前应按规定申请飞行许可；禁飞区未经批准绝对不得飞入，这三项都是合规飞行的基本要求。而随意拍摄他人隐私侵犯肖像权和个人信息保护规定，属于违法行为，法律并不允许。"},{"id":283,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机平飞转弯时（）。","A":"转弯中，如果坡度过大，应协调地适当回杆回舵","B":"转弯中，如果坡度过小，应协调地适当回杆回舵","C":"转弯中，如果坡度过大，应协调地适当增加压杆扭舵量","D":"以上均不正确","answer":"A","exp":"平飞转弯中坡度决定盘旋半径和升力的水平分量：坡度过大时升力垂直分量不足，飞机下沉、状态过猛，应协调地适当回杆回舵减小坡度，恢复高度和速度；坡度过小时转弯缓慢，才需要加大压杆量，两者操纵方向不能搞反。"},{"id":284,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆拉平时，对拉平操作描述不恰当的是（）。","A":"主动地、有预见地、机动灵活地去操纵飞机","B":"严格按高度值执行动作","C":"正确的拉平动作，必须按照实际情况","D":"以上均不正确","answer":"B","exp":"着陆拉平要根据当时的下沉快慢、高度和姿态，主动而有预见地机动操纵，按实际情况决定拉杆分量和时机；拉平高度随载重、风速等条件变化，死板地严格按固定高度值执行动作，反而容易拉高或重接地，是不恰当的做法。"},{"id":285,"type":"single","cat":"飞行原理","stem":"翼载荷是无人机（）升力面所承受的气动力载荷翼载荷可衡量飞行中机翼的受载状况，直接影响到无人机的飞行性能。","A":"单位体积","B":"单位长度","C":"单位面积","D":"单位高度","answer":"C","exp":"翼载荷是无人机重量与机翼面积之比，即单位翼面面积承受的气动力载荷，常用千克每平方米表示。它反映飞行中机翼的受载状况，翼载荷越大失速速度越高、转弯半径越大，直接影响起降和机动性能，与体积、长度等度量无关。"},{"id":286,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，如果拉平前飞机的俯角较大、下降快，应（）。","A":"拉杆稍早些","B":"拉杆稍晚些","C":"还按正常时机拉杆","D":"以上均不正确","answer":"A","exp":"拉平的目的是消除俯角和下沉率：拉平前俯角较大、下沉速度快时，状态恶化得更早，必须适当提前拉杆，才能及时改出俯冲姿态、平缓减小下沉，避免接地过重；此时若仍按正常时机拉杆或拖后，就会来不及改出。"},{"id":287,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，下列哪种情况，收油门的时机应适当延迟，收油门的动作适当减慢？（）","A":"当时的高度与预定高度吻合","B":"当时的高度高于预定高度","C":"当时的高度低于预定高度","D":"以上均不正确","answer":"C","exp":"收油门决定速度减小的时机与快慢：当时高度低于预定高度，说明飞机能量偏少、下沉趋势明显，应适当延迟收油门并放缓动作，借助剩余拉力保持速度，争取修正高度的机会；高度吻合时按常规收，偏高时才需提前收小油门。"},{"id":288,"type":"single","cat":"设备与维护","stem":"电调、电机和螺旋桨是旋翼飞机的（）。","A":"控制系统","B":"电力系统","C":"动力系统","D":"稳定系统","answer":"C","exp":"电调按飞控指令把电池电能分配给电机，电机将电能转为机械旋转，螺旋桨再把旋转转化为拉力，三者串联构成动力系统，负责产生飞行所需的推力；控制指令虽来自飞控，但电调、电机、桨属于动力输出环节，不是控制或稳定系统。"},{"id":289,"type":"single","cat":"操纵与飞行技术","stem":"下列属于无人驾驶航空器核心控制装置的是（）。","A":"定位系统","B":"飞控系统","C":"电力系统","D":"动力系统","answer":"B","exp":"飞控系统（自动驾驶仪）是无人机的核心控制装置，实时解算传感器数据并输出控制量，完成姿态稳定、导航与任务执行，相当于无人机的大脑；定位、电力、动力系统分别承担定位、供能与推力功能，都受飞控统一调度，并非控制核心。"},{"id":290,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机平飞转弯前（）。","A":"根据转弯坡度大小，减油门5%-10%，保持好平飞状态","B":"根据转弯坡度大小，加油门5%-10%，保持好平飞状态","C":"保持当前平飞状态","D":"以上均不正确","answer":"B","exp":"进入转弯后升力方向随坡度倾斜，维持高度的垂直分量减小，飞机会掉高度，所以平飞转弯前要根据坡度大小适当加油门约5%至10%，用增加的功率补偿垂直升力损失，保持高度速度不变地进入盘旋，转弯中再按状态微调。"},{"id":291,"type":"single","cat":"基础概念","stem":"机翼1/4弦线与垂直机身中心线的直线之间的夹角称为机翼的（）。","A":"安装角","B":"上反角","C":"后掠角","D":"以上均不正确","answer":"C","exp":"机翼后掠角指1/4弦线与垂直于机身中心线的直线之间的夹角，后掠布局可推迟激波产生、改善高速性能与航向稳定性；安装角是翼弦与机身纵轴的夹角，上反角是翼面相对水平面的上翘角，三个角度的定义各不相同，不能混淆。"},{"id":292,"type":"single","cat":"电力巡检","stem":"（）是根据故障情况选择适用机型开展故障查找，巡检图像质量应满足故障分析需要。","A":"正常巡检","B":"故障巡检","C":"特殊巡检","D":"灾后特巡","answer":"B","exp":"故障巡检是在发现设备异常或缺陷后，根据故障情况选择适用机型和载荷，有针对性地开展故障查找，图像质量须满足缺陷分析需要，为检修决策提供依据；正常巡检按周期例行开展，特殊巡检、灾后特巡则针对恶劣天气或灾害后的专项检查。"},{"id":293,"type":"single","cat":"设备与维护","stem":"无人机装配报告中任务载荷系统复检项包括任务载荷系统安装方向正确且牢固、任务载荷系统活动部分手动推动阻尼正常、任务载荷系统信号线插接正确且牢固、（）、任务载荷系统电源线插接正确且牢固。","A":"任务载荷系统完好无损","B":"任务载荷系统自检通过","C":"任务载荷系统完成校验","D":"任务载荷系统指示灯运行正常","answer":"A","exp":"任务载荷系统装配复检覆盖机械与电气两方面：安装方向正确且牢固、活动部分手动推动阻尼正常、信号线插接正确且牢固、电源线插接正确且牢固，还要确认载荷系统整体完好无损，防止运输磕碰留下隐蔽损伤影响作业成像。"},{"id":294,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，关于收油门描述正确的是（）。","A":"收油门的过程要拉长一些，拉长了可以柔和，使速度减小均匀，有利于做好着陆","B":"收油门的过程要尽量短，短了可以柔和，使速度减小均匀，有利于做好着陆","C":"收油门的过程可以随意些，跟着感觉就好","D":"以上均不正确","answer":"A","exp":"收油门的过程要适当拉长、动作柔和，使飞行速度均匀减小、飞机状态变化平稳，有利于把准拉平高度和接地姿态；收得过快过猛会让速度骤减、下沉加快，难以做好着陆，随意跟着感觉操作更不可取，节奏必须与高度速度匹配。"},{"id":295,"type":"single","cat":"领航与任务规划","stem":"典型的无人机是由飞行器平台、动力系统、控制站与飞行控制系统、通信导航系统、任务载荷系统以及（）系统组成。","A":"发射/回收系统","B":"燃油系统","C":"制导系统","D":"飞行系统","answer":"A","exp":"典型无人机由飞行器平台、动力系统、控制站与飞行控制系统、通信导航系统、任务载荷系统及发射回收系统组成：发射回收系统负责起飞升空与任务后的安全回收，对固定翼需弹射、跑道或拦阻回收的平台尤为必要；燃油、制导只是局部环节。"},{"id":296,"type":"single","cat":"设备与维护","stem":"一款四旋翼其1号电机通电后发现旋转方向为顺时针，这时应（）。","A":"飞行器电调故障，更换电调","B":"将1号电机的螺旋桨更换为CW桨叶即可","C":"将1号电机引出线2根线与电调线2根线进行对调即可","D":"飞行器严重错误，禁止飞行","answer":"C","exp":"无刷电机的旋转方向由电调与电机三相接线的相序决定，1号电机转向与设定相反时，把该电机的两根引出线与电调输出线任意两根对调，相序反转即可纠正转向；换用CW桨会破坏桨距与转向的匹配，属错误做法，电调本身并无故障。"},{"id":297,"type":"single","cat":"飞行原理","stem":"螺旋桨的螺距是什么？（）","A":"螺距是指螺旋桨旋转一周所上升或前进的距离","B":"螺距是指螺旋桨旋转一周所上升的距离","C":"螺距是指螺旋桨旋转一周所前进的距离","D":"以上均不正确","answer":"A","exp":"螺旋桨螺距指桨叶旋转一周理论上沿轴向前进（或上升）的距离，如同螺丝拧进介质的进程，它决定每转做功与转速的匹配关系：螺距大则每转前进远、适合高速，螺距小则拉力响应快；只说上升或只说前进都只描述了部分含义。"},{"id":298,"type":"single","cat":"基础概念","stem":"（）不属于垂直起降固定翼无人机主要组成部分。","A":"外翼段","B":"中翼段","C":"尾翼","D":"上翼段","answer":"D","exp":"垂直起降固定翼通常由机身、机翼、尾翼和旋翼动力等部分组成，机翼常分为中翼段与外翼段以便拆装运输，尾翼提供纵向与方向稳定操纵；上翼段并不是这类机型结构的标准组成部件，属于干扰说法。"},{"id":299,"type":"single","cat":"设备与维护","stem":"遥控器开机按钮操作顺序（）。","A":"长按","B":"短按再长按","C":"短按一下","D":"长按再短按","answer":"B","exp":"多数遥控器的开机按钮需先短按一下再长按：短按唤醒电路，持续按压完成开机，关机顺序相反，这种设计可防止误触开关造成空中失控；只短按或只长按往往无法正常启动，具体操作还应以所用型号的说明书为准。"},{"id":300,"type":"single","cat":"设备与维护","stem":"无人机装配报告中动力系统复检项包括电机安装、（）、电池安装和桨叶安装。","A":"飞行控制系统（自驾仪）安装","B":"无线图像传输（无线图传）系统安装","C":"电子调速器（电调）安装","D":"无线数据传输（无线数传）系统安装","answer":"C","exp":"动力系统装配复检的项目包括电机安装、电子调速器（电调）安装、电池安装和桨叶安装：电调是动力链中连接电池与电机的关键环节，其安装位置、散热与接线质量直接关系供电可靠；飞控、图传、数传属于控制与通信系统，不在动力复检清单内。"},{"id":301,"type":"single","cat":"基础概念","stem":"无人机系统中，起降操作手一般不参与哪个阶段控制（）。","A":"起飞阶段","B":"降落阶段","C":"巡航阶段","D":"以上均不正确","answer":"C","exp":"起降操作手的职责集中在风险最高的起飞与降落阶段，负责离地、爬升以及进近、接地操纵；进入巡航后飞行状态平稳，通常由任务操作手或地面站按航线自动控制管理，起降操作手不再直接参与，分工协作以提高安全裕度。"},{"id":302,"type":"single","cat":"基础概念","stem":"四旋翼飞行器支架中间的空间中安放（）和外部设备。","A":"定位装置","B":"摄像头","C":"飞行控制计算机","D":"机载设备","answer":"C","exp":"四旋翼的中心机架空间用来安放飞行控制计算机（自驾仪）：它处于机体几何中心，姿态解算基准最准确，又便于向四周电调、接收机布线，还可搭配其他外部设备；摄像头、定位装置等属于按需外挂的机载设备，并非中心舱的标准配置。"},{"id":303,"type":"single","cat":"领航与任务规划","stem":"360°圆周航线飞行训练科目中，操作无人机在姿态模式下，完成360°圆周航线飞行，在飞行过程中与地面标识物的水平误差不得大于±（）cm。","A":"10","B":"30","C":"50","D":"100","answer":"C","exp":"姿态模式下的360°圆周航线训练，要求飞手全程用杆量配合保持圆形轨迹，与地面标识物的水平误差不得大于±50厘米，这一标准考验高度、速度、坡度的协调控制能力；限值过小不切实际，过大则达不到训练精度要求。"},{"id":304,"type":"single","cat":"基础概念","stem":"固定翼无人机电子调速器的标称电流应（）电动机的最大额定电流。","A":"大于或等于","B":"小于或等于","C":"大于","D":"小于","answer":"A","exp":"电调持续输出的标称电流必须大于或等于电机的最大额定电流，否则电机大负荷运转时电调会过流发热甚至空中断电烧毁；留足电流裕量是动力匹配的基本原则，选小了危险，一味选大也徒增重量成本，底线是不小于电机最大额定值。"},{"id":305,"type":"single","cat":"基础概念","stem":"关于四旋翼飞行器的描述，以下错误的是？（）","A":"桨叶分为正反桨","B":"需按照说明书将桨叶装在正确的位置上","C":"飞行器启动前需检查桨叶是否有旋紧","D":"桨叶有严重破损无需更换","answer":"D","exp":"四旋翼桨叶分正反桨，须按说明书装到对应电机位置，起动前还要逐片检查旋紧到位；桨叶出现裂纹、缺口等严重破损后，高速旋转的离心力和不平衡振动可能导致空中解体或振裂机臂，必须立即更换新桨，绝不能凑合继续使用。"},{"id":306,"type":"single","cat":"基础概念","stem":"多轴飞行器重心过高于或过低于桨平面会（）。","A":"增加稳定性","B":"降低机动性","C":"显著影响电力消耗","D":"以上均不正确","answer":"B","exp":"多轴飞行器的重心应尽量贴近桨平面：重心过高会产生类似不倒翁的摆动趋势，过低则姿态响应迟钝，两者都会降低机动性和操纵品质，恢复过程也更易震荡；重心偏离主要影响稳定与操纵特性，对电力消耗的影响并不显著。"},{"id":307,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，收油门过早、过粗，速度减小快，使拉平时的速度小，飞机下沉快（）。","A":"容易拉平低或者进入平飘时仰角较大","B":"对飞机无影响","C":"容易拉平高或者进入平飘时仰角较小","D":"以上均不正确","answer":"A","exp":"收油门过早过粗会使速度减小过快，拉平时可用速度偏小，为维持升力只能更多拉杆、机头仰角增大，容易出现拉平过低、贴近地面才改平，或进入平飘时仰角较大的状态，接地时容易失速式下沉；速度控制不当对飞机影响明显。"},{"id":308,"type":"single","cat":"设备与维护","stem":"如果数据链路上行中断，会发生（）的后果。","A":"无人机退出地面站控制模式","B":"不能获取无人机状态信息","C":"无法在线重规划航线航点及发送任务指令","D":"以上均不正确","answer":"C","exp":"数据链路上行负责把地面站指令送往无人机，上行中断后，下行链路仍可获取状态和图传，飞机会继续执行既有任务或进入失控保护，但无法在线重规划航线航点、发送任务指令，指挥通道被切断；说退出地面站模式或完全失去状态信息都不准确。"},{"id":309,"type":"single","cat":"基础概念","stem":"飞行高度层应当根据（）配备。","A":"航线或航路走向、航空器性能、飞行区域以及航线的地形、天气和飞行情况等","B":"飞行任务的性质、航空器等级、飞行区域以及航线的地形、天气和飞行情况等","C":"飞行任务的性质、航空器性能、飞行区域以及航线的地形、天气和飞行情况等","D":"航线或航路走向、航空器等级、飞行区域以及航线的地形、天气和飞行情况等","answer":"C","exp":"飞行高度层的配备依据包括飞行任务的性质、航空器性能、飞行区域以及航线的地形、天气和飞行情况等，须综合任务需要、飞机升限、地形安全与管制间隔统筹确定，保证足够的垂直间隔；混入航线走向或航空器等级的说法与标准表述不符。"},{"id":310,"type":"single","cat":"设备与维护","stem":"以下种类的电池，具有记忆效应的是（）。","A":"铅酸电池","B":"聚合物锂电池","C":"镍镉电池","D":"以上均不正确","answer":"C","exp":"镍镉电池存在明显记忆效应，长期不彻底充放电会让电芯记住缩短的容量，可用容量逐次下降，使用中应定期深度放电再充满；锂电池和铅酸电池基本没有记忆效应，锂电池反而要避免深度放电，这是不同电化学体系的重要差异。"},{"id":311,"type":"single","cat":"操纵与飞行技术","stem":"在修改完毕摇杆模式后，在起飞前应轻压低油门，轻微晃动俯仰与横滚，因为（）。","A":"确认舵量","B":"确认摇杆模式修改是否成功","C":"确认油门","D":"激活机器","answer":"B","exp":"修改摇杆模式后，起飞前应轻压低油门并轻微晃动俯仰与横滚杆，通过观察电机响应和舵量方向是否与设定一致，确认摇杆模式修改已成功生效，防止空中才发现舵向相反来不及纠正；这一检查的目的是验证模式设置，而非确认油门或激活机器。"},{"id":312,"type":"single","cat":"飞行原理","stem":"起飞时，可操纵变距螺旋桨的桨叶角到什么状态（）。","A":"小桨叶角及低转速","B":"大桨叶角及高转速","C":"小桨叶角及高转速","D":"以上均不正确","answer":"C","exp":"可操纵变距螺旋桨在起飞时将桨叶角调到最小、转速拉到最高：小桨叶角阻力小，发动机能迅速达到最大功率转速，获得最大拉力便于加速爬升；进入巡航后再增大桨叶角、降低转速以提高效率，桨叶角与转速的搭配随飞行阶段变化。"},{"id":313,"type":"single","cat":"领航与任务规划","stem":"菱形航线平移训练科目中，由H点起飞，控制好油门，操控无人机匀速垂直上升至（）m高度，保持无人机姿态平稳，悬停1-3秒。","A":"1","B":"1.5","C":"3","D":"7","answer":"C","exp":"菱形航线平移训练由H点起飞后，控制油门使无人机匀速垂直上升至3米高度，保持姿态平稳、悬停1至3秒后再开始平移：这一高度既留有安全裕度，又便于目视判断位置偏差；上升过程要匀速平稳，避免忽快忽慢造成高度超差或姿态晃动。"},{"id":314,"type":"single","cat":"领航与任务规划","stem":"众所周知，物体运动的速度是一个矢量，关于飞行过程中空速与地速的关系，下列正确的是（）。","A":"正侧风时，空速=地速","B":"无论何时，空速+风速=地速","C":"逆风时，空速＜地速","D":"以上均不正确","answer":"B","exp":"空速是飞机相对空气的运动速度，地速是相对地面的速度，二者与风速构成矢量关系：地速矢量等于空速矢量与风速矢量之和，该关系在任何风况下都成立。正侧风时地速方向偏移、大小一般不等于空速，逆风时地速小于空速，说小于空速就反了。"},{"id":315,"type":"single","cat":"领航与任务规划","stem":"以下不是导航飞控系统组成部分的是（）。","A":"传感器","B":"电台","C":"执行机构","D":"以上均不正确","answer":"B","exp":"导航飞控系统由传感器、飞控计算机和执行机构等组成：传感器感知姿态与位置，计算机解算控制律，执行机构落实操纵指令；电台属于数据链路（通信系统），负责地面与机上的信息传输，不属于导航飞控系统的组成部分。"},{"id":316,"type":"single","cat":"设备与维护","stem":"无人机数据链的关键能力不包括（）。","A":"抗干扰能力","B":"安全性","C":"抗欺骗性","D":"高速传输","answer":"D","exp":"无人机数据链最关键的能力是保证链路在复杂电磁环境下的可靠与可信：抗干扰能力防止被压制中断，安全性保证信息不被截获篡改，抗欺骗性防止被伪造指令或假信号诱骗；高速传输只是性能指标，速率可按需取舍，不属于这类关键能力。"},{"id":317,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机起飞降落的特点是（）。","A":"安全性高","B":"受场地限制小","C":"稳定性高","D":"其他全是","answer":"D","exp":"多旋翼靠旋翼差动实现垂直起降，不需要跑道，受场地限制小；起降过程速度低、姿态可控，安全性较高；飞控增稳使起降全程姿态平稳，稳定性好。三项特点同时成立，这些优势正是多旋翼成为航拍、巡检等主流平台的重要原因。"},{"id":318,"type":"multi","cat":"电力巡检","stem":"航线规划根据（）等信息，规划巡检飞行航线，满足工作任务要求。","A":"气象条件","B":"空域情况","C":"线路通道环境","D":"无人直升机性能","answer":"BCD","exp":"输电线路巡检的航线规划依据空域情况确定可飞范围并申请许可，结合线路通道环境确定与导线的安全距离和障碍规避，同时匹配无人直升机的性能如续航、抗风与载荷能力；气象条件属于起飞前的风险研判和飞行中动态监控的内容，不在航线规划的信息依据之列。"},{"id":319,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，作业人员应具备必要的（）等巡检飞行知识和相关业务技能，熟悉在《电力安全工作规程（线路部分）》（Q/GDW1799.2）和本标准，并经考试合格。","A":"电气","B":"机械","C":"气象","D":"航线规划","answer":"ABCD","exp":"按安全工作规程要求，巡检作业人员应具备电气、机械、气象和航线规划等必要的巡检飞行知识与业务技能，熟悉《电力安全工作规程（线路部分）》（Q/GDW1799.2）及巡检作业标准，并经考试合格后上岗，四类知识缺一不可，确保既会操控飞机又懂线路与天气风险。"},{"id":320,"type":"multi","cat":"电力巡检","stem":"小型无人直升机巡检工作班成员至少应包括（）。","A":"操控手","B":"程控手","C":"任务手","D":"安全监护员","answer":"AB","exp":"小型无人直升机巡检的最小工作班配置为操控手和程控手：操控手负责飞行操纵，程控手负责地面站程控与任务监视，两人配合即可完成小型机巡检；任务手和安全监护员在中大型机型或复杂作业中按需增配，不属于小型机的最低人员配置。"},{"id":321,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人直升机巡检系统》中，无人直升机巡检系统的地面站系统包括（）。","A":"硬件设备","B":"飞行控制软件","C":"检测软件","D":"地面通信系统","answer":"ABC","exp":"无人直升机巡检系统的地面站由硬件设备、飞行控制软件和检测软件组成：硬件设备提供计算、显示与操控平台，飞行控制软件监视和控制飞行状态，检测软件处理巡检图像与数据，三者构成完整的地面指挥分析平台；地面通信系统属于数据链路部分，不列入地面站系统。"},{"id":322,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，按照维修保养等级可分为（）。","A":"日常维护","B":"一级技术保养维护","C":"二级技术保养维护","D":"三级技术保养维护","answer":"ABC","exp":"按维修保养技术要求，保养分为日常维护、一级技术保养维护和二级技术保养维护三个等级：日常维护在每次作业前后清洁检查，一级保养按周期开展紧固、润滑等基础项目，二级保养进行深度检查与部件更换，层级逐级深入；不存在第三级保养。"},{"id":323,"type":"multi","cat":"基础概念","stem":"安全保护功能自检项目包括（）、（）、（）和（）等。","A":"飞行控制模块","B":"电池电压值","C":"发动机（电机）工况","D":"遥控遥测信号","answer":"ABCD","exp":"起飞前的安全保护功能自检覆盖四大项：飞行控制模块工作是否正常，直接关系控制权；电池电压值须在安全阈值内保证供电；发动机（电机）工况要确认启动平稳、输出正常；遥控遥测信号要求链路畅通、强度足够。任何一项异常都应排除后再起飞。"},{"id":324,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机下降到10米以下时，应重点关注的信息是（）。","A":"飞机航行灯开闭状态","B":"飞机下降速度、姿态和空速","C":"飞机剩余油量","D":"以上均不正确","answer":"B","exp":"临近地面下降时风险陡增，应重点关注飞机的下降速度、姿态和空速：下沉过快会重着陆，姿态异常容易失稳翻落，速度与风向不当影响接地平稳；10米以下目视范围小、处置余量短，这些飞行状态信息比油量、灯光状态更直接决定着陆安全。"},{"id":325,"type":"single","cat":"基础概念","stem":"多旋翼无人机机体一般不使用材料（）。","A":"碳纤维材料","B":"高强度工程塑料","C":"玻纤维材料","D":"以上均不正确","answer":"C","exp":"多旋翼机体结构件普遍采用碳纤维复合材料和高强度工程塑料：碳纤维比强度和刚度高、质量轻，工程塑料韧性好、成型方便、成本低；玻璃纤维材料虽也用于部分部件，但轻量化与比刚度优势不明显，一般不作为机体主结构材料。"},{"id":326,"type":"single","cat":"基础概念","stem":"下列哪个属于对冲击流？（）","A":"风沿迎风坡上升","B":"背风坡下降","C":"雷雨气流上升下降","D":"以上均不正确","answer":"C","exp":"雷雨云内部及周边存在强烈的上升与下沉气流交替，方向剧烈变化形成对飞行威胁极大的冲击流，可能瞬间造成高度骤变、结构过载甚至失控，应远离雷雨区；迎风坡上升、背风坡下沉属于地形性气流，相对平稳，与雷雨冲击流的突发剧烈不同。"},{"id":327,"type":"single","cat":"操纵与飞行技术","stem":"电调是连接（）与电机的部件，主要功能是接收飞控发出的信号，再将控制信号转换为电流的大小，调节电机转速，从而影响和控制飞行器的飞行状态。","A":"飞控","B":"信号接收器","C":"姿态感知器","D":"GPS","answer":"A","exp":"电调串接在飞控与电机之间：接收飞控输出的控制信号，将其转换为相应大小的驱动电流送到电机，调节电机转速，从而改变拉力和飞行状态，是动力系统的执行桥梁；信号接收器、GPS、姿态感知器都不直接驱动电机，与电调的连接位置不符。"},{"id":328,"type":"single","cat":"基础概念","stem":"小型固定翼飞机的主要部件包括（）起落装置和动力裝置。","A":"机体","B":"机翼","C":"机械臂","D":"云端","answer":"A","exp":"小型固定翼飞机的主要部件包括机体、机翼、尾翼等结构，加上起落装置和动力装置：机翼承担主要升力，起落装置支持地面停放与起降，动力装置提供推拉力，机体把各部分连成整体并容纳设备；机械臂、云端与飞机部件无关。"},{"id":329,"type":"single","cat":"飞行原理","stem":"小型固定翼飞机的结构系统主要包括机身、机翼、尾翼、起降装置，（）是无人机产生升力的主要部件。","A":"机身","B":"机翼","C":"尾翼","D":"起降装置","answer":"B","exp":"固定翼的升力主要由机翼产生：机翼采用非对称翼型并带有安装角，前飞时上下表面气流速度不同形成压差，托起整机重量；机身用于装载和连接各部件，尾翼负责稳定与操纵，起降装置只在地面阶段使用，都不是升力的主要来源。"},{"id":330,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆到平飘阶段（）。","A":"平飘前段，速度较大，下沉较慢，拉杆量应小一些","B":"平飘前段，速度较大，下沉较慢，拉杆量应大一些","C":"平飘后段，速度较小，下沉较快，拉杆量应适当减小","D":"以上均不正确","answer":"A","exp":"平飘是接地前的贴地减速阶段：前段速度还较大、下沉缓慢，只需少量拉杆柔和增大迎角，拉杆过多会飘起过高或擦尾；进入后段速度减小、下沉加快，拉杆量才需逐渐增大。前段小拉杆、后段渐增，是平飘操纵的基本规律。"},{"id":331,"type":"single","cat":"设备与维护","stem":"固定翼无人机航程的测试受电池电量、（）的影响。","A":"距离对信号","B":"GPS","C":"电机输出马力","D":"桨叶尺寸","answer":"A","exp":"固定翼航程测试主要受两方面制约：电池电量决定可用飞行时间，是航程的硬上限；距离对信号的影响限制远离操纵点的可靠通信范围，超出后链路恶化可能触发返航。GPS、电机马力、桨叶尺寸影响性能，但不是航程测试的主要影响因素。"},{"id":332,"type":"single","cat":"基础概念","stem":"可能需要处置的危急情况不包括：（）。","A":"任务设备故障","B":"舵面故障","C":"动力装置故障","D":"以上均不正确","answer":"A","exp":"需要立即处置的危急情况指直接威胁飞行安全的故障：舵面卡滞或失效会丧失操纵，动力装置停车、推力骤降会导致坠机，必须按预案果断处置；任务设备故障只影响作业成效，飞机本身仍可控可返，属一般故障，不算危急情况。"},{"id":333,"type":"single","cat":"设备与维护","stem":"飞控子系统可以不具备如下功能：（）。","A":"姿态稳定与控制","B":"增稳与姿态解算","C":"任务分配与航迹规划","D":"以上均不正确","answer":"C","exp":"飞控子系统的基本职能是姿态解算、增稳和姿态稳定与控制，保证无人机稳定可控飞行；任务分配与航迹规划通常由地面站或任务规划系统完成，规划结果下发给飞控执行，因此该功能可以不在飞控子系统内实现，属于其可不具备的部分。"},{"id":334,"type":"single","cat":"设备与维护","stem":"无人机装配中机翼、电机、机臂和（）需要用到水平尺。","A":"电池","B":"电子调速器（电调）","C":"飞行控制系统（自驾仪）","D":"分电板","answer":"C","exp":"装配中水平尺用于校准机翼、电机、机臂的安装水平度，也用于飞行控制系统（自驾仪）的安装调平：自驾仪内的陀螺仪、加速度计以安装平面为基准，装歪会造成姿态解算零位偏差，影响飞行品质；电池、电调、分电板的安装不要求水平精度。"},{"id":335,"type":"single","cat":"领航与任务规划","stem":"下列哪种规划是任务规划的主体核心（）。","A":"任务分配规划","B":"航迹规划","C":"应急预案规划","D":"以上均不正确","answer":"B","exp":"任务规划包含任务分配、航迹规划、应急预案等多个层面，其中航迹规划是主体核心：它把任务要求转化为具体的三维飞行路径，综合空域、地形、能耗与时间等约束，直接决定飞行能否安全高效执行；任务分配是前提，应急预案属于保障环节。"},{"id":336,"type":"single","cat":"设备与维护","stem":"以下哪种动力电池放电电流最大（）。","A":"20000mAh，5C","B":"8000mAh，20C","C":"2000mAh，30C","D":"以上均不正确","answer":"B","exp":"最大放电电流等于容量乘以放电倍率：20000毫安时按5C放100安，8000毫安时按20C达160安，2000毫安时按30C仅60安。容量大、倍率低未必电流大，8000毫安时20C的电池放电电流最大，选型须两者结合。"},{"id":337,"type":"single","cat":"飞行原理","stem":"关于失速，下面哪个说法是不正确的？（）","A":"机翼迎角超过临界角，导致升力急剧降低的飞行状态称为失速","B":"直升机飞速度过快，可能导致后行旋翼出现失速","C":"失速会导致升力急剧减小，阻力系数缓慢减小","D":"以上均不正确","answer":"C","exp":"失速是迎角超过临界迎角后机翼上表面气流大面积分离，表现为升力系数急剧下降、阻力急剧增大，说阻力缓慢减小正好相反，是不正确的说法；固定翼大迎角会失速，直升机前飞速度过大时后行桨叶相对气流减小、迎角增大，也可能进入失速。"},{"id":338,"type":"single","cat":"操纵与飞行技术","stem":"在固定翼无人机中，无人机的飞行姿态是通过调节各个（）来实现的。","A":"固定翼","B":"电机","C":"电调","D":"舵面","answer":"D","exp":"固定翼无人机由飞控驱动舵机偏转各气动舵面：升降舵控制俯仰，方向舵控制偏航，副翼控制横滚，靠舵面产生的气动力矩改变飞行姿态，这与多旋翼靠调节电机转速差动控制的方式不同；电调在固定翼上主要管理动力输出，不直接控制姿态。"},{"id":339,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行员操纵方向舵时，飞行器将绕（）。","A":"横轴运动","B":"纵轴运动","C":"立轴运动","D":"以上均不正确","answer":"C","exp":"方向舵偏转产生侧向气动力，对重心形成偏航力矩，使飞行器绕立轴（垂直轴）转动改变机头方向；绕横轴的俯仰由升降舵控制，绕纵轴的横滚由副翼控制，三轴分别对应三大操纵面，是固定翼气动操纵的基本对应关系。"},{"id":340,"type":"single","cat":"基础概念","stem":"旋翼水平铰的作用（）。","A":"自动调节桨叶升力变化，消除侧倾力矩","B":"使桨叶拉力发生周期性变化，也会使桨叶根部受到的弯矩发生周期性变化","C":"产生自下而上的挥舞相对气流，这会使桨叶迎角减小，拉力减小","D":"以上均不正确","answer":"A","exp":"旋翼的水平铰（挥舞铰）允许桨叶上下挥舞：前进侧相对气流大，桨叶上挥使迎角减小，后退侧相反，从而自动调节两侧桨叶的升力差异，消除横侧不平衡引起的侧倾力矩；根部弯矩的周期变化只是挥舞的伴生现象，并非设置水平铰的目的。"},{"id":341,"type":"single","cat":"操纵与飞行技术","stem":"着陆目测是驾驶员驾驶员对飞机飞行高度和降落点进行目视判断，对于目测质量的评判为（）。","A":"飞机没有达到目测接地范围就接地的，叫目测低","B":"飞机没有达到目测接地范围就接地的，叫目测高","C":"飞机超过目测接地范围才接地的，叫目测低","D":"以上均不正确","answer":"A","exp":"着陆目测是飞手对飞行高度和降落点的目视判断，评判看接地位置：飞机尚未到达目测接地范围就接地，说明下滑轨迹偏低，称为目测低；超过接地范围才接地则称为目测高，两者反映目视判断与实际下滑点的偏差方向，低与高不能颠倒。"},{"id":342,"type":"single","cat":"电力巡检","stem":"巡检作业前，根据相应（）和巡检任务编制无人直升机巡检作业指导书。","A":"性能","B":"机型","C":"航程","D":"载荷","answer":"B","exp":"无人直升机巡检作业前，应依据所用机型的性能特点和巡检任务要求编制作业指导书，明确航线、高度、速度、安全措施和应急处置流程，使作业有章可循；机型是编制的基础依据，仅凭性能、航程或载荷等单项参数无法支撑完整作业方案。"},{"id":343,"type":"single","cat":"设备与维护","stem":"遥控器开机以后检查哪几项？（）","A":"电压、模型名称、混控","B":"电压、模型类型、发射制式、中立微调","C":"电压、混控、大小舵","D":"以上均不正确","answer":"B","exp":"遥控器开机后应逐项核对电压是否满足飞行要求、模型类型是否与实际机型一致、发射制式是否与接收机匹配，并将中立微调归零，保证各通道操纵基准正确。模型名称、混控等并非每次开机必查的校准项，容易误选。"},{"id":344,"type":"single","cat":"基础概念","stem":"现有脉冲宽度调制（PWM）信号波的周期为10ms，高电平的持续时间为4ms，其占空比为（）。","A":"0.2","B":"0.4","C":"0.6","D":"0.8","answer":"B","exp":"占空比是一个周期内高电平持续时间与周期的比值，即4毫秒除以10毫秒等于0.4，它反映信号有效电平所占时间比例，是电调、舵机依据脉宽判定控制量的依据。0.2、0.6、0.8都是未按这一定义正确相除得出的结果。"},{"id":345,"type":"single","cat":"设备与维护","stem":"发射机的天线是可调整的，飞行过程中若天线直接对着无人机，这可能会（）接收机信号强度。","A":"增强","B":"过滤","C":"屏蔽","D":"减弱","answer":"D","exp":"鞭状天线信号最强的方向在天线侧面即垂直于天线的方向，天线末端指向的轴向方向信号最弱。飞行中若把发射天线直接对准无人机，等于用信号最弱的方向朝向接收机，会明显减弱信号强度甚至导致失控，天线侧面朝向飞机才是正确做法。"},{"id":346,"type":"single","cat":"设备与维护","stem":"长时间不用时应把电池放在阴凉且干燥的地方保存，电池每隔大约3个月或经过约（）次充放电后，需进行一次完整的充电和放电过程再保存，以保证电池的最佳工作状态。","A":"50","B":"20","C":"40","D":"30","answer":"D","exp":"锂聚合物电池长期存放应置于阴凉干燥处并保存至储存电压，每隔约3个月或累计约30次充放电后，进行一次完整的充放电循环再存放，以保持电芯活性、防止电芯老化失衡，维持最佳工作状态。20、40、50次都不是推荐的保养周期。"},{"id":347,"type":"single","cat":"设备与维护","stem":"多轴飞行器飞控计算机的功能不包括（）。","A":"稳定飞行器姿态","B":"接收地面控制信号","C":"导航","D":"以上均不正确","answer":"B","exp":"飞控计算机的核心功能是稳定飞行器姿态并完成导航解算，控制飞行轨迹。接收地面控制信号属于遥控接收机和数据链路的职责，信号先被接收机接收，再交由飞控解算执行，这一接收环节不属于飞控计算机自身的功能。"},{"id":348,"type":"single","cat":"基础概念","stem":"以下（）不属于固定翼无人机的机电系统。","A":"螺旋桨","B":"电调","C":"伺服机构","D":"配电系统","answer":"C","exp":"固定翼无人机的机电系统涵盖动力与电气部分，螺旋桨、电调、配电系统分别承担产生动力、调节电机功率和分配电能的职责。伺服机构是操纵舵面的执行部件，归入操纵执行环节，不属于机电系统范畴。"},{"id":349,"type":"single","cat":"设备与维护","stem":"飞控系统的核心是（）。","A":"主控制模块","B":"信号调理及接口模块","C":"数据采集模块","D":"舵机驱动模块","answer":"A","exp":"飞控系统由主控制模块、信号调理及接口模块、数据采集模块和舵机驱动模块等组成。主控制模块负责传感器数据融合与控制律解算，输出控制指令，是整个飞控系统的核心；其余模块只承担信号采集、调理与执行驱动的辅助功能。"},{"id":350,"type":"single","cat":"操纵与飞行技术","stem":"任务分配提供可用的无人机资源和着陆点的显示，辅助操作人员进行（）。","A":"载荷规划、通信规划和目标分配","B":"链路规划、返航规划和载荷分配","C":"任务规划、返航规划和载荷分配","D":"以上均不正确","answer":"A","exp":"任务分配环节向操作人员提供可用无人机资源和着陆点的显示，据此进行载荷规划、通信规划和目标分配，使任务载荷与平台资源、通信手段合理匹配。链路规划、返航规划属于后续航迹设计阶段的内容，不在任务分配的辅助范围之内。"},{"id":351,"type":"single","cat":"电力巡检","stem":"无人直升机巡检系统应定置存放，并由（）管理。","A":"无人机班组","B":"输电运检部门","C":"专人","D":"仓库管理员","answer":"C","exp":"无人直升机巡检系统是价值高、操作要求严的专业设备，应定置存放在指定位置，并由专人负责保管、维护和领用登记，做到状态受控、责任到人。交由无人机班组、输电运检部门或仓库管理员兼管，容易责任不清、保管不善。"},{"id":352,"type":"single","cat":"操纵与飞行技术","stem":"已知一款多旋翼为四旋翼设计，推重比为2，单电机最大推力为3kg，其标准起飞重量是多少kg（）。","A":"8","B":"7","C":"6","D":"4","answer":"C","exp":"推重比是最大总推力与起飞重量之比。四旋翼四台电机最大总推力为3×4=12千克，推重比为2，标准起飞重量=12÷2=6千克，留有足够的机动和抗风裕度。8千克、7千克都未按总推力与推重比的关系换算。"},{"id":353,"type":"single","cat":"操纵与飞行技术","stem":"微型无人机，是指空机重量小于（）千克，设计性能同时满足飞行真高不超过（）米、最大飞行速度不超过（）千米/小时、无线电发射设备符合微功率短距离无线电发射设备技术要求的遥控驾驶航空器。","A":"4，20，40","B":"0.25，50，40","C":"0.25，20，40","D":"4，50，40","answer":"B","exp":"微型无人机指空机重量小于0.25千克，且飞行真高不超过50米、最大飞行速度不超过40千米/小时、无线电符合微功率短距离技术要求的遥控驾驶航空器。0.25千克是微型与轻型的重量分界，4千克是轻型的空机重量界限，注意区分。"},{"id":354,"type":"single","cat":"基础概念","stem":"开展无人机作业，风力应不大于（）级。","A":"4","B":"5","C":"6","D":"7","answer":"B","exp":"无人机作业对风敏感，一般要求作业时风力不大于5级。风级过大时飞行姿态晃动加剧、悬停漂移、耗电明显增加，抗风能力接近极限容易失控坠机。认为6级、7级仍可作业，高估了多旋翼的抗风性能，存在安全隐患。"},{"id":355,"type":"single","cat":"基础概念","stem":"关于温度对多旋翼飞行器的影响，以下错误的是？（）","A":"低温环境下电池需要保温","B":"低温环境下飞行器IMU需要预热","C":"温环境会导致电池、电机发热加剧，从降低飞行效率","D":"温对飞行器没有任何影响","answer":"D","exp":"低温会使锂电池容量和放电能力下降，需要保温，飞控的IMU在低温下也应预热以减小漂移；高温则使电池、电机发热加剧，降低飞行效率，还可能触发过热保护。高温对飞行器同样有明显影响，说没有任何影响是错误的。"},{"id":356,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，收油门的基本要领是（）。","A":"跟着感觉操作","B":"适时、柔和","C":"适时、快速","D":"以上均不正确","answer":"B","exp":"着陆收油门的基本要领是适时、柔和：接地前适时收光油门让飞机平缓下沉，动作柔和避免突然失速。收得过快过猛会导致飞机下沉过快造成重着陆，收得过晚会平飘过远偏离接地点，凭感觉操作缺乏要领规范。"},{"id":357,"type":"single","cat":"基础概念","stem":"6045R螺旋桨，45什么意思，是CW桨还是CCW桨？（）","A":"螺距、正桨","B":"螺距、反桨","C":"直径、反桨","D":"以上均不正确","answer":"B","exp":"螺旋桨型号6045R中，前两位60表示桨直径为6英寸，后两位45表示螺距为4.5英寸，即桨旋转一圈理论上前进的距离；后缀R表示反桨，与正桨配套安装到转向相反的电机上。45不是直径数值，带R也不是正桨。"},{"id":358,"type":"single","cat":"基础概念","stem":"随着飞行控制系统能力的不断提升，（）的作用越来越小。","A":"电气系统","B":"遥控系统","C":"飞行控制系统","D":"动力系统","answer":"B","exp":"随着飞控系统能力不断提升，无人机越来越多地依靠自主导航和程序控制完成任务，人工遥控介入的程度越来越低，遥控系统的作用随之减小。动力系统、电气系统和飞控系统是飞行的基础保障，作用并未被削弱。"},{"id":359,"type":"single","cat":"飞行原理","stem":"某多轴螺旋型号为1045，那么他的桨长（）毫米，螺距（）毫米。","A":"254,114","B":"10，45","C":"25，11","D":"11，25","answer":"A","exp":"型号1045中，前两位10表示桨直径10英寸，1英寸约25.4毫米，折合254毫米；后两位45表示螺距4.5英寸，约114毫米，即桨转一圈理论前进的距离。把10和45直接当作毫米读数会得出错误结果，关键是英寸单位换算。"},{"id":360,"type":"single","cat":"设备与维护","stem":"长期不使用电池需在多少V电压下存放？（）","A":"3.75","B":"3.65","C":"3.95","D":"3.85","answer":"D","exp":"锂电池长期存放时每片电芯电压应保持在3.85伏左右的储存电压：满电4.2伏存放会加速电芯老化，低于3.65伏存放则可能过放损伤电芯，都会缩短寿命并带来安全隐患，3.85伏左右是兼顾安全与寿命的保存电压。"},{"id":361,"type":"single","cat":"设备与维护","stem":"固定翼无人机地面控制站包括地面站电脑、（）、数据链地面终端等通讯设备，用以辅助完成路线规划任务和飞行过程的监控。","A":"服务器","B":"平板终端","C":"手机","D":"操纵手柄","answer":"D","exp":"固定翼无人机地面控制站由地面站电脑、操纵手柄和数据链地面终端等组成：电脑运行地面站软件完成路线规划与飞行监控，操纵手柄用于人工介入操纵，数据链地面终端负责与机上设备通信。服务器、平板终端、手机不是其标准通讯操纵配置。"},{"id":362,"type":"single","cat":"法规与空域","stem":"（）是为保护航空器起飞、飞行和降落安全，根据民用机场净空障碍物限制图要求划定的空间范围。","A":"机场净空区","B":"航空限制区","C":"机场限制区","D":"航空净空区","answer":"A","exp":"机场净空区是为保护航空器起飞、飞行和降落安全，依据民用机场净空障碍物限制图划定的空间范围，区内建筑物、障碍物高度和无人机活动都受到严格限制，防止障碍物侵入起降飞行走廊。航空限制区、机场限制区、航空净空区都不是规范名称。"},{"id":363,"type":"single","cat":"设备与维护","stem":"以下哪一项不属于调试飞控是的校准内容（）。","A":"磁罗盘","B":"加速度计","C":"空速计","D":"陀螺仪","answer":"C","exp":"空速计通过测量动压差获得空速，属于大气数据测量装置。飞控调试的常规校准包括陀螺仪零偏校准、加速度计水平校准和磁罗盘磁场校准，用于消除传感器误差、保证姿态与航向测量准确，空速计不在这些常规校准项目之列。"},{"id":364,"type":"single","cat":"飞行原理","stem":"增大飞机机翼的展弦比，目的是减小飞机的（）。","A":"摩擦阻力","B":"压差阻力","C":"诱导阻力","D":"以上均不正确","answer":"C","exp":"展弦比是翼展与平均气动弦长之比，增大展弦比能削弱翼尖绕流涡的影响，减小诱导阻力，滑翔机和长航时无人机因此采用大展弦比长直机翼。摩擦阻力取决于表面粗糙度，压差阻力取决于物体外形，都与展弦比关系不大。"},{"id":365,"type":"single","cat":"设备与维护","stem":"无刷电机如果遇到旋转方向相反，正确的处理方法是（）。","A":"电调与电源的连线进行对换","B":"电调与电机的连线3根中任意对换2根","C":"电调与飞控的连线进行对换","D":"以上均不正确","answer":"B","exp":"无刷电机的旋转方向由三相绕组的通电相序决定，把电调与电机之间的三根连线中任意两根对调，相序改变，电机即反向旋转。对调电调与电源连线会改变供电极性，可能损坏设备；对调电调与飞控的连线只影响信号，不能改变转向。"},{"id":366,"type":"single","cat":"航空气象","stem":"实际飞行时，使用有飞控的飞机，以起降场或视界内的某一点为（），飞机升空绕原点爬高探测云底的高度。","A":"中心","B":"参照物","C":"原点","D":"终点","answer":"C","exp":"利用有飞控的飞机探测云底高度时，以起降场或视界内某一点作为原点，操纵飞机绕该点盘旋爬高，飞机接近云底时记录的飞行真高即为云底高度。原点就是绕飞和高度测量的基准点，中心、参照物、终点都不是这一作业流程的规范叫法。"},{"id":367,"type":"single","cat":"设备与维护","stem":"IMU方向选择，即飞控安装方向选择，需要根据飞控实际的安装位置，选择正确的安装方向，错误的选择将会导致（）。","A":"起飞后向后飞","B":"起飞后向左飞","C":"起飞后向右飞","D":"严重的飞行事故","answer":"D","exp":"飞控安装方向必须根据飞控的实际安装位置正确选择，使传感器坐标系与机体坐标系一致。方向选错后姿态解算基准错误，俯仰、横滚的修正方向随之颠倒，通常导致起飞即翻覆失控等严重的飞行事故，而不是单纯向某个方向偏飞。"},{"id":368,"type":"single","cat":"领航与任务规划","stem":"无人机航迹规划需要综合应用（），以获得全面详细的无人机飞行现状以及环境信息，结合无人机自身技术指标特点，按照一定的航迹规划方法，制定最优或次优路径。","A":"导航技术、地理信息技术以及远程感知技术","B":"导航技术、航迹优化算法以及地理信息技术","C":"飞控技术、导航技术以及地理信息技术","D":"以上均不正确","answer":"A","exp":"航迹规划需掌握飞行现状与环境信息：靠导航技术确定位置，靠地理信息技术获取地形地貌等空间数据，靠远程感知技术获知区域实时状况，再结合无人机自身技术指标按规划方法生成最优或次优路径。仅靠飞控技术或算法无法获得全面环境信息。"},{"id":369,"type":"single","cat":"基础概念","stem":"固定翼无人机飞行时，出现机体晃动，此时应检查（）。","A":"电机安装角度是否有偏差","B":"螺旋桨是否完好","C":"机翼是否平衡","D":"上述部件都可能有故障，都要检查","answer":"D","exp":"固定翼飞行中机体晃动可能源于多个环节：电机安装角度偏差造成推力不对称，螺旋桨破损变形引起振动，机翼两侧不平衡导致横向摆动。这些故障的表现相近，只查一处容易漏判，应对上述部件逐一检查，综合定位晃动来源。"},{"id":370,"type":"single","cat":"飞行原理","stem":"固定翼无人机提高供升阻比的措施下列说法正确的是（）。","A":"选择平凸形翼型","B":"减小飞行速度","C":"减小展弦比","D":"设置翼梢小翼","answer":"D","exp":"翼梢小翼能阻挡上下翼面气流在翼尖的绕流，削弱翼尖涡强度，从而减小诱导阻力、提高升阻比。平凸形翼型并非普遍最优，减小飞行速度和减小展弦比都不利于提高升阻比，设置翼梢小翼才是正确有效的措施。"},{"id":371,"type":"single","cat":"飞行原理","stem":"螺旋桨叶本身是扭转的，因此桨叶角从毂轴到叶尖是变化的最大安装角或者最大桨距在（）。","A":"叶尖处","B":"桨叶中部","C":"毂轴处","D":"以上均不正确","answer":"C","exp":"螺旋桨桨叶是扭转的，为使各叶切面在不同切向速度下保持合适迎角，桨叶角从毂轴到叶尖逐渐减小：毂轴处切向速度最小，需要最大桨叶角；叶尖切向速度最大，桨叶角最小。因此最大安装角即最大桨距出现在毂轴处。"},{"id":372,"type":"single","cat":"操纵与飞行技术","stem":"四轴如何实现左转90°？（）","A":"逆时针旋转的桨加速","B":"顺时针旋转的桨减速","C":"顺时针旋转的桨加速","D":"以上均不正确","answer":"C","exp":"四旋翼依靠反扭力实现偏航：电机顺时针旋转时，机身受到的反作用力矩为逆时针方向。使顺时针旋转的桨加速，反扭力矩增大并占优，机体即绕立轴向左偏转，完成左转90度。单独加速逆时针桨会使机体向右转。"},{"id":373,"type":"single","cat":"基础概念","stem":"无人直升机或多旋翼飞行器飞行时间的含义是指（）。","A":"自旋翼机起飞离地到着陆接地的瞬间","B":"自旋翼机起飞滑跑至着陆滑跑终止的瞬间","C":"自旋翼机旋翼开始转动至旋翼停止转动的瞬间","D":"以上均不正确","answer":"C","exp":"无人直升机或多旋翼的飞行时间指自旋翼（螺旋桨）开始转动至旋翼停止转动这两个瞬间之间的时间，涵盖启动、飞行和停转全过程，是统计设备使用时间与寿命的标准口径。以离地接地或滑跑起止来计算，都不符合这一定义。"},{"id":374,"type":"single","cat":"基础概念","stem":"围绕多轴飞行器立轴的是什么运动（）。","A":"滚转运动","B":"俯仰运动","C":"偏航运动","D":"以上均不正确","answer":"C","exp":"机体坐标系中，绕纵轴的转动是滚转，绕横轴的转动是俯仰，绕立轴即垂直轴的转动是偏航。偏航只改变机头指向而不改变机体倾角，多旋翼靠反扭力差实现，固定翼靠方向舵实现。滚转、俯仰所绕的轴都不是立轴。"},{"id":375,"type":"single","cat":"领航与任务规划","stem":"“卫星接收信号强度符合要求，确认任务规划正确无误，数据上传和下传工作正常”是（）的工作内容之一。","A":"飞行器整体目视检查","B":"遥控器检査","C":"地面站检査","D":"环境与飞行场地检査","answer":"C","exp":"检查卫星接收信号强度是否符合要求、确认任务规划正确无误、验证数据上传下传工作正常，都围绕地面控制站的导航定位、任务装订和数据链路状态展开，属于地面站检查内容。机体目视检查、遥控器检查、场地环境检查都不涉及这些项目。"},{"id":376,"type":"single","cat":"领航与任务规划","stem":"机场的起落航线通常为（）航线，起落航线的飞行高度通常为（）。","A":"左，300至600米","B":"右，300至500米","C":"左，300至500米","D":"以上均不正确","answer":"C","exp":"机场起落航线通常采用左航线，即沿航线各边飞行时转弯方向都向左，起落航线的飞行高度通常为300至500米，便于管制掌握和统一运行标准。600米超出常规高度范围，右航线只在特殊情况使用，不是常规安排。"},{"id":377,"type":"single","cat":"基础概念","stem":"以下不是多轴飞行器优点的是（）。","A":"气动效率高","B":"结构简单","C":"成本低廉","D":"以上均不正确","answer":"A","exp":"多旋翼依靠旋翼直接产生升力，滑流损失大，气动效率明显低于固定翼，续航时间短是其固有短板；结构简单、成本低廉、操控方便才是它的优点。气动效率高与多旋翼的气动特点相反，不属于其优点。"},{"id":378,"type":"single","cat":"基础概念","stem":"多旋翼无人机机体平台起装载和承力的作用，加强对机体平台的检查并及时发现、正确处理裂纹，消除飞行中因机体平台振动所导致的机体平台（）风险。","A":"故障","B":"断裂","C":"变形","D":"事故","answer":"B","exp":"多旋翼机体平台承担装载和承力功能，长期振动会在应力集中处萌生裂纹，裂纹扩展会导致机体结构断裂，直接威胁飞行安全。加强机体平台检查、及时发现并正确处理裂纹，就是要消除振动导致的机体平台断裂风险，防止空中解体。"},{"id":379,"type":"single","cat":"操纵与飞行技术","stem":"电调是连接飞控与电机的部件，主要功能是接收飞控发出的信号，再将控制信号转换为（），调节电机转速，从而影响和控制飞行器的飞行状态。","A":"电压的大小","B":"电流的大小","C":"脉冲信号","D":"光波信号","answer":"B","exp":"电调接收飞控发出的控制信号，将其转换为相应大小的电流输出给电机，电流大小决定电机转速，进而改变各旋翼的升力和力矩，实现对飞行状态的调节控制。电调不是直接改变电压或输出脉冲、光波信号来驱动电机的。"},{"id":380,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼飞行器悬停时的平衡不包括（）。","A":"俯仰平衡","B":"升力平衡","C":"诱导阻力平衡","D":"以上均不正确","answer":"C","exp":"多旋翼悬停时，各旋翼升力合力与重力平衡构成升力平衡，前后、左右力矩相等构成俯仰等姿态力矩平衡，选项中俯仰平衡和升力平衡都属于悬停平衡内容。悬停气流仍存在诱导阻力，但不存在诱导阻力平衡这一说法。"},{"id":381,"type":"single","cat":"基础概念","stem":"测试多旋翼无人机的载重量是否正常，需测出多旋翼无人机的（）、基本重量。","A":"最大起飞重量","B":"负载重量","C":"任务载荷系统重量","D":"电池重量","answer":"A","exp":"判断多旋翼载重能力是否正常，需测出最大起飞重量和基本重量，两者之差即为可用载荷能力，再通过实际加载验证动力余量。只测负载重量或电池重量无法反映整机载重水平，任务载荷系统重量只是其中一部分数据。"},{"id":382,"type":"single","cat":"基础概念","stem":"固定翼无人机的方向舵负责完成无人机的（）动作。","A":"横滚","B":"俯仰","C":"偏航","D":"以上均不正确","answer":"C","exp":"常规布局固定翼的三个主舵面各司其职：升降舵控制俯仰，副翼控制横滚，方向舵装在垂尾后缘，偏转后产生侧向力形成偏航力矩，使机头左右偏转完成偏航动作。横滚和俯仰分别由副翼、升降舵负责，与方向舵无关。"},{"id":383,"type":"single","cat":"航空气象","stem":"（）包括携带的传感器类型、摄像机类型和专用任务设备类型等，规划设备工作时间及工作模式，同时需要考虑气象情况对设备的影响程度。","A":"任务规划","B":"载荷规划","C":"任务分配","D":"以上均不正确","answer":"B","exp":"载荷规划确定携带的传感器类型、摄像机类型和专用任务设备类型，安排设备工作时间及工作模式，并评估气象情况对设备工作的影响程度，保证任务载荷与飞行计划匹配。任务分配、任务规划是更宏观的环节，不含载荷设备细节安排。"},{"id":384,"type":"single","cat":"基础概念","stem":"短程无人机活动半径在（）以内。","A":"15km","B":"15-50km","C":"50-200km","D":"以上均不正确","answer":"C","exp":"按活动半径划分，短程无人机的活动半径在50至200千米范围，再往上依次为中程和远程；15千米以内属于超近程范畴，15至50千米为近程无人机的典型范围。掌握由近及远的分档界限即可正确区分各型别。"},{"id":385,"type":"single","cat":"基础概念","stem":"活塞发动机混合气过富油燃烧将引起（）的问题。","A":"发动机过热","B":"电嘴积碳","C":"发动机工作平稳，但燃油消耗量变大","D":"以上均不正确","answer":"B","exp":"活塞发动机混合气过富油时燃油过多、氧气不足，燃烧不完全，未燃碳粒沉积在电嘴上形成积碳，使火花变弱甚至断火，发动机功率下降、运转不稳。过贫油才容易引起气缸过热，富油时排烟重、油耗大。"},{"id":386,"type":"single","cat":"操纵与飞行技术","stem":"当飞机飞行时所需功率小，留空时间长的平飞速度又称为（）。","A":"直线速度","B":"经济速度","C":"续航速度","D":"最大速度","answer":"B","exp":"平飞所需功率最小时，单位时间能耗最低、留空时间最长，这一平飞速度称为经济速度，也叫久航速度，是追求最大续航时间的巡航状态。最大速度耗能最快，直线速度不是性能术语，低速平飞同样需要大攻角维持升力。"},{"id":387,"type":"single","cat":"操纵与飞行技术","stem":"无人机着陆目测须重点决断着陆方向和（）。","A":"三四转弯位置","B":"一转弯位置","C":"二转弯位置","D":"以上均不正确","answer":"A","exp":"着陆目测的核心是判断风的影响，选定着陆方向，并根据当时的高度和位置决断三转弯、四转弯的进入位置，使飞机沿正确下滑线进入跑道接地。一转弯、二转弯位于起落航线前段，位置偏差可在后续边修正，不是目测决断重点。"},{"id":388,"type":"single","cat":"基础概念","stem":"（）包括在执行任务的过程中，需要根据环境情况的变化制定一些通信任务，调整与任务控制站之间的通信方式等。","A":"目标分配","B":"链路规划","C":"通信规划","D":"以上均不正确","answer":"C","exp":"无人机执行任务中环境变化会影响数据链质量，通信规划的内容就是根据环境变化制定相应的通信任务，适时调整与任务控制站之间的通信方式、频段和中继关系，保证链路畅通。链路规划侧重整体链路资源安排，目标分配针对任务目标本身。"},{"id":389,"type":"single","cat":"基础概念","stem":"对装备定距螺旋桨的活塞发动机，通常用来反映功率的仪表的是（）。","A":"进气压力表","B":"转速表","C":"燃油流量表","D":"以上均不正确","answer":"B","exp":"装备定距螺旋桨时桨叶角固定，发动机功率与转速一一对应，转速越高功率越大，转速表因此成为反映功率的主要仪表。进气压力表用于变距螺旋桨场合间接反映功率，燃油流量表只反映耗油情况，都不能直接表征输出功率。"},{"id":390,"type":"single","cat":"领航与任务规划","stem":"无人机任务规划需要实现的功能包括（）。","A":"自主导航功能，应急处理功能，航迹规划功能","B":"任务分配功能，航迹规划功能，仿真演示功能","C":"自主导航功能，自主起降功能，航迹规划功能","D":"以上均不正确","answer":"B","exp":"无人机任务规划系统需实现任务分配、航迹规划和仿真演示等功能：任务分配将资源与目标合理匹配，航迹规划生成满足约束的飞行路径，仿真演示在地面预先验证方案可行性。自主导航、自主起降属于飞控的执行功能，不在任务规划功能之列。"},{"id":391,"type":"single","cat":"领航与任务规划","stem":"360°圆周航线飞行训练科目中，操作无人机在姿态模式下，完成360°圆周航线飞行，在飞行过程中每两个航点之间的垂直误差不大于±（）cm。","A":"10","B":"30","C":"50","D":"100","answer":"B","exp":"圆周航线训练要求在姿态模式下匀速完成360度盘旋，考核姿态与油门的协调操纵精度，按训练考核标准，相邻两个航点之间的垂直误差应不大于正负30厘米。10厘米过于苛刻，50厘米和100厘米都超出允许误差范围。"},{"id":392,"type":"single","cat":"设备与维护","stem":"以下地面链路天线哪一种是定向天线（）。","A":"八木天线","B":"鞭状天线","C":"三叶草天线","D":"以上均不正确","answer":"A","exp":"八木天线由有源振子和引向器、反射器组成，能量集中指向单一方向，增益高，是典型的定向天线，常用于地面站对空数据链。鞭状天线和三叶草天线在水平面内近似均匀辐射，属于全向天线，适合近距离全方位通信。"},{"id":393,"type":"single","cat":"法规与空域","stem":"无人机系统（），由运营人指派对无人机的运行负有必不可少责任并在飞行期间适时操纵无人机的人。","A":"安全员","B":"驾驶员","C":"机长","D":"观测员","answer":"B","exp":"无人机驾驶员是由运营人指派、对无人机运行负有必不可少责任并在飞行期间适时操纵无人机的人。机长对整个飞行活动全面负责并统领机组，观测员负责目视观察飞行状态，安全员不是这一操纵岗位的定义主体。"},{"id":394,"type":"single","cat":"航空气象","stem":"气压计是反映无人机的什么物理量？（）","A":"速度","B":"高度","C":"温度","D":"以上均不正确","answer":"B","exp":"气压高度计利用大气压强随高度升高而降低的规律，通过测量静压换算出飞行高度，是飞控获取高度信息、实现定高与高度保持的主要传感器。气压计不能直接测量速度和温度，空速由空速计测量，温度另有温度传感器。"},{"id":395,"type":"single","cat":"领航与任务规划","stem":"以下正确的任务规划流程是（）。","A":"接受任务-任务理解-环境评估-任务分配-航迹规划-航迹优化-生产计划","B":"接受任务-任务理解-任务分配-环境评估-航迹规划-航迹优化-生产计划","C":"接受任务-任务理解-任务分配-航迹规划-环境评估-航迹优化-生产计划","D":"以上均不正确","answer":"A","exp":"任务规划流程为：接受任务、任务理解、环境评估、任务分配、航迹规划、航迹优化、生产计划。先理解任务，再评估环境摸清约束，随后任务分配，接着规划并优化航迹，最后形成生产计划。环境评估在任务分配、航迹规划之前，颠倒顺序即错。"},{"id":396,"type":"single","cat":"设备与维护","stem":"无人机在正常条件下使用，每飞行（）小时进行一次简易维护，包括清理机体异物（如灰尘、油泥等）。","A":"10","B":"20","C":"30","D":"40","answer":"B","exp":"无人机在正常条件下使用时，按每飞行20小时进行一次简易维护，内容包括清理机体灰尘、油泥等异物，检查紧固件和运动部件状态，防止异物积累影响气动外形和运转部件工作。10小时过于频繁，30小时、40小时的间隔又偏长。"},{"id":397,"type":"single","cat":"飞行原理","stem":"机翼的安装角是（）。","A":"翼弦与相对气流速度的夹角","B":"翼弦与机身纵轴之间所夹锐角","C":"翼弦与水平面之间所夹的锐角","D":"以上均不正确","answer":"B","exp":"机翼安装角指翼弦与机身纵轴之间所夹的锐角，反映机翼相对机身轴线的固定安装姿态，出厂时即已确定。翼弦与相对气流速度的夹角是迎角，随飞行状态不断变化；翼弦与水平面的夹角也不是安装角的定义，注意安装角与迎角的区别。"},{"id":398,"type":"single","cat":"基础概念","stem":"下列关于操作人员要求，描述错误的是（）。","A":"不可将植保无人机操作到人员正上方，不可接近飞行中的无人机","B":"植保无人机提示需磁罗盘校准时，第一时间进行校准","C":"飞行前8小时禁止饮酒","D":"作业区域有农户在拔草，依然继续作业","answer":"D","exp":"作业区域有农户在田里拔草时必须停止或调整作业，待人员撤离后再飞行，防止坠落伤人或喷洒物危害，继续作业是明显违反安全要求的做法。不飞到人员正上方、及时进行磁罗盘校准、飞行前8小时禁止饮酒都是规范要求。"},{"id":399,"type":"multi","cat":"基础概念","stem":"空速管安装位置一定要选在无人机外面气流受影响较小的位置，一般选择在（）。","A":"机身正上方","B":"机头正前方","C":"垂尾","D":"翼尖方向","answer":"BCD","exp":"空速管应安装在机身外气流受影响较小的位置：机头正前方处于未受扰动的来流中，垂尾前方和翼尖方向受机身干扰也较小，都能测得较真实的总压静压。机身正上方处于螺旋桨滑流和机身附面层影响区，压力测量误差大，不宜安装空速管。"},{"id":400,"type":"multi","cat":"基础概念","stem":"目前国内天气获取途径有（）。","A":"口述天气","B":"民航机场预报","C":"军用气象台站","D":"通过互联网查询气象信息","answer":"BCD","exp":"获取飞行气象资料的正规途径包括民航机场发布的机场预报、军用气象台站提供的观测和预报资料，以及通过互联网查询气象部门发布的天气信息，这些来源权威且更新及时。口述天气缺乏客观观测依据，不能作为飞行决策的气象来源。"},{"id":401,"type":"multi","cat":"领航与任务规划","stem":"从实施时间上分，任务规划可以分为（）。","A":"预先规划","B":"航迹规划","C":"载荷规划","D":"实时规划","answer":"AD","exp":"按实施时间划分，任务规划分为预先规划和实时规划：预先规划在起飞前完成，确定任务方案和航迹；实时规划在飞行中根据态势变化动态调整路径。航迹规划、载荷规划是按规划内容划分的类别，与实施时间分类不是同一维度。"},{"id":402,"type":"multi","cat":"基础概念","stem":"无人机遥感系统可完成对水土流失的（）等的实时动态监测。","A":"成因","B":"强度","C":"影响范围","D":"防治成效","answer":"ABCD","exp":"无人机遥感分辨率高、机动灵活，可对水土流失开展实时动态监测：通过多期影像对比分析流失成因，评估流失强度，圈定影响范围，并检验治理措施的防治成效。四个方面都依托高分辨率遥感影像实现，均属其监测内容。"},{"id":403,"type":"multi","cat":"基础概念","stem":"对流层的主要特征（）。","A":"气温随高度升高而升高","B":"气温、湿度的水平分布很不均匀","C":"空气具有强烈的垂直混合","D":"气流混乱","answer":"BC","exp":"对流层的主要特征：气温随高度升高而降低而不是升高，气温、湿度的水平分布很不均匀，空气具有强烈的垂直混合作用，云雨雾等天气现象都发生在这一层。气流混乱不是规范的气象学术语，气温随高度升高是逆温的特征。"},{"id":404,"type":"multi","cat":"设备与维护","stem":"无人直升机电池不应（）等，电源正负极标识清晰正确，接头有防松措施，宜使用防误插接头","A":"变形","B":"表面有针眼","C":"碰磕","D":"裂纹","answer":"ABCD","exp":"无人直升机电池应保持完好：外壳不应有变形、裂纹和表面针眼，也不应受到碰磕撞击，这些缺陷都会损伤电芯结构，带来鼓包、漏液甚至起火隐患。同时电源正负极标识要清晰正确，接头应有防松措施，宜使用防误插接头。"},{"id":405,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人直升机巡检系统》中，中型无人直升机巡检系统应装有（）的航行灯。","A":"左红","B":"右绿","C":"尾白","D":"左绿","answer":"ABC","exp":"参照《架空输电线路无人直升机巡检系统》的规定，中型无人直升机巡检系统应装有左红、右绿、尾白的航行灯，与航空界航行灯布置惯例一致，便于夜间判别机体方位与运动方向。左绿与右红与此惯例相反，属于错误布置。"},{"id":406,"type":"multi","cat":"基础概念","stem":"（）是常规布局的飞机主要舵面。","A":"升降舵","B":"襟翼","C":"方向舵","D":"副翼","answer":"ACD","exp":"常规布局飞机的主要舵面是升降舵、方向舵和副翼：升降舵操纵俯仰，方向舵操纵偏航，副翼操纵横滚，三者配合完成姿态控制。襟翼位于机翼后缘，放下后增大升力改善起降性能，属于增升装置而非主操纵舵面。"},{"id":407,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆分为哪几个阶段？（）","A":"下滑","B":"拉平","C":"平飘接地","D":"着陆滑跑","answer":"ABCD","exp":"无人机着陆按高度和速度的消耗依次分为下滑、拉平、平飘接地、着陆滑跑四个阶段：先沿下滑线下滑减高减速，接近地面时拉平转入平飞，随后平飘缓慢下沉接地，接地后滑跑减速直至停止，四个阶段依次衔接构成完整着陆过程。"},{"id":408,"type":"single","cat":"电力巡检","stem":"巡检作业区域出现雷雨、（）等突变天气或空域许可情况发生变化时，应采取措施控制无人直升机返航或就近降落。","A":"低温","B":"大雾","C":"高温","D":"大风","answer":"D","exp":"巡检区域出现雷雨、大风等突变天气时，强风和雷暴直接威胁飞行安全，应立即采取措施控制无人直升机返航或就近降落，脱离危险天气影响。大雾影响能见度但发展较缓，低温高温属渐进环境因素，突变性和危害都不及大风突出。"},{"id":409,"type":"single","cat":"基础概念","stem":"螺旋桨安装在电动机上，多旋翼无人机安装的都是（）的螺旋桨。","A":"不可变","B":"可变","C":"可变总距","D":"不可变总距","answer":"D","exp":"多旋翼靠改变电机转速调节升力和力矩，螺旋桨桨距固定，安装的都是不可变总距的定距螺旋桨，结构简单可靠。可变总距桨用在有人直升机等场合，通过总距杆直接改变桨叶角，多旋翼通常不采用这种复杂机构。"},{"id":410,"type":"single","cat":"法规与空域","stem":"空域管理的具体办法由（）制定。","A":"中国民用航空局","B":"中共中央军事委员","C":"中华人民共和国国务院和中共中央军事委员会","D":"机场塔台","answer":"C","exp":"空域管理涉及国家安全和军民航协调，依照国家飞行管理法规，空域管理的具体办法由国务院和中央军事委员会制定发布。中国民用航空局和机场塔台只是执行层面的管理与运行机构，无权制定空域管理的具体办法。"},{"id":411,"type":"single","cat":"领航与任务规划","stem":"已经实际飞行的航线应及时存档，并标注（）信息。","A":"区域坐标","B":"任务区域","C":"特殊区段","D":"警示区域","answer":"C","exp":"已经实际飞行的巡检航线应及时存档，作为后续复飞的基础数据，并标注航线上的特殊区段，如交叉跨越段、缺陷集中段等，便于再次飞行时重点关注和比对。区域坐标、任务区域属于规划阶段信息，警示区域不是航线存档的必标内容。"},{"id":412,"type":"single","cat":"基础概念","stem":"（）无人机侦察监测区域应预先标注，主要包括任务区域范围，侦察监测范围对象等。","A":"场地标注","B":"任务区域标注","C":"警示标注","D":"以上均不正确","answer":"B","exp":"无人机侦察监测任务执行前，应在电子地图上进行任务区域标注，内容包括任务区域的范围、侦察监测的对象等，使航线和任务目标明确清晰，便于执行和检查。场地标注针对起降场地，警示标注针对危险警告区域，均非这一用途。"},{"id":413,"type":"single","cat":"领航与任务规划","stem":"航向角是飞行器（）在水平面的投影与指北线之间的夹角。","A":"纵轴","B":"横轴","C":"立轴","D":"经线","answer":"A","exp":"航向角是机体纵轴在水平面上的投影与指北线之间的夹角，反映机头指向相对正北的方位，由磁罗盘和导航解算提供，是航线飞行控制的重要基准。横轴、立轴对应的投影夹角属于姿态角范畴，经线是地理概念不是机体轴。"},{"id":414,"type":"single","cat":"飞行原理","stem":"固定翼型无人机机体主要由机身及机翼、起落架、（）、螺旋桨、油箱、机上飞行控制系统等组成。","A":"发动机","B":"操作手柄","C":"备件","D":"飞控计算机","answer":"A","exp":"固定翼无人机机体主要由机身、机翼、起落架、发动机、螺旋桨、油箱和机上飞控系统等组成，发动机是动力核心，与螺旋桨、油箱共同构成动力装置，推动飞机前飞使机翼产生升力。操作手柄属地面设备，飞控计算机已单独列出。"},{"id":415,"type":"single","cat":"操纵与飞行技术","stem":"维修无人机飞行控制系统（自驾仪）系统时，飞行控制系统（自驾仪）尽可能安装在固定翼无人机的重心，确保自动驾驶仪上的箭头的方向（）。","A":"向上","B":"向下","C":"无人机朝前的方向相同","D":"无人机朝前的方向相反","answer":"C","exp":"固定翼自驾仪应尽可能安装在重心附近，安装时必须保证自驾仪上的箭头方向与无人机机头朝前的方向相同，使传感器敏感轴与机体坐标系对齐，姿态和航向解算才准确。箭头朝上、朝下或朝后都会造成坐标系错位，修正方向出错。"},{"id":416,"type":"single","cat":"操纵与飞行技术","stem":"（）的主要功用是支持飞机在地面停放，并用于飞机的起飞和降落。","A":"起落装置","B":"螺旋桨","C":"机臂","D":"动力系统","answer":"A","exp":"起落装置的主要功用是支持飞机在地面停放和滑行，并在起飞、着陆时吸收和缓冲冲击能量，保障起降安全，常见形式有轮式起落架和滑撬。螺旋桨与动力系统产生推力，机臂是机架结构件，都不承担地面支撑缓冲功能。"},{"id":417,"type":"single","cat":"航空气象","stem":"垂起固定翼无人机电子电气部件中的飞行控制系统（自驾仪），测试内容为（）、气压计、空速计，下列选项错误的是。","A":"飞控仪本体","B":"遥控器、接收机对频","C":"相关飞控组件","D":"惯性测量单元","answer":"B","exp":"垂起固定翼电子电气部件中对飞控（自驾仪）的测试对象包括飞控仪本体、惯性测量单元、气压计、空速计及相关飞控组件，验证各部件功能正常。遥控器、接收机对频属于地面遥控链路检查环节，不属于飞控部件的测试内容，这一选项描述错误。"},{"id":418,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的飞控（自驾仪）的理想安装位置是无人机重心，若飞控（自驾仪）远离重心，将会产生（），引起加速度的测量误差，即杆臂效应。","A":"离心加速度","B":"切向加速度","C":"离心加速度和切向加速度","D":"向心加速度","answer":"C","exp":"飞控理想安装位置是无人机重心。飞控偏离重心时，机体绕重心旋转，飞控安装点除随重心平移外，还附加感受到旋转产生的离心加速度和切向加速度，使加速度计测量出现误差，即杆臂效应。只提离心或切向一种加速度都不完整。"},{"id":419,"type":"single","cat":"电力巡检","stem":"无人直升机在巡检过程中，通讯链路保持畅通的范围称（）。","A":"操控范围","B":"视距内范围","C":"无人直升机数据链范围","D":"巡检范围","answer":"C","exp":"无人直升机巡检过程中与地面站之间保持通讯链路畅通的范围称为无人直升机数据链范围，超出该范围图传数传中断，无法监控和操控。操控范围、视距内范围分别指人的操纵能力和肉眼可见范围，巡检范围指作业区域，都不是链路概念。"},{"id":420,"type":"single","cat":"基础概念","stem":"多旋翼设计上反角的作用是（）。","A":"机动","B":"稳定","C":"省电","D":"以上均不正确","answer":"B","exp":"上反角使桨臂或机翼向上倾斜，作用是增强横向稳定性：机体受扰倾斜后，左右两侧拉力或升力出现差异，产生自动恢复原姿态的力矩，抑制滚转发散，使飞行更平稳。上反角不提供机动能力，也不直接节省电能，核心价值在于稳定。"},{"id":421,"type":"single","cat":"飞行原理","stem":"固定翼型无人机通过（）和机翼的滑行实现起降和飞行，遥控飞行和程控飞行均容易实现。","A":"电气系统","B":"动力系统","C":"机身","D":"飞控","answer":"B","exp":"固定翼无人机依靠动力系统产生拉力或推力获得前进速度，机翼在相对气流中产生升力，达到起飞速度后离地，起降和飞行建立在动力系统与机翼滑行结合的基础上，遥控飞行和程控飞行均易实现。电气、飞控系统属保障环节，机身是结构载体。"},{"id":422,"type":"single","cat":"基础概念","stem":"小型无人机，是指空机质量小于等于（）千克的无人机，微型和轻型无人机除外。","A":"116","B":"5700","C":"1260","D":"以上均不正确","answer":"B","exp":"按民用无人驾驶航空器管理规定，空机质量不超过5700千克、又不属于微型和轻型的无人机划为小型，空机质量大于5700千克的属大型，5700千克是大小型的分界数值。116、1260等数值与该分类界限无关，不要混淆记忆。"},{"id":423,"type":"single","cat":"操纵与飞行技术","stem":"启动发动机时，遥控器的油门杆应置于（）。","A":"高速位置","B":"怠速位置","C":"中速位置","D":"以上均不正确","answer":"B","exp":"启动发动机前应将遥控器油门杆置于怠速位置，使发动机以最小风门起动，避免一启动就进入大功率状态导致飞机窜动伤人；怠速状态也便于观察运转是否平稳，确认正常后再缓慢加大油门。高速或中速位起动缺乏安全裕度。"},{"id":424,"type":"single","cat":"领航与任务规划","stem":"无人机任务规划是实现（）的有效途径，它在很大程度上决定了无人机执行任务的效率。","A":"自主导航与飞行控制","B":"飞行任务与载荷匹配","C":"航迹规划与自主导航","D":"以上均不正确","answer":"A","exp":"任务规划把任务要求转化为可执行的航迹和动作序列，上传后由飞控自主执行，是实现无人机自主导航与飞行控制的有效途径，在很大程度上决定执行任务的效率。载荷匹配、航迹规划只是任务规划内部的环节，不是其整体定位。"},{"id":425,"type":"single","cat":"基础概念","stem":"无人机怎么飞最省油或最省电？（）","A":"匀速","B":"高速","C":"底速","D":"以上均不正确","answer":"A","exp":"匀速飞行时推力只需平衡稳定的阻力，功率输出平稳，推进系统工作在较高效率区，单位距离能耗最低；忽快忽慢需频繁加速消耗额外能量，高速飞行阻力随速度急剧增大，过低速度又要大攻角维持升力，都更费油费电。"},{"id":426,"type":"single","cat":"基础概念","stem":"地面与通信车之间的交流电压为220V，经整流、滤波等一系列处理之后成为近（）的高压直流电，通过系留电缆输送至无人机。","A":"600V","B":"400V","C":"500V","D":"450V","answer":"B","exp":"系留无人机由地面交流电源供电，220伏交流电经整流、滤波和功率变换等处理成为接近400伏的高压直流电，经系留电缆输送至无人机，提高输电效率、降低线路损耗。600伏、500伏、450伏不符合该系统的典型电压设计。"},{"id":427,"type":"single","cat":"基础概念","stem":"多旋翼飞行器在运输过程中的注意事项是（）。","A":"做好减震措施，固定云台并安装云台固定支架，装箱运输","B":"可随意拆装运输","C":"装箱运输，也可行李箱运输","D":"以上均不正确","answer":"A","exp":"多旋翼运输时应做好减震措施，将云台固定并安装云台固定支架后装箱运输，防止运输颠簸震动损坏云台相机、电机和桨叶等部件。随意拆装运输容易丢失零件、装错线缆，普通行李箱缺乏缓冲固定，均不符合设备运输要求。"},{"id":428,"type":"single","cat":"基础概念","stem":"下面哪个单位领导全国的飞行管制工作（）。","A":"国务院","B":"民航局","C":"国务院﹑中央军委空中交通管制委员会","D":"中央军委","answer":"C","exp":"全国飞行管制工作由国务院、中央军事委员会空中交通管制委员会领导，该机构统一领导全国飞行管制和空域协调工作。国务院、中央军委单独作为领导主体不完整，民航局负责民用航空行业管理，都不是该领导体制的正确表述。"},{"id":429,"type":"single","cat":"设备与维护","stem":"铰接式旋翼在吹风挥舞时，旋翼每转一周，桨叶挥舞速度和挥舞角分别出现一次周期性变化下面正确的是（）。","A":"挥舞角的变化比挥舞速度的变化滞后90°","B":"桨叶在90°方位下挥速度最大，在270°方位上挥速度最大","C":"桨叶在180°方位挥舞最低，在360°方位挥舞最高","D":"以上均不正确","answer":"A","exp":"铰接式旋翼桨叶绕水平铰吹风挥舞，每转一周，挥舞速度和挥舞角各出现一次周期性变化；由于桨叶具有惯性，挥舞角的变化比挥舞速度的变化滞后90度方位角，这一相位关系是分析旋翼挥舞运动的基础，各方位出现最大值的表述与此不符。"},{"id":430,"type":"single","cat":"操纵与飞行技术","stem":"姿态传感器应安装在无人机（）附近，振动要尽可能的小，有较高的安装精度要求。","A":"中心","B":"重心","C":"焦点","D":"以上均不正确","answer":"B","exp":"姿态传感器应安装在无人机重心附近，机体转动时传感器与重心距离最小，附加的离心和切向加速度影响最小，能减小杆臂效应带来的测量误差；安装处振动要尽可能小并保证较高安装精度，避免振动干扰姿态解算。中心、焦点不是力学测量基准。"},{"id":431,"type":"single","cat":"领航与任务规划","stem":"应急航线的主要目的是确保飞机安全返航，规划一条安全返航通道和（），以及（）。","A":"应急迫降点，安全返航策略","B":"应急迫降点，航线转移策略","C":"安全着陆点，安全着陆策略","D":"以上均不正确","answer":"B","exp":"应急航线的主要目的是确保飞机安全返航，规划内容包括一条安全返航通道、通道沿线的应急迫降点，以及航线转移策略，即在返航过程中把飞机从当前航线切换到应急航线的方法。安全着陆点与安全着陆策略的组合没有涵盖航线切换这一关键环节。"},{"id":432,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器姿态数据中，“H.S”代表什么？（）","A":"飞行器与起飞点之间的相对度","B":"飞行器与起飞点之间的水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平方向的飞行速度","answer":"D","exp":"大疆飞行器姿态数据中，H.S是Horizontal Speed的缩写，表示飞行器沿水平方向的飞行速度；D.H是与起飞点的水平距离，H是相对起飞点的高度，V.S是垂直方向的升降速度。掌握缩写全称即可区分这些姿态参数。"},{"id":433,"type":"single","cat":"领航与任务规划","stem":"（）在无人机任务规划中的作用是显示无人机的飞行位置、画出飞行航迹、标识规划点以及显示规划航迹等。","A":"电子地图","B":"飞行航迹","C":"地理位置","D":"以上均不正确","answer":"A","exp":"电子地图是任务规划的可视化基础：在地图上显示无人机实时飞行位置，画出已飞航迹，标识规划点并显示规划航迹，操作人员据此直观掌握任务全局与飞行进程。飞行航迹、地理位置只是地图上呈现的内容要素，不是承载这些功能的平台。"},{"id":434,"type":"single","cat":"飞行原理","stem":"无人直升机的基本结构一般包括：机身、主旋翼、尾桨、操作系统、传动系统、电动机或发动机和（）。","A":"起落架","B":"起落台","C":"遥控器","D":"赛道","answer":"A","exp":"无人直升机基本结构一般包括机身、主旋翼、尾桨、操作系统、传动系统、发动机或电动机和起落架：主旋翼产生升力与操纵力，尾桨平衡反扭力并操纵航向，起落架支持地面停放和起降。起落台、赛道不是航空器结构术语，遥控器属地面设备。"},{"id":435,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的动力电机调速不采用（）的方法调速。","A":"电枢供电电压","B":"改变电机主磁通","C":"改变电枢回路总电阻","D":"改变外接电阻","answer":"D","exp":"直流电机调速的三种经典途径是改变电枢供电电压、减弱电机主磁通、改变电枢回路总电阻，多旋翼电调正是通过调节电枢供电电压实现无级调速。单纯改变外接电阻只是串接电阻消耗能量、发热严重，不属于电机调速采用的方法。"},{"id":436,"type":"single","cat":"设备与维护","stem":"遥控接收机连接在飞行控制器上，没有输出遥控信号，此时应检查（）。","A":"飞控电源电压是否为5V","B":"飞控电源电压是否为9V","C":"飞控电源电压是否为11.3V","D":"飞控电源电压是否为14.8V","answer":"A","exp":"遥控接收机通常由飞控输出的5伏电源供电，接收机无遥控信号输出时，应先检查飞控电源电压是否为正常的5伏，电压缺失或偏低会导致接收机无法工作。9伏、11.3伏、14.8伏是锂电池组的电压等级，不是接收机供电标准。"},{"id":437,"type":"single","cat":"操纵与飞行技术","stem":"电动无人驾驶航空器的动力系统主要有（）、电池组、电子调速器和螺旋桨组成。","A":"减震器","B":"电池电压检测器","C":"电动机","D":"飞控系统","answer":"C","exp":"电动动力系统由电动机将电能转为机械能并带动螺旋桨产生拉力，电池组提供电能、电调控制电机转速，四者构成完整动力链路。飞控系统负责姿态与导航控制，属于控制部分而非动力系统，最易误选。"},{"id":438,"type":"single","cat":"基础概念","stem":"高原地区16*8两叶、17*6两叶、15*5三叶，灵活性最好的是哪一个，最省电是哪一个？（）","A":"灵活：15*5三叶；最省：17*6两叶","B":"灵活：16*8两叶；最省：17*6两叶","C":"灵活：15*5三叶；最省：16*8两叶","D":"以上均不正确","answer":"A","exp":"15×5三叶桨直径小、转动惯量小，升力响应快、操纵灵敏，灵活性最好；17×6两叶桨桨盘面积大、诱导功率损失小，气动效率高最省电，高原空气稀薄更需要大桨盘补偿升力。16×8两叶桨尺寸居中，灵活性与经济性都不占优。"},{"id":439,"type":"single","cat":"航空气象","stem":"飞机上产生的摩擦阻力与大气的哪种物理性质有关（）。","A":"可压缩性","B":"粘性","C":"温度","D":"以上均不正确","answer":"B","exp":"空气具有粘性，气流贴附机体表面形成附面层，层内速度梯度产生内摩擦力，其合力即摩擦阻力，故摩擦阻力源于大气的粘性。可压缩性主要影响高速飞行的波阻，温度只是影响粘性大小的环境因素，并非直接成因。"},{"id":440,"type":"single","cat":"基础概念","stem":"无人机分类的方法多种多样，其中通常所说的固定翼无人机、多旋翼无人机、无人直升机是按照（）的方法来分类的。","A":"动力及能源","B":"控制方式","C":"平台结构","D":"续航时间","answer":"C","exp":"固定翼、多旋翼、无人直升机的区别在于升力产生部件与气动构型不同，属于按平台结构分类；按动力及能源可分油动、电动，按控制方式分遥控与自主，这些分类标准都不以机翼或旋翼形式为依据。"},{"id":441,"type":"single","cat":"领航与任务规划","stem":"航迹优化是指航迹规划完成后，系统根据无人机飞行的（）对航迹进行优化处理，制定出适合无人机飞行的航迹。","A":"最大转弯半径和最大俯仰角","B":"最小转弯半径和最大俯仰角","C":"最大转弯半径和最小俯仰角","D":"以上均不正确","answer":"B","exp":"航迹优化按无人机的机动能力约束平滑已规划航迹：水平转弯受最小转弯半径限制，转弯半径小于它飞机就转不过来；垂直面内升降受最大俯仰角限制。用最大转弯半径作约束过松，无法保证航迹可飞且贴合实际性能。"},{"id":442,"type":"single","cat":"基础概念","stem":"起降点四周（）条件应良好，满足安全起降要求。","A":"起降","B":"作业","C":"飞行","D":"净空","answer":"D","exp":"起降点四周要求净空条件良好，即周边无树木、电线、建筑等障碍物侵入起降剖面，进离场空域畅通，这是安全起降的基本前提。起降、作业、飞行描述的是活动状态，都不是描述周边障碍环境的规范用词。"},{"id":443,"type":"single","cat":"基础概念","stem":"模型飞机使用的双向对称线性热收缩聚酯薄膜，通常称为（），是轻型高强度、高收缩性双向拉伸聚酯薄膜。","A":"热缩薄膜","B":"双向薄膜","C":"线性薄膜","D":"聚酯薄膜","answer":"A","exp":"该蒙皮遇热即收缩绷紧，是双向对称、线性收缩的热塑性聚酯薄膜，业内通称热缩薄膜，具有轻质高强度、高收缩率的特点，熨烫后蒙面平整光洁，是模型飞机常用蒙皮材料。其余叫法都不是这一材料的惯用名称。"},{"id":444,"type":"single","cat":"基础概念","stem":"远程无人机活动半径在（）。","A":"50-200km","B":"200-800km","C":"＞800km","D":"以上均不正确","answer":"C","exp":"按活动半径划分，近程约50～200km，中程为200～800km，远程无人机航程最远，活动半径超过800km，可执行跨区域长距离任务。50～200km是近程量级，200～800km属中程范围，分界数值容易记混。"},{"id":445,"type":"single","cat":"操纵与飞行技术","stem":"影响飞机俯仰平衡的力矩主要是（）。","A":"机身力矩和机翼力矩","B":"机翼力矩和垂尾力矩","C":"机翼力矩和水平尾翼力矩","D":"以上均不正确","answer":"C","exp":"俯仰是绕横轴的转动，决定俯仰平衡的主要是机翼升力形成的机翼力矩和水平尾翼升力形成的水平尾翼力矩，两者相互配平飞机才能保持俯仰平衡。垂直尾翼产生的是方向力矩，影响偏航而非俯仰，最易与之混淆。"},{"id":446,"type":"single","cat":"基础概念","stem":"以机械结构复杂性来对比，三种飞行器结构从简单到复杂排列正确的是（）。","A":"直升机、固定翼、多旋翼","B":"直升机、多旋翼、固定翼","C":"多旋翼、固定翼、直升机","D":"固定翼、直升机、多旋翼","answer":"C","exp":"多旋翼无变距机构和复杂传动，仅靠电机转速差控制，结构最简单；固定翼有舵面操纵机构但无旋翼系统，复杂程度居中；直升机需要主旋翼、自动倾斜器、尾桨及传动系统，结构最复杂，故从简单到复杂依次为多旋翼、固定翼、直升机。"},{"id":447,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，接地后跳跃的修正方法是（）。","A":"飞机跳离地面时，应稳住杆，迅速判明离地的高度和飞机状态","B":"飞机跳离地面时，应迅速拉杆，避免再次坠落弹起","C":"飞机跳离地面时，应迅速推杆，压住飞机状态","D":"以上均不正确","answer":"A","exp":"接地弹跳时正确做法是稳住杆，迅速判明跳离地面的高度和飞机姿态，再视情况柔和修正，避免盲目动作加剧跳跃。迅速拉杆会使迎角突增，落地再次弹起甚至失速；迅速推杆易使机头或前轮撞地，都会加重险情。"},{"id":448,"type":"single","cat":"电力巡检","stem":"灾情检查主要是对受灾区域内的输电线路设备状态和（）进行检查和评估。","A":"设备受损情况","B":"通道环境","C":"弧垂状态","D":"树木情况","answer":"A","exp":"灾情检查的核心是对受灾区域输电线路的设备状态和设备受损情况进行检查评估，查明受损范围与程度，为抢修恢复提供依据。通道环境、弧垂、树木属于常规巡检内容，不是灾后评估的主要对象。"},{"id":449,"type":"single","cat":"法规与空域","stem":"无人机系统的机长是指（）。","A":"协作操控无人机的人","B":"负责整个无人机系统运行和安全的驾驶员","C":"操控无人机的人","D":"以上均不正确","answer":"B","exp":"机长是对整个无人机系统运行和安全负责的驾驶员，运行期间承担指挥与安全职责，其余参与操控的人员属一般驾驶员。仅在协作中参与操控或单纯操控无人机的人不必然对整体运行安全负责，这是机长概念的关键所在。"},{"id":450,"type":"single","cat":"领航与任务规划","stem":"无人机RTK模式需要良好的卫星可见性和接收能力，维修完后不要在室内或者建筑物附近测试设备，以下哪种情况不适合测试：接收天线附近有阻挡天空视图（）。","A":"高于地平线5°的障碍物","B":"高于地平线10°的障碍物","C":"高于地平线25°的障碍物","D":"高于地平线40°的障碍物","answer":"D","exp":"RTK依靠卫星信号定位，要求接收天线天空视图开阔；障碍物高于地平线40°会大面积遮挡卫星，信号可见性严重不足，不适合测试。5°、10°的轻微遮挡影响有限，遮挡仰角越高对定位越不利。"},{"id":451,"type":"single","cat":"电力巡检","stem":"使用无人机巡检系统进行的架空线路巡检作业，作业人员包括（）和工作班成员。","A":"工作负责人","B":"监护人","C":"工作许可人","D":"无人机超控员","answer":"A","exp":"按架空输电线路无人机巡检作业安全工作规程，巡检作业人员由工作负责人和工作班成员组成，工作负责人全面负责现场组织与安全。工作许可人属于停电检修许可流程中的角色，超控员并非该规程定义的作业岗位。"},{"id":452,"type":"single","cat":"设备与维护","stem":"下面关于M600所使用电池的参数准确的是（）。","A":"6S4600MAH20CLIPO","B":"6S5700MAH20CLIPO","C":"6S6000MAH20CLIPO","D":"12S12000MAH20CLIPO","answer":"B","exp":"M600配用的智能电池为6S、5700mAh、20C放电倍率的锂聚合物电池，六节电芯串联提供约22.2V电压，容量与倍率匹配该机动力需求。4600mAh、6000mAh容量不符，12S12000mAh远超其单块电池规格。"},{"id":453,"type":"single","cat":"领航与任务规划","stem":"（）功能通常包括指挥调度、任务规划、操作控制、显示记录等功能。","A":"数据链路分系统","B":"无人机地面站系统","C":"飞控与导航系统","D":"以上均不正确","answer":"B","exp":"无人机地面站是地面对飞行器实施指挥管理的人机系统，通常包括指挥调度、任务规划、操作控制、显示记录等功能，覆盖从航线制定到飞行监控的全过程。数据链路只负责信息传输，飞控导航系统在机载端执行，均不具备这些综合功能。"},{"id":454,"type":"single","cat":"操纵与飞行技术","stem":"着陆后检查内容不包括（）。","A":"飞行器外观检查","B":"燃油动力飞行器需要称重检查","C":"气象检查","D":"以上均不正确","answer":"C","exp":"飞行结束落地后应检查飞行器外观有无损伤、结构连接是否松动，燃油动力飞行器还需称重，以核算油耗并判断供油是否正常。气象条件属于飞行前准备检查项目，落地后无需复查，因此不属于着陆后检查内容。"},{"id":455,"type":"single","cat":"基础概念","stem":"存储无人机的所有设备应装箱存放在室内，保持干燥，存储温度为（）。","A":"-40℃～50℃","B":"-50℃～60℃","C":"-30℃～60℃","D":"-40℃～60℃","answer":"D","exp":"无人机设备应装箱存放于干燥室内，按要求存储温度为-40℃～60℃，既能适应北方冬季低温，也能耐受夏季高温，是设备长期存放的通用环境条件。下限取-50℃或上限仅到50℃的范围都不符合存储要求。"},{"id":456,"type":"single","cat":"基础概念","stem":"长期存放的飞行器，至少（）进行一次通电试车检査。","A":"每季度","B":"每月","C":"每周","D":"每年","answer":"B","exp":"长期存放的飞行器，电子元件和电池会缓慢劣化，接插件可能氧化受潮，至少每月通电试车检查一次，及时发现隐患，防止存放后性能下降或突发故障。每季度、每年间隔过长，每周又过于频繁，均不符合维护要求。"},{"id":457,"type":"single","cat":"基础概念","stem":"中程无人机活动半径为（）。","A":"50～200km","B":"＞800km","C":"200～800km","D":"以上均不正确","answer":"C","exp":"按活动半径分类，近程无人机约50～200km，中程无人机活动半径为200～800km，远程超过800km，中程承担中远距离任务，介于两者之间。三个量级的数值界限是常考记忆点，相近数字极易互相混淆。"},{"id":458,"type":"single","cat":"设备与维护","stem":"3508/2835两个电机（）。","A":"带动的桨宽大","B":"带动的速度快","C":"2835外观上的更细更高","D":"以上均不正确","answer":"C","exp":"3508与2835按定子尺寸命名：2835定子直径较小而轴向更高，外观上更细更高，两者外形与转矩特性各有特点。带桨宽窄和转速快慢取决于绕组与KV值，并非型号本身决定的固定差异，前两种说法都不成立。"},{"id":459,"type":"single","cat":"设备与维护","stem":"一款电机参数为3S最大电流23A，下面哪一款电调搭配最为适合（）。","A":"2-3S20A","B":"2-6S40A","C":"2S30A","D":"2-3S30A","answer":"D","exp":"电机按3S设计、最大电流23A，电调须覆盖3S电压且持续电流留足余量，2-3S30A电压匹配、电流余量合适最为适合。20A电调电流不足易过载烧毁，2S30A电压不够，2-6S40A电压上限远超该电机适用范围。"},{"id":460,"type":"single","cat":"设备与维护","stem":"以下属于闭源飞行控制系统（自驾仪）的是（）。","A":"A3","B":"APM","C":"PX4","D":"CCD3","answer":"A","exp":"A3是大疆商用自驾仪，源代码与接口不对外开放，属于闭源飞控。APM与PX4是知名开源项目，代码公开可自由裁剪移植，CCD3同为开源方案，四者中只有A3不对用户开放源码。"},{"id":461,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机复飞时，正确的操纵方式是（）。","A":"迅速推满油门，同时快速拉杆转入爬升","B":"保持油门，快速拉杆转入爬升","C":"柔和地加满油门，保持好方向，同时柔和拉杆使飞机逐渐转入爬升，保持好爬升状态","D":"以上均不正确","answer":"C","exp":"复飞动作应柔和连贯：柔和地加满油门，保持好方向，柔和带杆使飞机逐渐转入爬升并稳定爬升状态，脱离着陆轨迹。动作粗猛会使迎角骤增而掉高度甚至失速，只保持油门不拉杆则无法中止下滑完成复飞。"},{"id":462,"type":"single","cat":"基础概念","stem":"飞机重心位置的表示方法是（）。","A":"用重心到平均几何弦后缘的距离和平均几何弦长之比的百分数来表示","B":"用重心到机体基准面的距离和平均气动力弦长之比的百分数来表示","C":"用重心到平均气动力弦前缘的距离和平均气动力弦长之比的百分数来表示","D":"以上均不正确","answer":"C","exp":"重心位置用重心到平均空气动力弦前缘的距离与该弦长之比的百分数表示，以平均气动力弦为基准可统一度量不同机翼平面形状的纵向位置。以几何弦后缘为基准不是规范方法，机体基准面用于全机定位，都不作重心位置的表示方式。"},{"id":463,"type":"single","cat":"设备与维护","stem":"飞行控制系统通过加速度传感器和角速度传感器融合测量无人机的（）。","A":"飞行速度","B":"飞行姿态","C":"飞行高度","D":"飞行温度","answer":"B","exp":"飞控通过陀螺仪测量角速度、加速度计测量线加速度，经滤波融合解算出无人机的俯仰、横滚、航向姿态角，构成姿态闭环控制的反馈基础。速度和高度要靠GPS、气压计等外部传感器测定，温度更不在其测量范围之内。"},{"id":464,"type":"single","cat":"设备与维护","stem":"无刷电机轴承损坏造成的现象，不包括的是（）。","A":"通电后无任何动作","B":"动平衡破坏","C":"空载电流增大","D":"旋转内部杂音","answer":"A","exp":"轴承损坏使转动摩擦增大，典型表现为旋转内部杂音、空载电流增大以及动平衡破坏引起振动。绕组与驱动正常时通电仍有动作响应，通电后无任何动作多属绕组断线、电调故障或供电问题，并非轴承损坏的表现。"},{"id":465,"type":"single","cat":"操纵与飞行技术","stem":"关于固定翼无人机起飞类型，下列说法正确的是（）。","A":"在地面发射时，无人机使用较为广泛的发射方式是母机空中发射与零长发射","B":"垂直起降的固定翼无人机均安装有专用的辅助动力系统","C":"容器式发射装置是一种封闭发射装置，兼备发射与贮存无人机功能","D":"所有特种固定翼无人机也可采用垂直方式发射和回收","answer":"C","exp":"容器式发射装置把无人机装在封闭容器内，平时贮存保护、发射时充当导向轨道，兼有发射与贮存两种功能。地面发射应用最广的是滑轨发射与手抛，母机空中发射属投放方式；垂起固定翼未必装专用辅助动力，并非所有特种固定翼都能垂直起降。"},{"id":466,"type":"single","cat":"基础概念","stem":"一般固定翼无人机螺旋桨旋转时距地面最近点的高度至少要大于其直径的（）。","A":"1/2","B":"1/5","C":"1/10","D":"1/20","answer":"C","exp":"为避免桨叶击地伤人并减轻地面对螺旋桨气流的干扰，固定翼无人机螺旋桨旋转扫过的最低点离地至少应大于桨直径的1/10，保留安全裕度。取1/2裕度过大并无必要，1/20距地面太近，均不符合要求。"},{"id":467,"type":"single","cat":"基础概念","stem":"活塞发动机中，CDI系统属于（）的一部分。","A":"排气系统","B":"进气系统","C":"点火系统","D":"以上均不正确","answer":"C","exp":"CDI是电容放电式点火系统，靠电容储能、触发器件在火花塞上产生高压电火花点燃混合气，是活塞发动机点火系统的重要组成部分。进气系统负责供气，排气系统负责排出废气，均与点火过程无关。"},{"id":468,"type":"single","cat":"操纵与飞行技术","stem":"起飞前，应确认现场的（）符合该机型的作业范围。","A":"湿度","B":"温度","C":"风速","D":"气压","answer":"C","exp":"起飞前应确认现场风速在该机型允许的作业范围内，风超过抗风等级会直接威胁起飞时的姿态保持与安全，必须停飞或改期。湿度、温度、气压虽也影响性能，但风速是起飞前须现场核对、决定能否起飞的首要条件。"},{"id":469,"type":"multi","cat":"电力巡检","stem":"巡检前，作业人员应了解巡检线路情况（）、所需空域等。","A":"海拔高度","B":"地形地貌","C":"气象环境","D":"植被分布","answer":"ABCD","exp":"巡检前应全面了解巡检线路情况：海拔高度影响无人机动力与抗风性能，地形地貌决定起降点选择与航线布置，气象环境关系飞行安全和作业窗口，植被分布影响目标查找与信号遮挡判断，加上所需空域，各项都须提前掌握。"},{"id":470,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，巡检作业点是指中小型无人直升机巡检作业时，无人直升机巡检系统停留进行（）等作业的位置。","A":"拍照","B":"摄像","C":"查找","D":"分析","answer":"AB","exp":"作业点指中小型无人直升机巡检系统停留开展拍照、摄像等作业的位置，核心是在停留位置获取线路影像，拍照和摄像都属于图像采集作业。查找和分析是对所获影像资料的后续处理工作，不在停留作业点完成，不属于作业点定义内容。"},{"id":471,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆时观察地面关系的目的是（），以便准确地操纵飞机着陆。","A":"判断高度、下沉情况、飞行状态和运动的方向","B":"判断下降率","C":"了解速度","D":"目测的情况","answer":"ABCD","exp":"着陆时观察地面关系是为了准确操纵接地：判断高度和下沉情况以把握拉平时机，判断下降率以控制接地轻重，了解速度以决定收油门与带杆量，掌握飞行状态和运动方向以便及时修正，结合目测情况选准接地点和方向，各项共同保证着陆平稳。"},{"id":472,"type":"multi","cat":"电力巡检","stem":"输电线路在线监测系统需要实现系统主站和系统终端之间高速、可靠和透明的数据传输，远程通信可采用（）等多种通信方式。","A":"局域网","B":"光纤专网","C":"无线专网","D":"无线公网","answer":"BCD","exp":"在线监测主站与终端相距遥远，远程通信须依托广域通道：光纤专网带宽大、可靠性高，无线专网专用安全，无线公网覆盖广、成本低，三者均可采用。局域网只覆盖园区楼宇等小范围，承担不了远距离数据传输，故不在可选之列。"},{"id":473,"type":"multi","cat":"电力巡检","stem":"中型无人直升机巡检和固定翼无人机巡检工作班成员至少应包括（）。","A":"操控手","B":"程控手","C":"任务手","D":"安全监护员","answer":"ABC","exp":"按规程要求，中型无人直升机巡检和固定翼无人机巡检的工作班成员至少应包括操控手、程控手、任务手：操控手负责飞行操纵，程控手负责地面站与航线监控，任务手负责任务载荷操作。安全监护员不属于规程规定的最低人员配置。"},{"id":474,"type":"multi","cat":"领航与任务规划","stem":"应急航线的主要目的是确保飞机安全返航，规划（）。","A":"安全着陆点","B":"应急迫降点","C":"航线转移策略","D":"安全返航通道","answer":"BCD","exp":"应急航线为故障时安全返航服务：规划安全返航通道避开禁飞区与障碍，选定沿途应急迫降点供就近降落，制定航线转移策略使正常航线能平滑切换到应急航线。安全着陆点属于正常任务航线规划的内容，不在应急航线范畴之内。"},{"id":475,"type":"multi","cat":"电力巡检","stem":"固定翼无人机巡检系统包括（）","A":"固定翼无人机系统","B":"任务载荷","C":"发射回收系统","D":"综合保障系统","answer":"ABCD","exp":"固定翼无人机巡检系统由四部分组成：固定翼无人机系统提供飞行平台，任务载荷完成拍照摄像等巡检作业，发射回收系统解决起飞与回收着陆，综合保障系统提供地面站、通信、运输维护等支持，四者缺一便无法完整实施巡检任务。"},{"id":476,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机是指具有（）个及以上旋翼，能垂直起降、自由悬停的无人驾驶航空器。","A":"二","B":"三","C":"四","D":"五","answer":"B","exp":"多旋翼无人机指具有三个及以上旋翼、能垂直起降并自由悬停的无人驾驶航空器，靠多组旋翼转速差实现姿态与位置控制，三旋翼即属多旋翼范畴。二旋翼归入直升机类，四、五只是常见的具体构型数量，并非定义下限。"},{"id":477,"type":"single","cat":"设备与维护","stem":"关于无人机飞行控制系统（自驾仪）调参时电压保护设置叙述正确的是（）。","A":"有两级低电压报警设置，第一级报警出现红灯闪烁，表示电量较低，可以继续飞行","B":"第一级报警出现红灯闪烁，表示电量极低，飞行控制系统（自驾仪）恒定设置为自动下降，可更改","C":"设置低电压报警值无需注意测算线损电压，提高精度","D":"出现低电压报警时最好及时降落，避免出现危险","answer":"B","exp":"低电压保护分两级，第一级红灯闪烁表示电量极低，该级在自驾仪中恒定设置为自动下降以保障安全，且此设置允许用户更改。红灯闪烁绝非电量较低还能继续飞行的提示，设置报警阈值不计入线损压降也会失准。"},{"id":478,"type":"single","cat":"操纵与飞行技术","stem":"无人机的回收方式可归纳为伞降回收，空中回收，起落架轮式着陆，拦阻网回收，气垫着陆和垂直着陆等类型，下列说法错误的是（）。","A":"空中回收，在飞机上必须有空中回收系统，在无人机上除了有阻力伞和主伞之外，还需要有钩挂伞，吊索和旋转的脱离机构","B":"起落架轮式着陆，多数无人机的起落架局部被设计成坚固，局部较脆弱","C":"用拦截网系统回收无人机是目前世界上小型无人机采用的回收方式之一","D":"以上均不正确","answer":"B","exp":"空中回收时无人机须有阻力伞、主伞及钩挂伞、吊索、旋转脱离机构供飞机钩取，拦截网也是小型无人机常用回收方式，两者说法都成立。轮式着陆的起落架须整体坚固以承受接地冲击，设计成局部脆弱会导致着陆损坏，该说法错误。"},{"id":479,"type":"single","cat":"基础概念","stem":"为防止民用无人机飞入或者飞出特定区域，在相应电子地理范围中画出其区域边界，保障区域安全的软硬件系统叫（）。","A":"净空系统","B":"融合空域","C":"电子围栏","D":"隔离系统","answer":"C","exp":"电子围栏是在电子地理范围内划定区域边界，由软硬件配合阻止无人机飞入或飞出特定区域的安全保障系统，广泛用于机场净空区、敏感区域防护。净空描述场地障碍环境，融合空域和隔离系统属空域管理概念，均非该系统名称。"},{"id":480,"type":"single","cat":"基础概念","stem":"对频在多旋翼飞行器当中，是指哪个动作（）。","A":"将飞行器与遥控器进行唯一性的连接","B":"将飞行器进行数据下载","C":"将遥控器射频信号进行校对","D":"将遥控器与飞行器进行图传传输","answer":"A","exp":"对频是让遥控器与飞行器建立唯一对应的无线连接，配对识别码存入接收机，使其只响应本遥控器指令，防止同频信号误控，是飞行前必须完成的绑定动作。对频不是数据下载或射频校对，图传另有独立的传输链路。"},{"id":481,"type":"single","cat":"领航与任务规划","stem":"航线库应根据（）及时更新。","A":"飞行航迹","B":"作业实际情况","C":"现场气象条件","D":"电子地图","answer":"B","exp":"航线库应结合作业实际情况及时更新，如障碍物变化、禁飞要求调整、新任务需求等，保证库存航线始终安全可用。飞行航迹只是历史记录，气象条件实时多变不宜作为更新依据，电子地图仅是基础底图资料。"},{"id":482,"type":"single","cat":"设备与维护","stem":"“在与地面站保持不少于2米的距离测试各指令通道工作正常”是（）的工作内容之一。","A":"飞行器整体目视检查","B":"遥控器检査","C":"地面站检査","D":"环境与飞行场地检査","answer":"B","exp":"该项检查用于验证遥控器油门、升降、副翼、方向等各指令通道输出正常，要求与地面站保持不少于2米距离，防止射频发射干扰地面站设备，属于飞行前遥控器检查的内容。地面站检查针对软件与显示功能，与测试指令通道无关。"},{"id":483,"type":"single","cat":"基础概念","stem":"无人机的基本感度是什么感度？（）","A":"磁罗盘的感度","B":"姿态角的感度","C":"陀螺仪的感度","D":"以上均不正确","answer":"C","exp":"基本感度即陀螺仪感度，反映陀螺对角速度偏差的修正灵敏度，感度越高抗扰纠正越快，过高则易引起机体高频抖动振荡。磁罗盘感度与姿态角感度是在此基础上派生的参数，不是基本感度的定义来源。"},{"id":484,"type":"single","cat":"基础概念","stem":"地球自转产生的地球自转偏向力对风向产生影响，下列哪个是正确的？","A":"北半球，地球自转偏向力使得气流向左偏转","B":"北半球，地球自转偏向力使得气流向右偏转","C":"北半球，地球自转偏向力使得气流先向右再向左偏转","D":"以上均不正确","answer":"B","exp":"地球自转产生的地转偏向力使运动气流发生偏转：北半球向右偏，南半球向左偏，赤道上为零，这是大气环流和地转风形成的重要原因。北半球向左偏是南半球的规律，先向右再向左的折向并不存在。"},{"id":485,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在姿态遥控状态下，如出现动力失效则正确的处理方法是？（）","A":"遥控器油门保持中间略上位置","B":"接地瞬间将油门收至最小","C":"始终保持油门最大位置试图恢复动力","D":"以上均不正确","answer":"B","exp":"姿态遥控模式下动力失效后升力无法维持，只能控制姿态尽量平稳下滑，接地瞬间将油门收至最小，防止电机意外转动伤人或打坏桨叶。保持油门最大无助于恢复动力，油门居中也毫无意义，都不利于安全处置。"},{"id":486,"type":"single","cat":"基础概念","stem":"无人机平台包括无人机本体和（）。","A":"图像传输系统","B":"飞行控制系统","C":"地面站系统","D":"动力系统","answer":"B","exp":"无人机平台由机体本体和飞行控制系统组成，飞控负责飞行稳定与控制，与机体共同构成空中飞行部分。图传数传属于通信链路，地面站属地面设备，动力装置通常单列为动力系统，都不归入平台范畴。"},{"id":487,"type":"single","cat":"基础概念","stem":"下列关于飞行过程中出现指南针受到干扰的处理方式正确的是（）。","A":"迅速将飞行模式切换到手动模式，并尽快操作飞行器降落，若操作困难可采取就近降落","B":"迅速将飞行模式切换到姿态模式，并尽快操作飞行器降落，若操作困难可采取就近降落","C":"立即采取一键返航操作","D":"拉高飞行器等待干扰消失后继续作业","answer":"B","exp":"指南针受干扰时航向数据失真，一键返航可能误动作，应迅速切换到姿态模式转为人工控制，尽快操纵飞行器降落，操作困难时就近选择场地降落。切手动模式操纵难度更高，拉高等待干扰消失风险大，都会增加危险。"},{"id":488,"type":"single","cat":"法规与空域","stem":"航空器使用航路和航线，进入空域或者脱离空域，应当经（）同意。","A":"负责该航路和航线的飞行管制部门","B":"空中交通管理局下属的区域管制部门","C":"中国人民解放军空军","D":"中国民用航空总局或中国人民解放军空军","answer":"A","exp":"我国空域实行统一飞行管制，航空器使用航路航线、进入或脱离空域，须经负责该航路航线的飞行管制部门同意，由其掌握空域使用动态、防止危险接近。民航与军队主管部门负责管理体系，具体许可由相应飞行管制部门实施。"},{"id":489,"type":"single","cat":"领航与任务规划","stem":"GPS传感器测得的是以下下那一高度（）。","A":"真实高度","B":"相对高度","C":"海拔高度","D":"补偿高度","answer":"C","exp":"GPS通过卫星测得飞行器三维坐标，高程以平均海平面为基准，测出的是海拔高度即绝对高度。真实高度与相对高度以地面或起飞点为基准，须借助气压计或地形数据换算得到，GPS本身不直接给出这两类高度。"},{"id":490,"type":"single","cat":"设备与维护","stem":"遥控器接收机和发射机对频调试中，对码完成后ID编码存储在（）内。","A":"发射机","B":"接收机","C":"遥控器","D":"舵机","answer":"B","exp":"对码过程中遥控器与接收机约定唯一ID编码，完成后该编码存储在接收机内，接收机据此甄别遥控信号，只执行本机遥控器的指令，屏蔽同频段其他发射设备。发射机保存自身的识别信息，舵机是执行器件，都不承担对码存储。"},{"id":491,"type":"single","cat":"设备与维护","stem":"IMU与磁罗盘之间的关系是怎样的（）。","A":"磁罗盘对IMU的方位数据进行校正","B":"IMU对磁罗盘的方位数据进行校正","C":"IMU与磁罗盘之间的数据是平行的","D":"IMU与磁罗盘各种负责角速度和经纬度","answer":"A","exp":"陀螺仪积分解算航向会随时间漂移，磁罗盘感应地磁场提供绝对方位基准，对IMU的方位数据进行校正，两者融合才能得到稳定可靠的航向。IMU不输出经纬度，定位由GPS负责，二者数据也并非互不相关的平行关系。"},{"id":492,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机带左坡度时，下列正确的操纵是（）。","A":"应柔和地向左压杆","B":"应柔和地回杆或向右压杆","C":"应柔和地向前顶杆","D":"以上均不正确","answer":"B","exp":"爬升中带左坡度会使升力倾斜、航迹左偏，破坏爬升的直线保持，应柔和回杆或向右压杆消除坡度，让机翼恢复水平，配合带杆保持爬升。继续向左压杆会加大坡度，向前顶杆则压低机头破坏爬升姿态，均不可取。"},{"id":493,"type":"single","cat":"基础概念","stem":"旋翼无人机在空中飞行时具有（）个自由度。","A":"3","B":"6","C":"9","D":"以上均不正确","answer":"B","exp":"空中飞行的旋翼无人机具有六个自由度：沿前后、左右、上下三轴的平移和绕三轴的滚转、俯仰、偏航转动，六个自由度均可独立控制，这是其机动灵活的力学基础。只算三个是漏掉转动，九个则混淆了自由度概念。"},{"id":494,"type":"single","cat":"飞行原理","stem":"某多轴螺旋型号为15×5，那么他的桨长（）毫米，螺距（）毫米。","A":"381,127","B":"150，50","C":"15，50","D":"38，12","answer":"A","exp":"螺旋桨型号15×5的第一项是桨长15英寸，第二项是螺距5英寸，1英寸等于25.4毫米，换算后桨长约381毫米、螺距约127毫米。把英寸误当厘米直接换算会得出150和50，数值相差一个数量级。"},{"id":495,"type":"single","cat":"设备与维护","stem":"运动相机ISO调试中，调高的ISO使（），调低的ISO使影像画面细腻。","A":"画面抖动","B":"画面粗糙","C":"影像颗粒感很强","D":"画面不稳定","answer":"C","exp":"运动相机ISO调高后感光灵敏度增强，适合暗光拍摄，但信号放大的同时噪声增多，影像颗粒感很强、质感变差；调低ISO噪声小、画面细腻，但需要充足光照或更慢快门配合，应按光线条件权衡设定。"},{"id":496,"type":"single","cat":"基础概念","stem":"舵面操控是什么控制量？（）","A":"模拟控制量","B":"开关控制量","C":"模拟控制量也叫比例控制量","D":"以上均不正确","answer":"C","exp":"舵面偏转角度可以连续变化，操纵量大小与舵面偏角一一对应成比例，属于模拟控制量，也叫比例控制量，能精细调节舵面的气动效果。开关控制量只有通断两种状态，无法实现舵面连续偏转，不适合舵面操纵。"},{"id":497,"type":"single","cat":"领航与任务规划","stem":"侧风中着陆，为了修正偏流，可以采用既修正了偏流，又使飞机的升阻比不减小的（）。","A":"改变航向法","B":"改变航向法和侧滑法相结合","C":"侧滑法","D":"以上均不正确","answer":"A","exp":"改变航向法将机头偏向上风方向形成修正角，航迹保持对正跑道方向，飞机沿自身对称轴飞行，既修正了偏流又不产生侧滑阻力，升阻比不减小。侧滑法要压坡度带侧滑，阻力增大使升阻比下降，不满足升阻比不减小的要求。"},{"id":498,"type":"single","cat":"基础概念","stem":"物体的运动是各式各样的，车辆行驶、鸟类飞翔、机器运转等，从表面上看，运动方式千差万别，但实质上都离不开两种基本的运动：（）和转动。","A":"平移","B":"平行","C":"平动","D":"直行","answer":"C","exp":"一切机械运动实质上都由平动和转动两种基本运动组成：平动时物体各点轨迹形状相同，转动是绕轴线旋转，车辆行驶、机器运转都是两者的组合。平移是几何变换概念，平行描述位置关系，直行只是行驶状态的说法，均非规范力学用语。"},{"id":499,"type":"single","cat":"基础概念","stem":"关于固定翼无人机重心位置的调整及配平，下列说法错误的是（）。","A":"重心的位置影响飞机的纵向稳定性","B":"焦点位置是固定的","C":"重心在后，焦点在前稳定性好","D":"重心位置可以通过移动零部件摆放位置改变","answer":"C","exp":"纵向静稳定性要求重心位于焦点之前，重心越靠前稳定性越好；重心落在焦点之后飞机俯仰不稳定，说重心在后、焦点在前稳定性好是错误的。焦点位置由气动外形决定基本固定，重心可通过零部件摆放调整，前两项说法正确。"},{"id":500,"type":"single","cat":"航空气象","stem":"无人机定高系统中气压计定高，高度每升高（）米，气压下降1000Pa。","A":"1000","B":"100","C":"10","D":"1","answer":"B","exp":"气压计定高利用气压随高度升高而降低的规律，近地面高度每上升约100米，气压大约下降1000帕，测得气压变化即可换算出高度变化。按1000米或10米换算会差一个数量级，不符合实际大气的压高规律。"},{"id":501,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器姿态数据中，“D”代表什么？","A":"飞行器与起飞点之间的相对度距离","B":"飞行器与起飞点之间的相对水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平运动的飞行速度","answer":"B","exp":"大疆飞行器姿态数据中，D表示飞行器与起飞点之间的相对水平距离，与高度H配合反映水平位置远近，帮助掌握返航距离。它是水平投影距离，不含高度分量，上升下降速度与水平速度另有专门数据项表示。"},{"id":502,"type":"single","cat":"设备与维护","stem":"垂起固定翼机体结构件的日常维护保养，下列选项错误的是（）。","A":"检查电池有无破损，鼓包胀气，漏液等现象","B":"检查机身、机翼是否在搬运中有破损并及时维修","C":"检查机身、机翼连接处是否还连接牢固并及时维修","D":"对机身、机翼擦拭，保持干净","answer":"A","exp":"机体结构件的维护保养针对机身机翼本体：检查搬运中的破损、确认连接处牢固并及时维修、擦拭保持清洁，都属于结构保养内容。电池的破损鼓包漏液检查属于动力电池维护项目，不归入机体结构件保养范围，列入其中是错误的。"},{"id":503,"type":"single","cat":"设备与维护","stem":"无人机的舵机损坏后，按要求需更换指针型摇臂，这配件适合方向舵和（）使用。","A":"机身","B":"升降舵","C":"尾翼","D":"副翼","answer":"B","exp":"指针型摇臂便于连杆长度微调，适合方向舵和升降舵这类需要精确调定舵面中位与行程的舵面使用。副翼通常双侧同步动作，多采用其他形式摇臂，机身与尾翼是结构部件而不是舵面，都不适用指针型摇臂。"},{"id":504,"type":"single","cat":"基础概念","stem":"无人机的多机协同方式主要分为两类（）。","A":"一站多机模式、长僚机编队模式","B":"多站多机模式、长僚机编队模式","C":"多站多机模式、长机编队模式","D":"一站多机模式、僚机编队模式","answer":"A","exp":"多机协同主要分为两类：一站多机模式由一个地面站同时管控多架无人机，适合大范围区域作业；长僚机编队模式由长机引导、僚机跟随，适合编队协同任务。多站多机属于多系统联合，长机编队、僚机编队均不是规范的分类名称。"},{"id":505,"type":"single","cat":"设备与维护","stem":"飞机中常见大功率电源线有电池电源线、电机相线和（），其他低功率细电源线可和信号线一起布线。","A":"无线数据传输（无线数传）系统线","B":"电子调速器（电调）控制线","C":"电子调速器（电调）电源线","D":"无线图像传输（无线图传）系统线","answer":"C","exp":"电池电源线、电调电源线和电机三相线流经大电流，是强电磁干扰源，须与信号线分开布线并保持距离，防止干扰造成控制失灵。数传、图传线电流很小，电调控制线是弱电信号线，都可以与信号线一起布线。"},{"id":506,"type":"single","cat":"基础概念","stem":"飞行器在执行兴趣点环绕最低度是？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A","exp":"大疆飞行器执行兴趣点环绕设有最低高度限制，环绕时机体需带坡度转弯，高度过低姿态裕度不足，规定最低为5米，低于5米无法启动环绕。10米以上数值都高于实际限制值，属于把最小高度记忆偏大。"},{"id":507,"type":"single","cat":"设备与维护","stem":"固定翼无人机电动机KV电池电压等于（）。","A":"电动机负载转速","B":"电动机最大转速","C":"电动机最小转速","D":"电动机空载转速","answer":"C","exp":"KV值表示电机每伏电压对应的空载转速，KV值乘以电池电压理论上等于电动机的空载转速，负载增加后实际转速会低于该值。负载转速与最大转速须实测获得，把该乘积当作最小转速或负载转速都不符合电机特性。"},{"id":508,"type":"single","cat":"操纵与飞行技术","stem":"在起飞过程中，地面站操作员通常每隔（）向飞行操作员通报无人机当前飞行高度、速度等数据。","A":"5~10s","B":"1~5s","C":"10~15s","D":"15~20s","answer":"A","exp":"起飞阶段飞行状态变化快，地面站操作员通常每隔5～10秒向飞行操作员通报当前高度、速度等数据，既保证信息及时，又不因通报过密干扰操纵注意力。间隔超过10秒可能漏掉状态突变，1～5秒则过于频繁。"},{"id":509,"type":"single","cat":"电力巡检","stem":"使用的无人机巡检系统应通过（）。","A":"试验检测","B":"型号检测","C":"厂家检测","D":"系统检查","answer":"A","exp":"用于架空输电线路巡检的无人机巡检系统应通过试验检测，验证飞行性能、任务载荷、通信链路等指标满足巡检要求后方可投入使用，保证作业可靠安全。厂家检测只属出厂环节，型号检测、系统检查均非规程规定的准入要求。"},{"id":510,"type":"single","cat":"操纵与飞行技术","stem":"以下哪种方式不属于无人机的起飞方式（）。","A":"空中投放","B":"火箭助飞","C":"手抛起飞","D":"垂直起飞","answer":"A","exp":"无人机起飞方式包括手抛起飞、滑跑起飞、弹射起飞、火箭助飞、垂直起飞等，共同点是由地面或载体使无人机获得升空能力。空中投放是母机携带无人机升空后释放，属于发射方式而非起飞过程，与起飞性质不同。"},{"id":511,"type":"single","cat":"设备与维护","stem":"在整个飞行器系统中，电调信号线最终插入哪个部分（）。","A":"主控","B":"IMU","C":"PMU","D":"IOSD","answer":"A","exp":"电调信号线把飞控输出的转速指令送入电调，其末端接入飞行控制主控，由主控统一调度各路电调完成电机转速分配。IMU是姿态传感器，PMU负责电源管理，IOSD负责数据叠加，都不是电调信号线的接入对象。"},{"id":512,"type":"single","cat":"飞行原理","stem":"如果无人机没有前进速度，那么桨叶角就（）桨叶迎角。","A":"大于","B":"等于","C":"小于","D":"以上均不正确","answer":"B","exp":"桨叶角是桨叶弦线与旋转平面的夹角，桨叶迎角是弦线与相对气流的夹角。没有前进速度时，桨叶相对气流就在旋转平面内，迎角恰好等于桨叶角；一旦有了前进速度，合成气流方向改变，迎角便小于桨叶角。"},{"id":513,"type":"single","cat":"领航与任务规划","stem":"下列关于RTK的特性，描述错误的是（）。","A":"RTK定位可达厘米级别，偏差较小","B":"RTK定向功能，具备抗电磁干扰能力","C":"执行航线作业时，RTK在同源情况下，无需纠正偏移","D":"网络RTK在无网络情况下也可正常使用","answer":"D","exp":"网络RTK须通过数据链实时接收基准站改正信息，没有网络就无法获得改正数，厘米级定位随之失效，说无网络也能正常使用是错误的。RTK定位可达厘米级、定向具备抗电磁干扰能力、同源情况下航线作业无需纠正偏移，均为真实特性。"},{"id":514,"type":"single","cat":"设备与维护","stem":"关于固定翼无人机载荷能力提升改造，下列说法正确的是（）。","A":"减小机翼展弦比","B":"减小机翼面积","C":"采用对称型机翼","D":"增大机翼展弦比","answer":"D","exp":"增大机翼展弦比可提高升阻比、减小诱导阻力，相同动力条件下能携带更大载荷或延长航程，是提升载荷能力的有效途径。减小展弦比或减小机翼面积都会削弱升力，对称翼型升力特性差，均不利于载荷提升。"},{"id":515,"type":"single","cat":"操纵与飞行技术","stem":"起飞前有围观群众近距离观看，我们应当采取以下什么方式起飞（）。","A":"飞手站在飞行器机头前，直接解锁起飞","B":"周围人员不会干扰到无人机信号，无需理会，直接解锁起飞","C":"未等地勤将围观人员疏散至安全区域，直接解锁起飞","D":"疏散人群至安全距离后，飞手站在飞行器尾部6米处，解锁起飞","answer":"D","exp":"起飞前应先将围观群众疏散至安全距离以外，飞手站在飞行器尾部约6米处再解锁起飞，远离桨叶危险区又便于观察飞行器状态。站在机头前有桨叶伤人风险，不顾围观人群直接起飞违反安全要求，均为禁止做法。"},{"id":516,"type":"single","cat":"设备与维护","stem":"无线图像传输（无线图传）系统接收端通常直接和（）连接。","A":"无线无线数据传输（无线数传）系统","B":"显示器","C":"飞行控制系统（自驾仪）","D":"监视器","answer":"B","exp":"无线图传接收端接收机载图像信号后解调还原成视频，通常直接与显示器连接实时呈现画面，供飞手和观察员监视飞行与作业情况。数传系统传输控制与遥测数据，自驾仪位于机载端，都不是图传接收端的直接连接对象。"},{"id":517,"type":"single","cat":"领航与任务规划","stem":"动力系统工作恒定的情况下（）限制了航迹在垂直平面内上升和下滑的最大角度。","A":"最大俯仰角","B":"最大转弯半径","C":"最小转弯半径","D":"以上均不正确","answer":"A","exp":"动力系统工作恒定时，航迹在垂直平面内能爬升或下滑的最大角度受最大俯仰角限制，俯仰角决定机身轴线相对水平面的姿态极限，超过即无法保持所需升力与速度。转弯半径约束的是水平面内的机动能力，与垂直剖面无关。"},{"id":518,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机舵机如果不处于中立位置时，则可能在无人机起飞后产生（），而中立微调则是修改舵机中立位置的设置。","A":"加速","B":"减速","C":"偏移","D":"无法起飞","answer":"C","exp":"各舵面处于中立位置时飞机才能保持直线平衡飞行，舵机若偏离中立位，舵面带初始偏角产生不平衡力矩，起飞后飞机向一侧偏移或出现俯仰偏斜，中立微调正是把舵机校回中立位置的设置。该偏差影响航向姿态，不会直接造成加速或无法起飞。"},{"id":519,"type":"single","cat":"法规与空域","stem":"关于为什么人机要远离国家边境线，描述最准确的是？（）","A":"从电磁安全方考虑","B":"从象安全方考虑","C":"从避免出现边境纠纷方考虑","D":"因为边境线飞行环境不好","answer":"C","exp":"无人机贴近国家边境线飞行极易越境进入他国领空，侵犯领空主权，可能引发外交交涉与边境纠纷，因此必须远离边境线作业，这是最主要的考虑。电磁与气象安全只是次要因素，边境飞行环境好坏并非核心原因。"},{"id":520,"type":"single","cat":"设备与维护","stem":"以下电池类型中，记忆效应最强的是（）。","A":"锂电池","B":"镍氢电池","C":"镍镉电池","D":"以上均不正确","answer":"C","exp":"镍镉电池记忆效应最强，经常不完全充放电会使容量“记住”较低的放电终点而明显下降，需要定期深度放电维护。镍氢电池记忆效应较弱，锂电池几乎没有记忆效应、可随用随充，三者使用维护方式差异明显。"},{"id":521,"type":"single","cat":"设备与维护","stem":"指挥控制与（）是无人机地面站的主要功能。","A":"飞行状态监控","B":"任务规划","C":"飞行视角显示","D":"以上均不正确","answer":"B","exp":"无人机地面站的主要功能概括为指挥控制与任务规划：指挥控制对飞行和任务执行全程实施监控指挥，任务规划完成航线设计、装订与修改。飞行状态监控与视角显示只是其中的具体子功能，不能与指挥控制并列为主要功能。"},{"id":522,"type":"single","cat":"基础概念","stem":"下面哪种连接是对的？（）","A":"电池—电调—电机","B":"电机—电调—电池—IMU","C":"电机—电调—IMU—电池","D":"以上均不正确","answer":"A","exp":"动力系统的正确连接为电池—电调—电机：电池输出电能给电调，电调按飞控指令将直流电逆变为三相电驱动电机。IMU是姿态传感器，串入供电回路会阻断动力供电且毫无作用，其余连接方式均不成立。"},{"id":523,"type":"single","cat":"飞行原理","stem":"操纵无人机时，若迎角超过临界迎角，升力系数将会（）。","A":"迅速增大","B":"迅速减小","C":"缓慢增大","D":"以上均不正确","answer":"B","exp":"迎角在临界迎角以内时升力系数随迎角增大，一旦超过临界迎角，机翼上表面气流大面积分离，涡流区扩大，升力系数迅速减小，飞机进入失速状态。缓慢增大或继续增大都不符合失速后的气动力变化规律。"},{"id":524,"type":"single","cat":"基础概念","stem":"在机翼表面附面层由层流状态转变为紊流状态的转捩点的位置。","A":"在飞行M数小于一定值时保持不变","B":"将随着飞行速度的提高而前移","C":"将随着飞行速度的提高而后移","D":"以上均不正确","answer":"B","exp":"附面层由层流转变为紊流的位置称转捩点，飞行速度提高使雷诺数增大，气流扰动增强，转捩点向机翼前缘方向前移，层流段随之缩短。M数较小时转捩点并非保持不变，随速度提高而后移的说法与雷诺数规律相反。"},{"id":525,"type":"single","cat":"操纵与飞行技术","stem":"（）是指最大起飞重量超过25千克不超过150千克，且空机重量超过15千克的无人机。","A":"小型无人机","B":"中型无人机","C":"大型无人机","D":"轻型无人机","answer":"B","exp":"按无人驾驶航空器飞行管理暂行条例的分类，中型无人机指最大起飞重量超过25千克不超过150千克，且空机重量超过15千克的无人机，规格介于小型与大型之间。小型上限为25千克，大型超过150千克，重量界限容易记混。"},{"id":526,"type":"single","cat":"基础概念","stem":"磁罗盘所主要感应的参数是（）。","A":"经纬度","B":"角度方位","C":"角速度","D":"加速度","answer":"B","exp":"磁罗盘感应地磁场，主要测出机体相对磁北的角度方位，为飞控提供航向基准，与陀螺仪、加速度计融合解算姿态与航向。经纬度由GPS测定，角速度、加速度分别由陀螺仪和加速度计测量，都不是磁罗盘的感应对象。"},{"id":527,"type":"single","cat":"基础概念","stem":"直升机、固定翼、多旋翼三种飞行器，其续航性能从高到低排列正确的是（）。","A":"直升机、固定翼、多旋翼","B":"直升机、多旋翼、固定翼","C":"多旋翼、直升机、固定翼","D":"固定翼、直升机、多旋翼","answer":"D","exp":"续航性能由巡航需用功率决定：固定翼靠机翼产生升力，巡航功率最小，续航时间与航程最长；直升机旋翼效率较高居中；多旋翼全靠旋翼拉力平衡重力，悬停耗能最大，续航最短，从高到低为固定翼、直升机、多旋翼。"},{"id":528,"type":"single","cat":"设备与维护","stem":"无人机系统通讯链路主要包括：指挥与控制、感知和规避、（）三种。","A":"空中交通管制","B":"视频通信","C":"通信中继","D":"以上均不正确","answer":"A","exp":"无人机系统通讯链路按用途分三类：指挥与控制链路传递飞控指令和遥测数据，感知和规避链路支持避撞信息交互，空中交通管制链路实现与管制系统的信息互通。视频通信、通信中继属于具体业务功能，不属于这三类的标准划分。"},{"id":529,"type":"single","cat":"基础概念","stem":"下列关于操作无人机禁止行为描述错误的是（）。","A":"禁止任何形式的载人操作","B":"禁止靠近及抓握飞行当中的无人机","C":"禁止操作无人机飞行至密集人群上空","D":"飞行中的无人机失控时可手接飞行器","answer":"D","exp":"禁止任何形式载人、禁止靠近或抓握飞行中的无人机、禁止在密集人群上空飞行，都是操作无人机的基本安全要求。失控坠落时徒手去接高速旋转的桨叶会造成严重割伤，正确做法是远离坠落区域，该说法是错误的。"},{"id":530,"type":"single","cat":"设备与维护","stem":"多旋翼无人机抗风性测试结果表明，无人机抗风性与无人机的（）有关，下列选项错误的是。","A":"电池容量","B":"飞行控制系统（自驾仪）算法的精确度","C":"PID算法的协调性","D":"重量体积","answer":"A","exp":"抗风性取决于飞控算法对风扰响应的精确度、PID参数的协调性以及机体重量、体积等气动与控制因素，这些决定风扰下的姿态恢复能力。电池容量只影响续航时间，与抗风性能没有直接关系，列为影响因素是错误的。"},{"id":531,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，飞机速度减小太多时，下列正确的操纵是（）。","A":"迅速关闭发动机","B":"迅速增大俯仰角","C":"迅速减小俯仰角","D":"以上均不正确","answer":"C","exp":"姿态模式爬升靠增大俯仰角换取高度，俯仰角过大时升力的前进分量骤减，速度掉得太多会接近失速。此时应迅速减小俯仰角，压低机头让速度先恢复，再继续爬升；若反而增大俯仰角速度会更低，关车则直接失去动力，均不可取。"},{"id":532,"type":"single","cat":"飞行原理","stem":"直升机在前飞时桨叶在什么方位迎角最小？（）","A":"180°方位","B":"90°方位","C":"270°方位","D":"以上均不正确","answer":"B","exp":"前飞时旋翼各桨叶随方位角周期挥舞：转到前行侧90°方位时桨叶向上挥舞量最大，相对气流从下方吹向桨盘，使桨叶迎角减到最小；270°方位下挥最大、迎角最大。180°与0°方位处于过渡区，迎角介于两者之间。"},{"id":533,"type":"multi","cat":"基础概念","stem":"电动动力系统主要由（）组成。","A":"调速系统","B":"电池","C":"动力电机","D":"动力电源","answer":"ACD","exp":"电动动力系统按功能由三部分构成：动力电源提供电能，调速系统即电调按指令调节电机转速，动力电机把电能转为机械能带动螺旋桨。动力电源是对供电装置的统称，电池只是其中一种具体形式，此外还可能是燃料电池等，故不再单列电池一项。"},{"id":534,"type":"multi","cat":"电力巡检","stem":"使用中型无人直升机巡检系统的巡检作业，程控手应在巡检作业前一个工作日（），并交工作负责人检查无误。","A":"完成航线规划工作","B":"编辑生成飞行航线","C":"各巡检作业点作业方案","D":"安全策略","answer":"ABCD","exp":"巡检作业前一个工作日，程控手应完成全部准备工作并交工作负责人审核：先完成航线规划，据此编辑生成可执行的飞行航线，再编制各巡检作业点的作业方案和相应的安全策略，四项内容环环相扣，经检查无误后方可实施次日作业。"},{"id":535,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，操控手是利用遥控器以（）或控制无人机巡检系统飞行的人员","A":"增稳模式","B":"手动","C":"自动","D":"全自动","answer":"AB","exp":"操控手的定义强调人工参与：利用遥控器以手动或增稳模式直接控制无人机飞行。增稳模式下飞控只辅助稳定姿态，操纵量仍由人给出。自动、全自动模式由程控系统按预设航线自主执行，属于程控手职责范围，不属于操控手的操控方式。"},{"id":536,"type":"multi","cat":"设备与维护","stem":"维护保养人员应按维护保养手册要求按时开展（）等工作。","A":"日常维护","B":"零件维修更换","C":"大修保养","D":"试验","answer":"ABCD","exp":"维护保养手册对时间节点有明确要求，维护保养人员应按时开展四类工作：日常维护保持设备完好状态，对磨损损坏的零件及时维修更换，按周期进行大修保养恢复整机性能，并按要求开展试验验证维护效果，确保系统持续可用。"},{"id":537,"type":"multi","cat":"电力巡检","stem":"以下哪些属于小型无人直升机巡检系统出厂检验必做项目？","A":"外观及尺寸测量","B":"重量测量","C":"高低温工作试验","D":"抗风能力试验","answer":"AB","exp":"出厂检验针对每台产品逐项进行，耗时短、可快速完成：外观及尺寸测量检查制造质量，重量测量核实与设计值一致。高低温工作试验和抗风能力试验周期长、成本高，属于型式试验或定型试验项目，不在出厂必做之列。"},{"id":538,"type":"multi","cat":"基础概念","stem":"下面（）直升机不是采用了无轴承旋翼。","A":"S-76直升机","B":"苏制米-8直升机","C":"UH-60","D":"直升机","answer":"BCD","exp":"S-76直升机采用了无轴承旋翼结构，而米-8为典型的全铰接式旋翼，UH-60采用带弹性轴承的全铰接式旋翼，均不是无轴承式；直升机只是机种类别泛称，并非具体采用无轴承旋翼的型号。逐项核对型号对应的旋翼形式即可区分。"},{"id":539,"type":"single","cat":"领航与任务规划","stem":"在航拍任务中，若需获得1:2000比例尺的正射影像，飞行相对航高H（单位：m）与相机像元尺寸p（单位：μm）、焦距f（单位：mm）应满足的关系是","A":"H=2000·f/p","B":"H=2000·p/f","C":"H=2000·f·p","D":"H=2000/(f·p)","answer":"A","exp":"影像比例尺1:m要求像元地面尺寸GSD=m·p，而GSD=H·p/f，解得H=2000·f/p：航高与焦距成正比、与像元尺寸成反比，焦距越长、像元越小允许航高越高。把两者影响方向颠倒的关系式即为错误项。"},{"id":540,"type":"multi","cat":"基础概念","stem":"下列哪些因素会导致空三解算“分层”","A":"曝光时间差异>2档","B":"重叠度局部<30%","C":"相机主距标定误差>3%","D":"测区高差>1/3航高","answer":"ABC","exp":"空三解算分层即同一区域被拟合为上下错开的多层平面，多因几何或辐射一致性遭破坏：曝光档位差异过大使影像色调不统一，同名点匹配出错；局部重叠度低于30%时连接点过少，约束不足；主距标定误差超过3%导致投影关系失真。测区高差大属地形条件，靠合理航高与分区即可应对，不是分层的直接成因。"},{"id":541,"type":"single","cat":"设备与维护","stem":"无人机装配报告编制主要包括括装配工序、装配标准、（）、装配工具、装配材料清单和装配安全规范。","A":"装配进度表","B":"装配复检表","C":"装配时间","D":"装配图","answer":"B","exp":"装配报告用于指导装配并留档追溯，完整条目为装配工序、装配标准、装配复检表、装配工具、装配材料清单和装配安全规范。复检表逐项记录装配后的检验结果，保证工序质量可查；进度表与时间属生产计划管理，装配图是图样而非报告必备条目。"},{"id":542,"type":"single","cat":"领航与任务规划","stem":"GPS系统不能提供哪个参数（）。","A":"方位角度","B":"高度","C":"经纬度","D":"速度","answer":"A","exp":"GPS接收机能解算经纬度、高度构成的三维位置，还能利用多普勒频移测出速度，这三类参数均可直接输出。方位角度即航向，GPS单天线无法直接给出，需依靠磁罗盘测量或由运动轨迹推算，故方位角度不是GPS原生提供的参数。"},{"id":543,"type":"single","cat":"基础概念","stem":"物体的运动是各式各样的，车辆行驶、鸟类飞翔、机器运转等，从表面上看，运动方式千差万别，但实质上都离不开两种基本的运动：平动和（）。","A":"转动","B":"旋转","C":"下降","D":"上升","answer":"A","exp":"无论车辆行驶、鸟类飞翔还是机器运转，构件的运动虽表象各异，实质都可分解为平动和转动两种基本形式：平动是各点轨迹相同的移动，转动是绕定轴的旋转，复杂运动均为两者合成。下降上升只是平动的方向，旋转与转动同义。"},{"id":544,"type":"single","cat":"航空气象","stem":"危及飞行安全和影响正常飞行的重要天气现象，包括（）、降水、地面和近地面层的凝结、凝华和冻结现象、沙尘暴和雷暴等。","A":"空气湿度","B":"大气压","C":"云","D":"雨","answer":"C","exp":"危及飞行安全和影响正常飞行的重要天气现象包括云、降水、地面和近地面层的凝结凝华冻结现象、沙尘暴和雷暴等。云影响最广，蕴含积冰与颠簸条件，云底云顶直接决定能否目视飞行。雨只是降水的一种形态，湿度、大气压仅是气象要素。"},{"id":545,"type":"single","cat":"设备与维护","stem":"（）的主要功能是根据飞控计算机的指令，按规定的静态和动态要求，通过对无人机各控制舵面和发动机节风门等的控制，实现对无人机的飞行控制。","A":"电源","B":"伺服执行机构","C":"数据链","D":"以上均不正确","answer":"B","exp":"伺服执行机构是飞控指令的执行环节：接收飞控计算机输出的控制信号，按规定的静态精度和动态响应要求驱动各控制舵面及发动机节风门动作，从而实现对无人机的飞行控制。电源只负责供电，数据链负责信息传输，均不具备操纵执行功能。"},{"id":546,"type":"single","cat":"基础概念","stem":"以下飞行器不是多轴飞行器的是（）。","A":"Uh-60黑鹰","B":"Phantom精灵","C":"Inspire悟","D":"以上均不正确","answer":"A","exp":"UH-60黑鹰是单旋翼带尾桨的军用直升机，不属于多轴飞行器；Phantom精灵与Inspire悟均为四旋翼多轴航拍机。多轴飞行器的特征是依靠多个旋翼的差动转速实现平衡与操纵，黑鹰靠倾斜盘与尾桨操纵，原理完全不同。"},{"id":547,"type":"single","cat":"设备与维护","stem":"关于电调的主要作用，下面描述正确的是（）。","A":"驱动电机运转","B":"接收飞行信号","C":"存储飞行数据","D":"调节飞行的姿态","answer":"A","exp":"电调全称电子调速器，核心作用是根据飞控或接收机送来的油门信号，以三相驱动方式控制无刷电机的转速与转向，即驱动电机运转。接收飞行信号由接收机完成，存储飞行数据靠飞控或记录模块，调节飞行姿态是飞控的职责。"},{"id":548,"type":"single","cat":"领航与任务规划","stem":"无人机驾驶员操纵无人机定高平飞航迹偏离时，下列描述正确的是（）。","A":"如果轨迹方向偏离目标5°以内，应快速大幅度地向偏转的反方向适当扭舵杆","B":"如果轨迹方向偏离目标5°以内，应柔和地向偏转的方向适当扭舵杆","C":"如果轨迹方向偏离目标5°以内，应柔和地向偏转的反方向适当扭舵杆","D":"以上均不正确","answer":"C","exp":"平飞中航迹方向偏离目标在5°以内属小偏差，修正应柔和地向偏离的反方向适当扭舵杆，让机头缓缓对正目标航线，防止修过量来回摆动。只有偏差较大时才需较大舵量，向偏离同方向打舵只会越偏越远。"},{"id":549,"type":"single","cat":"基础概念","stem":"（）的功能是向无人机各用电系统或设备提供满足预定设计要求的电能。","A":"电源","B":"配电系统","C":"供电系统","D":"以上均不正确","answer":"C","exp":"供电系统是功能性统称，由电源与配电系统组合而成，负责向无人机各用电系统或设备提供满足电压、容量等预定设计要求的电能。电源仅完成电能产生，配电系统只完成电能分配，单独任一环节都不构成完整的供电能力。"},{"id":550,"type":"single","cat":"基础概念","stem":"一般我们说的4级风，风速为（）。","A":"10.8-13.8m/s","B":"8.0-10.7m/s","C":"5.5-7.9m/s","D":"以上均不正确","answer":"C","exp":"蒲福风级中4级风对应风速5.5～7.9 m/s，表现为吹起地面灰尘纸张、小树枝摇动。10.8～13.8 m/s已是6级强风，8.0～10.7 m/s为5级。户外飞行前应据此评估，4级风已需谨慎，5级以上一般不宜作业。"},{"id":551,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操纵无人机坡度转弯时，同时操纵方向舵作用是（）。","A":"进行协调转弯，可有效增大转弯半径并减少侧滑","B":"进行协调转弯，可有效减小转弯半径并减少侧滑","C":"进行协调转弯，可有效减小转弯半径并增大侧滑","D":"以上均不正确","answer":"B","exp":"转弯时副翼压出坡度，升力的水平分量提供向心力；同时压方向舵使机头跟随转弯方向偏转，消除机身侧滑，实现协调转弯。协调后气流沿机身轴线流入，阻力减小、向心力利用充分，可有效减小转弯半径并避免侧滑带来的航向不稳。"},{"id":552,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，风速大或气温低时（）。","A":"如目测低，加油门量相应小些","B":"如目测高，收油门量相应大些","C":"如目测低，加油门量相应大些","D":"以上均不正确","answer":"C","exp":"着陆目测低说明飞机下沉快、到不了接地点。风速大时下滑角变平、平飘距离增长，气温低时空气密度大、升力增加使下滑轨迹变远，目测偏低加剧，因此加油门量应相应大些，用更多功率拉平下沉。收油门只会更低，与修正方向相反。"},{"id":553,"type":"single","cat":"设备与维护","stem":"在飞行中当发动机停车时，地面站会（）(飞机安装有转速传感器)。","A":"报警","B":"失控","C":"没有影响","D":"断开连接","answer":"A","exp":"发动机装有转速传感器时，其转速信号实时传回地面站显示。飞行中发动机停车，转速骤降或归零会被立即识别，地面站发出报警提醒操纵员处置，此时链路并未中断，飞机也不会因此失控或断开连接。"},{"id":554,"type":"single","cat":"领航与任务规划","stem":"飞行器在执行航点飞行时，相邻航点的设置应大于？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A","exp":"航点飞行时飞控需在相邻航点间完成转向与航迹平滑，两点间距过小，飞机来不及建立新航向就会冲过航点，造成转弯超调或轨迹抖动。因此相邻航点设置应大于5米，间距过近反而使航线执行精度变差。"},{"id":555,"type":"single","cat":"基础概念","stem":"以下哪个英文缩写对应是错误的？（）","A":"舵机反向REV","B":"功能设置FUNC","C":"失控保护F-C","D":"以上均不正确","answer":"C","exp":"遥控器常用缩写需对应准确：REV是Reverse的缩写，表示舵机反向；FUNC即Function，用于功能设置；失控保护的英文是Fail-Safe，缩写为F/S而非F-C，该对应关系错误，其余两项均正确。"},{"id":556,"type":"single","cat":"设备与维护","stem":"（）是指通过遥控器屏幕可以查看各个通道的工作状态，也可以分辨通道的正反相。","A":"舵量显示","B":"舵机相位","C":"相位功能","D":"定向功能","answer":"A","exp":"舵量显示功能在遥控器屏幕上实时显示各通道的输出量与方向，操纵摇杆即可观察对应通道数值变化及正反相是否正确，是检查通道设置、判断舵机反应方向的直观手段。舵机相位、相位功能与定向功能均非此功能的名称。"},{"id":557,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机在预定高度由平飞转爬升时（）。","A":"注视地平仪，柔和地加油门至100%，同时稍拉杆转为爬升","B":"注视地平仪，快速加油门至100%，同时快速拉杆转为爬升","C":"注视地平仪，快速加油门至100%，同时快速顶杆","D":"以上均不正确","answer":"A","exp":"由平飞转爬升时动作要领是柔和加油门、稍拉杆：注视地平仪保持姿态参考，柔和地将油门加至100%获得爬升功率，同时稍拉杆使机头缓缓抬起进入爬升状态。快速推油门加急拉杆会造成姿态过冲、速度骤降，顶杆则是下降动作。"},{"id":558,"type":"single","cat":"领航与任务规划","stem":"若一架无人机在飞行中可以进行舵面遥控，但无实时图像信号，地面站有各类仪表信息，但无法编辑航点航线，请问该无人机的遥控器（）正常，图传（）故障，数据电台（）正常，（）故障。","A":"下行链路、上行链路、下行链路、上行链路","B":"上行链路、下行链路、下行链路、上行链路","C":"上行链路、上行链路、下行链路、下行链路","D":"以上均不正确","answer":"B","exp":"链路方向以飞机为参照：遥控器到飞机的指令通道是上行链路，飞机到地面站的图像与数据通道是下行链路。能遥控舵面说明遥控器上行正常；无图像说明图传下行故障；地面站有仪表数据说明数据电台下行正常；无法编辑上传航点说明上行故障。"},{"id":559,"type":"single","cat":"领航与任务规划","stem":"在垂直矩形航线飞行训练科目中，无人机最大飞行高度为（）m。","A":"1","B":"1.5","C":"3","D":"7","answer":"D","exp":"垂直矩形航线属于无人机驾驶员实践考试科目，按考试要求最大飞行高度为7米，需在此高度内完成四边航线、90°转弯并保持高度与航迹稳定。1米、1.5米、3米高度过低，转弯半径和安全裕度均不能满足科目要求。"},{"id":560,"type":"single","cat":"设备与维护","stem":"以大疆产品为例，飞行器与遥控器电源开启方法为（）。","A":"短按","B":"长按","C":"短按，再长按","D":"长按，再短按","answer":"C","exp":"大疆飞行器与遥控器均采用短按再长按的开机方式：先短按一次激活电源键指示，再长按约2秒确认开机，防止运输携带中误触开机耗电。单一短按不生效，单一长按也不启动，关机为同样操作次序。"},{"id":561,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，姿态数据中，“H”代表什么？（）","A":"飞行器与起飞点之间的相对度距离","B":"飞行器与起飞点之间的相对水平距离","C":"飞行器沿垂直方向的上升、下降速度","D":"飞行器沿水平运动的飞行速度","answer":"A","exp":"大疆姿态数据中H是Height的缩写，表示飞行器与起飞点之间的相对高度，即垂直方向的距离，是判断限高和返航高度的依据。水平距离用D表示，垂直速度为V/S，水平速度为H/S，各字段含义不能混淆。"},{"id":562,"type":"single","cat":"基础概念","stem":"微型无人机，是指空机重量小于（）千克的无人机？","A":"0.25千克","B":"0.20千克","C":"0.15千克","D":"0.35千克","answer":"A","exp":"《无人驾驶航空器飞行管理暂行条例》按性能将无人机分类，微型无人机指空机重量小于0.25千克的无人驾驶航空器，可在符合规定的低空条件飞行。0.25千克是法规明确给出的界限值，其余数值均不符合该定义。"},{"id":563,"type":"single","cat":"设备与维护","stem":"已知某锂电池铭牌标记为6S2P3C，单片锂电池容量为16000mAh，则该电池最大放电电流是（）。","A":"16A","B":"48A","C":"96A","D":"以上均不正确","answer":"C","exp":"6S2P表示6串2并，并联使容量翻倍：16000mAh×2=32000mAh即32Ah。3C为放电倍率，最大放电电流=容量×倍率=32Ah×3=96A。只按单片16Ah计算得48A，漏算了并联，16A则连倍率都没乘。"},{"id":564,"type":"single","cat":"电力巡检","stem":"每次巡检作业结束后，（）应填写无人机巡检系统使用记录单。","A":"操控手","B":"程控手","C":"工作负责人","D":"工作许可人","answer":"C","exp":"巡检作业实行工作负责人负责制：每次作业结束后由工作负责人填写无人机巡检系统使用记录单，记录任务执行、设备状态与异常情况，形成闭环台账。操控手、程控手负责具体操作执行，工作许可人负责许可与接收报告，均不承担该记录职责。"},{"id":565,"type":"single","cat":"基础概念","stem":"关于多轴飞行器的优势描述不正确的是（）。","A":"成本低廉","B":"气动效率高","C":"结构简单便携","D":"以上均不正确","answer":"B","exp":"多旋翼的优势在于结构简单、成本低廉、便于携带、可垂直起降悬停，但其桨盘载荷大、滑流干扰强，气动效率并不高，续航性能也弱于固定翼，气动效率高恰是它的短板而非优势。其余描述均符合多旋翼特点。"},{"id":566,"type":"single","cat":"基础概念","stem":"对于续航时间计算，当检测到电量剩余（）时，开始报警，提示用户应该注意剩余点亮，提前做好返航准备。","A":"30%","B":"20%","C":"40%","D":"50%","answer":"A","exp":"按续航管理策略，飞控检测到电量剩余30%时触发低电报警，提示注意剩余电量并提前规划返航，为返航备降留足裕度；更低电量才报警可能来不及返航即被迫迫降。40%、50%报警过早影响作业效率，20%时已接近安全底线。"},{"id":567,"type":"single","cat":"操纵与飞行技术","stem":"飞机的姿态需要通过加速度计、（）等惯性传感器进行测量。","A":"陀螺仪","B":"GPS","C":"双目传感器","D":"位置传感器","answer":"A","exp":"姿态测量依赖惯性传感器：陀螺仪敏感角速度，积分得到姿态角变化，加速度计测量比力辅助解算，二者共同构成惯导姿态基准。GPS只能提供位置速度，双目传感器用于视觉避障与定位，位置传感器不感知角运动。"},{"id":568,"type":"single","cat":"基础概念","stem":"下列不属于在恶劣环境中使用过的飞机，进行清洁重点的选项是（）。","A":"电机","B":"飞控","C":"机架","D":"螺旋桨","answer":"C","exp":"在沙尘、盐雾、雨雪等恶劣环境中使用后，清洁重点是对性能和安全影响最直接的部位：电机内部进沙影响轴承与动平衡，飞控及接口易受污染短路，螺旋桨污损破坏气动外形。机架为承力结构件，表面积污对性能影响相对最小，不属清洁重点。"},{"id":569,"type":"single","cat":"领航与任务规划","stem":"无人机的GPS模块因损坏需进行替换，替换后重新安装，其位置距离螺旋桨有一定要求，下面安装位置正确的是（）。","A":"距离螺旋桨12cm","B":"距离螺旋桨8cm","C":"距离螺旋桨5cm","D":"安装在机体正下方","answer":"A","exp":"GPS模块靠接收微弱的卫星信号工作，电机与螺旋桨旋转产生的电磁干扰和振动会显著降低定位精度，安装时应远离螺旋桨等干扰源，距离保持12cm左右，并朝上避开机体遮挡。距离过近或装在机体正下方都会引入干扰与遮挡。"},{"id":570,"type":"single","cat":"航空气象","stem":"气压随高度按指数递减，其规律性比较明显，且飞机一般沿等压面飞行，故空气密度的变化主要由空气（）的变化所引起。","A":"压强","B":"湿度","C":"温度","D":"速度","answer":"C","exp":"标准大气中气压随高度按指数规律递减，飞机基本沿等压面飞行，气压差引起的密度变化很小，空气密度的变化主要取决于温度：温度升高气体膨胀密度减小，温度降低则密度增大，这也是高温天飞行性能下降的原因。湿度影响次要，速度不是成因。"},{"id":571,"type":"single","cat":"基础概念","stem":"在风中全马力飞行的固定翼民用无人机（）。","A":"顺风飞行时空速较大","B":"逆风飞行时空速较大","C":"顺风逆风空速相同","D":"以上均不正确","answer":"C","exp":"空速是无人机相对空气的运动速度，由空速管等直接测量。全马力飞行时发动机状态不变、相对气流的飞行状态不变，无论顺风还是逆风，空速都保持相同；风只改变无人机相对地面的地速，顺风地速大、逆风地速小，两种速度不能混淆。"},{"id":572,"type":"single","cat":"基础概念","stem":"爬升的注意事项，正确的是（）。","A":"飞行员不应以垂直上升作为主要的飞行方式","B":"垂直上升中，保持直升机状态比较容易","C":"要进入回避区","D":"标准","answer":"A","exp":"直升机爬升的注意要点是不应把垂直上升作为主要飞行方式：垂直上升需用功率最大，接近涡环回避区，稳定性差、余量小，仅狭小场地临时使用。垂直上升中保持状态其实很困难，更不能主动进入回避区，否则可能陷入涡环状态。"},{"id":573,"type":"single","cat":"飞行原理","stem":"8040螺旋桨，其螺距为（）。","A":"4in","B":"40in","C":"8in","D":"10.16in","answer":"A","exp":"螺旋桨型号8040前两位表示直径8英寸，后两位表示螺距4英寸，即桨叶旋转一周理论上前进的距离。40in把螺距放大十倍，8in误将螺距读成直径，10.16in则是8英寸换算成厘米的数值，均属常见误读。"},{"id":574,"type":"single","cat":"设备与维护","stem":"无刷电机去除了电刷，最直接的变化就是没有了有刷电机运转时产生的电火花，这样就极大减少了电火花对（）的干扰。","A":"动力系统","B":"地面站接收设备","C":"遥控无线电设备","D":"飞控系统","answer":"C","exp":"有刷电机靠电刷与换向器滑动接触换向，运转中不断产生电火花，是宽频电磁噪声源。无刷电机以电子换向取代机械换向，消除了电火花，最直接的收益就是大大减少对遥控无线电设备的干扰，避免遥控链路受噪声影响而失控。"},{"id":575,"type":"single","cat":"领航与任务规划","stem":"应根据无人直升机的（）合理规划航线。","A":"型号","B":"性能","C":"航程","D":"载荷","answer":"B","exp":"航线规划的前提是平台能力：应根据无人直升机的性能数据，包括最大航程、升限、速度、抗风、续航等，确定航点间距、飞行高度与任务剖面，使航线始终在安全包线之内。型号、航程、载荷只是性能的具体侧面，性能才是综合依据。"},{"id":576,"type":"single","cat":"航空气象","stem":"当在山谷、山脊或山区做低空飞行时，最容易碰到乱流造成危险的情况是（）。","A":"在山的背风面顺风飞行","B":"在山的背风面逆风飞行","C":"在山的迎风面逆风飞行","D":"在山的迎风面顺风飞行","answer":"A","exp":"山区低空飞行最危险的情形是沿背风面顺风飞行：气流越山后在背风坡形成强烈下沉气流与滚轴状乱流，顺风飞行使飞机快速进入下沉气流区，高度损失快且操纵裕度小，极易撞地。迎风面气流相对平稳，背风面逆风至少能及时脱离下沉区。"},{"id":577,"type":"single","cat":"电力巡检","stem":"（）应在每次巡检作业结束后的第二个工作日内前将相关变化情况报送工作许可人。","A":"工作负责人","B":"程控手","C":"工作许可人","D":"操控手","answer":"A","exp":"巡检信息报送责任在工作负责人：每次作业结束后的第二个工作日内，工作负责人应将设备、环境、电网等相关变化情况报送工作许可人，由其掌握现场条件、办理后续作业许可。程控手、操控手只负责操作层面，许可人本身是接收方。"},{"id":578,"type":"single","cat":"设备与维护","stem":"（）是后台指挥中心与前线地面执行人员沟通的枢纽，是最清楚整体行动方案的人，由云台手负责指挥飞行，（）主要负责飞行安全。","A":"飞手，云台手","B":"云台手，飞手","C":"飞手，飞手","D":"云台手，云台手","answer":"B","exp":"航拍作业分工中，云台手负责取景构图，掌握任务画面需求，是后台指挥中心与前线执行人员沟通的枢纽，最清楚整体行动方案，并据此指挥飞行；飞手专注操纵飞行器、规避风险，主要负责飞行安全。两个角色的核心职责不能互换。"},{"id":579,"type":"single","cat":"基础概念","stem":"多旋翼无人机为保证机身稳定防止机身自旋，相对旋翼转动方向（）。","A":"相同","B":"相反","C":"垂直","D":"水平","answer":"A","exp":"多旋翼靠相邻旋翼转向相反、反扭矩相互抵消来防止机身自旋。沿同一对角线布置的相对旋翼转向相同，两对角线之间转向相反，这样每对旋翼的反扭矩相互平衡，总反扭矩可控。因此相对旋翼的转动方向是相同的。"},{"id":580,"type":"single","cat":"基础概念","stem":"无人机飞行摇杆常规操作方式是（）。","A":"姿态遥控和舵面遥控","B":"自主控制","C":"人工修正","D":"以上均不正确","answer":"A","exp":"无人机摇杆的常规操作方式分两类：舵面遥控直接操纵升降舵、方向舵等舵面，类似有人机操纵；姿态遥控时摇杆控制飞行器姿态角，飞控闭环稳定飞行。日常飞行训练围绕这两种方式进行，自主控制由地面站上传航线完成，不依赖摇杆连续操作。"},{"id":581,"type":"single","cat":"基础概念","stem":"不能在压线、信号发射塔附近进行飞行的原因不包含的是？（）","A":"有可能对飞行器磁罗盘信号造成扰","B":"会造成飞行器飞行效率下降","C":"有可能对飞行器遥控器信号造成扰","D":"有可能造成飞行器失控","answer":"B","exp":"高压线与信号发射塔的主要威胁是电磁干扰：交变电磁场可能干扰磁罗盘信号，发射塔的射频场强可能干扰遥控器信号，严重时导致飞行器失控。这些风险都源于电磁环境，飞行效率下降与电磁干扰无必然联系，不是此类区域应避开的原因。"},{"id":582,"type":"single","cat":"基础概念","stem":"应核对（）是否满足安全飞行要求。","A":"航迹规划","B":"任务规划","C":"航线规划","D":"飞行规划","answer":"C","exp":"飞行前应核对航线规划是否满足安全飞行要求：检查航线高度、与障碍物和禁飞区的距离、航点衔接及返航路径，确认无冲突后方可执行。任务规划、飞行规划是泛化说法，缺乏明确对象，核对的具体对象就是已编辑完成的航线。"},{"id":583,"type":"single","cat":"基础概念","stem":"一份详细的测试报告包含足够的信息，包括（），下列选项错误的是。","A":"产品质量和测试过程的评价","B":"测试报告基于测试中的数据采集","C":"测试原因","D":"对最终的测试结果分析","answer":"C","exp":"完整的测试报告应包含产品质量与测试过程的评价、基于测试过程的数据采集以及对最终测试结果的分析，三者构成证据链。测试原因属于立项阶段的输入信息，记录在测试方案或任务书中，不属测试报告的必备内容，故该说法错误。"},{"id":584,"type":"single","cat":"设备与维护","stem":"电机的定子22084T1000KV是指（）。","A":"22定子直径毫米，08定子的高度毫米，1000KV每分钟每V电压1000转","B":"22定子直径英寸，08定子的高度英寸，1000KV每分钟每V电压1000转","C":"22定子直径毫米，08定子的高度毫米，1000KV每分钟1000转","D":"以上均不正确","answer":"A","exp":"无刷电机定子型号2208表示定子直径22毫米、高度08毫米；KV值1000表示每施加1伏电压电机每分钟空载转1000转，KV值乘以电压即可估算转速。以英寸为单位与毫米标注不符，每分钟1000转的说法漏掉了每伏这一条件。"},{"id":585,"type":"single","cat":"操纵与飞行技术","stem":"飞机在起飞着陆前放下襟翼的作用是（）。","A":"增加升力","B":"增加阻力","C":"增大摩擦力","D":"增大升力的同时增加阻力","answer":"D","exp":"襟翼放下后增大机翼弯度与有效面积，同速下升力增大，便于以更低速度起飞离地与着陆；同时襟翼也显著增大阻力，使飞机减速快、下滑角变陡、接地更稳。只说增升或只说增阻都不完整，两项作用同时存在。"},{"id":586,"type":"single","cat":"基础概念","stem":"下哪种情况，磁罗盘信号不会受扰？（）","A":"停车场","B":"空旷场地","C":"磁矿上方","D":"大块属四周","answer":"B","exp":"磁罗盘敏感地磁场定向，凡存在人工磁场的环境都会干扰：停车场车辆与钢筋结构密集，磁矿上方地磁异常，大块金属四周磁场畸变，均导致罗盘误差甚至校准失败。空旷场地无上述磁源，罗盘信号不受干扰，是校准与起降的理想环境。"},{"id":587,"type":"single","cat":"设备与维护","stem":"测试过程中多旋翼无人机通过牵引绳对测重块施加向上提拉力，从而使测力传感器的检测数据逐渐减小，当所述测力传感器的检测数值稳定后，减小量即为多旋翼无人机的（）。","A":"载重量","B":"重量","C":"起飞重量","D":"安全重量","answer":"A","exp":"测试原理是差值测量：多旋翼悬停时通过牵引绳向上提拉测重块，测力传感器读数减小，稳定后的减小量正等于无人机实际输出的向上提升载荷，即载重量。无人机自身重量、起飞重量是整机参数，不能由该提拉差值直接得出。"},{"id":588,"type":"multi","cat":"基础概念","stem":"操控手应始终注意观察无人机（）等信息，判断系统工作是否正常。","A":"巡检系统飞行姿态","B":"发动机或电机运转声音","C":"电池电压","D":"航向","answer":"AB","exp":"操控手目视操控时应持续观察两类直观信息：飞行姿态是否平稳、有无异常晃动或倾斜，发动机或电机运转声音是否均匀正常，借助视觉与听觉及时判断系统工作状态。电池电压由地面站仪表监测，航向由程控系统与地面站掌握，均不属操控手的目视判断要素。"},{"id":589,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中：目前，以（）无人机为飞行平台的输电线路无人机巡检技术已取得了显著的成效。","A":"小型旋翼","B":"固定翼","C":"中型","D":"中大型","answer":"AB","exp":"输电线路巡检实践表明，成效显著的是两类平台：小型旋翼机可悬停、机动灵活，适合对杆塔金具近距离精细拍照；固定翼机速度快、航程远，适合长距离走廊巡线。中型、中大型平台受空域管制和成本限制，尚未大规模普及。"},{"id":590,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，白天工作间断时，应将发动机处于（），并采取其他必要的安全措施，必要时派人看守。","A":"停运状态","B":"电机下电","C":"关闭","D":"电机运行","answer":"AB","exp":"白天工作间断时为消除意外启动与误动风险，应将发动机处于停运状态，并使电机下电，切断动力输出，同时采取其他必要安全措施，必要时派人看守。保持电机运行与间断安全要求直接相悖，仅关闭点火或电源而不使电机下电也不能满足要求。"},{"id":591,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，当无人机出现（）等故障时，应及时修正舵向，调节速度、高度，恢复通信链路，若长时间无法恢复正常，应视无人机状态由工作负责人决定是否终止巡检作业。","A":"姿态不稳","B":"航迹偏移大","C":"链路不畅","D":"速度过快","answer":"ABC","exp":"巡检中若出现姿态不稳、航迹偏移大、链路不畅等故障，应及时修正舵向、调节速度高度，尝试恢复通信链路；长时间无法恢复的，由工作负责人视无人机状态决定是否终止作业。速度过快属于可由操纵直接调节的飞行参数，不属于此处列举的系统故障类型。"},{"id":592,"type":"multi","cat":"电力巡检","stem":"使用固定翼无人机巡检系统进行的架空输电线路巡检作业，工作班成员至少包括（）","A":"飞控手","B":"任务手","C":"程控手","D":"操控手","answer":"CD","exp":"固定翼巡检作业按规程至少配置两名工作班成员：程控手负责航线装订、程控飞行与参数监控，操控手负责起降阶段的遥控操纵与应急接管，二者互为备份确保链路和飞行安全。飞控手、任务手不是该规程规定的工作班岗位名称。"},{"id":593,"type":"single","cat":"基础概念","stem":"无人机（）越大，爬升需用功率也越（）。","A":"质量、小","B":"质量、大","C":"体积、大","D":"体积、小","answer":"B","exp":"爬升需用功率近似等于重力与爬升率的乘积，再叠加平飞需用功率。无人机质量越大，重力越大，维持同样爬升率所需功率越大，同时诱导阻力也随之增大，进一步推高功率需求。体积与爬升功率没有直接的函数关系。"},{"id":594,"type":"single","cat":"基础概念","stem":"固定翼无人机机电系统由动力单元、（）、燃油、电子调速器、配电系统和机载电源组成，提供无人机飞行所需的动力和能源。","A":"机翼","B":"螺旋桨","C":"数据链机载终端","D":"地面站","answer":"B","exp":"固定翼机电系统由动力单元、螺旋桨、燃油、电子调速器、配电系统和机载电源组成：燃油经动力单元做功，由螺旋桨转化为拉力，电调、配电与机载电源完成能量调节分配。机翼属气动结构，数据链与地面站属信息链路，不在其中。"},{"id":595,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机机体通常由（）的模块化机体组成，既方便携带，又可以在短时间内完成组装、起飞。","A":"可重复利用","B":"可拆卸","C":"可回收","D":"可丢弃","answer":"B","exp":"固定翼无人机机体普遍采用可拆卸的模块化设计，机翼、尾翼、机身分段通过快拆机构连接，运输时拆开便于携带，到场后短时间内即可完成组装检查并起飞。可重复利用、可回收描述的是材料属性，可丢弃与模块化便于组装的初衷相悖。"},{"id":596,"type":"single","cat":"设备与维护","stem":"遥控无人机固定翼当蒙皮上结霜（）。","A":"失速速率减小","B":"失速速率增加","C":"失速速率增大或减小","D":"以上均不正确","answer":"B","exp":"蒙皮结霜后表面粗糙度增大，边界层提前分离，相同迎角下升力系数下降、最大升力系数减小，失速提前发生，对应的失速速率即失速速度增大。结霜使失速速率减小的说法与空气动力学规律相反，临界迎角也随霜层降低。"},{"id":597,"type":"single","cat":"基础概念","stem":"关于多旋翼无人机抗雨性能测试，下列说法错误的是（）。","A":"静置淋雨，放置在台风淋雨箱体中间位置，启动并处于怠速状态，保持运行5分钟，多旋翼无人机在雨中能正常旋转","B":"淋雨后检验，放置在外场，检查雨后机体状态，并进行起飞、悬停、降落检查，多旋翼无人机运行正常","C":"雨中悬停，进行雨中悬停，保持5分钟，多旋翼无人机在雨中正常悬停，起降正常","D":"雨中应急返航，进行应急返航，只需返航过程中多旋翼无人机运行正常，安全降落即可","answer":"D","exp":"多旋翼抗雨测试包含静置淋雨、淋雨后检验、雨中悬停、雨中应急返航等项目，其中应急返航不能只要求返航过程运行正常：还应检查机体进水情况、电气系统状态与降落质量，确认安全降落且功能完好才算通过，只需返航正常即可的放宽表述错误。"},{"id":598,"type":"single","cat":"飞行原理","stem":"测量机翼的翼弦是从（）。","A":"机身中心线到翼尖","B":"左翼尖到右翼尖","C":"机翼前缘到后缘","D":"以上均不正确","answer":"C","exp":"翼弦是翼型前后缘的连线长度，测量机翼翼弦即从机翼前缘量到后缘，它是计算迎角、展弦比与雷诺数的基本几何参数。机身中心线到翼尖量的是半翼展，左翼尖到右翼尖是翼展，均非弦长。"},{"id":599,"type":"single","cat":"领航与任务规划","stem":"遥控无人机着陆时，对用侧滑与改变航向相结合的方法修正侧风影响描述正确的是（）。","A":"退出第四转弯的时机应根据风向适当提前或延迟","B":"退出第四转弯的时机一律适当提前","C":"退出第四转弯的时机一律适当延迟","D":"以上均不正确","answer":"A","exp":"修正侧风采用侧滑与改变航向相结合：第四边保持侧滑对正跑道，转弯改出时根据风向调整时机，侧风使航线偏移提前时适当提前退出第四转弯，偏移滞后则适当延迟，随机应变对正下滑线。一律提前或一律延迟都会造成五边偏出。"},{"id":600,"type":"single","cat":"基础概念","stem":"无人机越往高空飞行（飞行速度不变），飞行所获得的（）就越小。","A":"升力","B":"重力","C":"推力","D":"以上均不正确","answer":"A","exp":"升力与空气密度成正比，表达式为升力系数乘二分之一密度乘速度平方乘机翼面积。高度升高空气密度按指数规律下降，飞行速度不变时动压减小，无人机获得的升力随之减小；重力取决于质量不变，推力不随高度按同一规律下降。"},{"id":601,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员姿态遥控模式下操纵无人机下降，速度过大时，下列正确的操纵是（）。","A":"适当增加带杆量，减小下滑角","B":"适当减小带杆量，减小下滑角","C":"适当减小带杆量，增大下滑角","D":"以上均不正确","answer":"A","exp":"姿态模式下降中速度过大，说明下滑角过陡、重力前向分量过强，应适当增加带杆量抬机头减小下滑角，下滑角变小后下降速度随之减小，同时注意保持速度不低于安全值。减小带杆量只会加大下滑角使速度更快，与修正目标相反。"},{"id":602,"type":"single","cat":"基础概念","stem":"低高度通场是指无人机在飞行过程中从机场跑道上空飞过或是从观礼台前方上空飞过，是无人机表达敬意的一种方式一般认为（）米以下都可以视为低高度。","A":"5","B":"50","C":"100","D":"150","answer":"A","exp":"低高度通场是无人机从跑道或观礼台上空通过以表达敬意的飞行仪式，通场高度一般认为在5米以下，既保证视觉效果，又留有最小安全裕度。50米以上已属正常飞行高度，达不到通场的仪式意义，100米、150米更高。"},{"id":603,"type":"single","cat":"领航与任务规划","stem":"关于航向锁定功能，下列描述正确的是（）。","A":"飞行器始终按机头为前向飞行","B":"飞行器按锁定前的机头朝向为前向飞行","C":"需将遥控器切换到S档","D":"需将遥控器切换到A档","answer":"B","exp":"航向锁定即机头朝向锁定功能：启动瞬间记录当前机头朝向，此后无论摇杆向哪个方向打杆，飞行器都以锁定前的机头朝向作为前进方向飞行，便于失控找回或定向拍摄。切换S档A档是运动模式与姿态模式的操作，与该功能无关。"},{"id":604,"type":"single","cat":"基础概念","stem":"无人机盘旋飞行时，无人机内，外机翼的线速度是不相同的内翼速度（），外翼速度（）。","A":"小，小","B":"大，大","C":"小，大","D":"大，小","answer":"C","exp":"盘旋时全机绕同一圆心以相同角速度转动，线速度等于角速度乘半径：内机翼旋转半径小、线速度小，外机翼半径大、线速度大。两侧翼面速度差导致升力差，这正是盘旋需要压坡度并配合副翼修正的原因。"},{"id":605,"type":"single","cat":"设备与维护","stem":"垂起固定翼无人机电子电气部件的日常维护保养，下列选项错误的是（）。","A":"检查各电线外皮是否完好，有无刮擦脱皮等现象","B":"检查飞行器的重心位置是否正确","C":"检查飞行器电池安装是否正确，电池电量是否充足","D":"检查电机安装是否紧固，有无松动等现象","answer":"B","exp":"垂起固定翼电子电气部件的日常保养对象是电气系统本身：检查电线外皮有无刮擦脱皮、电池安装与电量、电机安装有无松动等均属电子电气范围。重心位置属于机体结构与装载平衡检查项目，不归入电子电气部件维护，故该项说法错误。"},{"id":606,"type":"single","cat":"基础概念","stem":"无人机电气系统中，电源和（）两者组合统称为供电系统。","A":"配电系统","B":"供电线路","C":"用电设备","D":"以上均不正确","answer":"A","exp":"供电系统的定义为电源与配电系统的组合：电源产生电能，配电系统将电能按各用电设备的需求分配并保护线路，二者合起来才能完成从产生到分配的完整供电过程。供电线路只是配电的载体，用电设备是供电对象，均不能与电源并列构成供电系统。"},{"id":607,"type":"single","cat":"基础概念","stem":"亚音速气流经过收缩管道后（）。","A":"速度增加，压强增大","B":"速度降低，压强下降","C":"速度增加，压强下降","D":"以上均不正确","answer":"C","exp":"亚音速气流满足连续性方程与伯努利定理：管道收缩时截面积减小，流速必须增大以保持质量流量守恒；由伯努利定理，速度增加则静压下降。速度增加压强增大违背能量守恒，速度降低对应的是管道扩张而非收缩。"},{"id":608,"type":"single","cat":"操纵与飞行技术","stem":"使用返航锁定时，遥控器横滚杆向左打杆，飞行器将？（）","A":"向左曲线飞行","B":"向左沿直线飞行","C":"向右曲线飞行","D":"向右沿直线飞行","answer":"A","exp":"返航锁定状态下飞行器自主飞向返航点，此时打横滚杆仍可横向修正：横滚杆向左打杆，飞行器向左偏移，沿曲线绕向返航点，用于绕开沿途障碍物。返航锁定并非完全锁死操纵，沿直线向左飞行与向右动作均不符合其响应逻辑。"},{"id":609,"type":"single","cat":"基础概念","stem":"以下无人机中，需要跑道起降的是（）？","A":"固定翼无人机","B":"无人直升机","C":"多旋翼无人机","D":"六轴飞行器","answer":"A","exp":"固定翼无人机依靠机翼与空气的相对速度产生升力，常规起降需要滑跑加速到离地速度，因此需要跑道；无人直升机、多旋翼与六轴飞行器具备垂直起降能力，只需小块平整场地即可起降，不依赖跑道。"},{"id":610,"type":"single","cat":"设备与维护","stem":"用遥控器设置无人机的电调，需要（）。","A":"断开电机","B":"接上电机","C":"断开动力电源","D":"以上均不正确","answer":"B","exp":"用遥控器设置电调如油门行程校准时必须接上电机：设置过程依赖电调提示音和电机转动反馈确认油门行程端点，缺了电机无法判断设置是否生效。设置时通常卸掉螺旋桨防止转动伤人，但不能断开电机或动力电源。"},{"id":611,"type":"single","cat":"基础概念","stem":"多旋翼无人机磁罗盘正确校准的方法是（）。","A":"校准时需要水平和垂直","B":"校准时应靠近强磁场区域","C":"校准时可以在雷雨天气","D":"校准时机身可以任意倾斜角度","answer":"A","exp":"多旋翼磁罗盘校准的正确做法是让机身在水平位置绕竖轴旋转数圈，再将机头朝下或朝上在垂直位置旋转数圈，使传感器感知全向磁场建立补偿模型。校准应远离强磁场并在天气良好时进行，雷雨天气电磁环境复杂不宜操作，任意倾斜无法建准模型。"},{"id":612,"type":"single","cat":"设备与维护","stem":"打开遥控器前检查哪几步？（）","A":"天线、开关、油门位置","B":"电压、油门位置、中立微调","C":"发射制式、模型类型、电压","D":"以上均不正确","answer":"A","exp":"开机前对遥控器的检查顺序是：确认天线安装完好无松动、各开关处于预设位置、油门摇杆位于最低位，防止通电瞬间电机意外转动。电压、中立微调属开机后核对项，发射制式与模型类型是初次配置内容，均不属于开机前的检查步骤。"},{"id":613,"type":"single","cat":"设备与维护","stem":"经验表明无人机每飞行（）小时或者更少就需要某种类型的预防性维护，至少每（）小时进行较小的维护。","A":"30，60","B":"20，50","C":"25，40","D":"以上均不正确","answer":"B","exp":"维修经验统计表明，无人机每飞行20小时或更少就需要进行某种类型的预防性维护，且至少每50小时进行一次较小的维护，以超前发现松动、磨损等隐患。间隔放到30/60或25/40都会超出经验验证的维护周期，安全裕度不足。"},{"id":614,"type":"single","cat":"基础概念","stem":"飞行前检查，下列哪一项最危险（）。","A":"电池表面有轻微污渍","B":"电池电量90%","C":"遥控器表面有污渍","D":"套筒未旋紧或卡扣未卡紧","answer":"D","exp":"四项检查项中最危险的是套筒未旋紧或卡扣未卡紧：飞行中螺旋桨或部件高速旋转，一旦脱落飞机会立即失去升力或平衡，直接坠机并可能伤人。表面污渍只影响外观，电量90%属充足状态，都不构成飞行安全隐患。"},{"id":615,"type":"single","cat":"操纵与飞行技术","stem":"直升机飞行中需要的操纵（）。","A":"需要六个，因为直升机空中有六个自由度","B":"需要三个操纵就可以改变俯仰、横测和航向姿态","C":"需要四个操纵才能改变与保持所需姿态","D":"以上均不正确","answer":"B","exp":"直升机通过三个基本操纵即可改变俯仰、横滚和航向姿态：周期变距杆控制旋翼锥体倾斜实现俯仰与横滚，脚蹬改变尾桨拉力控制航向，总距杆与油门联动控制升沉，三个通道覆盖姿态与航向操纵需求。空中虽有六个自由度，但并不需要六个操纵。"},{"id":616,"type":"single","cat":"基础概念","stem":"飞行前检查的第一项是（）。","A":"重心","B":"紧固件","C":"电压","D":"以上均不正确","answer":"B","exp":"飞行前检查的第一项是紧固件：逐个确认机臂、桨夹、起落架等部位螺丝与卡扣紧固到位。结构连接是安全的基础，任何松动在振动中都会放大直至部件脱落；重心、电压等检查都在确认结构可靠之后再进行，顺序不能颠倒。"},{"id":617,"type":"single","cat":"基础概念","stem":"多旋翼1.1米轴距代表什么意思？（）","A":"对角电机之间的直径距离为1.1米","B":"相邻电机之间的直径距离为1.1米","C":"对角电机之间的半径距离为1.1米","D":"以上均不正确","answer":"A","exp":"多旋翼轴距指沿对角线方向相对两个电机轴之间的距离，1.1米轴距即对角电机之间的直径距离，它决定可搭配的螺旋桨尺寸与整机推重比。相邻电机间距小于轴距，半径距离则是轴距的一半，均不是轴距的定义。"},{"id":618,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操纵无人机无坡度转弯，正确的操纵方式是（）。","A":"向转弯方向压方向舵，副翼同方向打以保证坡度水平","B":"向转弯方向压方向舵，副翼反打以保证坡度水平","C":"向转弯方向压方向舵，副翼同方向打以形成坡度","D":"以上均不正确","answer":"B","exp":"无坡度转弯要求机身保持水平、不压坡度，仅改变航向：向转弯方向压方向舵使机头偏转，同时副翼反方向修正以抵消转弯中的自然滚转趋势，保证坡度始终水平。副翼同向打杆会形成坡度，那就成了普通的压坡度转弯。"},{"id":619,"type":"single","cat":"基础概念","stem":"多旋翼无人机机体一般由机身、（）、起落架和结构挂载件组成。","A":"电气系统","B":"任务载荷设备","C":"机臂","D":"地面站","answer":"C","exp":"多旋翼机体结构一般由机身、机臂、起落架和结构挂载件组成：机身安装中心板与设备，机臂连接电机承载旋翼，起落架支撑缓冲，结构挂载件安装任务设备。电气系统、任务载荷是功能系统，地面站属地面设备，都不在机体结构之列。"},{"id":620,"type":"single","cat":"飞行原理","stem":"为了使固定翼无人机飞行中俯仰为矩平衡，电动机相对无人机纵轴一般有向下（）的下拉安装角。","A":"1～1.5°","B":"1.5～3°","C":"3～4.5°","D":"5.5～6°","answer":"B","exp":"为使固定翼飞行中俯仰力矩平衡，电动机相对机身纵轴一般设置向下的下拉安装角，取1.5～3°：拉力线相对重心产生配平力矩，与机翼、平尾的俯仰力矩相抵，油门变化时俯仰扰动更小。角度过小配平不足，过大则推进效率损失明显。"},{"id":621,"type":"single","cat":"基础概念","stem":"多轴飞行时地面人员手里拿的“控”指的是（）。","A":"地面遥控发射机","B":"链路系统","C":"导航飞控系统","D":"以上均不正确","answer":"A","exp":"地面人员手持的控是地面遥控发射机即遥控器，通过无线电链路把摇杆指令发往机载接收机，是人工操纵的直接工具。链路系统是包含发射、接收、传输的整体，导航飞控系统位于机载端，均不是这个口语说法所指的对象。"},{"id":622,"type":"single","cat":"设备与维护","stem":"多旋翼机身由上中心板、下中心板、分电板、电池挂板和（）组成。","A":"飞行控制系统（自驾仪）减震板","B":"飞行控制系统（自驾仪）主板","C":"相机挂板","D":"光流挂板","answer":"A","exp":"多旋翼机身的标准组成是上中心板、下中心板、分电板、电池挂板和飞行控制系统减震板：上下中心板构成机架主体，分电板分配动力电，电池挂板承载电池，减震板隔离机体振动、保护自驾仪姿态传感器，这是成熟机架的典型配置。"},{"id":623,"type":"single","cat":"领航与任务规划","stem":"飞行器与返航点超过（）米才可以启动返航锁定？（）","A":"5米","B":"10米","C":"15米","D":"20米","answer":"A","exp":"返航锁定要求飞行器与返航点距离超过5米才可启动：距离过近时若执行返航，飞行器先爬升到返航高度再水平返回反而增加风险，近距离应采用直接降落的处置方式。10米以上数值并非该功能的判定门限。"},{"id":624,"type":"single","cat":"设备与维护","stem":"检查无刷电机动平衡是否良好的方法描述正确的是（）。","A":"电机不带螺旋桨进行旋转","B":"电机带动螺旋桨进行旋转","C":"用手转动电机","D":"将飞行器起飞，感受飞行器机身振动","answer":"A","exp":"检查无刷电机动平衡应让电机不带螺旋桨旋转：此时观察到的振动即来自电机转子本身，若运转平稳说明电机平衡良好。带动桨旋转无法区分振动源于电机还是螺旋桨，手转只能感受轴承阻力，起飞感受则混入整机所有振源，都不能定位电机问题。"},{"id":625,"type":"single","cat":"操纵与飞行技术","stem":"民用无人驾驶航空器系统视距内运行是指航空器处于驾驶员或观测员目视视距内半径（）米，相对高度低于（）米的区域内。","A":"500、120","B":"500、100","C":"120、50","D":"250、120","answer":"A","exp":"视距内运行以驾驶员或观测员肉眼能直接看见航空器为前提，规定目视视距内半径不超过500米、相对高度低于120米，其中真高120米与无人机适飞空域高度上限一致，超出即为超视距运行；易混淆的100米并非法定界限。"},{"id":626,"type":"single","cat":"飞行原理","stem":"为了飞行安全，飞机飞行时的升力系数和迎角一般为（）。","A":"最大升力系数和临界迎角最大","B":"最大升力系数和小于临界迎角的迎角限定值","C":"小于最大升力系数和临界迎角的两个限定值","D":"以上均不正确","answer":"C","exp":"飞行中迎角应控制在临界迎角以内并留有裕度，升力系数相应小于最大升力系数，若接近临界迎角，气流分离导致失速，升力骤降且操纵变差；以为可用最大升力系数和临界迎角飞行，忽略了必须保留的安全余量。"},{"id":627,"type":"single","cat":"飞行原理","stem":"关于旋翼的反扭矩说法正确的是（）。","A":"旋翼的反扭矩会迫使直升机向旋翼旋转的反方向偏转","B":"旋翼反扭矩的大小取决于发动机最大功率的大小","C":"发动机带动旋翼旋转时，旋翼诱导阻力力矩为发动机传递给旋翼轴的扭矩所平衡标准","D":"以上均不正确","answer":"A","exp":"发动机驱动旋翼旋转时，空气对旋翼的反作用扭矩使机身向旋翼旋转的反方向偏转，需靠尾桨拉力形成平衡力矩；反扭矩大小随飞行状态所需功率变化，并非取决于发动机最大功率，也不能由诱导阻力力矩自身平衡。"},{"id":628,"type":"single","cat":"法规与空域","stem":"（）是指专门分配给无人机系统运行的空域，通过限制其他航空器的进入以规避碰撞风险。","A":"隔离空域","B":"融合空域","C":"监视空域","D":"报告空域","answer":"A","exp":"隔离空域是专门划设分配给无人机运行的空域，通过限制其他航空器进入实现隔离、规避碰撞风险；融合空域则是无人机与有人航空器在同一空域内混合飞行，把专门分配、限制他人进入的特征记到融合空域上就错了。"},{"id":629,"type":"single","cat":"基础概念","stem":"下面直升机旋翼的结构形式是无铰式旋翼的是（）。","A":"法国的松鼠直升机","B":"BO-105直升机","C":"直-11型直升机","D":"以上均不正确","answer":"B","exp":"BO-105是较早实现批量生产的无铰式旋翼直升机，桨叶经柔性元件与桨毂相连，取消了挥舞铰和摆振铰；法国松鼠采用星形柔性旋翼，直-11沿用松鼠的技术路线，均不属无铰式，判别关键在桨毂构造。"},{"id":630,"type":"single","cat":"法规与空域","stem":"关于为什么无人机要远离国家边境线，描述最准确的是？（）","A":"从电磁安全方考虑","B":"从气象安全方考虑","C":"从避免出现边境纠纷方考虑","D":"因为边境线飞行环境不好","answer":"C","exp":"边境线附近飞行一旦偏航越境即侵入他国领空，可能引发边境纠纷甚至军事误判，涉外后果远重于一般安全事故，故无人机作业应远离国境线；电磁、气象因素并非主要原因，边境环境好坏更是表面说法。"},{"id":631,"type":"single","cat":"基础概念","stem":"无人机更换舵角时，以下各部件中只有（）的活动面适合安装。","A":"机身","B":"副翼","C":"襟翼","D":"机臂","answer":"B","exp":"舵角是与舵机拉杆相连、把操纵力传给舵面的传动件，必须装在受舵机直接操纵的活动面上，副翼正是这样的活动舵面；机身、机臂是固定结构无法偏转，襟翼多用于增升不单独承担横侧操纵，不适合安装舵角。"},{"id":632,"type":"single","cat":"设备与维护","stem":"下面关于遥控器闲置情况下的描述正确是（）。","A":"遥控器闲置10分钟后将发出报警，闲置15分钟将关机","B":"遥控器闲置8分钟后将发出报警，闲置15分钟将关机","C":"遥控器闲置6分钟后将发出报警，闲置12分钟将关机","D":"遥控器闲置5分钟后将发出报警，闲置10分钟将关机","answer":"D","exp":"遥控器设有闲置保护：长时间无操作时，闲置约5分钟先发出报警提醒，闲置约10分钟自动关机，防止误耗电和误触发；10分钟报警、15分钟关机等其他时间组合与这一设定不符，记住先报警、后关机的先后顺序。"},{"id":633,"type":"single","cat":"设备与维护","stem":"遥控器（美国手）左侧摇杆向前推飞行器会做怎样动作（）。","A":"飞行器向前飞行","B":"飞行器向左飞行","C":"飞行器向上飞行","D":"飞行器逆时针旋转","answer":"C","exp":"美国手即Mode 2布局，左摇杆上下通道为油门，向前推则油门增大，旋翼转速与总拉力增加，飞行器上升；左摇杆左右才是偏航，前进后退由右摇杆控制，把它当成向前飞行是通道功能没分清。"},{"id":634,"type":"single","cat":"操纵与飞行技术","stem":"姿态遥控模式下操纵无人机爬升，俯仰角偏低时，下列正确的操纵是（）。","A":"应柔和地向右扭舵","B":"应柔和地向前顶杆","C":"应柔和地向后带杆","D":"以上均不正确","answer":"C","exp":"姿态模式下摇杆量直接对应俯仰角，爬升中俯仰角偏低说明机头上仰不足，应柔和向后带杆增大俯仰角、增强爬升趋势；向前顶杆会压低机头使爬升更弱甚至转为下滑，扭舵只改变航向，不改变俯仰。"},{"id":635,"type":"single","cat":"航空气象","stem":"无人机飞行员在操纵飞机平飞时，遇到强烈的垂直上升气流时，为了防止过载超规定应（）。","A":"适当减小飞行速度","B":"加大油门迅速脱离","C":"以最大上升率增大高度","D":"以上均不正确","answer":"A","exp":"强烈垂直气流使相对气流方向突变、迎角骤增，升力猛增形成附加过载，速度越大阵风过载越大，故平飞遇到强上升气流应适当减小飞行速度以降低过载峰值；加大油门迅速脱离反而增大速度，过载更容易超限。"},{"id":636,"type":"single","cat":"操纵与飞行技术","stem":"固定翼无人机着陆和起飞时，描述正确的是（）。","A":"固定翼无人机一般顺风起飞","B":"固定翼无人机一般顺风着陆","C":"固定翼无人机一般逆风着陆","D":"固定翼无人机起降不受风的影响","answer":"C","exp":"逆风着陆时相对空速大、升力充足，地速小使滑跑距离短、接地平稳，操纵裕度大，故固定翼通常逆风起飞着陆；顺风起降会使滑跑距离明显增长、接地速度偏大，起降并非不受风影响，风向选择是基本功。"},{"id":637,"type":"single","cat":"基础概念","stem":"在对无人机电动系统组装时，依据所选电动机的最大额定电流选择所需（）。","A":"电池","B":"电动机","C":"电调","D":"飞控","answer":"C","exp":"电调串接在电池与电机之间，必须承受并调节电机的最大工作电流，选配时应依据所选电动机的最大额定电流，使电调持续电流留有余量；电池容量按续航需求选择，飞控、机臂与该电流匹配无直接关系。"},{"id":638,"type":"single","cat":"飞行原理","stem":"关于多轴飞行器的反扭矩说法不正确的是（）。","A":"多轴飞行器的俯仰运动通过改变各个旋翼的反扭矩来实现","B":"单个旋翼反扭矩的大小取决于电动机转速","C":"单个旋翼的反扭矩会迫使多轴飞行器向旋翼旋转的反方向偏转","D":"以上均不正确","answer":"A","exp":"多轴的俯仰靠横轴前后电机升力差实现，偏航才利用各旋翼反扭矩之差控制，把俯仰运动归因于改变反扭矩的说法不成立；单个旋翼反扭矩大小确实随电机转速变化，方向则与旋翼旋转方向相反，使机身反转。"},{"id":639,"type":"single","cat":"基础概念","stem":"无人机系统飞行器平台主要使用的是（）空气的动力驱动的航空器。","A":"等于","B":"重于","C":"轻于","D":"以上均不正确","answer":"B","exp":"无人机飞行器平台绝大多数属于重于空气的航空器，依靠机翼或旋翼相对空气运动产生升力克服重力，如固定翼、多旋翼与无人直升机；轻于空气的气球、飞艇仅占少数，重于空气是无人机平台的基本属性。"},{"id":640,"type":"single","cat":"设备与维护","stem":"一块聚合物锂电池上标有25C字样，C代表（）。","A":"充电倍率","B":"容量倍率","C":"放电倍率","D":"以上均不正确","answer":"C","exp":"锂电池标注的C指放电倍率，衡量持续放电能力，如25C配2200毫安时容量，理论持续放电电流约55安，数值越大支持的大电流放电越强；充电倍率一般远小于此并另行标注，把C当成容量倍率就混淆了概念。"},{"id":641,"type":"single","cat":"领航与任务规划","stem":"同航线同重量，哪种受风力影响最小？（）","A":"速度快","B":"速度慢","C":"速度比重","D":"以上均不正确","answer":"A","exp":"风以矢量叠加方式改变地速，飞行速度越大，同一风速在地速中所占比例越小，往返航线的时间偏差也越小，故速度快受风力影响小；速度慢时风占比大，往返总耗时偏差更明显，同重量同航线条件下尤其如此。"},{"id":642,"type":"single","cat":"操纵与飞行技术","stem":"悬停状态的六轴飞行器如何实现向前移动（）。","A":"纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速","B":"横轴前侧的螺旋桨减速，横轴后侧的螺旋桨加速","C":"横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速","D":"以上均不正确","answer":"B","exp":"多轴靠前后电机升力差产生俯仰力矩，前移需机头前倾，应使横轴前侧螺旋桨减速、横轴后侧加速，升力合力向后倾斜产生前向分量推动飞行器前飞；纵轴左右桨转速差改变的是横滚姿态，注意分清横轴与纵轴对应的运动。"},{"id":643,"type":"multi","cat":"设备与维护","stem":"民用无人机系统有哪几种链路？（）","A":"数传链路","B":"图传链路","C":"卫星链路","D":"遥控器链路","answer":"ABD","exp":"民用无人机系统的链路按用途分为三类：遥控链路上行传送飞手操纵指令，图传链路下行回传摄像头图像，数传链路收发飞行状态与任务数据；卫星链路多用于大型或特定超视距系统，不属民用无人机常规链路分类。"},{"id":644,"type":"multi","cat":"基础概念","stem":"以下哪几项属于无人机动力装置检查与启动（）。","A":"发动机油量检查","B":"微型无人机进行不同姿态发动机稳定性检查","C":"电动机进行正反转检查","D":"动力装置启动后与其他系统的干扰检查","answer":"ABCD","exp":"动力装置检查涵盖发动机油量等能量准备，微型无人机要在不同姿态下检查发动机运转稳定性，电动机须核对正反转方向是否正确，启动后还要检查动力对飞控、罗盘等其他系统的干扰，四项都是启动前后的常规检查内容。"},{"id":645,"type":"multi","cat":"基础概念","stem":"关于“飞行管理”正确的是（）。","A":"在一个划定的管制空域内，可由两个空中交通管制单位负责空中交通管制","B":"通常情况下，民用航空器不得飞入禁区和限制区","C":"民用航空器未经批准不得飞出中华人民共和国领空","D":"民用航空器在管制空域内飞行必须取得空中交通管制单位的许可","answer":"BCD","exp":"同一管制空域通常由一个空中交通管制单位统一实施管制，称可由两个单位负责不成立；民用航空器通常不得飞入禁区和限制区，未经批准不得飞出中华人民共和国领空，在管制空域内飞行必须取得管制单位许可，后三项符合飞行管理规定。"},{"id":646,"type":"single","cat":"操纵与飞行技术","stem":"遥控器中升降舵、副翼、方向舵、油门控制通道的英文缩写分别正确的是（）。","A":"ELE，AIL，RUD，THR","B":"ELE，THR，RUD，AIL","C":"RUD，AIL，ELE，THR","D":"以上均不正确","answer":"A","exp":"遥控通道的通用英文缩写为：升降舵ELE、副翼AIL、方向舵RUD、油门THR，按此一一对应即可核对通道；其余组合把THR误放到升降或副翼位置，属于缩写与通道功能对位记混，记忆时按舵面名称对应。"},{"id":647,"type":"single","cat":"基础概念","stem":"飞行控制是指采用（）对无人机在空中整个飞行过程的控制。","A":"遥感方式","B":"遥测方式","C":"遥控方式","D":"以上均不正确","answer":"C","exp":"飞行控制指采用遥控方式对无人机在空中整个飞行过程实施的远距离控制，地面指令经数据链路上传、由飞控系统解算执行；遥测负责状态参数回传，遥感是对地探测手段，二者都不是对飞行过程的控制方式。"},{"id":648,"type":"single","cat":"操纵与飞行技术","stem":"（）既是直流无刷电机的调制机构，也可以看作是电动无人驾驶航空器的油门执行机构。","A":"发动机","B":"电子调速器","C":"螺旋桨","D":"调压器","answer":"B","exp":"电子调速器接收飞控或接收机输出的油门信号，将其调制成三相驱动电流控制电机转速，既是直流无刷电机的调制机构，也充当电动无人机的油门执行机构；发动机属油动平台，螺旋桨是拉力输出端，调压器只稳定电压。"},{"id":649,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时（）。","A":"机场气温较高时，跑道上升气流明显，会导致下滑距离增长","B":"机场气温较高时，跑道下降气流明显，会导致下滑距离增长","C":"机场气温较高时，跑道下降气流明显，会导致下滑距离减小","D":"以上均不正确","answer":"A","exp":"机场气温高时地表受热强烈，跑道上方易形成明显上升气流，无人机下滑中受气流顶托，下滑角变缓、下滑距离增长，容易目测过高；说气温高出现下降气流与热对流规律相反，把气流方向记反是常见错误。"},{"id":650,"type":"single","cat":"操纵与飞行技术","stem":"固定翼常规无人机飞行辅助操纵面有（）。","A":"副翼，升降舵，方向舵，调整片","B":"缝翼，全动平尾，襟翼，调整片","C":"缝翼，襟翼，调整片","D":"以上均不正确","answer":"C","exp":"副翼、升降舵、方向舵承担三个轴的基本操纵，属主操纵面；缝翼与襟翼用于增升、改善升力特性，调整片用于配平减轻杆力，三者才是辅助操纵面，划分主辅的依据是直接操纵飞行姿态还是辅助增升配平。"},{"id":651,"type":"single","cat":"设备与维护","stem":"锂电池长期不用，保存电压是多少？（）","A":"3.8V","B":"3.85V","C":"3.75V","D":"以上均不正确","answer":"B","exp":"锂聚合物电池长期存放应保持半电状态，单片电芯约3.85伏，此时电化学状态最稳定、容量衰减最慢；3.7伏是标称电压，4.2伏是满电电压，长期按满电或空电存放都会加速老化，存放前应调整到贮存电压。"},{"id":652,"type":"single","cat":"设备与维护","stem":"经测试，某多轴飞行器稳定飞行时，动力电池的持续输出电流为10安培，该多轴可以选用（）。","A":"15A的电调","B":"10A的电调","C":"50A的电调","D":"以上均不正确","answer":"C","exp":"电调持续电流必须大于动力系统的实际最大持续输出并留足余量，稳定飞行持续输出10安时选50安电调余量充足、发热小、可靠性高；10安电调无任何裕度极易烧毁，15安余量也偏小，都不满足安全裕度要求。"},{"id":653,"type":"single","cat":"设备与维护","stem":"民用无人机上的舵机一般输出行程为（）。","A":"正负120度","B":"正负45度","C":"正负20度","D":"以上均不正确","answer":"C","exp":"民用无人机舵机的输出行程一般为正负20度左右，已能满足舵面偏转与操纵灵敏度的需要；行程过大会使操纵过量、连杆受力剧增，正负45度和正负120度远超常规舵面所需范围，安装调试时不必追求大行程。"},{"id":654,"type":"single","cat":"电力巡检","stem":"巡检作业区域出现其他飞行器或飘浮物时，应（），在确保安全后方可继续执行巡检作业，否则应采取避让措施。","A":"迅速采取措施保证无人机巡检系统安全","B":"立即评估巡检作业安全性","C":"立即控制无人机巡检系统降落","D":"立即控制无人机巡检系统返航","answer":"B","exp":"巡检作业区域出现其他飞行器或飘浮物时，规程要求立即评估巡检作业的安全性，确认安全后方可继续执行，否则果断采取避让措施；不评估就继续飞行有相撞风险，直接降落或返航则属过度处置，打乱作业节奏。"},{"id":655,"type":"single","cat":"领航与任务规划","stem":"作业过程中，任务手如发现（）、悬停点与预设航线偏差较大，应及时告知程控手（操控手）调整飞行航线。","A":"任务目标","B":"飞行航向","C":"飞行航线","D":"飞机轨迹","answer":"C","exp":"任务手负责监视作业画面与飞行状态，当实际飞行航线或悬停点与预设航线偏差较大时，应及时告知程控手调整飞行航线，保证覆盖效果与飞行安全；比对的标准是预设航线本身，任务目标与飞机轨迹不是判断偏差的依据。"},{"id":656,"type":"single","cat":"设备与维护","stem":"无人机（）是指根据无人机需要完成的任务、无人机的数量以及携带任务载荷的类型，对无人机制定飞行路线并进行任务分配。","A":"航迹规划","B":"任务规划","C":"飞行规划","D":"以上均不正确","answer":"B","exp":"根据任务需求、无人机数量和任务载荷类型，制定飞行路线并进行任务分配的全过程称任务规划，涵盖航线规划、载荷安排与资源调配；航迹规划只生成飞行航迹本身，是任务规划的一个环节，范围小于任务规划，勿混用。"},{"id":657,"type":"single","cat":"法规与空域","stem":"轻型无人机，是指同时满足空机重量不超过（）千克，最大起飞重量不超过（）千克，最大飞行速度不超过（）千米/小时，具备符合空域管理要求的空域保持能力和可靠被监视能力的遥控驾驶航空器，但不包括微型无人机。","A":"2，7，100","B":"3，7，100","C":"4，7，100","D":"5，7，100","answer":"C","exp":"轻型的量化门槛为空机重量不超过4千克、最大起飞重量不超过7千克、最大飞行速度不超过100千米每小时，并具备空域保持能力和可靠被监视能力；错选多为把空机重量界限记成2或3千克，7与100两项数值不变。"},{"id":658,"type":"single","cat":"设备与维护","stem":"（）传感器是飞行控制系统的基本传感器之一，用以改善系统的阻尼特性、提高稳定性。","A":"迎角，侧滑角","B":"空速","C":"角速率","D":"以上均不正确","answer":"C","exp":"角速率传感器即速率陀螺，测量机体转动角速度并构成阻尼回路，能改善控制系统阻尼特性、抑制振荡、提高稳定性，是飞控基本传感器之一；迎角和空速传感器属大气数据测量，用于飞行参数计算，不直接改善阻尼。"},{"id":659,"type":"single","cat":"基础概念","stem":"主控主要的功能是（）。","A":"接收传感器信号并实现飞行器的所有功能","B":"经纬度定位","C":"方位确定","D":"确定角速度","answer":"A","exp":"主控即飞控计算机，接收陀螺、加速度计、GPS等传感器信号并综合解算，输出控制指令实现飞行器的姿态稳定和全部飞行功能；经纬度定位、方位确定、角速度测定分别由GPS、罗盘、陀螺提供，只是主控的输入来源。"},{"id":660,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机四转弯后（）。","A":"目测过低时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段","B":"等飞机降到较低高度时再做偏差调整","C":"目测过高时，应在加大油门的同时适当增加带杆量，减小下滑角，必要时可平飞一段","D":"以上均不正确","answer":"A","exp":"四转弯后目测过低说明高度损失偏多、下滑点过近，应加大油门并适当增加带杆量，减小下滑角延长平飘过程，必要时平飞一段重新建立下滑；等降到较低高度再调整为时已晚，目测高时则应收小油门而非加大。"},{"id":661,"type":"single","cat":"基础概念","stem":"无人机配平的主要考虑是（）沿纵轴的前后位置。","A":"气动焦点","B":"发动机","C":"中心","D":"重心","answer":"D","exp":"配平的核心考虑是重心沿纵轴的前后位置，重心偏前偏后都会改变俯仰力矩平衡、操纵杆量和静稳定性，须通过装载配平或调整片补偿；气动焦点由机翼气动布局决定，发动机位置属总体设计，均非配平可调因素。"},{"id":662,"type":"single","cat":"设备与维护","stem":"多轴无人机，电调上较细的白红黑3色排线，也叫杜邦线，用来连接（）。","A":"电机","B":"机载遥控接收机","C":"飞控","D":"以上均不正确","answer":"C","exp":"电调上较细的白红黑多色排线是信号线，用于连接飞控，接收飞控输出的PWM等油门控制信号；粗线端才是电源输入和电机三相输出，接机载遥控接收机的另有专门信号线，接口性质不同，接错会烧毁设备。"},{"id":663,"type":"single","cat":"基础概念","stem":"固定翼无人机起落架安装的后三点安装是指主起落架对称安装在无人机（）之前，第三个支点（尾轮）在机尾安装。","A":"中心","B":"重心","C":"焦点","D":"压力中心","answer":"A","exp":"后三点式起落架的两个主轮对称安装在机身中心之前，第三个支点尾轮装在机尾，停机时机头昂起，起飞抬头离地容易；对照位置取机身中心而非重心或焦点，这是结构安装的惯用表述，前后三点以主轮位置区分。"},{"id":664,"type":"single","cat":"设备与维护","stem":"电机、电调、电池、接收机、数传电台请把他们用合格的方式连接（）。","A":"数传电台—电池—电调—电机","B":"接收机—电池—电调—电机","C":"电池—电调—电机","D":"以上均不正确","answer":"C","exp":"动力主回路按电池、电调、电机的顺序连接，电调电源输入端接电池，输出三相线接电机，信号线接飞控或接收机；数传电台和接收机有独立供电与信号接口，不串入动力主回路，接错顺序或接口极易烧毁电调。"},{"id":665,"type":"single","cat":"基础概念","stem":"安装电动机时无人机机头方向的左上和右下为（）电动机，右上和左下为（）电动机。","A":"逆时针(CCW)，顺时针(CW)","B":"顺时针(CW)，逆时针(CCW)","C":"逆时针(CCW)，逆时针(CCW)","D":"顺时针(CW)，顺时针(CW)","answer":"B","exp":"X型布局中相邻电机转向相反以抵消反扭矩，常见约定为机头方向左上、右下位置装顺时针CW电机，右上、左下装逆时针CCW电机；若转向装反，起飞时机身会反转甚至翻覆，装机后应逐一核对电机转向与桨的匹配。"},{"id":666,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，面对拉平高正确的操作方式是（）。","A":"拉平高时，如果飞机不下沉，应稍拉杆，使飞机下沉到预定高度","B":"拉平高时，如果飞机随即下沉，应稳住杆，待飞机下沉到一定高度时，再柔和拉杆","C":"发现有拉高的趋势，应推杆","D":"以上均不正确","answer":"B","exp":"拉平过高时不能急于推杆，若飞机随即下沉，应稳住杆保持姿态，待飞机下沉到规定高度再柔和拉杆接地；发现有拉高趋势就猛推杆，会造成接地跳跃或前轮先触地，稍拉杆则使拉平更高，均不可取。"},{"id":667,"type":"single","cat":"基础概念","stem":"固定翼无人机起落架安装的前三点安装是指主起落架对称的安置在无人机（）后面，第三个支点（前轮）位于机身前部。","A":"压力中心","B":"焦点","C":"中心","D":"重心","answer":"D","exp":"前三点式起落架的主轮对称安装在无人机重心后面，第三个支点前轮位于机身前部，停机时机身接近水平，滑跑方向稳定性好、着陆接地平稳；区分前后三点的关键是主轮与重心的相对位置，主轮在重心后即前三点。"},{"id":668,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员关于无人机飞行速度范围不需要了解的是（）。","A":"海平面不同重量下的速度范围","B":"极限高度内的速度范围","C":"极限高度外的速度范围","D":"以上均不正确","answer":"C","exp":"驾驶员应掌握海平面不同重量下的速度范围和极限高度内的速度范围，这两个包线直接关系起飞巡航安全；极限高度之外已超出飞行包线，不存在正常使用的速度范围，了解它没有运行意义，属干扰说法。"},{"id":669,"type":"single","cat":"设备与维护","stem":"用遥控器设置电调，需要（）。","A":"接上电机","B":"断开动力电源","C":"断开电机","D":"以上均不正确","answer":"A","exp":"用遥控器设置电调油门行程时，需要接上电机，通过电机的鸣叫节拍和转动状态判断是否进入设置模式及校准节点；断开电机或断开动力电源后电调无法反馈，行程校准无法完成，操作时务必注意桨叶安全。"},{"id":670,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，DJIGO界面中，姿态球中的飞行器状态与实际不符，可能是因为。","A":"移动设备指南针异常，需校准","B":"移动设备未连接蜂窝数据网络","C":"移动设备未登录DJIGO账户","D":"移动设备信号受到干扰","answer":"A","exp":"姿态球显示与实际不符，多因移动设备自身指南针异常或受磁性干扰，应校准指南针后使用；未连接蜂窝网络、未登录账户只影响地图加载与设备激活，信号干扰一般表现为图传遥控卡顿，不会改变姿态球的方位逻辑。"},{"id":671,"type":"single","cat":"操纵与飞行技术","stem":"在自主飞行过程中，遥控器油门得位置应处于（）。","A":"油门处于最上方","B":"油门处于最下方","C":"油门处于中间略上","D":"以上均不正确","answer":"C","exp":"自主飞行时由飞控自动控制油门，遥控器油门应放在中间略上位置，需要人工接管时上下都有调节余量，避免切手动瞬间因油门过低骤降或过高急升；置于最上或最下都会让接管瞬间姿态突变，增加风险。"},{"id":672,"type":"single","cat":"设备与维护","stem":"作为无人机系统的重要组成部分，链路系统的主要任务是建立一个空地（）数据传输通道。","A":"上行","B":"单向","C":"双向","D":"下行","answer":"C","exp":"链路系统的主要任务是在地面站与无人机之间建立空地双向数据传输通道，上行传送遥控指令与任务装订，下行回传遥测参数、图像等信息，双向完整通道才能支撑闭环控制；上行或下行单独都只覆盖半个链路功能。"},{"id":673,"type":"single","cat":"基础概念","stem":"关于固定翼无人机机体与旋翼大小改造，下列说法错误的是（）。","A":"减小旋翼大小能增大飞行速度","B":"增大垂尾面积能提高无人机纵向稳定性","C":"平尾距离重心越远能提高无人机纵向稳定性","D":"设置上反角能提高无人机横向稳定性","answer":"B","exp":"垂尾提供的是方向即航向稳定性，增大垂尾面积改善的是航向稳定而非纵向稳定，纵向稳定性取决于水平尾翼及其距重心的距离；减小旋翼尺寸有利增速，平尾后置增强纵向稳定，设置上反角增强横向稳定，说法均正确。"},{"id":674,"type":"single","cat":"基础概念","stem":"以下（）不属于固定翼无人机系统的地面控制站。","A":"地面站","B":"数据链地面终端","C":"操作手柄","D":"飞控计算机","answer":"D","exp":"地面控制站由地面站软硬件、数据链地面终端、操纵手柄等地面设备组成，负责监控与操纵无人机；飞控计算机安装在无人机机体上属机载系统，随飞行器升空工作，把它归入地面控制站是站上站下的概念混淆。"},{"id":675,"type":"single","cat":"基础概念","stem":"部分多轴飞行器会安装垂尾（）。","A":"会减小高速前飞时的稳定性，增加悬停时的稳定性","B":"会增加高速前飞时的稳定性，减小悬停时的稳定性","C":"会增加高速前飞时的稳定性，增加悬停时的稳定性","D":"以上均不正确","answer":"B","exp":"多轴悬停时垂尾不产生有效气动力，反受旋翼下洗气流干扰带来扰动；高速前飞时垂尾呈风标效应，提供航向稳定性并抑制偏航摆动，故装垂尾增加高速前飞稳定性、减小悬停稳定性，是否加装须结合飞行状态权衡。"},{"id":676,"type":"multi","cat":"领航与任务规划","stem":"航线规划应避开（）。","A":"军事禁区","B":"军事管理区","C":"空中危险区","D":"空中限制区","answer":"ABCD","exp":"军事禁区、军事管理区严禁未经许可进入，空中危险区内有炮射、试验等危险活动，空中限制区须符合规定条件方可飞行，航线规划必须全部避开这四类区域；穿越任一类都构成违规飞行，应经审批或另行规划安全航线。"},{"id":677,"type":"multi","cat":"电力巡检","stem":"应根据巡检线路的杆塔坐标、塔高、塔型等技术参数，结合线路途经区域地图和现场勘查情况（），制定（）。","A":"绘制航线","B":"巡检方式","C":"起降位置","D":"安全策略","answer":"ABCD","exp":"输电线路巡检准备应依据杆塔坐标、塔高、塔型等技术参数，结合线路途经区域地图和现场勘查情况，绘制巡检航线、确定巡检方式、选定起降位置并制定安全策略，四项共同构成完整的巡检作业方案，缺一不可。"},{"id":678,"type":"multi","cat":"基础概念","stem":"固定翼无人机自动定高模式飞行时，持续升高或下降，可能的原因是（）。","A":"角速度计故障","B":"动力系统故障","C":"高度传感器故障","D":"加速度计故障","answer":"BC","exp":"自动定高依赖高度传感器测量与动力系统执行：气压计等高度传感器故障使高度基准失真，电机、电调或电池等动力故障使拉力失控，都会造成持续升高或下降；角速度计和加速度计服务姿态控制，不直接参与定高回路。"},{"id":679,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，使用中型无人直升机巡检系统进行的架空输电线路巡检作业，作业人员包括工作负责人和工作班成员。工作班成员至少包括（）。","A":"程控手","B":"控制手","C":"操控手","D":"任务手","answer":"ACD","exp":"按巡检安全工作规程，中型无人直升机巡检作业的工作班成员至少包括程控手、操控手和任务手，分别负责航线与程序控制、飞行操纵、任务监视，岗位齐备方可作业；控制手不是该规程列明的岗位名称，属干扰表述。"},{"id":680,"type":"multi","cat":"基础概念","stem":"活塞发动机在（）时，容易发生爆震。","A":"发动机处于小转速工作","B":"大进气压力状态工作","C":"发动机处于大转速工作","D":"小进气压力转台工作","answer":"AB","exp":"爆震是混合气在火焰前锋到达前自燃的异常燃烧，活塞发动机小转速、大进气压力状态下工作时，气缸内压力温度高、燃烧持续时间长，最容易发生爆震；大转速下气体扰动强、燃烧时间短，反而不易爆震。"},{"id":681,"type":"single","cat":"领航与任务规划","stem":"多旋翼无人机功能改造需要考虑的因素通常包括起飞重量与载重比要求、续航时间要求、飞行控制与导航要求、通信传输要求、（）等。","A":"外观要求","B":"颜色要求","C":"维保要求","D":"飞行器平台与任务载荷系统的连接与联调","answer":"D","exp":"多旋翼功能改造通常在起飞重量与载重比、续航时间、飞控导航、通信传输等要求之外，还要落实飞行器平台与任务载荷系统的连接与联调，保证载荷接口匹配、整机联合调试合格；外观、颜色、维保属次要或后期事项。"},{"id":682,"type":"single","cat":"操纵与飞行技术","stem":"操作无人机起飞前，动力装置不需要检查的是（）。","A":"发动机稳定性检查","B":"发动机生产日期","C":"发动机油路检查","D":"以上均不正确","answer":"B","exp":"起飞前的动力装置检查围绕运行状态进行，包括发动机运转稳定性、油路渗漏堵塞等状态项目；生产日期是出厂档案信息，与当前运行状态无直接关联，列入起飞前检查没有意义，日常检查应聚焦油、电、机械状态。"},{"id":683,"type":"single","cat":"基础概念","stem":"固定翼无人机组装后，要对机翼、机身和尾翼的相互位置进行检查若发现机翼在机身上左右高低位置不一致，可将（），直到把机翼摆平为止。","A":"较高一侧机身侧板的安装机翼处削去一些","B":"较低一侧机身侧板的安装机翼处填补一些","C":"较高一侧机翼削短一些","D":"较短一侧机翼加长一些","answer":"A","exp":"装配后发现机翼左右高低不一致，应处理机身侧板的机翼安装面：把较高一侧机身侧板安装机翼处削去一些，使两侧安装面等高，机翼即可摆平；削短加长机翼会破坏翼型和左右对称，属于破坏结构的错误做法。"},{"id":684,"type":"single","cat":"法规与空域","stem":"固定翼无人机的基本飞行性能，起飞距离指从开始滑跑到飞机越过安全高度时所经过的水平距离，影响起飞距离的因素中错误的是（）。","A":"飞机起飞重量","B":"发动机的推力","C":"减小迎角","D":"爬升角","answer":"C","exp":"起飞距离受起飞重量、发动机推力、爬升角等影响：重量越大滑跑越长，推力越小增速越慢，爬升角小则越过安全高度更晚；迎角应按离地姿态适当增大以获得足够升力，减小迎角反而延缓离地，列为影响因素是错误表述。"},{"id":685,"type":"single","cat":"领航与任务规划","stem":"任务规划时还要考虑（），即应急航线。","A":"异常应急措施","B":"安全返航措施","C":"紧急迫降措施","D":"以上均不正确","answer":"A","exp":"任务规划除正常航线外还须考虑异常应急措施，即为动力、链路故障或天气突变等情况预设应急航线，明确返航点、备降点与迫降场地；安全返航、紧急迫降只是其中的具体手段，整体概念应表述为异常应急措施。"},{"id":686,"type":"single","cat":"基础概念","stem":"多旋翼无人机无人机的轴距是指（）。","A":"相邻两电机轴间的距离","B":"相对电机轴间的距离","C":"电机轴距飞机立轴的距离","D":"电机轴的长度","answer":"B","exp":"多旋翼轴距指处于对角位置的相对两电机轴之间的距离，直接决定机体尺寸和可配桨的规格；相邻两电机轴间距只反映机臂布置，轴距必须沿对角线量取相对电机，这是选桨和机架匹配的基础参数。"},{"id":687,"type":"single","cat":"设备与维护","stem":"电调的全称是（）。","A":"电子调速器","B":"电子调压器","C":"电池调压器","D":"电机调速器","answer":"A","exp":"电调全称电子调速器，按控制信号调节电机转速和输出功率，是无刷动力系统的核心部件；电子调压器、电池调压器管的是电压稳定，电机调速器并非其规范名称，术语要与部件功能准确对应。"},{"id":688,"type":"single","cat":"基础概念","stem":"多旋翼遥控状态下动力失效的处理办法是（）。","A":"迅速收油门","B":"开伞迫降","C":"自动返航","D":"以上均不正确","answer":"B","exp":"多旋翼动力失效后失去拉力，不能像固定翼那样滑翔迫降，遥控状态下正确处置是立即开伞迫降，用降落伞减缓下降速度减轻坠地损失；收油门只会加速坠落，自动返航依赖动力正常，动力失效时都无法执行。"},{"id":689,"type":"single","cat":"基础概念","stem":"在保障无人机飞行安全的基础上，为无人分配最高效的故障处置策略，例如，分配高度源故障和位置源故障的首选策略分别是（）。","A":"航迹返回和迫降","B":"定高盘旋和航向返回","C":"迫降和航向返回","D":"航迹返回和航向返回","answer":"D","exp":"故障处置按失效环节分配策略：高度信息源故障时定高不可信，首选航迹返回沿预置航迹安全返航；位置源故障时导航定位失效，改用航向返回按记录航向返航，两者首选策略分别是航迹返回和航向返回，不可套用同一模式。"},{"id":690,"type":"single","cat":"电力巡检","stem":"测绘作业一般采用（）航高，电力线路巡检采用（）作业模式。","A":"固定，变航高","B":"变航高，变航高","C":"固定，固定","D":"变航高，固定","answer":"A","exp":"测绘要求影像比例尺一致、成图精度统一，一般采用固定航高飞行；电力线路巡检沿线路走廊作业，需随杆塔高度和地形起伏调整高度，采用变航高作业模式，两类任务的航高要求由成果精度和作业对象决定。"},{"id":691,"type":"single","cat":"基础概念","stem":"有些无人机通过（）加速到发射速度。","A":"引力","B":"重量","C":"导轨或轨道","D":"加速度","answer":"C","exp":"部分无人机如弹射起飞的固定翼缺乏足够滑跑距离，通过导轨或轨道在短时间内将其加速到起飞所需速度，获得足够升力离地；引力、重量不是加速的动力来源，加速度只是描述过程的物理量，实体加速手段是导轨或轨道。"},{"id":692,"type":"single","cat":"操纵与飞行技术","stem":"飞行控制系统是无人驾驶航空器的关键核心系统之一，简称（）。","A":"遥控","B":"飞控","C":"自控","D":"制控","answer":"B","exp":"飞行控制系统是无人驾驶航空器的关键核心系统之一，行业通用简称飞控，由传感器、主控计算机和执行机构组成，负责姿态稳定与航线控制；遥控指地面操纵方式，自控、制控均非规范简称，术语对应要准确。"},{"id":693,"type":"single","cat":"基础概念","stem":"下列错误的选项是（）。","A":"粘性阻力是由于空气和飞行器表面接触产生的","B":"形状阻力是由于空气和飞行器表面接触产生的","C":"蒙皮摩擦阻力是由于空气和飞行器表面接触产生的","D":"以上均不正确","answer":"B","exp":"形状阻力由飞行器前后表面的压力差形成，与迎风面积和外形整流程度有关，并非空气与表面接触摩擦产生；粘性阻力和蒙皮摩擦阻力才是空气贴附表面流动时摩擦所致，把摩擦成因安到形状阻力上是错误说法。"},{"id":694,"type":"single","cat":"设备与维护","stem":"多旋翼无人机飞行控制系统（自驾仪）固件升级时，为保持（）稳定，应使用USB数据线连接飞行控制系统（自驾仪）进行固件升级。","A":"全球定位系统（GPS）信号","B":"动力电机","C":"飞行姿态","D":"数据传输","answer":"D","exp":"自驾仪固件升级对链路连续性要求高，用USB数据线直连可保持数据传输稳定，避免无线链路中断导致升级失败甚至设备变砖；升级在地面完成，与GPS信号、动力电机、飞行姿态并无直接关联。"},{"id":695,"type":"single","cat":"设备与维护","stem":"关于图传信号丢失有可能是什么原因造成，以下哪项表述最全（）。","A":"遥控器天线未展开","B":"飞背对着飞行器","C":"遥控器与飞行器中间隔有障碍物","D":"其他全是","answer":"D","exp":"图传信号丢失常由多因素叠加：遥控器或图传天线未展开导致收发增益不足，操作员身体背对飞行器遮挡信号，遥控器与飞行器之间隔有山体建筑等障碍物，电磁干扰同样会造成中断，排查时应逐项检查这些因素。"},{"id":696,"type":"single","cat":"设备与维护","stem":"无刷电机相对于有刷电机的优势不包括的是（）。","A":"效率更高","B":"扭矩更大","C":"寿命更长","D":"功率密度大","answer":"B","exp":"无刷电机以电子换向取代电刷摩擦，效率更高、寿命更长、功率密度更大且免维护；同等体积下扭矩并非其固有优势，有刷电机低速大扭矩反而突出，说无刷电机扭矩更大不成立，这是两者特性对比中的常见误解。"},{"id":697,"type":"single","cat":"基础概念","stem":"飞行器的失控行为不包括的是（）。","A":"返航","B":"悬停","C":"下降","D":"上升","answer":"D","exp":"失控保护触发后飞控执行既定安全策略，常见为自动返航、原地悬停或缓慢下降，目的是尽快转入可回收的安全状态，不会主动爬升；上升会增大高度和能量消耗、加大落地风险，不属于失控行为范畴。"},{"id":698,"type":"single","cat":"操纵与飞行技术","stem":"以大疆产品为例，飞行器飞行过程中，红三角形位于姿态球左上方，三角形尖端朝向姿态球中，请问飞行器处于操作者哪个位置，机头朝向如何？","A":"飞行器处于操作者左前方，机头朝向操作者自","B":"飞行器处于操作者左后方，机头朝向操作者自","C":"飞行器处于操作者右后方，机头朝向操作者前方","D":"飞行器处于操作者右前方，机头朝向操作者后方","answer":"A","exp":"姿态球以中心代表操作者位置，红三角形位于左上方说明飞行器在操作者左前方，三角形尖端指向姿态球中心即指向操作者，表明机头朝向操作者自己；判读时以中心为原点，按图标方位直接对应真实方位。"},{"id":699,"type":"single","cat":"操纵与飞行技术","stem":"无人机定速遥控飞行时放下起落架，驾驶员需（）。","A":"增加油门以保持空速","B":"减小油门以保持空速","C":"针对此情况，无需做相关动作","D":"以上均不正确","answer":"A","exp":"放下起落架后飞机废阻力显著增大，同样油门下空速下降、下滑角变陡，为保持规定空速应适当增加油门补偿阻力损失；减小油门会进一步掉速，认为无需动作忽略了起落架对阻力的明显影响，定速飞行须主动补偿。"},{"id":700,"type":"single","cat":"操纵与飞行技术","stem":"未来无人驾驶航空器地面控制站的发展不包括（）。","A":"友好的人机界面","B":"低成本","C":"一站多机","D":"多样性","answer":"D","exp":"地面控制站的发展方向包括友好的人机界面以降低操作门槛、低成本以利于普及、一站多机以提高操控效率；多样性并非公认发展方向，行业趋势强调通用化、标准化，而非追求样式繁多。"},{"id":701,"type":"single","cat":"操纵与飞行技术","stem":"油门测试是以下哪一项测试的主要内容之一（）。","A":"有桨调试","B":"无桨调试","C":"主控调试","D":"油门调试","answer":"A","exp":"有桨调试指装上螺旋桨后的地面动力测试，油门测试是其主要内容，逐档推动油门检查电机响应、转向和桨的动平衡状况；无桨调试不装桨，侧重电调行程与参数设置，主控调试针对飞控，均不涉及真实带桨油门测试。"},{"id":702,"type":"single","cat":"操纵与飞行技术","stem":"起飞场地从北京移至拉萨，对哪类无人机的高度性能影响最严重（）。","A":"油动固定翼","B":"电动固定翼","C":"电动多轴","D":"以上均不正确","answer":"A","exp":"拉萨海拔高、空气密度低，油动发动机进气量减少导致功率明显下降，叠加螺旋桨推力和机翼升力同步衰减，高度性能受损最严重；电动电机的输出不依赖空气含氧量，受密度影响相对小，故油动固定翼最敏感。"},{"id":703,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，拉飘的修正方法是（）。","A":"发现拉飘时，稳住并保持杆量","B":"发现拉飘时，应立即继续拉杆","C":"发现拉飘时，应立即柔和推杆制止飞机继续上飘","D":"以上均不正确","answer":"C","exp":"拉飘是接地前拉杆过量使飞机上飘、浮空不落，发现拉飘应立即柔和推杆减小迎角，制止继续上飘并让飞机下沉接地；稳杆保持或继续拉杆都会使高度损失更多、接地姿态更差，容易造成跳跃或擦机尾。"},{"id":704,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机进入下滑后（）。","A":"当下滑线正常时，如速度大，表明目测高，应适当收小油门","B":"当下滑线正常时，如速度大，表明目测低，应适当增加油门","C":"当下滑线正常时，如速度小，表明目测高，应适当收小油门","D":"以上均不正确","answer":"A","exp":"下滑线正常而速度偏大，说明飞行能量偏多、目测偏高，接地点会偏远，应适当收小油门减速修正；速度偏小则表明目测低，应加大油门补速，把下滑速度大小与目测高低的对应关系记牢是着陆修正的关键。"},{"id":705,"type":"single","cat":"领航与任务规划","stem":"导航子系统功能是向无人机提供（）信息，引导无人机沿指定航线安全、准时、准确的飞行。","A":"高度、速度和位置","B":"角速度","C":"角加速度","D":"温度、湿度","answer":"A","exp":"导航子系统向飞控提供高度、速度和位置等实时导航参数，引导无人机沿预定航线安全、准时、准确飞行；角速度与角加速度由陀螺等传感器测量、服务姿态控制，温湿度属环境监测数据，都不是导航子系统的输出。"},{"id":706,"type":"single","cat":"飞行原理","stem":"某多轴螺旋桨长254毫米，螺距114毫米，那么他的型号可表述为（）。","A":"2511","B":"1045","C":"254114","D":"以上均不正确","answer":"B","exp":"螺旋桨型号以英寸标注，前两位是直径、后两位是螺距：254毫米约合10英寸，114毫米约合4.5英寸，型号记作1045；直接用毫米数254114或截取2511都不符合英寸命名规则，换算时按1英寸25.4毫米计算。"},{"id":707,"type":"single","cat":"设备与维护","stem":"一款电机为300KV，其在3SLIPO下，最大空载转速为（）。","A":"4280RPM","B":"3000RPM","C":"3330RPM","D":"3780RPM","answer":"D","exp":"KV值表示每伏电压对应的空载转速，3S锂电池满电电压约12.6伏，300KV乘以12.6伏约为3780转每分，即最大空载转速；按标称电压11.1伏算得的3330转是标称工况转速而非最大值，4280转对应电压明显偏高。"},{"id":708,"type":"single","cat":"航空气象","stem":"云还伴随出现其他一些天气现象，仍会对飞行的安定性产生影响，尤其是（），常造成飞机积冰、飞机颠簸、强烈风切变、雷击和冰暴，成为飞行障碍甚至危及飞行安全。","A":"雨层云","B":"高积云","C":"积状云","D":"层云","answer":"C","exp":"积状云即积云和积雨云，内部对流强烈，常伴随积冰、颠簸、强烈风切变、雷击和冰暴等危险天气，是威胁飞行安定性与安全的主要云体；雨层云、高积云、层云属层状或中高云，对流弱，危害程度远低于积状云。"},{"id":709,"type":"single","cat":"操纵与飞行技术","stem":"组装固定翼无人机后进行试飞，如果发现飞机偏航，首先要检查的位置是（）。","A":"螺旋桨","B":"电池","C":"起落架","D":"机翼和尾翼","answer":"D","exp":"试飞偏航多源于气动不对称，应首先检查机翼与尾翼：左右安装角是否一致、垂直尾翼有无偏斜、各舵面角度是否对称，这些直接决定航向力矩平衡；螺旋桨和电池缺陷多引起振动或动力问题，起落架影响滑跑，均非偏航首要排查对象。"},{"id":710,"type":"single","cat":"基础概念","stem":"因照明系统发热量大，安装位置应远离（）。","A":"分电板","B":"全球导航卫星系统（GNSS）","C":"螺旋桨","D":"起落架","answer":"B","exp":"照明系统工作时发热量大，安装位置应远离GNSS模块等对温度敏感的电子部件，高温会引起晶振频偏、接收灵敏度下降，导致定位精度降低甚至丢星；分电板、螺旋桨、起落架对热不敏感，布置时主要考虑结构与配重。"},{"id":711,"type":"multi","cat":"电力巡检","stem":"特殊巡检根据季节特点、设备状况及特殊需要，选择适用机型开展（）巡检。","A":"加强性","B":"防范性","C":"安全性","D":"针对性","answer":"ABD","exp":"特殊巡检按季节特点、设备状况及特殊需要，选择适用机型开展加强性巡检、防范性巡检和针对性巡检，以应对高温、覆冰、故障多发等特殊情形；安全性巡检不属规程列举的特殊巡检类别，三类巡检均强调机型与任务匹配。"},{"id":712,"type":"multi","cat":"基础概念","stem":"以下做法正确的是（）。","A":"先启动无人机飞行器，再开启遥控器","B":"更换飞行地点需重新校准指南针","C":"避免超视距飞行","D":"选择在宽阔的无人场地飞行","answer":"BCD","exp":"更换飞行地点后磁场环境变化，必须重新校准指南针，否则罗盘数据失真；选择宽阔的无人场地飞行并避免超视距飞行能显著降低风险；开机顺序应为先开遥控器、后启动飞行器，反序存在失控风险，先启动飞行器的做法错误。"},{"id":713,"type":"multi","cat":"基础概念","stem":"飞行过程中可能需要处置的紧急情况包括","A":"飞控系统故障","B":"上行通讯链路故障","C":"控制站显示系统故障","D":"电池电量不足","answer":"BC","exp":"按教材归类，飞行中需临机处置的紧急情况包括上行通讯链路故障造成指令中断、控制站显示系统故障造成状态监视失效，两者都要求立即启用应急预案接管或返航；飞控系统故障和电池电量不足主要靠飞行前检查与电量监控预先防范。"},{"id":714,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，民用航空的空中管制区包括（）、（）和（）等。","A":"塔台管制区","B":"进近管制区","C":"区域管制区","D":"管制区","answer":"ABC","exp":"民用航空空中交通管制区按服务范围分为塔台管制区、进近管制区和区域管制区，分别负责机场及起落航线活动、进离场过渡阶段和航路区域的飞行管制；管制区是总称，不能与三个具体层级并列，三级划分是标准分类。"},{"id":715,"type":"multi","cat":"电力巡检","stem":"在试验和推广（）时，应制定相应的安全措施，确定无人机巡检系统状态良好，并履行相关审批手续后方可执行","A":"新方法","B":"新技术","C":"新工艺","D":"新设备","answer":"BCD","exp":"试验和推广新技术、新工艺、新设备时，因缺乏成熟运行经验，应制定相应安全措施，确认无人机巡检系统状态良好并履行相关审批手续后方可执行；新方法不在规程列举范围之内，三项新内容均强调先审批、后实施。"},{"id":716,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统环境适应性等级按适用环境温度进行划分，无人直升机巡检系统分为（）和特殊型","A":"普通型","B":"高温型","C":"低温型","D":"极低温型","answer":"ABCD","exp":"无人直升机巡检系统的环境适应性等级按适用环境温度划分，分为普通型、高温型、低温型和特殊型，用以匹配不同气候区域的作业需求；选型时应结合巡检地区气温条件与设备等级对应，避免设备在超出适应范围的温度下工作。"},{"id":717,"type":"multi","cat":"设备与维护","stem":"链路系统的本质就是两个相互通信的电台通过链路系统，无人机系统可以实现数据、图像等信息的发送和接收常用的链路系统分为（）。","A":"遥控上行链路","B":"数传链路","C":"图传下行链路","D":"数图一体的局域网链路","answer":"ABCD","exp":"无人机链路按传输内容与方向分为遥控上行链路、数传链路、图传下行链路和数图一体的局域网链路，分别承载遥控指令、飞行数据与图像信息；空地两台电台通过这些链路完成双向通信，四类均属常用链路形式，共同构成空地信息通道。"},{"id":718,"type":"single","cat":"基础概念","stem":"按飞行平台构型分类，多旋翼无人机属于下列哪一类？","A":"固定翼无人机","B":"旋翼无人机","C":"扑翼无人机","D":"伞翼无人机","answer":"B","exp":"按飞行平台构型分类，多旋翼依靠多个旋翼旋转产生升力和操纵力，与无人直升机同属旋翼无人机；固定翼靠固定机翼升力，扑翼模仿生物扑动，伞翼以柔性伞面承载，分类依据是升力产生方式与平台气动构型。"},{"id":719,"type":"single","cat":"操纵与飞行技术","stem":"某多旋翼无人机悬停时，所有电机转速突然同时下降，机体开始下降，最可能的原因是？","A":"单个电调损坏","B":"飞控参数错误","C":"电池电压过低触发低电压保护","D":"GPS信号丢失","answer":"C","exp":"悬停中所有电机转速同步下降，说明动力受限来自整机供电而非个别部件：电池电压过低时电调或飞控触发低电压保护，主动限制输出功率，升力不足便开始掉高度。单个电调损坏只会让对应机臂电机失效，引起倾斜侧坠，不会使全部电机同时减速。"},{"id":720,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在无风条件下悬停时，增加某个电机的转速，机身会向哪个方向倾斜？","A":"向该电机所在机臂方向","B":"向该电机所在机臂相反方向","C":"绕垂直轴顺时针旋转","D":"不产生倾斜","answer":"B","exp":"增大某一电机转速后，该侧升力大于对称侧，机体绕轴翻转，远离该电机的一侧被压低，机身便向该电机机臂的反方向倾斜。多旋翼正是靠调节对称电机的转速差产生倾斜，再由倾斜得到水平分力实现移动，向电机一侧倾斜的说法把升力方向弄反了。"},{"id":721,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中，地面站显示的“地速”是指？","A":"无人机相对于空气的速度","B":"无人机相对于地面的速度","C":"风速","D":"电机转速","answer":"B","exp":"地速是无人机相对地面的水平运动速度，由卫星导航等定位手段测得，等于空速与风速的矢量合成；相对周围空气的速度叫空速，两者在有风时不相等，逆风飞行地速小于空速，顺风则相反。把空速与地速混为一谈是常见错误。"},{"id":722,"type":"single","cat":"基础概念","stem":"多旋翼无人机的“电子调速器（ESC）”主要功能是？","A":"将交流电转换为直流电","B":"将飞控输出的PWM信号转换为电机转速控制，并调节电机供电","C":"测量电池电压","D":"接收遥控器信号","answer":"B","exp":"电调接收飞控输出的PWM等控制信号，按占空比调节供给无刷电机的三相电流，从而控制电机转速与总升力，是动力系统的功率控制环节。交流变直流是整流器的功能，测量电压靠电压检测模块，接收遥控信号由接收机完成，都不是电调的职责。"},{"id":723,"type":"single","cat":"设备与维护","stem":"下列哪种电池最适合为中小型多旋翼无人机提供动力？","A":"铅酸电池","B":"镍镉电池","C":"锂聚合物电池（LiPo）","D":"碱性电池","answer":"C","exp":"锂聚合物电池能量密度高、可大电流放电、重量轻，能在起飞和机动时提供突发大电流，是中小型多旋翼的主流动力电池。铅酸电池笨重且能量密度低，镍镉电池有记忆效应、能量密度也不足，碱性电池放电能力弱，均难以满足航空动力要求。"},{"id":724,"type":"single","cat":"设备与维护","stem":"无人机上安装的“IMU”指的是什么？","A":"电子调速器","B":"惯性测量单元","C":"图像传输模块","D":"气压计","answer":"B","exp":"IMU即惯性测量单元，内部集成三轴加速度计与三轴陀螺仪，测量加速度和角速度，经姿态解算得到俯仰、横滚等姿态数据，是飞控增稳的核心传感器。电调、图传模块和气压计都是独立部件，分别负责驱动、图像传输和测高，与IMU无关。"},{"id":725,"type":"single","cat":"法规与空域","stem":"根据我国现行法规，微型无人机空机重量范围通常为？","A":"0～500g","B":"500g～2kg","C":"2kg～7kg","D":"7kg～25kg","answer":"A","exp":"微型是无人机按空机重量分级中最轻的一级，现行《无人驾驶航空器飞行管理暂行条例》把空机重量小于0.25千克的划为微型，四个量级中只有0～500克与其百克级口径相符；500克以上已进入轻型等更重级别对应范围。"},{"id":726,"type":"single","cat":"设备与维护","stem":"多旋翼无人机桨叶安装时，正桨和反桨的区分主要依据？","A":"颜色不同","B":"桨叶旋转方向不同","C":"材质不同","D":"直径不同","answer":"B","exp":"正桨与反桨以旋转方向区分，即配套电机俯视时按顺时针还是逆时针旋转，桨叶旋向必须与电机转向匹配才能产生向上拉力，否则效率极低甚至反转下坠。颜色只是便于区分的辅助标识，材质、直径属于桨叶本身规格，与正反桨无关。"},{"id":727,"type":"single","cat":"设备与维护","stem":"在无人机飞行中，出现“炸机”通常指的是？","A":"无人机正常降落","B":"无人机发生严重碰撞坠毁","C":"无人机失去GPS信号","D":"电池过放","answer":"B","exp":"炸机是航模圈对坠机事故的俗称，指飞行中因失控、碰撞、动力故障等原因坠地撞毁或严重受损，与正常降落相对。GPS信号丢失、电池过放只是可能诱发炸机的原因或另一种故障状态，本身并不等于炸机。"},{"id":728,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机的偏航运动主要依靠？","A":"改变各旋翼的总升力","B":"改变各旋翼的反扭矩平衡","C":"改变机体重心位置","D":"改变机翼迎角","answer":"B","exp":"多旋翼对称布置正反桨，悬停时各旋翼反扭矩相互抵消；偏航时飞控让部分电机加速、对称位置电机减速，反扭矩失去平衡，机体便绕垂直轴转动，总升力保持不变。改变总升力引起升降，多旋翼也没有机翼迎角和重心调节机构，均非偏航手段。"},{"id":729,"type":"single","cat":"设备与维护","stem":"飞行前检查时，发现桨叶有细小裂纹，正确的处理方式是？","A":"用胶水粘合后继续使用","B":"更换桨叶","C":"忽略，继续飞行","D":"用砂纸打磨平滑","answer":"B","exp":"桨叶高速旋转时离心力很大，细小裂纹会迅速扩展导致断裂，机体瞬间失衡炸机，危害极大；胶粘、打磨都无法恢复结构强度。发现裂纹必须更换同型号新桨，带裂纹飞行属于严重安全隐患，绝不能抱侥幸心理继续使用。"},{"id":730,"type":"single","cat":"领航与任务规划","stem":"无人机飞控中的“姿态模式”相比“GPS模式”缺少的功能是？","A":"姿态稳定","B":"定高","C":"定点悬停和自动返航","D":"手动操控","answer":"C","exp":"姿态模式只依靠IMU和气压计实现姿态增稳与定高，没有卫星定位参与，无法实现定点悬停，也不能执行自动返航和航线飞行，松杆后机体随风漂移，位置须由飞手持续手动修正。姿态稳定和手动操控两种模式都具备，并非缺失项。"},{"id":731,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的标称电压一般为？","A":"1.2V","B":"3.7V","C":"12V","D":"24V","answer":"B","exp":"锂聚合物电池单节标称电压3.7V，满充约4.2V，放电电压过低会永久损伤电芯；标称值是估算整组电池电压的基准，N节串联电压约为N倍3.7V。1.2V是镍镉、镍氢电池的单节电压，与之混淆容易算错电池组参数。"},{"id":732,"type":"single","cat":"基础概念","stem":"无人机在飞行中遭遇强风，以下哪种操作最危险？","A":"降低高度","B":"迎风飞行增加空速","C":"顺风高速飞行","D":"增大油门保持悬停","answer":"C","exp":"顺风高速飞行时地速叠加风速，容易超出安全速度和控制范围，且返程必须逆风，耗电剧增甚至无法返回，风险最大。迎风飞行增加空速是抗风的常规做法，降低高度可避开高空强风，适当增大油门维持悬停也不属于最危险操作。"},{"id":733,"type":"single","cat":"飞行原理","stem":"多旋翼无人机的失速现象通常表现为？","A":"所有电机停转","B":"某一侧桨叶进入涡环状态或升力骤降","C":"GPS信号丢失","D":"电池鼓包","answer":"B","exp":"多旋翼大速度垂直下降或急收油门时，桨盘被自身下洗气流重新包裹进入涡环状态，桨叶工作在紊乱气流中升力骤降，机体抖动并加速下沉，此时推油门短时也难见效，应前推杆让桨盘脱离涡流。电机停转、GPS丢失和电池鼓包与失速机理无关。"},{"id":734,"type":"single","cat":"操纵与飞行技术","stem":"无人机遥控器上“油门杆”控制的是？","A":"飞机的俯仰","B":"飞机的横滚","C":"电机的总转速（总升力）","D":"飞机的偏航","answer":"C","exp":"油门杆控制所有电机的总转速，即总升力大小，用于操纵飞机升降，是四个基础通道之一；俯仰、横滚、偏航分别由另外三个通道控制。升降靠总推力与重量的平衡变化实现，与舵面、迎角等固定翼操纵概念无关。"},{"id":735,"type":"single","cat":"设备与维护","stem":"在无人机维护中，电机轴承缺油可能导致的典型现象是？","A":"电机温度升高、噪声增大、效率下降","B":"电池电压升高","C":"GPS信号变强","D":"桨叶转速增加","answer":"A","exp":"轴承缺油后摩擦阻力增大，电机运行温度升高、噪声明显增大，转速上不去，动力效率下降，长期缺油还会加速磨损直至轴承卡死。轴承状态只影响电机自身机械性能，与电池电压、GPS信号无关，桨叶转速只会下降不会增加。"},{"id":736,"type":"single","cat":"法规与空域","stem":"飞行计划中，通常要求无人机远离机场净空保护区，主要原因是？","A":"避免与有人机发生冲突","B":"避免电磁干扰","C":"节省电池","D":"方便降落","answer":"A","exp":"机场净空保护区是有人机起飞着陆和进近的关键区域，航班在此高度低、交通密集，无人机闯入极易造成相撞或迫使航班避让复飞，危及有人飞行安全。远离净空区的核心目的是避免与有人机冲突，省电、方便降落都不是主要原因。"},{"id":737,"type":"single","cat":"设备与维护","stem":"某四旋翼无人机使用4S锂聚合物电池，标称电压为14.8V，容量为5000mAh，该电池的标称能量约为多少Wh？","A":"50Wh","B":"74Wh","C":"100Wh","D":"148Wh","answer":"B","exp":"电池标称能量等于标称电压乘以容量：14.8V×5000mAh即14.8V×5Ah=74Wh。这一数值是估算续航和判断运输携带限制的依据；计算要用标称电压而非满充电压，还要把毫安时换算成安时，否则结果会差一个数量级。"},{"id":738,"type":"multi","cat":"设备与维护","stem":"多旋翼无人机飞行控制系统通常包含哪些传感器？","A":"加速度计","B":"陀螺仪","C":"气压计","D":"地磁罗盘","answer":"ABCD","exp":"加速度计测量三轴线加速度，参与姿态解算与悬停水平估计；陀螺仪测量三轴角速度，是姿态快速增稳的核心；气压计利用气压随高度变化的原理实现定高；地磁罗盘感知地磁场提供航向基准，与定位配合实现定向飞行和返航。四类传感器都是多旋翼飞控的常见配置。"},{"id":739,"type":"multi","cat":"基础概念","stem":"无人机动力系统包括哪些组成部分？","A":"电机","B":"电子调速器","C":"螺旋桨","D":"飞控计算机","answer":"ABC","exp":"动力系统由电机、电调和螺旋桨组成，负责把电能转化为拉力：电调按控制信号调节供给电机的功率，电机带动桨叶旋转产生升力。飞控计算机属于飞行控制系统，负责姿态解算和控制指令生成，与动力系统同机安装但职能不同，不属于动力系统组成。"},{"id":740,"type":"multi","cat":"操纵与飞行技术","stem":"下列哪些情况应禁止无人机起飞？","A":"能见度低于500m","B":"风力等级超过无人机抗风能力","C":"电池电压低于规定值","D":"空域未经批准","answer":"ABCD","exp":"能见度低于500米时目视观察和避让能力急剧下降，风力超过机型抗风极限会失控漂移，电池电压低于规定值意味着剩余电量不足以保障安全飞行和返航，空域未经批准属于违法飞行。四种情形都直接危及安全或合法性，均应禁止起飞。"},{"id":741,"type":"multi","cat":"基础概念","stem":"多旋翼无人机产生横滚运动可通过哪些方式？","A":"增加左侧电机转速，降低右侧电机转速","B":"增加右侧电机转速，降低左侧电机转速","C":"改变尾电机转速","D":"同时增加所有电机转速","answer":"AB","exp":"横滚由左右两侧电机转速差产生绕纵轴的力矩：升高左侧、降低右侧使机体向右倾斜，升高右侧、降低左侧则向左倾斜，两个方向分别对应前两种方式。四旋翼没有尾电机，改变尾桨转速是直升机偏航控制方式；同时增加全部电机转速只会垂直爬升，两侧升力依旧对称，不会横滚。"},{"id":742,"type":"multi","cat":"领航与任务规划","stem":"无人机飞行中GPS信号丢失后，飞控可能采取的措施包括？","A":"切换至姿态模式","B":"执行原地悬停","C":"自动返航","D":"立即断电","answer":"ABC","exp":"GPS失效后飞控通常自动降级为姿态模式，仅靠IMU和气压计维持姿态与定高，先保持在原地上空悬停等待信号恢复；若信号长时间未恢复且满足预设条件，会触发自动返航。立即断电会使动力彻底失效直接坠机，任何飞控都不会采取这种措施。"},{"id":743,"type":"multi","cat":"设备与维护","stem":"关于锂电池使用与保养，正确的做法有？","A":"避免过充过放","B":"存储电压保持在3.8V/cell左右","C":"鼓包电池可继续使用","D":"充电时有人看管","answer":"ABD","exp":"锂电池过充会引起鼓包甚至起火，过放会永久损失容量，两端都必须避免；长期满电存放会加速老化，存储电压保持在每节3.8V左右最合适；充电时必须有人看管，出现发热异味能立即断电处理。鼓包说明电芯内部已受损产气，继续使用极易起火，只能报废更换。"},{"id":744,"type":"multi","cat":"基础概念","stem":"无人机飞行中影响续航时间的主要因素有？","A":"电池容量","B":"整机重量","C":"风速风向","D":"桨叶效率","answer":"ABCD","exp":"电池容量决定可用能量的总量；整机越重，维持悬停所需升力和电流越大，续航越短；逆风飞行需要更大功率补偿，顺风相对省电，风速风向直接改变耗电速率；桨叶效率高意味着同样电能转化为更多有效拉力。四项因素共同决定续航时间，任何一项变化都会造成估算偏差。"},{"id":745,"type":"multi","cat":"设备与维护","stem":"以下哪些属于无人机日常维护内容？","A":"检查桨叶有无裂纹","B":"清洁电机","C":"校准指南针","D":"检查电池电压和内阻","answer":"ABCD","exp":"桨叶裂纹在离心力作用下会扩展断裂，每次飞行前都应目视检查；电机积尘影响散热需定期清洁；指南针受磁干扰会破坏航向基准，更换场地或出现异常时要重新校准；电压与内阻反映电芯健康度，内阻明显增大说明电池老化应淘汰。四项都是日常维护的基本内容。"},{"id":746,"type":"multi","cat":"操纵与飞行技术","stem":"无人机在飞行中遇到“涡环状态”时，正确的改出方法有？","A":"加大油门快速爬升","B":"减小下降速度","C":"向侧前方飞行以脱离下沉气流","D":"收油门快速下降","answer":"BC","exp":"涡环状态是下降中桨盘被自身下洗气流包裹、升力骤降的危险状态，改出要点是让桨盘脱离紊乱气流：减小下降速度，并向前或向侧方飞行，利用相对气流吹散涡环即可恢复升力。单纯加大油门会让桨叶继续在涡流中消耗功率，收油门快速下降则使涡环加剧，都会延长危险状态。"},{"id":747,"type":"multi","cat":"法规与空域","stem":"根据无人机飞行管理相关规定，下列哪些区域属于禁飞区？","A":"军用机场净空区","B":"核电站周边规定范围","C":"政府机关上空","D":"普通公园上空","answer":"ABC","exp":"军用机场净空区直接关系国防飞行安全，核电站周边为防止撞击引发重大事故而划设保护范围，政府机关等敏感目标上空禁止未经许可飞行，三者均属禁飞范畴。普通公园上空通常不属于法定禁飞区，一般按限飞管控或当地管理规定执行，未经批准同样不得随意飞行。"},{"id":748,"type":"single","cat":"操纵与飞行技术","stem":"无人机着陆目测与有人机相比不同之处为（）。","A":"有人机是从飞机观察着陆场，无人机是从着陆场观察飞机","B":"有人机为第三视角，无人机为第一视角","C":"有人机驾驶员通过地面人员通告仪表参考值，无人机起降驾驶员可自行观察仪表参考值","D":"以上均不正确","answer":"A","exp":"目测视角正好相反：有人机驾驶员身处机上，从空中观察着陆场地貌判断高度和姿态；无人机驾驶员站在地面，从着陆场观察飞机外形变化估计高度与下沉快慢，判断依据对调。无人机操控者不在机上，谈不上第三视角。"},{"id":749,"type":"single","cat":"操纵与飞行技术","stem":"飞行驾驶员操作无人机定高平飞时，下列正确的是（）。","A":"不断检查空速、高度、和航向指示","B":"定高平飞结束前可以休息","C":"偶尔关注以下空速，高度和航向指示","D":"以上均不正确","answer":"A","exp":"定高平飞中高度、空速、航向随时可能因风和动力状态变化而偏离，驾驶员必须不断扫视三项指示，发现偏差立即修正，才能保持航线与高度稳定；认为可以休息或只是偶尔关注，违背了全程监控的基本操纵要求，容易积累偏差导致偏离预定航线。"},{"id":750,"type":"single","cat":"设备与维护","stem":"地面控制站的组成包括地面遥控设备、通讯链路硬件、计算机软硬件平台、（）。","A":"地面站软件系统","B":"飞行控制系统","C":"GPS控制系统","D":"调参系统","answer":"A","exp":"地面控制站由地面遥控设备、通讯链路硬件、计算机软硬件平台和地面站软件系统组成，软件承担地图显示、航线上传、遥测解析等核心人机交互功能。飞行控制系统安装在机载端，不属于地面站组成，GPS和调参只是局部功能模块。"},{"id":751,"type":"single","cat":"基础概念","stem":"下列不属于飞行前检査重点的选项是（）。","A":"飞行器整体目视检查","B":"遥控器检査","C":"飞行器商标检查","D":"环境与飞行场地检査","answer":"C","exp":"飞行前检查围绕飞行安全展开：目视检查机体结构与桨叶状态，检查遥控器电量、配对和摇杆响应，评估气象环境与起降场地条件。机体上的商标只是外观标识，与系统状态和安全无关，不属于检查重点。"},{"id":752,"type":"single","cat":"基础概念","stem":"以下通用配置中，可以不配置的是（）。","A":"飞行数据记录仪","B":"机载追踪器","C":"无人机避障系统","D":"插拔式存储设备","answer":"C","exp":"飞行数据记录仪用于事后分析飞行数据，机载追踪器便于飞机丢失后定位，插拔式存储设备保存任务与日志，这些属于常见通用配置。避障系统属于高端机型的辅助功能，基础机型依靠驾驶员目视规避障碍，可以不配置。"},{"id":753,"type":"single","cat":"领航与任务规划","stem":"固定翼无人机进行水平8字飞行时，要求在高度为（）米的航线上。","A":"30-50","B":"60-80","C":"90-120","D":"120-140","answer":"B","exp":"水平8字属于考核科目，按考纲要求在60～80米高度完成：高度过高观察困难、动作易变形，过低则安全裕度不足，该区间兼顾目视效果与安全余量，其余区间与考核标准不符。"},{"id":754,"type":"single","cat":"设备与维护","stem":"电动型多旋翼无人机螺旋桨的型号必须与（）的型号相匹配。","A":"电动机","B":"电调","C":"飞控","D":"电池","answer":"A","exp":"螺旋桨的尺寸与螺距必须与电动机KV值和功率特性匹配：KV高的电机配小桨，KV低的电机配大桨，搭配不当会电流过大烧毁电机电调，或拉力不足无法起飞。电调只需电流余量合适，飞控和电池与桨型没有直接的匹配对应关系。"},{"id":755,"type":"single","cat":"领航与任务规划","stem":"下列关于航线规划中障碍物测量的描述，错误的是（）。","A":"如果作业区域内存在障碍物，则建议对障碍物测量，否则有可能造成撞机","B":"障碍物区域的形状和大小，可通过调整其边界点进行微调","C":"障碍物区域测量后，应设置障碍物边距，保障飞行安全","D":"障碍物区域不受内缩距离的影响","answer":"D","exp":"作业区内存在障碍物必须进行测量，否则航线可能穿越障碍造成撞机；障碍物区域的形状大小可通过边界点微调，测量后还要设置安全边距防止擦碰。障碍物区域同样受内缩距离影响、会随作业区内缩而调整，不受影响的说法与实际处理逻辑相反。"},{"id":756,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员遥控无人机起飞滑跑描述正确的是（）。","A":"将油门迅速推至大车，等飞机速度积累到足够使其自动起飞","B":"逐渐将油门推至大车并在速度达到起飞速度时柔和拉杆起飞","C":"迅速将油门推至大车并快速拉杆起飞","D":"以上均不正确","answer":"B","exp":"正确的滑跑起飞方法是将油门柔和连续推至大车位，用方向舵保持滑跑方向，待速度达到起飞速度后柔和带杆抬轮离地。猛推油门易使机体摆头、动力受冲击，速度不足就急拉杆会擦尾甚至失速，起飞操纵讲究循序渐进而非求快求猛。"},{"id":757,"type":"single","cat":"基础概念","stem":"以大疆御Mavic2变焦版为例，在DJIGO4APP中设置连拍模式，最多可连拍几张？（）","A":"3张","B":"5张","C":"7张","D":"9张","answer":"C","exp":"御Mavic 2在DJIGO4中提供3张、5张、7张三档连拍模式，最多一次可连拍7张，便于抓拍运动瞬间并从中挑选最清晰画面，该上限由相机处理能力决定，9张超出其连拍规格。"},{"id":758,"type":"single","cat":"基础概念","stem":"无人机燃油箱通气目的之一是（）。","A":"通气增大供油流量","B":"保证向发动机正常供油","C":"通气减小供油流量","D":"以上均不正确","answer":"B","exp":"油箱通气管使箱内与大气连通，燃油消耗时空气进入补充，维持箱内压力平衡，防止形成负压导致供油不足甚至断油，保证发动机连续正常供油。通气既不是为了增大也不是为了减小供油流量，而是稳定供油的前提条件。"},{"id":759,"type":"single","cat":"基础概念","stem":"旋翼的地面效应，是指飞行器在接近地面的高度工作时，被旋翼排向地面的气流受到地面阻挡，从而影响旋翼空气动力的一种现象影响地面效应的因素包括（）。","A":"温度、飞行速度和风、地表环境","B":"湿度、飞行速度和风、地表环境","C":"高度、飞行速度和风、地表环境","D":"以上均不正确","answer":"C","exp":"地面效应强弱首先取决于旋翼离地高度，越贴近地面下洗气流受阻越明显；同时还受飞行速度和风的影响，相对气流会改变下洗流场，以及地表环境的影响，平坦硬质地面效应强，粗糙松软地面效应弱。温度、湿度对其影响较小，不是主要因素。"},{"id":760,"type":"single","cat":"设备与维护","stem":"电调的输出电流必须（）电动机的最大电流。","A":"等于","B":"大于","C":"小于","D":"不等于","answer":"B","exp":"电调的持续输出电流必须大于电机最大工作电流并留出余量，一般按最大电流再留两成以上裕量选型，否则电机满负荷时电调过流发热甚至烧毁。等于或小于电机最大电流都存在过流风险，不等于则没有工程参考意义。"},{"id":761,"type":"single","cat":"设备与维护","stem":"无桨调试的基本目的是进行（），检査飞控、电调和电机是否可以正常通电。","A":"断电调试","B":"强电测试","C":"弱电测试","D":"通电测试","answer":"D","exp":"无桨调试是拆除螺旋桨后给整机通电，检查飞控、电调和电机能否正常通电自检、识别信号并响应指令，属于通电测试；因不带桨没有升力和气流风险，操作安全，是动力系统装机后的第一步验证。"},{"id":762,"type":"single","cat":"基础概念","stem":"关于天气以及作业之间的关系，以下描述错误的是（）。","A":"内吸性农药施药后应保证12小时内无降雨","B":"应在晴天以及阴天进行植保作业","C":"可在下雨后立即进行植保作业","D":"气温高于35摄氏度应停止作业","answer":"C","exp":"降雨后叶片布满水珠，药液被稀释、附着差，应等叶面干燥后再作业，下雨后立即作业的描述错误。内吸性农药需保证施药后12小时内无降雨，晴天阴天适合喷洒，气温高于35℃药液蒸发快且作物易受药害，应停止作业。"},{"id":763,"type":"single","cat":"基础概念","stem":"无人机发动机采用重力供油系统但装有增压泵，主要目的是为了（）。","A":"减小油箱的剩余燃油","B":"保证大速度巡航的用油","C":"保证爬升、下降及其他的特殊情况下的正常供油","D":"以上均不正确","answer":"C","exp":"重力供油靠油箱与汽化器的高度差自然输油，平飞时已够用；加装增压泵是为了在爬升、下降、加速或姿态剧烈变化导致供油不稳的特殊情况下强制输油，防止断油熄火。它不是为减小剩余油量，核心是保障特殊状态下的连续供油。"},{"id":764,"type":"single","cat":"航空气象","stem":"雾霾天气对多旋翼飞行器飞行的最大影响是？（）","A":"降低电池放电性能","B":"影响飞手身体健康","C":"降低飞行效率","D":"降低能见度","answer":"D","exp":"雾霾使能见度大幅下降，目视飞行时难以看清无人机姿态、方位和障碍物，一旦超出视距就无法安全避让，这是对多旋翼飞行最大的影响。电池放电性能主要取决于温度，雾霾并不直接降低放电能力，飞行效率与飞手健康也不是最大的飞行安全影响。"},{"id":765,"type":"single","cat":"设备与维护","stem":"多旋翼无人机自驾仪与机架的隔振改造方法，下列说法不正确的是（）。","A":"双面泡沫胶、尼龙扣","B":"螺纹固定连接","C":"凝胶垫","D":"耳塞式或O型环悬挂安装","answer":"B","exp":"自驾仪隔振需要柔性元件衰减机架传来的高频振动，双面泡沫胶、尼龙扣、凝胶垫以及耳塞式或O型圈悬挂都属于弹性减振安装。螺纹固定连接是刚性连接，会把机架振动原样传给IMU，造成姿态数据抖动，不属于隔振改造方法。"},{"id":766,"type":"single","cat":"设备与维护","stem":"两块16000MAH6S25C电池，一种方式串联，一种方式并联，哪种方式能输出电流更大？（）","A":"不联","B":"并联","C":"串联","D":"以上均不正确","answer":"B","exp":"并联时电压不变、总容量加倍，两块电池同时对外放电，可输出的总电流约为单块的两倍，等效内阻减半，放电能力更强；串联则是电压翻倍，电流仍受单块电池放电能力限制。需要更大输出电流时应采用并联方式。"},{"id":767,"type":"single","cat":"基础概念","stem":"同一架多旋翼飞行器，在同样做好动力匹配的前提下（）。","A":"两叶桨的效率高","B":"三叶桨的效率高","C":"两种桨效率一样高","D":"以上均不正确","answer":"A","exp":"桨叶数量越少，桨叶间气流干扰和诱导损失越小，同等动力匹配下两叶桨效率高于三叶桨；三叶桨的优势在于拉力分布均匀、振动小，但以牺牲效率为代价，追求续航的机型普遍采用两叶桨。"},{"id":768,"type":"single","cat":"基础概念","stem":"移动通信模块传输模块安装前区分其类型，根据功能它可以分为图像传输型，（），数据传输型三类。","A":"遥控数据传输型","B":"电子信息传输型","C":"数图一体型","D":"全球导航卫星系统（GNSS）数据传输型","answer":"C","exp":"按传输内容划分，无线传输模块分为三类：图像传输型负责传输视频画面，数据传输型负责遥测与控制数据，数图一体型则同时兼顾图像和数据传输。遥控指令传输归入数据传输范畴，GNSS是定位系统而非传输模块的类型划分。"},{"id":769,"type":"single","cat":"基础概念","stem":"无人机飞防作业关于风的方面，描述错误的是（）。","A":"大风会引起飘移增加","B":"禁止人员处于下风向","C":"应在3级风以内作业","D":"7米/秒的风速有助于提升作业效果","answer":"D","exp":"7米/秒约合4级风，药液会被大幅吹散造成飘移污染和覆盖不均，明显降低作业质量，有助于提升效果的说法错误。植保作业应在3级风以内进行，大风会增加飘移，人员必须处于上风向，禁止停留在下风向接触药雾。"},{"id":770,"type":"single","cat":"基础概念","stem":"（）是最佳的航空飞行层。","A":"对流层","B":"平流层","C":"高层大气","D":"底层","answer":"B","exp":"平流层大气以平流运动为主，水汽和杂质少，没有对流云和剧烈天气，气流平稳、能见度好，是航空飞行最理想的层次；对流层集中了绝大部分天气过程，颠簸与气象变化剧烈，不利于平稳飞行。"},{"id":771,"type":"single","cat":"操纵与飞行技术","stem":"自动驾驶仪中的陀螺是用来测量哪些物理量？（）","A":"飞机角速度或飞机姿态","B":"飞机角速率或飞机姿态角","C":"飞机角速度或飞机姿态角","D":"以上均不正确","answer":"C","exp":"陀螺仪直接输出机体绕各轴转动的角速度，经积分解算后得到俯仰角、横滚角等姿态角，作为自动驾驶仪姿态控制的基础。严格说陀螺给出的是角速度和姿态角参数，泛称姿态不够准确，角速率与姿态角的组合表述也不如该选项规范。"},{"id":772,"type":"single","cat":"基础概念","stem":"在无人机协调指挥中哪个角色更适合与后方指挥人员沟通（）。","A":"飞手","B":"云台手","C":"地面人员","D":"维修员","answer":"B","exp":"协同作业中飞手必须全神贯注操纵飞机，云台手专注取景拍摄，精力相对宽裕，由云台手与后方指挥人员沟通最合适，既能实时报告画面情况，又不干扰飞行操纵。地面人员主要承担警戒观察，维修员负责装备保障，都不宜承担主要沟通职责。"},{"id":773,"type":"single","cat":"基础概念","stem":"无人机飞行时放下起落架，会使飞机（）。","A":"全机阻力减小","B":"全机阻力无明显变化","C":"全机阻力增大","D":"以上均不正确","answer":"C","exp":"起落架及其支柱、机轮突出在气流中，会产生大量废阻力，放下后全机阻力明显增大，平飞需要更大推力维持速度，着陆时正是利用其辅助减速。阻力减小或无明显变化的说法与增阻事实相反。"},{"id":774,"type":"single","cat":"基础概念","stem":"空机重量不包含（）的重量。","A":"云台相机","B":"电机","C":"电池","D":"桨叶","answer":"A","exp":"空机重量指无人机机体及电机、电池、桨叶等组成部分的重量总和，任务载荷不计入其中；云台相机用于执行拍摄任务，属于典型的任务载荷，统计空机重量时不包含。这一口径是划分微型、轻型、中型等级别的关键依据。"},{"id":775,"type":"single","cat":"基础概念","stem":"请选择出哪一个功能选项，在手动遥控飞行时，可以改变各通道的操作灵敏度？（）","A":"行程比例","B":"微调比例","C":"通道速度","D":"以上均不正确","answer":"A","exp":"行程比例设定摇杆行程与输出舵量之间的对应比例，调小后同样杆量对应更小的输出变化，操纵变得柔和易控，用来改变各通道的操作灵敏度。微调用于修正通道中位零点偏差，通道速度控制舵机响应快慢，都不是灵敏度比例参数。"},{"id":776,"type":"single","cat":"操纵与飞行技术","stem":"经常在草地、碎石路面起飞、着陆的固定翼无人机，螺旋桨旋转时距地面最近点的高度至少要大于螺旋桨直径的（）。","A":"1/2","B":"1/5","C":"1/10","D":"1/20","answer":"B","exp":"在草地、碎石面起降时杂物易被桨叶吹起或撞伤桨尖，按相关教材的安全要求，螺旋桨旋转时距地面最近点至少应大于桨叶直径的1/5，为弹起物和桨叶变形留出安全余量，比例过低极易打伤桨叶或吸入异物导致事故。"},{"id":777,"type":"single","cat":"基础概念","stem":"下列不属于有桨调试主要内容是（）。","A":"油门测试","B":"动力测试","C":"俯仰测试","D":"滚转测试","answer":"B","exp":"有桨调试在装桨状态下进行，主要内容是油门测试（校准油门行程、检查转速响应）和动力测试（拉力、电流表现），确认动力系统工作正常。俯仰测试属于飞控姿态响应检查，与动力系统调试性质不同，不属于有桨调试的主要内容。"},{"id":778,"type":"single","cat":"设备与维护","stem":"一般锂聚合物电池上都有2组线1组是输出线（粗，红黑各1根）；1组是单节锂电引出线（细，与s数有关），用以监视平衡充电时的单体电压，下面说法正确的是（）。","A":"6S电池有5根红色引出线，1根黑色引出线","B":"6S电池有7根引出线","C":"6S电池有6根引出线","D":"以上均不正确","answer":"B","exp":"6S电池有6个单体电芯，平衡引出线按单体逐节串联取样，6个单体再加一根公共端共7根引出线，才能监测每一个单体的电压；只有6根会漏测一个单体，红线黑线数量的说法混淆了线序概念。"},{"id":779,"type":"single","cat":"操纵与飞行技术","stem":"视距内运行航空器处于驾驶员或观测员目视视距内半径多少米？（）","A":"500米","B":"600米","C":"700米","D":"1000米","answer":"A","exp":"视距内运行指驾驶员或观测员与无人机保持直接目视接触的运行，按现行规定范围为目视视距内半径500米、相对高度120米以内，超出后属于超视距运行，需相应资质和条件。其余数值与规定的距离不符。"},{"id":780,"type":"multi","cat":"基础概念","stem":"飞行前必须检查（）是否正常。","A":"遥控设备控制距离","B":"伺服系统舵面方向","C":"动力系统运转情况","D":"模型结构完整牢固","answer":"ABCD","exp":"遥控设备控制距离不足会导致信号中断失控坠机，起飞前应确认链路有效；舵面方向错误会造成操纵反向，极其危险；动力系统运转不正常则无法维持飞行；机体结构不牢固在飞行载荷下可能解体散架。四项都直接决定飞行安全，必须逐项检查确认。"},{"id":781,"type":"multi","cat":"基础概念","stem":"以下（）属于警用固定翼无人机系统降落方式。","A":"起落架滑行降落","B":"垂直降落","C":"撞网/撞绳回收","D":"降落伞回收","answer":"ABCD","exp":"常规固定翼采用起落架滑跑降落；具备垂起能力的机型可垂直降落；警用场景场地受限时采用撞网、撞绳等拦截方式回收；降落伞回收则开伞减速落地保护机体。四种方式在警用固定翼无人机系统中都有应用，均属于其降落回收方式。"},{"id":782,"type":"multi","cat":"电力巡检","stem":"巡检作业区域出现雷雨、大风等可能影响作业的突变天气时，应及时评估巡检作业安全性，在确保安全后方可继续执行巡检作业，否则应采取措施控制无人机巡检系统（）。","A":"起飞","B":"避让","C":"返航","D":"就近降落","answer":"BCD","exp":"突发雷雨大风时，安全评估不通过就应中止作业：立即操纵无人机避让危险天气区域，具备条件时执行返航，无法返航则选择安全场地就近降落，使系统始终处于受控状态。此时起飞只会把设备暴露在更恶劣的环境中，与安全规程完全相悖。"},{"id":783,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，选定的无人机巡检系统起飞和降落区应远离（），尽量避开周边军事禁区、军事管理区、森林防火区和人员活动密集区等，且满足对应机型的技术指标要求。","A":"公路","B":"铁路","C":"重要建筑","D":"重要设施","answer":"ABCD","exp":"起降区应远离公路和铁路，防止飞行活动干扰交通或引发围观事故；远离重要建筑与重要设施，避免坠机撞击造成重大损失；同时尽量避开军事禁区、军事管理区、森林防火区和人员密集区，并满足对应机型的场地技术指标。四项都是必须远离的对象。"},{"id":784,"type":"multi","cat":"设备与维护","stem":"检查无刷电机动平衡是否良好的方法描述错误的是（）。","A":"电机不带螺旋桨进行旋转","B":"电机带动螺旋桨进行旋转","C":"用手转动电机","D":"将飞行器起飞，感受飞行器机身振动","answer":"BCD","exp":"检查动平衡应让电机不带螺旋桨高速旋转，凭振动与声音判断转子平衡状态。带桨旋转会混入桨叶自身不平衡和气流噪声，无法分辨振源；用手转动转速太低，感受不出微小失衡；起飞后机身振动是机架、桨、电机多种振源叠加的结果，不能归因于电机。"},{"id":785,"type":"multi","cat":"基础概念","stem":"大型固定翼无人机，机翼与机身常用的连接形式主要有（）。","A":"铰接接头(只传递力)","B":"固接接头(传递力和力矩)","C":"围框式接头(传递力和力矩)","D":"连动式接头（只传递力）","answer":"ABC","exp":"大型固定翼机翼与机身常用连接形式：铰接接头通过耳片铰接，只传递力；固接接头将翼梁与机身框直接连成整体，力和力矩都传递；围框式接头沿连接面布置围框结构传力，同样传递力和力矩。并无连动式接头这一结构形式，属于杜撰的干扰项。"},{"id":786,"type":"single","cat":"法规与空域","stem":"执行紧急救护，抢险救灾或其他紧急任务，飞行计划申请最迟应在飞行前（）H提出。","A":"0.5","B":"1","C":"2","D":"3","answer":"B","exp":"按飞行管制相关规定，执行紧急救护、抢险救灾等紧急任务时，飞行计划申请可以简化，最迟应在飞行前1小时提出，以便管制部门快速审批、优先放行。半小时不足以完成协调流程，2小时和3小时则无必要地拖延紧急任务响应。"},{"id":787,"type":"single","cat":"基础概念","stem":"下列关于动压的说法是正确的（）。","A":"总压与静压之和","B":"总压与静压之差","C":"动压和速度成正比","D":"以上均不正确","answer":"B","exp":"动压等于总压与静压之差，反映气流动能，数值上等于二分之一乘以空气密度再乘以速度平方，与速度平方成正比而非正比；皮托管正是靠测量总压与静压差获得动压，再解算空速。总压与静压之和没有物理意义。"},{"id":788,"type":"single","cat":"基础概念","stem":"用万用表检测无人机黏合后防打火头和接头外壁之间的电阻值，以下哪个阻值是正常的？（）","A":"1.2Ω","B":"2.5Ω","C":"3.3Ω","D":"6.3Ω","answer":"D","exp":"防打火头与接头外壁之间靠绝缘黏合层隔电，正常情况下阻值应远大于导电接触的水平，四个数值中6.3Ω最大、最接近绝缘要求，视为正常；1.2Ω至3.3Ω的阻值过小，说明黏合绝缘不良，通电时易发热打火。"},{"id":789,"type":"single","cat":"操纵与飞行技术","stem":"四轴旋翼机使用的是（），所以应当使用无刷电调。","A":"有刷电机","B":"无刷电机","C":"智控电机","D":"非智控电机","answer":"B","exp":"四轴旋翼机普遍采用无刷电机，其换向靠外部电子换相完成，必须配无刷电调把直流电逆变为三相电并按指令换相驱动；有刷电机靠电刷机械换向，使用的是有刷电调。智控、非智控电机并不是动力配置的规范分类说法。"},{"id":790,"type":"single","cat":"设备与维护","stem":"地面站电子地图图元标注不包含下列哪种信息（）。","A":"场地标注","B":"警示标注","C":"地形标注","D":"以上均不正确","answer":"C","exp":"地面站电子地图的图元标注主要包含场地标注（起降点、作业区域）和警示标注（禁飞区、危险区提醒），用于辅助飞行决策；地形由底图数据呈现，不属于图元标注信息，地形标注的说法不成立。"},{"id":791,"type":"single","cat":"操纵与飞行技术","stem":"在多旋翼无人机油门曲线调试中，关于油门表述不正确的是（）。","A":"默认的油门曲线为正比例曲线","B":"自主飞行时，油门值应处于中间略上或在中点","C":"油门曲线可以作为摇杆灵敏度设置","D":"降落过程中需要缓慢拉下油门","answer":"B","exp":"自主飞行时油门由飞控闭环控制，升力输出与摇杆位置没有对应关系，无需人为保持在中点或略上，杆位只在手动和半自动模式起作用。默认油门曲线为正比例曲线、油门曲线可兼作灵敏度调节、降落时缓慢收油门，这些表述都是正确的。"},{"id":792,"type":"single","cat":"设备与维护","stem":"地面站电子地图显示的信息分为三个方面：一是（）二是（）三是其他辅助信息。","A":"无人机地理坐标信息，无人机飞行姿态信息","B":"无人机位置和飞行航迹，无人机航迹规划信息","C":"无人机飞行姿态信息，无人机航迹规划信息","D":"以上均不正确","answer":"B","exp":"地面站电子地图显示的信息分三类：一是无人机位置和飞行航迹，实时反映飞机在哪里、飞过哪里；二是航迹规划信息，即预设航线、航点与任务参数；三是其他辅助信息。地理坐标与飞行姿态属于遥测数据内容，不是地图信息的分类表述。"},{"id":793,"type":"single","cat":"基础概念","stem":"汽化器式活塞发动机在（）容易出现汽化器回火现象。","A":"热发动起动时","B":"油门收的过猛","C":"寒冷天气第一次起动时","D":"以上均不正确","answer":"C","exp":"寒冷天气第一次起动时发动机温度很低，混合气形成不均、燃烧迟缓，火焰容易沿进气道回窜，在汽化器处形成回火，因此冷起动前应泵油预热、起动后缓慢暖机。热发动工况稳定，油门收得过猛主要引起贫火或熄火，均不是回火的典型工况。"},{"id":794,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机由爬升转为平飞时（）。","A":"到达预定高度时，开始改平飞","B":"上升至预定高度前10-20米时，开始改平飞","C":"超过预定高度10-20米时，开始改平飞","D":"以上均不正确","answer":"B","exp":"退出爬升存在惯性冲高：开始改平后飞机仍会继续上升一段距离，因此应在到达预定高度前10～20米提前推杆改平并适当收油门，使飞机恰好稳定在预定高度。到高度才改平会冲过预定高度，超过预定高度再改平则低于目标高度。"},{"id":795,"type":"single","cat":"操纵与飞行技术","stem":"小型无人驾驶航空器最常用的起降装置就是起落架，根据起落架的不同安装方式可分为前三点、后三点和（）起落架。","A":"平行式","B":"滑橇式","C":"交叉式","D":"车轮式","answer":"C","exp":"起落架按安装布置方式分为前三点式、后三点式和交叉式等类型，不同布置影响滑跑方向稳定性与起降特性；滑橇式、车轮式是按着地结构划分的类别，平行式并不是起落架安装方式的规范术语。"},{"id":796,"type":"single","cat":"操纵与飞行技术","stem":"垂直起降固定翼无人机中翼段连接（）和外翼段，悬停动力臂安装在中翼段上，无人机的悬停动力系统全部集中在悬停动力臂上，为无人机提供起降动力。","A":"外翼段","B":"尾翼","C":"机身","D":"悬停动力臂","answer":"C","exp":"复合翼垂直起降无人机的中翼段连接机身和外翼段，悬停动力臂就装在中翼段上，全部悬停动力集中布置其上，起降时提供垂直升力，平飞时由前推动力接续，外翼段、尾翼都不是中翼段的对接对象。"},{"id":797,"type":"single","cat":"设备与维护","stem":"同样容量不同类型的电池，最轻的是（）。","A":"铅酸蓄电池","B":"聚合物锂电池","C":"碱性电池","D":"以上均不正确","answer":"B","exp":"锂聚合物电池能量密度最高，同样容量下重量最轻，这是它成为无人机主流动力电池的根本原因；铅酸电池能量密度极低，同等容量要笨重得多，碱性电池能量密度也低且不能大电流放电，都不适合航空动力应用。"},{"id":798,"type":"single","cat":"基础概念","stem":"拉距离试验是（）应该注意的问题。","A":"安装定位装置时","B":"测试动力系统时","C":"使用遥控器时","D":"测试地面站时","answer":"C","exp":"拉距离试验是使用遥控器时应注意的问题：飞行前应在开阔场地拉开距离测试遥控链路有效范围，确认信号强度和失控保护动作可靠，避免超距失控。安装定位装置、测试动力系统和地面站各有独立的检查内容，与拉距离试验无关。"},{"id":799,"type":"single","cat":"基础概念","stem":"目前世界上无人机的频谱使用主要集中在（）。","A":"UHF、L和C","B":"VHF","C":"任意","D":"以上均不正确","answer":"A","exp":"无人机测控与数据链的频谱使用主要集中在UHF、L和C频段：UHF常用于遥控遥测，绕射与穿透能力较好；L、C频段适合图传和中继链路，带宽与抗干扰性能满足任务数据传输。VHF主要用于广播与话音通信。"},{"id":800,"type":"single","cat":"设备与维护","stem":"下列关于充电环境注意事项描述错误的是（）。","A":"避免处于阳光暴晒环境下充电","B":"应在车辆、室内等密闭空间内充电","C":"避免处于降雨条件下充电","D":"尽量处于通风常温环境下充电","answer":"B","exp":"锂电池充电存在发热甚至起火风险，车辆、室内等密闭空间散热差，起火后难以处置并危及人员安全，不应在其中充电；正确环境是通风、常温处，并避免阳光暴晒和降雨条件，防止高温触发热失控或短路。"},{"id":801,"type":"single","cat":"基础概念","stem":"（）是指军事重地、核电站和行政中心等关乎国家安全的区域及周边。","A":"安保净空区","B":"安全净空区","C":"重点地区","D":"重要地区","answer":"C","exp":"军事重地、核电站、行政中心等关乎国家安全的区域及周边，在无人机管理中统称为重点地区，未经批准禁止飞入或需特别审批。安保净空区、安全净空区侧重机场净空与安保管控概念，重要地区是泛称，都不是这一范围定义的规范用语。"},{"id":802,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆的过程不包括（）。","A":"平飘接地和着陆滑跑","B":"下降和定高","C":"下滑和拉平","D":"以上均不正确","answer":"B","exp":"着陆的完整过程是下滑、拉平、平飘接地和着陆滑跑：下滑建立稳定的进近轨迹，拉平减小下降角并转为平飞姿态，平飘消耗速度后柔和接地，随后滑跑减速停止。定高是航线飞行中保持高度的动作，发生在巡航阶段，不属于着陆过程。"},{"id":803,"type":"single","cat":"基础概念","stem":"雷达的主要功能，不包括的是（）。","A":"避障","B":"定高","C":"提前预判障碍物","D":"照明","answer":"D","exp":"雷达通过发射电磁波并接收回波探测目标，机载雷达可用于避障、对地测距定高以及提前预判障碍物的方位和距离，为飞控提供决策数据。照明依靠可见光源实现，属于灯光系统的功能，与电磁探测原理无关，雷达不具备照明功能。"},{"id":804,"type":"single","cat":"基础概念","stem":"无人机具体执行的飞行任务主要包括到达时间和进入目标方向等，需满足如下要求：（）。","A":"航迹距离约束，固定的目标进入方向","B":"执行任务时间，进入目标位置","C":"返航时间，接近目标的飞行姿态","D":"以上均不正确","answer":"A","exp":"任务对飞行轨迹的约束包括航迹距离约束和固定的目标进入方向：距离约束保证航线长度在续航能力之内，固定进入方向保证按预定方位接近目标完成任务。执行任务时间、返航时间属于计划安排要素，接近姿态也不是此类约束。"},{"id":805,"type":"single","cat":"操纵与飞行技术","stem":"影响直升机起飞载重量的主要因素不包括（）。","A":"机场标高，空气湿度","B":"风速和风向","C":"上反效应场地面积和周围障碍物","D":"以上均不正确","answer":"C","exp":"起飞载重量受机场标高和空气湿度影响，空气密度降低则旋翼拉力下降，又受风速风向影响，这些因素直接限制可用升力与安全裕度。上反效应是机翼横侧稳定性的设计特性，场地面积和周围障碍物属于场地条件，均与起飞载重量无关。"},{"id":806,"type":"single","cat":"基础概念","stem":"（）的内容包括出发地点、途径地点、目的地点的位置信息、飞行高度速度和需要到达的时间段。","A":"航线规划","B":"航迹规划","C":"任务规划","D":"以上均不正确","answer":"A","exp":"航线规划的内容正是出发地点、途经地点、目的地点的位置信息，加上飞行高度、速度和需要到达的时间段，形成从起点到终点的计划航线；航迹规划侧重对实际飞行轨迹的约束与优化，任务规划是整个任务层面的组织安排。"},{"id":807,"type":"single","cat":"基础概念","stem":"多旋翼飞行器通常至少装有（）及以上旋翼，利用空气动力克服自身重量，可自主或遥控飞行，能携带各种任务设备，并可多次回收使用。","A":"一个","B":"两个","C":"三个","D":"四个","answer":"C","exp":"多旋翼飞行器通常至少装有三个及以上旋翼，依靠旋翼旋转产生升力克服自重，通过调节各旋翼转速差实现姿态与位置控制；单旋翼带尾桨属于直升机，两个旋翼的共轴、纵列构型一般单独归类，常见多旋翼为四旋翼、六旋翼和八旋翼。"},{"id":808,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，收油门过晚、过细，速度减小慢，使拉平时的速度大，飞机下沉慢（）。","A":"容易拉平高或者进入平飘时仰角较小","B":"对飞机无影响","C":"容易拉平低或者进入平飘时仰角较大","D":"以上均不正确","answer":"A","exp":"收油门过晚、过细使速度消散慢，拉平时速度偏大、升力富余，飞机下沉缓慢，容易拉得过高，且平飘阶段速度大所需迎角小、仰角较小，接地距离随之拉长；拉平低、仰角较大对应的是收油门过早过粗的情形，两种错误方向相反。"},{"id":809,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行员操纵升降舵时，飞行器将绕（）。","A":"横轴运动","B":"纵轴运动","C":"立轴运动","D":"以上均不正确","answer":"A","exp":"升降舵偏转产生俯仰操纵力矩，使飞行器绕横轴运动，实现机头上仰或下俯；绕纵轴的运动由副翼操纵实现横滚，绕立轴的运动由方向舵操纵实现偏航。三组气动舵面分别对应三根机体轴，构成固定的操纵对应关系。"},{"id":810,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，无人机采用的导航技术中，多普勒导航具有（）优点","A":"自主性好","B":"反应快","C":"抗干扰性强","D":"测速精度高","answer":"ABCD","exp":"多普勒导航利用雷达波的多普勒频移测量地速和偏流角，不依赖外部导航台站与卫星信号，自主性好；测量实时解算，反应快；频移信息难以被欺骗和干扰，抗干扰性强；测速精度高，适合复杂地形和卫星信号受限环境的巡检飞行。四个优点均成立。"},{"id":811,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，多旋翼无人机特殊环境适应性能类检测项目包括（）。","A":"低温环境飞行性能","B":"高低温存储试验","C":"跌落试验","D":"高海拔环境飞行性能","answer":"AD","exp":"特殊环境适应性能类检测考察无人机在特殊气象和地理条件下的飞行能力，包括低温环境飞行性能与高海拔环境飞行性能，验证低气温、低气压空气稀薄条件下的动力和操控表现。高低温存储试验属于存储适应性而非飞行性能，跌落试验属于机械冲击类检测，都不在该类别中。"},{"id":812,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中：国家电网有限公司直升机、无人机、人工协同巡检模式试点工作收集现场应用数据，分析直升机巡检、不同类型无人机巡检、人工巡检的影响因子，采用层次分析法确定权重系数，从（）等方面构造效益评价指标。","A":"质量","B":"安全","C":"效率","D":"经济性","answer":"ABCD","exp":"国网协同巡检试点用层次分析法确定直升机、无人机、人工巡检的权重系数，效益评价指标从质量、安全、效率、经济性四方面构造：质量看数据采集与缺陷检出效果，安全看作业风险水平，效率看单位时间巡检覆盖能力，经济性看成本投入产出。四个维度共同构成评价体系。"},{"id":813,"type":"multi","cat":"基础概念","stem":"飞机飞行时的稳定性可分为（）。","A":"纵向稳定性","B":"航向稳定性","C":"侧向稳定性","D":"横向稳定性","answer":"ABD","exp":"飞机稳定性按机体三轴划分为三类：绕横轴的纵向稳定性（俯仰方向）、绕立轴的航向稳定性（偏航方向）和绕纵轴的横向稳定性（滚转方向），三者共同保证飞机受扰后能自动恢复原状态；侧向稳定性不是规范的分类名称，滚转方向的稳定已由横向稳定性涵盖。"},{"id":814,"type":"multi","cat":"操纵与飞行技术","stem":"无人机第四转弯点的位置是由第三转弯的（）决定的。","A":"高度","B":"角度","C":"时机","D":"风速","answer":"BC","exp":"矩形起落航线中，第四转弯点的位置由第三转弯的角度和时机共同决定：角度决定第三边航迹的延伸方向，时机决定从哪一点开始转入第四边，两者结合即可确定转弯点的空间位置；高度只影响航迹的垂直剖面形状，风速通过地速影响航迹保持，都不直接决定转弯点位置。"},{"id":815,"type":"multi","cat":"领航与任务规划","stem":"随着未来体系化警务实战不断推进，以及无人机装备技术的快速发展，任务规划系统和任务规划技术需要主动适应警务实战需求和任务载荷使用特点其未来主要发展趋势有以下几点（）。","A":"多元、实时的作战信息保障","B":"通用化的软件架构","C":"智能自主规划","D":"联合协同规划","answer":"ABCD","exp":"警务无人机任务规划的未来发展趋势有四方面：多元实时的作战信息保障为实战决策提供支撑；通用化的软件架构便于不同机型、载荷快速集成接入；智能自主规划减少人工干预、提升应急响应速度；联合协同规划支持多机多部门协同作战，四项均是技术演进的明确方向。"},{"id":816,"type":"single","cat":"设备与维护","stem":"四旋翼桨叶安装必须区分正反桨、相邻位置桨叶相反、对角之间转向相反和（）。","A":"桨叶安装牢固","B":"按顺时针安装","C":"按逆时针安装","D":"安装螺丝加垫圈","answer":"A","exp":"相邻桨叶反转、对角转向相反是为了让各电机反扭矩相互抵消，机头才不会自转；在此布局下桨叶还必须安装牢固，高速旋转的离心力会使松动桨叶甩出导致失控坠机，统一按顺时针或逆时针安装、加垫圈都不是通用安装要求。"},{"id":817,"type":"single","cat":"操纵与飞行技术","stem":"悬停状态的四轴飞行器如何实现向右移动（）。","A":"纵轴右侧的螺旋桨减速，纵轴左侧的螺旋桨加速","B":"纵轴右侧的螺旋桨加速，纵轴左侧的螺旋桨减速","C":"横轴前侧的螺旋桨加速，横轴后侧的螺旋桨减速","D":"以上均不正确","answer":"A","exp":"悬停中要向右平移，须让机体向右倾斜形成横滚：纵轴右侧的螺旋桨减速、左侧加速，升力合力随之绕纵轴向右偏转，产生指向右侧的水平分量推动飞行器右移；若右侧加速机身将向左倾斜而向左移动，前后桨差动改变的只是俯仰姿态而非横滚。"},{"id":818,"type":"single","cat":"航空气象","stem":"易造成飞机积冰的原因是（）。","A":"过冷雨滴","B":"雨滴","C":"雾气","D":"雾滴","answer":"A","exp":"积冰最典型的成因是过冷雨滴：温度低于0℃仍保持液态的水滴，碰到机体表面立即冻结成冰，附着快、积冰厚、危害大；普通雨滴温度在冰点以上不易冻结，雾气和雾滴含水量小、积冰缓慢，都不如过冷雨滴危险。"},{"id":819,"type":"single","cat":"基础概念","stem":"在M600飞行器当中，负责显示飞行器状态的部分是（）。","A":"遥控器","B":"DJIGO","C":"遥控器显示面板","D":"手机","answer":"B","exp":"经纬M600的飞行器状态、参数与告警通过移动设备上的DJI GO呈现，遥控器没有集成显示面板，只承担操纵输入与链路传输功能；手机只是运行App的载体，遥控器和遥控器显示面板都不是状态显示的承担部分。"},{"id":820,"type":"single","cat":"电力巡检","stem":"若飞行航线、悬停点与杆塔坐标偏差较大，应及时修（）。","A":"航线库","B":"飞行航向","C":"飞行航迹","D":"飞行航线","answer":"A","exp":"预设飞行航线、悬停点与杆塔实际坐标偏差较大，说明航线库中存储的点位数据已不准确，必须及时修订单航线库，从数据源头保证巡检点位准确；临时修飞行航向、航迹只是现场操纵补救，无法消除基础数据的偏差，还会影响后续架次的作业质量。"},{"id":821,"type":"single","cat":"电力巡检","stem":"无人机技术规程适用于采用中、小型无人直升机在（）及以上电压等级架空输电线路所进行的巡检作业，35kV架空输电线路参照执行。","A":"500kV","B":"330kV","C":"220kV","D":"110kV（66kV）","answer":"D","exp":"无人机巡检技术规程适用于中、小型无人直升机对110（66）kV及以上电压等级架空输电线路的巡检作业，35kV线路参照执行；110（66）kV是规程明确的适用下限，220kV及以上线路均涵盖在内，分界值不是35kV。"},{"id":822,"type":"single","cat":"领航与任务规划","stem":"任务规划的主要目标是依据地形信息和执行任务环境条件信息，综合考虑无人机的性能、到达时间、耗能、威胁以及飞行区域等约束条件，为无人机规划出一条或多条自（）的（），保证无人机高效、圆满地完成飞行任务，并安全返回基地。","A":"起点到终点，最短路径","B":"起飞点到着陆点，最佳路径","C":"出发点到目标点，最优或次优航迹","D":"以上均不正确","answer":"C","exp":"任务规划要根据地形与环境信息，综合无人机性能、时间、能耗、威胁和空域等约束，规划出一条或多条从出发点到目标点的最优或次优航迹；约束复杂时最优解未必存在，次优航迹同样能高效完成任务并安全返航，只讲最短或最佳路径都不完整。"},{"id":823,"type":"single","cat":"飞行原理","stem":"组装固定翼无人机后进行试飞，如果机翼和尾翼扭曲变形，则飞行时左右机翼迎角不同，会导致无人机（）。","A":"无法起飞","B":"无法转向","C":"自行俯仰","D":"偏航或横滚","answer":"D","exp":"机翼和尾翼扭曲变形使左右机翼的安装角与迎角不一致，飞行中两翼升力不等产生滚转力矩，安装角差异带来的侧力还会使机头偏转，因此表现为偏航或横滚；俯仰姿态由平尾和升降舵控制，与左右机翼迎角差没有直接对应关系。"},{"id":824,"type":"single","cat":"电力巡检","stem":"降落后，应进行（）及零部件检查，并做好无人直升机巡检系统使用记录。","A":"外观","B":"电量","C":"螺旋桨","D":"地面站","answer":"A","exp":"降落后应进行外观检查及零部件检查并做好使用记录：着陆冲击可能造成结构变形、紧固件松动、桨叶裂纹等损伤，外观检查能第一时间发现隐患；电量是状态数据，地面站是地面设备，螺旋桨检查已含在外观与零部件检查之内。"},{"id":825,"type":"single","cat":"基础概念","stem":"机翼空气动力受力最大的是（）。","A":"机翼上表面压力","B":"机翼下表面压力","C":"机翼上表面负压","D":"以上均不正确","answer":"C","exp":"机翼升力主要来自上表面吸力：气流加速流过翼型上表面，压力降到低于环境气压形成负压区，这部分吸力对总升力的贡献大于下表面正压的顶托作用，因此机翼上气动受力最大的是上表面负压；笼统说上表面压力或下表面压力都不准确。"},{"id":826,"type":"single","cat":"基础概念","stem":"关于对飞行器摇杆模式进行更改，下面描述正确的是（）。","A":"将遥控器开启，利用DJIGO的遥控器设置功能进行改手，必须接通飞行器电源","B":"将遥控器开启，利用DJIGO的遥控器设置功能进行改手，无需接通飞行器电源","C":"将遥控器开启，利用Assistant的遥控器设置功能进行改手，无需接通飞行器电源","D":"将遥控器开启，利用Assistant的遥控器设置功能进行改手，必须接通飞行器电源","answer":"B","exp":"用DJI GO的遥控器设置功能更改摇杆模式，只需开启遥控器并连接App即可完成，改手属于遥控器的参数设置，与飞控无关，因此无需接通飞行器电源；Assistant是地面调参软件，用途不同，接通飞行器电源并非改手的必要条件。"},{"id":827,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统速率陀螺是感知飞行器平台的传感器（）。","A":"姿态角度","B":"航向角","C":"角速度","D":"以上均不正确","answer":"C","exp":"速率陀螺感知的是飞行器绕机体三轴转动的角速度，飞控利用角速率信号进行阻尼增稳和姿态微分解算，故称速率陀螺；姿态角度需由陀螺与加速度计融合解算得到，航向角由磁罗盘和卫星导航提供，都不是速率陀螺直接测量的量。"},{"id":828,"type":"single","cat":"领航与任务规划","stem":"固定翼无人机航电系统由飞控计算机、导航传感器、（）、舵机/伺服机构组成，完成飞机控制系统的需要。","A":"机翼","B":"螺旋桨","C":"数据链机载终端","D":"地面站","answer":"C","exp":"固定翼无人机航电系统由飞控计算机、导航传感器、数据链机载终端和舵机/伺服机构组成：飞控解算指令，导航传感提供位置姿态，数传终端与地面站交换数据，舵机执行舵面偏转；机翼、螺旋桨是机体动力部件，地面站不属于机载航电。"},{"id":829,"type":"single","cat":"操纵与飞行技术","stem":"为了测算多旋翼无人机姿态偏斜角度，需要借助陀螺仪，以下有关陀螺仪表述正确的是（）。","A":"陀螺仪可以改变多旋翼无人机姿态","B":"陀螺仪可以测量多旋翼无人机加速度变化","C":"陀螺仪可以稳定多旋翼无人机姿态和角速度测算","D":"陀螺仪可以测定空气的密度","answer":"C","exp":"陀螺仪敏感角速度，飞控据此对多旋翼姿态实施稳定与阻尼控制，并配合姿态解算测算姿态偏斜角度；它只能感知转动而不能改变姿态，改变姿态要靠各电机转速差动，测量加速度变化是加速度计的职能，空气密度更与其无关。"},{"id":830,"type":"single","cat":"设备与维护","stem":"现有一块聚合物锂电池可能会长时间不使用，充放电至电量多少，电压多少储存合适？（）","A":"80%；4.7V","B":"40%至50%；3.8V","C":"20%；3.2V","D":"以上均不正确","answer":"B","exp":"聚合物锂电池长期存放应充放电至40%至50%电量（单节约3.8V）储存：满电存放加速电极老化、易鼓包，亏电存放可能过放损坏；4.7V远超单节满充电压4.2V，3.2V已接近放电截止电压，均不适合作为存储电压。"},{"id":831,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机复飞时，油门状态描述正确的是（）。","A":"保持小油门","B":"逐渐收至小车状态","C":"逐渐推至大车状态","D":"以上均不正确","answer":"C","exp":"复飞是中止着陆重新爬升的过程，需要尽快恢复飞行速度并获得爬升能力，因此油门应逐渐推至大车（最大）状态；保持小油门或收至小车会让速度继续损失、飞机持续下沉，无法脱离下滑状态，甚至危及安全。"},{"id":832,"type":"single","cat":"基础概念","stem":"无人机飞行人员在执行飞行任务时，应当随身携带（）。","A":"飞行记录本","B":"飞机适航证书","C":"驾驶员执照或合格证","D":"都不需要","answer":"C","exp":"无人机飞行人员执行飞行任务必须随身携带驾驶员执照或合格证，以备飞行管理机构和有关单位查验，这是对操控人员资质证明的基本要求；飞行记录本由维修环节填写保管，适航证书属于航空器的随机文件，都不是要求飞行人员随身携带的项目。"},{"id":833,"type":"single","cat":"基础概念","stem":"固定翼无人机结构组成不包括（）。","A":"机身","B":"机翼","C":"尾翼","D":"驾驶室","answer":"D","exp":"固定翼无人机结构由机身、机翼、尾翼以及起落装置、动力装置等组成，机上无人乘坐，不需要也不存在驾驶室（驾驶舱）；机身承载连接各部件，机翼产生升力，尾翼保证俯仰与方向安定性，驾驶室是载人飞机特有的结构。"},{"id":834,"type":"single","cat":"设备与维护","stem":"地面站，遥控器，飞机的通电顺序是（）。","A":"遥控器，飞机电，地面站","B":"飞机电，地面站，遥控器","C":"地面站，遥控器，飞机电","D":"以上均不正确","answer":"C","exp":"正确顺序是先开地面站，再开遥控器，最后给飞机上电：先建立地面站与遥控链路，飞控上电后即可搜索到稳定的控制信号，避免因链路未就绪而触发失控保护或接收干扰信号导致电机误转，也能防止上电瞬间意外伤人。"},{"id":835,"type":"single","cat":"基础概念","stem":"飞行前检查，下列哪项不是必须检查的项目（）。","A":"周围人员是否与无人机保持安全距离","B":"药箱是否有农药沉淀","C":"遥控器表面是否有污渍","D":"套筒是否旋紧或卡扣是否卡紧","answer":"C","exp":"飞行前检查针对直接影响安全的项目：人员保持安全距离、药箱有无农药沉淀（沉淀会堵塞喷洒系统）、套筒旋紧或卡扣卡紧都属于必查项；遥控器表面有无污渍只关乎外观清洁，不影响飞行安全，不是必须检查的项目。"},{"id":836,"type":"multi","cat":"基础概念","stem":"所谓运用中的电气设备系指（）的电气设备。","A":"全部带有电压","B":"一部分带有电压","C":"一经操作即带有电压","D":"在修试所进行检修","answer":"ABC","exp":"运用中的电气设备指全部带有电压、一部分带有电压以及一经操作即带有电压的设备：只要设备处于可能带电的状态，就必须按带电设备对待并落实安全措施；在修试所检修的设备已脱离运行系统，不再具备带电可能，不属于运用中的电气设备。"},{"id":837,"type":"multi","cat":"电力巡检","stem":"根据所用无人机巡检系统的不同，分为（）。","A":"大型无人直升机巡检作业","B":"中型无人直升机巡检作业","C":"小型无人直升机巡检作业","D":"固定翼无人机巡检作业","answer":"BCD","exp":"无人机巡检系统按所用机型分为中型无人直升机巡检作业、小型无人直升机巡检作业和固定翼无人机巡检作业三类，不同机型的载重能力、飞行性能与巡检方式不同，作业组织与安全要求也随之有别；该分类体系中不设大型无人直升机巡检作业这一类别。"},{"id":838,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，通信系统完成从控制站到无人机平台间的（）及其他数据信息的传输。","A":"控制信息","B":"任务载荷信息","C":"设备信息","D":"无人机状态信息","answer":"ABD","exp":"无人机通信系统承担控制站与无人机平台之间的双向数据传输：上行发送控制信息（操纵指令），下行回传无人机状态信息（位置、姿态、电源等）和任务载荷信息（如巡检图像、检测数据）；设备信息属于设备台账管理范畴，不是通信系统规定的传输内容。"},{"id":839,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，无人机平台需具备（）。","A":"足够的载重能力","B":"外形设计合理","C":"控制计算能力","D":"能完成特定的任务","answer":"ABD","exp":"无人机平台作为任务载体需具备足够的载重能力以挂载任务设备、合理的外形设计以保证气动效率与飞行稳定性、能完成特定的任务作为平台选型的最终目标；控制计算能力由机载飞控计算机实现，属于飞行控制系统的功能，不是对平台本体的要求。"},{"id":840,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统主要部件（如电机、（）等）更换或升级后，应进行检测，确保满足技术要求。","A":"飞控系统","B":"通讯链路","C":"任务设备","D":"操作系统","answer":"ABCD","exp":"电机、飞控系统、通讯链路、任务设备、操作系统等都是影响飞行安全与作业效果的主要部件，任何一件更换或升级后整机状态随之改变，必须重新进行检测，确认满足技术要求后才能继续执行巡检作业，防止部件变更引入隐性缺陷危及飞行安全。"},{"id":841,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，翻修是指通过对航空器或者航空器部件进行（）或者换件、重新组装和测试来恢复航空器或者航空器部件的使用寿命或者适航性状态。","A":"分解","B":"清洗","C":"检查","D":"必要的修理","answer":"ABCD","exp":"翻修是恢复航空器或部件使用寿命与适航状态的深层次维修，完整流程包括分解、清洗、检查、必要的修理或换件，随后重新组装并进行测试验证，各环节缺一不可；相比日常检查维护，翻修更深入彻底，这是界定维修深度的规范性定义。"},{"id":842,"type":"multi","cat":"飞行原理","stem":"无人直升机的基本结构一般包括：机身、主旋翼、尾桨、（）、（）、电动机或发动机和（）。","A":"操作系统","B":"传动系统","C":"遥控器","D":"起落架","answer":"ABD","exp":"无人直升机基本结构包括机身、主旋翼、尾桨、操作系统（操纵系统）、传动系统、起落架以及电动机或发动机：传动系统把动力传递给旋翼，操纵系统控制旋翼实现姿态与航向变化，起落架支撑停放与起降；遥控器属于地面操纵设备，不在机体结构之列。"},{"id":843,"type":"multi","cat":"设备与维护","stem":"地面站系统包括（）等硬件设备及地面测控车辆","A":"飞行控制软件","B":"飞行数据传输系统","C":"图像接收器","D":"飞行操控器","answer":"AD","exp":"地面站系统由飞行控制软件、飞行操控器等以及地面测控车辆构成：操控器供操作员直接发出飞行与任务指令，是地面站的核心硬件，飞行控制软件承担信息解算、显示与航线管理；数据传输系统和图像接收器属于数据链路的传输接收环节，不列入地面站系统硬件。"},{"id":844,"type":"single","cat":"设备与维护","stem":"X型四旋翼飞行器，其2号与3号电机搭配的螺旋桨分别是（）。","A":"CWCW","B":"CWCCW","C":"CCWCW","D":"CCWCCW","answer":"B","exp":"X型四旋翼的电机转向相邻相反、对角相同，2号与3号电机位置相邻，因此一个配正桨（CW顺时针）、一个配反桨（CCW逆时针），即CW与CCW搭配；相邻反转使反扭矩相互抵消，机身才能不自转，全同转向会破坏扭矩平衡。"},{"id":845,"type":"single","cat":"设备与维护","stem":"小型固定翼无人驾驶航空器机体部分主要包括：机身、（）、尾翼。","A":"发动机","B":"云端","C":"遥控器","D":"机翼","answer":"D","exp":"小型固定翼无人驾驶航空器机体部分由机身、机翼、尾翼构成，机翼是产生升力的主要气动部件，三者组成完整的机体气动布局；发动机属于动力装置，遥控器是地面操控设备，云端更与机体结构无关。"},{"id":846,"type":"single","cat":"设备与维护","stem":"多轴飞行器的飞控指的是（）。","A":"机载导航飞控系统","B":"机载遥控接收机","C":"机载任务系统","D":"以上均不正确","answer":"A","exp":"多轴飞行器的飞控指机载导航飞控系统，集成陀螺仪、加速度计、气压计、磁罗盘等传感器与解算计算机，完成姿态估计、增稳控制和导航；遥控接收机只接收并转交地面指令，任务系统承担作业载荷功能，均不能代替飞控。"},{"id":847,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机进入四转弯时（）。","A":"如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入早，应立即协调地减小坡度和转弯角速度","B":"如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入晚，应立即协调地增大坡度和转弯角速度","C":"如飞机接近跑道延长线较快，而转弯剩余角减小较慢时，表明进入晚，应立即协调地减小坡度和转弯角速度","D":"以上均不正确","answer":"B","exp":"四转弯中飞机接近跑道延长线较快而转弯剩余角减小较慢，说明转弯进入偏晚、坡度和转弯角速度不足，应立即协调地增大坡度和转弯角速度，加快消除剩余角，使飞机及时对正跑道延长线；减小坡度和角速度会进一步拖慢对正，方向正好相反。"},{"id":848,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，对用侧滑的方法修正侧风影响的正确描述是（）。","A":"判明偏流的方向及影响大小，适量向侧风反方向压杆形成坡度，并反扭舵抵制飞机转弯","B":"判明偏流的方向及影响大小，适量向侧风方向压杆形成坡度，并反扭舵抵制飞机转弯","C":"判明偏流的方向及影响大小，适量向侧风方向压杆形成坡度，并同向扭舵抵制飞机转弯","D":"以上均不正确","answer":"B","exp":"用侧滑法修正侧风：判明偏流方向及影响大小后，适量向侧风方向压杆形成坡度，利用升力的水平分量抵住侧风、阻止飞机被吹向下风侧，同时反扭舵抵消坡度引起的转弯，使航迹保持直线；压杆方向若弄反会加剧偏流漂移，扭舵也不应与压杆同向。"},{"id":849,"type":"single","cat":"基础概念","stem":"视距内运行指无人机驾驶员或无人机观测员与无人机保持直接目视视觉接触的操作方式，航空器处于驾驶员或观测员目视视距内半径（）米，相对高度低于120米的区域内。","A":"300","B":"500","C":"700","D":"1000","answer":"B","exp":"视距内运行要求驾驶员或观测员与无人机保持直接目视接触，航空器处于目视视距内半径500米、相对高度低于120米的区域内；超出即属超视距运行，需相应资质与条件，300米、700米、1000米都不符合规范定义。"},{"id":850,"type":"single","cat":"设备与维护","stem":"两块电池6S、5000mah的电池并联，用2C充电，充电的功率是多少？（）","A":"202W","B":"504w","C":"404W","D":"以上均不正确","answer":"B","exp":"两块6S 5000mAh电池并联容量10000mAh即10Ah，2C充电电流20A；6S锂电池满充电压25.2V（单节4.2V），按P=UI，充电功率约20×25.2=504W；按单块容量或标称电压算都会得出错误结果。"},{"id":851,"type":"single","cat":"设备与维护","stem":"（）通过调节四个电机的转速使四个旋翼间出现特定的转速差，从而实现飞行器的各种动作。","A":"定位系统","B":"动力系统","C":"电力系统","D":"飞控系统","answer":"D","exp":"飞控系统实时解算姿态误差并调节四个电机的转速，使四个旋翼之间形成特定的转速差，各旋翼升力与反扭矩随之改变，从而合成出俯仰、横滚、偏航和升降等各种动作；动力系统只按指令执行转速输出，定位系统、电力系统都不承担姿态控制解算。"},{"id":852,"type":"single","cat":"设备与维护","stem":"无刷电机的维护，以下不包括的是（）。","A":"长时间未使用，应定期通电","B":"避免进水","C":"轴承损坏及时更换","D":"注意避免轴承生锈","answer":"A","exp":"无刷电机没有碳刷磨损问题，其维护重点是避免进水受潮、轴承损坏及时更换、防止轴承生锈锈死；长时间未使用应定期通电并不属于无刷电机的维护项目，存放时保持干燥清洁即可，定期通电反而是多余操作。"},{"id":853,"type":"single","cat":"基础概念","stem":"地面保障分系统由地面保障设备和（）组成。","A":"地面接收单元","B":"地面显控单元","C":"数据接收链路","D":"备用设备","answer":"B","exp":"地面保障分系统由地面保障设备和地面显控单元组成：显控单元集中显示飞行状态、任务信息并下发操控指令，是地面人员掌握飞行情况、实施干预的直接界面；地面接收单元和数据接收链路属于测控信息传输部分，备用设备只是应急保障物资。"},{"id":854,"type":"single","cat":"领航与任务规划","stem":"无人机系统中的GPS模块为飞控提供了哪些信息？（）","A":"传感器、姿态与加速度","B":"位置、高度与地速","C":"经纬度、高度与空速","D":"以上均不正确","answer":"B","exp":"GPS模块向飞控提供位置、高度与地速：定位解算得到三维坐标和高度，速度解算给出相对地面的运动速度；姿态与加速度由IMU的陀螺和加速度计测量，空速需要空速管通过动压测量，GPS模块并不提供这些信息。"},{"id":855,"type":"single","cat":"飞行原理","stem":"无人机定速遥控飞行时放下襟翼，驾驶员需（）。","A":"增加油门以保持空速","B":"减小油门以保持空速","C":"针对此情况，无需做相关动作","D":"以上均不正确","answer":"A","exp":"放下襟翼后机翼升力系数增大，但型阻和诱导阻力也显著增加，定速飞行中若保持原油门，速度会因阻力增大而衰减，因此驾驶员需增加油门以维持原空速；收油门会使速度进一步损失，容易掉高度甚至失速，不做任何操作同样是错误的。"},{"id":856,"type":"single","cat":"基础概念","stem":"固定翼无人机的升降舵负责完成无人机的（）动作。","A":"横滚","B":"俯仰","C":"偏航","D":"以上均不正确","answer":"B","exp":"升降舵偏转改变水平尾翼的升力大小与方向，形成绕横轴的俯仰力矩，控制机头上仰或下俯，负责俯仰动作；横滚由左右副翼差动完成，偏航由方向舵完成，三个舵面各司其职，共同实现飞机的三轴操纵。"},{"id":857,"type":"single","cat":"基础概念","stem":"多轴旋翼飞行器通过改变（）控制飞行轨迹。","A":"总距杆","B":"尾桨","C":"转速","D":"以上均不正确","answer":"C","exp":"多轴旋翼飞行器没有总距杆和尾桨，所有操纵都通过改变各电机转速实现：同时增减转速改变总升力实现升降，差动转速使机体倾斜或偏航，升力的水平分量进而改变飞行轨迹；总距杆和尾桨是单旋翼直升机一类机型的操纵部件，多轴并不具备。"},{"id":858,"type":"single","cat":"操纵与飞行技术","stem":"多轴飞行器的操纵不包括（）。","A":"俯仰操纵","B":"航向操纵","C":"周期变距","D":"以上均不正确","answer":"C","exp":"多轴飞行器的操纵包括俯仰操纵、横滚操纵、航向（偏航）操纵和油门升降操纵，全部通过电机转速差动实现；周期变距是单旋翼直升机借助自动倾斜器周期改变桨叶桨距的操纵方式，多轴没有变距机构，自然不存在周期变距操纵。"},{"id":859,"type":"single","cat":"基础概念","stem":"由于加载的电子地图与实际操作时的地理位置信息有偏差，需要在使用前对地图进行（）。","A":"更新","B":"校准","C":"标注","D":"以上均不正确","answer":"B","exp":"电子地图加载的坐标与实际地理位置之间常存在系统性偏差，若不修正，规划的航线点会整体偏离真实位置，因此使用前需利用已知参考点对地图进行校准；更新只是更换地图版本，标注只是添加信息，都不能消除坐标系偏差。"},{"id":860,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机在预定高度由平飞转为下降时（）。","A":"注视地平仪，稍拉杆，收油门","B":"注视地平仪，稍拉杆，推油门","C":"注视地平仪，稍顶杆，收油门","D":"以上均不正确","answer":"C","exp":"由平飞转入下降需减小升力并降低推力：注视地平仪保持姿态基准，稍顶杆减小迎角使升力小于重力，飞机进入下降轨迹，同时收油门减小推力防止增速过快；拉杆会使飞机抬头转入爬升，与下降所需姿态正好相反。"},{"id":861,"type":"single","cat":"领航与任务规划","stem":"（）应具备的功能包括：标准飞行轨道生成功能，常规的飞行航线生成、管理功能。","A":"航线规划","B":"航迹规划","C":"任务规划","D":"以上均不正确","answer":"A","exp":"航线规划应具备标准飞行轨道生成功能，以及常规飞行航线的生成与管理功能，用于在预设区域内按既定航线组织飞行作业；航迹规划侧重对飞行轨迹的推演生成，任务规划是任务级的统筹安排，二者层级更高，不等同于这一功能定位。"},{"id":862,"type":"single","cat":"操纵与飞行技术","stem":"共轴式直升机的纵横向操纵多是何处得以实现的（）。","A":"下旋翼自动倾斜器的不动环","B":"下旋翼自动倾斜器的可动环","C":"上旋翼自动倾斜器的可动环","D":"以上均不正确","answer":"A","exp":"共轴式直升机上下两副旋翼反转布置，纵横向操纵多通过下旋翼自动倾斜器的不动环实现：操纵输入使不动环倾斜，周期改变下旋翼桨距，产生俯仰与横滚方向的操纵力；可动环随桨轴旋转负责传递周期变距，不是纵横向操纵的直接作用部位。"},{"id":863,"type":"single","cat":"基础概念","stem":"在高海拔地区，多轴飞行器出现较难离地时，最有效的应对措施是（）。","A":"减重","B":"更换大桨","C":"更换大容量电池","D":"以上均不正确","answer":"A","exp":"高海拔地区空气密度小，旋翼在同一转速下产生的升力下降，导致难以离地，最有效的措施是减重：直接降低所需升力，让现有动力有富余产生离地升力；更换大桨需要重新匹配动力与电流且改善有限，换大容量电池反而增加起飞重量，使问题加重。"},{"id":864,"type":"single","cat":"基础概念","stem":"民用无人机调整中的基本感度是（）。","A":"飞控PID调节中的比例项P的系数","B":"飞控PID调节中的I积分系数","C":"飞控PID调节中的D微分系数","D":"以上均不正确","answer":"A","exp":"民用无人机的基本感度对应飞控PID调节中的比例项P系数：P值越大，姿态偏差的纠正响应越快越强，过大则容易引起震荡；积分项I负责消除稳态误差，微分项D抑制超调震荡，三者分工不同，基本感度特指比例项。"},{"id":865,"type":"single","cat":"设备与维护","stem":"遥控器菜单中SUBTRIM代表什么意思？","A":"中立微调","B":"失控保护","C":"通道反向","D":"以上均不正确","answer":"A","exp":"SUBTRIM是中立微调，用于摇杆回中时对各通道输出做小量偏置，使舵面或电机获得准确的中立状态，是遥控器的基础设置项；失控保护对应FAILSAFE，通道反向对应REVERSE，功能含义完全不同，不能混为一谈。"},{"id":866,"type":"single","cat":"设备与维护","stem":"无人机装配报告控制系统复检中对飞行控制系统（自驾仪）信号线的检查包括电子调速器（电调）信号线、（）、接收机信号线、无线数据传输（无线数传）系统信号线、电流计信号线等。","A":"电机相线","B":"GPS天线","C":"全球导航卫星系统（GNSS）信号线","D":"电池平衡充排线","answer":"C","exp":"自驾仪信号线检查涵盖电调信号线、GNSS信号线、接收机信号线、无线数传信号线、电流计信号线等，保证各传感器与执行机构的信息通道连接可靠；电机相线属于动力主回路，电池平衡充排线属于充电设备，均不在飞控信号线检查范围内。"},{"id":867,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，应充分考虑无人机巡检系统在飞行过程中出现（）等故障的可能性，合理设置安全策略。","A":"偏离航线","B":"导航卫星颗数无法定位","C":"通讯链路中断","D":"动力失效","answer":"ABCD","exp":"无人机巡检系统飞行过程中可能出现偏离航线、导航卫星颗数不足无法定位、通讯链路中断、动力失效等故障，安全工作规程要求制定方案时充分考虑这些故障的可能性，预设悬停等待、自动返航、就近降落等安全策略，使任何故障发生时都有应对预案。"},{"id":868,"type":"multi","cat":"操纵与飞行技术","stem":"无人机控制站主要是由（）等组成，可完成对无人机机载任务载荷等的操纵控制。","A":"飞行操纵","B":"任务载荷控制","C":"数据链路控制","D":"通信指挥","answer":"ABCD","exp":"无人机控制站由飞行操纵、任务载荷控制、数据链路控制和通信指挥等部分组成：飞行操纵负责飞行状态与轨迹控制，任务载荷控制操纵机载相机等设备完成作业，数据链路控制管理上下行链路，通信指挥承担任务协调，各部分共同完成对无人机及其载荷的操纵控制。"},{"id":869,"type":"multi","cat":"电力巡检","stem":"无人直升机进行输电线路巡检的主要巡检内容中对基础可见光检测内容为（）。","A":"塌方","B":"护坡受损","C":"严重污秽","D":"回填土沉降","answer":"ABD","exp":"杆塔基础可见光检测围绕地基稳定和水土状态展开，内容包括塌方、护坡受损、回填土沉降等地质灾害类缺陷，反映基础及周边土体的健康状况；严重污秽属于绝缘子表面状态检测项目，用于污秽等级评定，不属于基础检测内容。"},{"id":870,"type":"multi","cat":"电力巡检","stem":"程控手是利用地面控制站以（）控制无人机巡检系统的作业人员。","A":"增稳","B":"手动","C":"监控","D":"全自主模式","answer":"AD","exp":"程控手是利用地面控制站以增稳和全自主模式控制无人机巡检系统的作业人员：增稳模式由飞控自动稳定姿态减轻操作负担，全自主模式按预设程序自动执行航线作业，两种模式都以飞控自动控制为主；手动模式由飞手直接操纵，监控只是岗位职责而非控制模式。"},{"id":871,"type":"single","cat":"法规与空域","stem":"我国民用无人驾驶航空器实名登记的主管部门是（）。","A":"国家市场监督管理总局","B":"国务院公安部门","C":"民用航空管理部门","D":"国家空中交通管理领导机构","answer":"C","exp":"民用无人驾驶航空器实名登记由民用航空管理部门主管，登记信息纳入统一的识别管理体系；市场监管部门管产品准入，公安部门管治安与违规飞行查处，空中交通管理领导机构统筹空域管理，都不承担实名登记职能。"},{"id":872,"type":"single","cat":"基础概念","stem":"微型无人驾驶航空器是指（）。","A":"空机重量小于0.25千克，最大飞行真高不超过50米，最大平飞速度不超过50千米/小时","B":"空机重量小于4千克，最大飞行真高不超过120米","C":"最大起飞重量不超过25千克","D":"最大起飞重量不超过150千克","answer":"A","exp":"微型无人驾驶航空器指空机重量小于0.25千克、最大飞行真高不超过50米、最大平飞速度不超过50千米/小时的机型；0.25千克是微型与轻型的分界线，4千克、25千克、150千克分别是轻型、小型、中大型机的界限值。"},{"id":873,"type":"single","cat":"法规与空域","stem":"在适飞空域内飞行，下列哪种类型无人机无需提出飞行活动申请？（）","A":"小型、中型无人机","B":"微型、轻型无人机","C":"全部类型无人机","D":"中型、大型无人机","answer":"B","exp":"微型、轻型无人驾驶航空器在适飞空域内飞行无需提出飞行活动申请，属于便利化管理类别，满足条件即可直接飞行；其余类型受到的运行限制更多，飞行需按规定履行申请批准手续，管制空域内任何无人机都不能免于申请。"},{"id":874,"type":"single","cat":"法规与空域","stem":"无人机在管制空域飞行，应当（）。","A":"提前向空中交通管理机构提出飞行活动申请","B":"只需完成实名登记即可飞行","C":"起飞后向当地派出所报告","D":"只要避开民航客机即可飞行","answer":"A","exp":"在管制空域飞行必须提前向空中交通管理机构提出飞行活动申请，经批准后方可按批准的时段、高度和区域实施，这是保障军民航飞行安全、防止危险接近的核心制度；仅完成实名登记、起飞后报告或只避开民航客机，都不能替代事前审批要求。"},{"id":875,"type":"single","cat":"法规与空域","stem":"关于无人机飞行高度，轻型无人驾驶航空器在适飞空域内的最大真高为（）。","A":"120米","B":"150米","C":"300米","D":"500米","answer":"A","exp":"轻型无人驾驶航空器在适飞空域内的最大飞行真高为120米，这一高度线将无人机活动限制在有人机低空飞行活动之下，防止同高度冲突；150米、300米、500米都超出允许高度，需另行申请批准才能进入相应空域飞行。"},{"id":876,"type":"single","cat":"法规与空域","stem":"操控轻型民用无人驾驶航空器在适飞空域内飞行，下列做法正确的是（）。","A":"无需取得操控员执照，但需熟悉安全操控要求","B":"必须取得民用无人机驾驶员执照","C":"必须持有机长执照并完成签注","D":"只需购买保险，无须任何资质","answer":"A","exp":"轻型民用无人驾驶航空器在适飞空域内飞行无需取得操控员执照，但操控者必须熟悉安全操控要求并遵守飞行规则，这是法规对小微无人机的宽松安排；强制取得执照针对小型及以上机型或特定情形，只买保险而无操控能力不满足安全要求。"},{"id":877,"type":"single","cat":"法规与空域","stem":"民用无人驾驶航空器操控员执照由哪个机构颁发？（）","A":"中国民用航空局","B":"公安部","C":"应急管理部","D":"工业和信息化部","answer":"A","exp":"民用无人驾驶航空器操控员执照由中国民用航空局统一颁发管理，执照标准、考试与签注均纳入民航管理体系；公安部负责治安管理和违规飞行查处，应急管理部承担应急救援职责，工信部管理无线电频率与产业发展，均不负责执照颁发。"},{"id":878,"type":"single","cat":"法规与空域","stem":"国内民航局无人机执照中，多旋翼视距内驾驶员理论考试合格分数线为（）。","A":"70分","B":"80分","C":"90分","D":"60分","answer":"A","exp":"民航局多旋翼视距内驾驶员理论考试满分100分，合格分数线为70分；超视距驾驶员（机长）级别的理论合格线更高，为80分，两个级别分数线不同，备考时须按申报级别掌握对应的合格标准。"},{"id":879,"type":"single","cat":"基础概念","stem":"视距内驾驶员（VLOS）飞行的基本限制是（）。","A":"飞行半径500米以内、真高120米以内，且全程保持视距内","B":"飞行半径5千米以内","C":"真高300米以内","D":"只要天气良好可任意飞行","answer":"A","exp":"视距内驾驶员的基本飞行限制是飞行半径500米以内、真高120米以内，并且全程保持目视接触，超出任一限制即属于超视距飞行，需要超视距驾驶员资质；5千米和300米真高都远超允许范围，天气良好也不能突破范围与目视要求。"},{"id":880,"type":"single","cat":"基础概念","stem":"无人机驾驶员饮酒后是否可以操控无人机飞行？（）","A":"可以，只要飞行技术熟练","B":"可以，但只能白天飞行","C":"不可以，酒后操控存在重大安全风险","D":"司法机关统一规定，视酒量而定","answer":"C","exp":"饮酒后不得操控无人机飞行：酒精降低反应速度、判断能力和动作协调性，而无人机操控是需要持续精准判断与手眼协调的安全岗位，性质与机动车驾驶相同；技术熟练不能弥补机能受损，任何酒量和任何时段都不允许酒后飞行。"},{"id":881,"type":"single","cat":"基础概念","stem":"无人机失联后，下列哪种行为最合理？（）","A":"原地等待，保持遥控器信号尝试重新连接，并观察飞行轨迹","B":"立即关闭遥控器","C":"不停地按遥控器油门摇杆","D":"立即驾车穿梭去寻找，不顾自身安全","answer":"A","exp":"无人机失联后最合理的是原地等待，保持遥控信号尝试重新连接，同时观察飞行轨迹，多数飞控失联后自动悬停或按预设返航；立即关闭遥控器等于放弃恢复链路的机会，乱打油门杆无济于事，不顾自身安全驾车乱找更不可取。"},{"id":882,"type":"single","cat":"基础概念","stem":"多旋翼无人机实现向左飞行，通常需要（）。","A":"机体向左倾斜，升力方向向左偏转提供水平分量","B":"只改变右侧电机转速","C":"改变桨叶总距","D":"降低全部电机转速","answer":"A","exp":"多旋翼向左飞行的条件是机体向左倾斜：合升力偏向左侧，水平分量推动飞行器左移，垂直分量继续平衡重力；未形成倾斜就没有水平分力，改变桨叶总距只影响升降，全部减速则直接下沉，都无法实现向左移动。"},{"id":883,"type":"single","cat":"基础概念","stem":"多旋翼无人机的偏航（机头转向）主要依靠（）实现。","A":"旋翼旋转产生反扭矩的差动变化","B":"尾桨推力","C":"方向舵偏转","D":"重心移动","answer":"A","exp":"多旋翼的偏航依靠旋翼反扭矩的差动变化实现：顺时针组与逆时针组电机的转速差改变后，两组反扭矩失去平衡，机身在反扭矩作用下绕竖轴转动完成机头转向；多旋翼没有尾桨和方向舵，移动重心也无法控制转向。"},{"id":884,"type":"single","cat":"领航与任务规划","stem":"无人机飞行过程中，若GPS信号丢失，多旋翼无人机通常会（）。","A":"自动进入姿态模式，可能发生漂移","B":"完全不受影响","C":"自动增加飞行速度","D":"立即自毁","answer":"A","exp":"GPS信号丢失后多旋翼无法获得可靠的位置定位，飞控自动降级进入姿态模式，仅依靠IMU保持姿态平稳，位置闭环失效，在风或不平衡扰动下会发生漂移；该过程不会完全不受影响，也不会自动加速或自毁，此时应及时手动操控返航降落。"},{"id":885,"type":"single","cat":"设备与维护","stem":"无人机气压计的主要作用是（）。","A":"测量相对高度","B":"测量地面速度","C":"测量水平位置","D":"测量姿态角","answer":"A","exp":"气压计感受大气静压随高度的变化，据此换算出相对高度，为飞控提供定高所需的高度信息；地速和水平位置由卫星导航提供，姿态角由IMU解算得到，都不是气压计的功能，它对气流扰动敏感，通常与导航高度信息融合使用。"},{"id":886,"type":"single","cat":"基础概念","stem":"无人机磁罗盘（指南针）受干扰后，可能导致（）。","A":"航向数据异常，无人机无法准确按预定航向飞行","B":"电池电量消耗变慢","C":"图传信号增强","D":"桨叶转速提高","answer":"A","exp":"磁罗盘（指南针）受铁磁物体、强电流或磁场干扰后航向基准失真，飞控依据错误航向解算，导致无法准确按预定航向飞行，甚至出现绕圈、姿态异常等现象；它只影响航向信息，与电池电量消耗、图传信号强度和桨叶转速没有关系。"},{"id":887,"type":"single","cat":"设备与维护","stem":"电动无人机动力电池常用类型是（）。","A":"锂聚合物电池","B":"铅酸蓄电池","C":"镍镉电池","D":"锌锰干电池","answer":"A","exp":"电动无人机动力电池主流采用锂聚合物电池：能量密度高、可大电流放电、重量相对较轻，满足航空模型级的动力需求；铅酸和镍镉电池能量密度过低、过于笨重，锌锰干电池无法承受大电流放电，均不适合作为航模动力电源。"},{"id":888,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的充电安全要求中，下列说法正确的是（）。","A":"必须使用专用平衡充电器，充电时人员在场看护","B":"可随意使用大功率充电器快充","C":"电池鼓包后仍可继续使用","D":"可在无人看管时通宵充电","answer":"A","exp":"锂聚合物电池充电必须使用专用平衡充电器，保证各串单体电压均衡，充电过程中人员要在场看护，随时处置鼓包、发热、冒烟等异常；随意使用大功率充电器快充、鼓包后继续使用、无人看管通宵充电都是引发火灾的主要隐患，严格禁止。"},{"id":889,"type":"single","cat":"设备与维护","stem":"一块5000mAh、20C的锂电池，其理论最大持续放电电流为（）。","A":"100A","B":"50A","C":"200A","D":"25A","answer":"A","exp":"锂电池最大持续放电电流等于容量乘以放电倍率：5000mAh×20C=100000mA即100A；50A、200A、25A分别是10C、40C、5C的换算结果，均属倍率错误，实际使用还应留出安全余量，不能顶格满倍率放电。"},{"id":890,"type":"single","cat":"操纵与飞行技术","stem":"无人机螺旋桨安装错误（如正反桨装反），起飞时会（）。","A":"拉力方向异常，机身剧烈抖动甚至无法稳定起飞","B":"飞行速度大幅提升","C":"对飞行无影响","D":"电池发热但飞行正常","answer":"A","exp":"正反桨装反后各旋翼拉力方向与反扭矩关系被打乱，升力矢量无法按设计合成，飞控纠偏输出与实际响应相反，起飞时机身剧烈抖动甚至无法稳定离地；装反不会提升速度也绝非无影响，必须按对角同向、相邻反转的原则安装。"},{"id":891,"type":"single","cat":"设备与维护","stem":"多旋翼无人机起飞前校准IMU和磁罗盘的主要目的是（）。","A":"保证飞控姿态解算和航向数据准确","B":"提高图传清晰度","C":"延长电池续航","D":"增大遥控距离","answer":"A","exp":"起飞前校准IMU和磁罗盘是为了消除传感器零偏和磁偏差，保证飞控的姿态解算准确、航向基准可靠，飞机才能稳定悬停并按计划航向飞行；校准与图传清晰度、电池续航、遥控距离都没有关系，那些性能由链路和动力设备决定。"},{"id":892,"type":"single","cat":"基础概念","stem":"在标准大气条件下，海平面气温为（）。","A":"15℃","B":"20℃","C":"25℃","D":"0℃","answer":"A","exp":"国际标准大气规定海平面气温为15℃，同时气压1013.25百帕，作为航空器性能计算、高度表标定和飞行仪表校准的统一基准；20℃、25℃、0℃都不是标准值，牢记该基准是气象与性能计算的基础。"},{"id":893,"type":"single","cat":"航空气象","stem":"对流层中，气温随高度增加而（）。","A":"降低","B":"升高","C":"不变","D":"先升高后降低","answer":"A","exp":"对流层的热量主要来自地面的长波辐射，越靠近地面气温越高，因此气温随高度增加而降低，平均每上升100米约降低0.65℃；逆温层只是局部的特殊情况，整体递减规律决定了云和降水等天气的垂直发展特征。"},{"id":894,"type":"single","cat":"基础概念","stem":"气温升高时，无人机的飞行性能将（）。","A":"下降，空气密度减小使升力降低、发动机功率降低","B":"提升，空气变稀薄阻力变小","C":"不受影响","D":"只影响航程不影响升力","answer":"A","exp":"气温升高时空气密度减小，旋翼和机翼单位时间获得的空气质量减少，升力随之下降，发动机进气量减少也导致功率降低，起飞距离变长、载重能力下降，飞行性能整体降低；阻力虽随密度减小而变小，但不足以弥补升力和功率的损失。"},{"id":895,"type":"single","cat":"操纵与飞行技术","stem":"某多旋翼无人机从真高120米处以5米/秒的速度匀速下降至20米处，所需时间约为（）。","A":"20秒","B":"24秒","C":"15秒","D":"30秒","answer":"A","exp":"匀速下降所需时间等于高度差除以下降率：从120米降到20米，高度差为100米，按5米/秒计算，100÷5=20秒；若直接用120米计算会得出24秒，错在未扣除终点高度，起点与终点高度之差才是有效下降距离。"},{"id":896,"type":"single","cat":"基础概念","stem":"无人机在大风天气飞行时，下列做法正确的是（）。","A":"顺风航行时注意地速增大导致返航电量不足","B":"逆风更适合长航时飞行","C":"大风对多旋翼没有影响","D":"风越大越省电","answer":"A","exp":"大风天气顺风飞行时地速增大、飞得快，但返程将转为逆风，空速不变时地速减小、飞行时间拉长、耗电增多，必须提前预留返航电量，防止归途电量不足无法返回；逆风并不省电省时，大风对多旋翼影响显著，风越大越耗电越危险。"},{"id":897,"type":"single","cat":"航空气象","stem":"遇有低能见度天气，下列哪种操作符合安全要求？（）","A":"取消飞行任务，待能见度改善后再执行","B":"降低高度强行目视飞行","C":"依赖图传信号冒险飞行","D":"申请更高高度飞行","answer":"A","exp":"低能见度下目视观察与避让能力大幅下降，图传画面视野窄、有延迟且缺乏周边态势感知，降低高度强行目视飞行或依赖图传冒险飞行都极易撞击障碍物；符合安全要求的做法是取消飞行任务，待能见度改善后再执行，申请更高高度只会增大风险。"},{"id":898,"type":"single","cat":"飞行原理","stem":"无人机机翼产生升力的根本原因是（）。","A":"气流流过机翼上下表面产生压力差","B":"发动机推力直接托举","C":"螺旋桨滑流吹起机翼","D":"机身浮力作用","answer":"A","exp":"机翼升力的根本原因是气流流过机翼上下表面时产生压力差：上表面流管收窄流速快、压力低，下表面流速慢、压力高，压差沿翼展合成为升力；发动机推力是前进动力，螺旋桨滑流和机身浮力都不构成升力来源。"},{"id":899,"type":"single","cat":"飞行原理","stem":"当机翼迎角超过临界迎角时，飞机将出现（）。","A":"失速，升力急剧下降","B":"升力线性增大","C":"阻力迅速减小","D":"速度自动增加","answer":"A","exp":"迎角超过临界迎角后，机翼上表面附面层大面积分离，升力系数不再增大反而急剧下降，阻力迅速增大，飞机进入失速状态而下坠；失速由迎角决定，与速度大小无直接关系，恢复失速要推杆减小迎角，升力线性增大、阻力减小都与失速特性相反。"},{"id":900,"type":"single","cat":"飞行原理","stem":"固定翼无人机在平飞时，升力与重力、推力与阻力的关系是（）。","A":"升力等于重力，推力等于阻力","B":"升力大于重力，推力大于阻力","C":"升力等于重力，推力大于阻力","D":"升力小于重力，推力等于阻力","answer":"A","exp":"平飞是匀速直线运动，作用在飞机上的力必须平衡：升力与重力相等保持高度不变，推力与阻力相等保持速度不变，合力为零飞行状态才能维持；升力大于重力会爬升，推力大于阻力会加速，都不是平飞状态。"},{"id":901,"type":"single","cat":"设备与维护","stem":"飞机重心位置过于靠前会导致（）。","A":"飞机配平阻力增大，操纵性变差","B":"飞机更容易抬头","C":"飞机航向不稳定","D":"飞机失速速度降低","answer":"A","exp":"重心过于靠前时，平尾需要产生更大的向下载荷才能配平，配平阻力增大，同时升降舵上仰操纵余量减小、效能变差，操纵性变差，着陆拉平也变得困难；重心靠前不会使飞机更容易抬头，失速速度也因配平下载荷增大而略有升高而非降低。"},{"id":902,"type":"single","cat":"基础概念","stem":"地面效应会使固定翼无人机在低空飞行时（）。","A":"诱导阻力减小，升力增大，感觉漂浮","B":"升力减小，产生下沉","C":"阻力急剧增大","D":"发动机功率自动升高","answer":"A","exp":"地面效应是贴近地面飞行时地面阻碍下洗气流和翼尖绕流，使下洗角减小、诱导阻力减小、有效升力增大的现象，飞机在低空会感觉漂浮、拉平阶段容易飘远；它是气动力的变化，不改变发动机功率，升力减小下沉恰是脱离地效后的表现。"},{"id":903,"type":"single","cat":"设备与维护","stem":"无人机飞行时发生机翼结冰，主要危害是（）。","A":"翼型改变、升力下降、阻力增大，严重时失速","B":"机体重量减轻","C":"燃油消耗减少","D":"对飞行安全无影响","answer":"A","exp":"机翼结冰改变翼型外形，破坏原有光顺的气动表面：升力系数下降、临界迎角减小、阻力增大，严重时提前失速危及飞行安全；结冰还会增加机体重量而非减轻，与燃油消耗无关，是低温潮湿天气飞行必须防范的主要危害。"},{"id":904,"type":"single","cat":"基础概念","stem":"任务载荷为可见光相机时，影响航拍照片清晰度的主要因素是（）。","A":"拍摄时的快门速度是否足以凝固飞机振动与运动","B":"遥控器天线朝向","C":"起落架形式","D":"桨叶颜色","answer":"A","exp":"可见光航拍照片清晰度的关键是拍摄瞬间快门速度能否凝固机体振动与飞行运动：快门过慢时振动和位移在曝光期内累积成影像模糊，镜头分辨率再高也无法弥补；天线朝向影响图传距离，起落架形式和桨叶颜色与成像质量无关。"},{"id":905,"type":"single","cat":"航空气象","stem":"无人机云台的主要功能是（）。","A":"隔离机体振动与姿态变化，保持相机稳定","B":"增大无人机推力","C":"修改飞行控制参数","D":"增加续航时间","answer":"A","exp":"云台的核心功能是隔离机体振动与姿态变化：通过三轴电机实时反向补偿俯仰、横滚、偏航的姿态波动，保持相机在惯性空间中姿态稳定，从而获得平稳清晰的画面；它不产生推力、不修改飞控参数，也不增加续航时间。"},{"id":906,"type":"single","cat":"基础概念","stem":"植保无人机作业中，造成药液漂移的因素不包括（）。","A":"药箱容量","B":"风力大小","C":"飞行高度","D":"雾滴粒径","answer":"A","exp":"药液漂移由作业环境与喷雾参数共同决定：风力大小决定雾滴被吹移的距离，飞行高度越高雾滴沉降路程越长，雾滴粒径越细越容易随风飘散；药箱容量只决定单次作业的装载量，与雾滴飘移过程无关。"},{"id":907,"type":"single","cat":"领航与任务规划","stem":"无人机测绘作业中，航线设计应重点考虑（）。","A":"航向与旁向重叠率、地面分辨率及地形起伏","B":"遥控器握持姿势","C":"桨叶数量","D":"电池品牌","answer":"A","exp":"测绘航线设计围绕成像质量与覆盖完整性展开：航向与旁向重叠率保证相邻影像可拼接建模，地面分辨率决定成图精度，地形起伏影响相对航高与实际重叠度，据此确定航高与航线间距；握持姿势、桨叶数量、电池品牌与任务规划无关。"},{"id":908,"type":"single","cat":"电力巡检","stem":"无人机在电力巡检中贴近铁塔飞行时，应特别注意（）。","A":"强电磁环境可能导致磁罗盘和飞控异常，保持安全距离","B":"图传信号会增强","C":"机翼产生额外升力","D":"没有任何风险","answer":"A","exp":"高压铁塔和输电线路周围存在强电场与磁场，会使磁罗盘读数失真、指南针校准失效，进而导致飞控定点与航向控制异常，贴近飞行须保持安全距离并提前校准罗盘。图传强弱与铁塔无关，无升力增益，风险客观存在。"},{"id":909,"type":"single","cat":"领航与任务规划","stem":"无人机紧急返航前，应当重点确认（）。","A":"返航点已刷新且卫星定位正常，飞行高度高于航线障碍物","B":"遥控器电池满电即可","C":"相机电量","D":"云台角度","answer":"A","exp":"返航依赖卫星定位与预设返航点：执行前应确认卫星定位良好、返航点已刷新为当前位置或起飞点，并把返航高度设定得高于航线上最高障碍物，防止返航途中撞障。遥控器电量只是条件之一，相机与云台参数与返航安全无直接关系。"},{"id":910,"type":"single","cat":"基础概念","stem":"无人机在人群上方飞行时，下列做法正确的是（）。","A":"禁止在人群上方飞行，防止失控坠落伤人","B":"可以飞行，只要高度超过50米","C":"可以飞行，只要速度快","D":"可以飞行，只要操作者技术熟练","answer":"A","exp":"人群上方是失控后果最严重的区域，法规明确禁止未经批准在其上空飞行，一旦动力失效或链路中断坠落极易造成人员伤亡；高度、速度和操作熟练度都不能弥补失控风险，必须把人群排除在飞行区域之外。"},{"id":911,"type":"single","cat":"基础概念","stem":"无人机降落后，正确的断电顺序是（）。","A":"先关闭遥控器电源，再断开飞行器电源","B":"先断开飞行器电源，再关闭遥控器电源","C":"两者不分先后","D":"长按遥控器油门即可","answer":"B","exp":"落地后应先给飞行器断电或锁定电机，再关闭遥控器。若先关遥控器，飞行器会因瞬间失去控制信号触发失控保护，可能自动重启电机甚至执行返航，造成二次伤害；开机顺序则相反，先开遥控器再接通飞行器。"},{"id":912,"type":"single","cat":"设备与维护","stem":"无人机机臂折叠机构的主要作用是（）。","A":"便于运输携带并减小收纳体积","B":"延长飞行时间","C":"增大摄像头视角","D":"提高飞行速度","answer":"A","exp":"折叠机构属于结构便携化设计，把机臂折拢后整机收纳体积大幅缩小，便于携带运输与快速展开布置；它不改变动力输出与气动外形，与续航、飞行速度、相机视角没有关系。"},{"id":913,"type":"single","cat":"设备与维护","stem":"无刷电机相比有刷电机的优点是（）。","A":"效率高、寿命长、维护少","B":"启动扭矩更小","C":"需要定期更换碳刷","D":"只能用于固定翼","answer":"A","exp":"无刷电机用电换向取代碳刷与换向器，消除了机械摩擦损耗，因此效率更高、寿命更长，日常几乎免维护；启动扭矩也并不小。需要定期更换碳刷的是有刷电机，它才是磨损件所在，这是两者的本质差别。"},{"id":914,"type":"single","cat":"基础概念","stem":"无人机电子调速器（ESC）的作用是（）。","A":"将飞控信号转换为电机转速控制","B":"为遥控器充电","C":"存储拍摄照片","D":"放大GPS信号","answer":"A","exp":"电子调速器接收飞控输出的控制信号，把直流电逆变为频率、幅值可控的三相交流电驱动无刷电机，实现转速调节，是动力系统的执行环节。充电、存照片、放大GPS信号分别属于充电器、存储与射频部分的功能。"},{"id":915,"type":"single","cat":"设备与维护","stem":"无人机图传系统的作用是（）。","A":"将机载相机画面实时传输回地面端","B":"传输遥控指令","C":"传输电池电量","D":"控制螺旋桨转速","answer":"A","exp":"图传是下行链路，把机载相机拍摄的画面实时回传到地面显示设备，供飞手取景构图和远距离监视；遥控指令走的是上行遥控链路，电量等信息由数传或屏显呈现，螺旋桨转速由电调控制，均与图传无关。"},{"id":916,"type":"single","cat":"操纵与飞行技术","stem":"无人机遥控器摇杆默认模式中，美国手（Mode2）的油门摇杆位于（）。","A":"左侧摇杆上下","B":"右侧摇杆上下","C":"左侧摇杆左右","D":"右侧摇杆左右","answer":"A","exp":"美国手Mode2规定左手摇杆负责油门（上下）和偏航（左右），右手负责俯仰与横滚。油门行程不打自中，所以固定在左杆上下方向；右侧上下是俯仰、左右是横滚，切勿与日本手等其他布局混淆。"},{"id":917,"type":"single","cat":"领航与任务规划","stem":"无人机上的GPS模块主要提供（）。","A":"经纬度与高度位置信息","B":"姿态角信息","C":"电机转速","D":"云台角度","answer":"A","exp":"GPS模块接收卫星信号解算出经纬度和高度，为无人机提供位置基准，支撑定点悬停、航线飞行与返航定位。姿态角由陀螺仪和加速度计解算，电机转速由电调感知，云台角度由自身编码器反馈，均不来自GPS。"},{"id":918,"type":"single","cat":"基础概念","stem":"关于无人机飞行前检查，下列说法错误的是（）。","A":"可不检查螺旋桨是否裂纹","B":"应检查电池电量与电压","C":"应检查固定螺丝与机臂","D":"应确认遥控器电量","answer":"A","exp":"螺旋桨出现裂纹、缺口会破坏动平衡甚至空中解体，起飞前必须逐片检查，绝不允许省略；电池电压电量、机臂与固定螺丝、遥控器电量都属于飞行前例行检查项目，说法均正确。"},{"id":919,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，除需遵守一般规定外，还应（）。","A":"开启导航灯并确保夜航能力，必要时报备","B":"关闭所有灯光以免暴露","C":"必须摘除云台","D":"禁止使用任何传感器","answer":"A","exp":"夜间飞行必须开启导航灯与位置灯保证可视性，飞行器及飞手须具备夜航能力，并按规定申报或报备后实施。关闭灯光反而违反安全要求；夜航与摘除云台、禁用传感器无关，传感器在暗环境中作用尤其重要。"},{"id":920,"type":"single","cat":"基础概念","stem":"无人机失控保护（Failsafe）设置中，当遥控信号丢失时最安全的默认动作是（）。","A":"自动返航或悬停，并按设定策略处理","B":"继续直线高速飞行","C":"立即解锁电机","D":"随机转向","answer":"A","exp":"失控保护的目的是链路丢失后保证可控与安全：默认策略是悬停等待信号恢复或自动返航至预设返航点，具体按设定策略执行。继续直线飞行、解锁电机或随机转向都会让飞行器不可控地远离甚至坠毁。"},{"id":921,"type":"single","cat":"设备与维护","stem":"多旋翼无人机飞行中若一个电机停转，通常会造成（）。","A":"机身剧烈偏航翻转，难以继续安全飞行","B":"剩余电机功率自动增大一倍，飞行不受影响","C":"无人机自动降落","D":"只影响续航不影响姿态","answer":"A","exp":"四轴布局动力冗余最小，任一电机停转后剩余桨的反扭矩立即失衡，机身会剧烈偏航、姿态翻转，一般无法继续安全飞行，只能依靠应急策略迫降。剩余电机不会倍增功率弥补，姿态与续航都受影响。"},{"id":922,"type":"single","cat":"设备与维护","stem":"选购无人机桨叶时，同一架多旋翼应使用（）。","A":"同一规格、动平衡良好的配套桨叶","B":"任意品牌任意尺寸桨叶","C":"新旧桨叶混合使用","D":"尽可能大的桨叶","answer":"A","exp":"桨叶的尺寸、螺距、材质必须与机架和电机匹配，同一架多旋翼应整套使用同规格、动平衡良好的配套桨，混用不同品牌尺寸或新旧桨会造成拉力不均、振动加剧甚至共振解体；盲目加大桨径还会过载电调。"},{"id":923,"type":"single","cat":"航空气象","stem":"无人机固定翼起飞时，逆风起飞的主要目的是（）。","A":"增大初始空速，缩短滑跑距离并提高升力","B":"缩短着陆滑跑距离","C":"减小发动机功率","D":"降低失速速度","answer":"A","exp":"逆风起飞时相对空速等于地速加风速，同样的滑跑距离就能获得更大升力，因此滑跑更短、更容易安全离地；失速速度只取决于载荷与构型，不随风改变，发动机功率也无需减小。"},{"id":924,"type":"single","cat":"设备与维护","stem":"无人机降落后发现电池鼓包，正确的处理是（）。","A":"停止使用并妥善回收，不可继续充放电","B":"继续用完剩余电量","C":"用针扎破放气后继续使用","D":"冷藏后继续使用","answer":"A","exp":"电池鼓包说明内部已发生产气与结构损伤，继续充放电有起火风险，正确做法是停止使用，按锂电池回收要求妥善处理，严禁扎破放气、冷藏后勉强使用或带伤飞行，任何一种都可能引发热失控。"},{"id":925,"type":"single","cat":"设备与维护","stem":"无人机飞控中的加速度计用于测量（）。","A":"三轴线加速度，辅助姿态解算","B":"磁场方向","C":"大气压力","D":"卫星信号强度","answer":"A","exp":"加速度计测量机体三轴方向的线加速度，与陀螺仪数据融合后解算俯仰、横滚姿态，并在卫星定位失效时辅助稳定。磁场方向由磁罗盘感知，气压由气压计测量，卫星信号强度与加速度计无关。"},{"id":926,"type":"single","cat":"设备与维护","stem":"无人机飞行时电机堵转的直接后果是（）。","A":"电流急剧增大，可能烧毁电调与电机","B":"电池电压升高","C":"图传信号增强","D":"无人机速度加快","answer":"A","exp":"桨叶被异物卡住或电机卡死形成堵转后，反电动势消失，绕组电流急剧上升，短时间内大量发热，极易烧毁电调功率管和电机绕组，飞控检测到堵转会立即锁定动力；电压、图传、速度都不会因此变好。"},{"id":927,"type":"single","cat":"操纵与飞行技术","stem":"无人机起飞前进行试悬停（悬停检查）的主要目的是（）。","A":"确认姿态、动力和遥控响应正常","B":"延长电池寿命","C":"增加航拍照片数量","D":"检查云台防水性能","answer":"A","exp":"低空试悬停让飞手在近地安全高度检验姿态是否稳定、动力响应是否正常、遥控指令与返航设定是否有效，发现问题可立即着陆排除；它与电池寿命、照片数量、防水性能没有关系。"},{"id":928,"type":"single","cat":"法规与空域","stem":"无人机在机场净空保护区飞行属于（）。","A":"违法违规行为，可能危及民航飞行安全","B":"正常飞行动作","C":"只要不拍摄客机即可","D":"超视距飞手的合法练习项目","answer":"A","exp":"机场净空保护区属于管制空域，未经批准任何无人机都不得飞入，低空飞行可能被吸入发动机或与起降航径上的航空器相撞，危及民航飞行安全，属于违法违规行为，与是否拍摄客机、是否超视距无关。"},{"id":929,"type":"single","cat":"设备与维护","stem":"无人机使用完毕后，对电池的正确保养方式是（）。","A":"若长期存放，将电池放电至存储电压（约3.8V/芯）并存放于阴凉处","B":"充满电长期存放","C":"放空电量长期存放","D":"随意放置于高温车内","answer":"A","exp":"锂聚合物电池长期满电存放会加速老化鼓包，放空又会过放报废，正确做法是充电或放电至每芯约3.8V的存储电压，置于阴凉干燥处并定期检查电压；高温车内温度极高，存放满电电池极易诱发热失控。"},{"id":930,"type":"multi","cat":"基础概念","stem":"无人机起飞前必须完成的检查包括（）。","A":"检查桨叶、机臂、螺丝是否完好紧固","B":"检查电池电压、电量和充电状态","C":"检查遥控器、图传、飞控参数与返航点设置","D":"检查空域申请、天气和周边环境","answer":"ABCD","exp":"A检查桨叶、机臂、螺丝是机体结构项，松动或裂纹会直接导致空中解体；B电池电压电量决定飞行时间与动力余量；C遥控器、图传、飞控参数与返航点关系到操控链路和应急安全；D空域合法性与天气环境决定能否起飞。四项缺一不可，均为起飞前必查内容。"},{"id":931,"type":"multi","cat":"飞行原理","stem":"下列哪些因素会影响多旋翼无人机产生的升力？（）","A":"空气密度","B":"桨叶直径与螺距","C":"旋翼转速","D":"云台相机重量","answer":"ABC","exp":"旋翼产生的拉力取决于空气密度、桨叶直径与螺距以及转速：密度越低拉力越小，桨盘面积和桨距越大、转速越高拉力越大。云台相机属于任务载荷，它影响的是所需拉力与续航表现，并不改变旋翼本身能产生的升力。"},{"id":932,"type":"multi","cat":"基础概念","stem":"无人机系统通常由哪些部分组成？（）","A":"飞行器平台与动力系统","B":"飞控系统与导航系统","C":"链路系统（遥控、图传）","D":"地面站与任务载荷","answer":"ABCD","exp":"完整的无人机系统不仅是飞行器本体：平台与动力提供飞行能力，飞控与导航负责姿态控制和定位，链路系统承载遥控指令上行与图传数据下行，地面站完成任务规划监控，任务载荷执行拍摄侦测等作业。四部分共同构成可用系统。"},{"id":933,"type":"multi","cat":"设备与维护","stem":"关于锂聚合物电池的使用，下列说法正确的有（）。","A":"不得过充、过放","B":"不得挤压、刺破或投入火中","C":"应使用专用平衡充电器充电","D":"充电时不得无人看管","answer":"ABCD","exp":"锂电池过充会鼓包起火、过放会永久损伤容量；挤压刺破或投入火中会造成内部短路直接热失控；充电必须使用配套平衡充电器，保证各串电压一致；充电过程化学状态活跃，无人看管时一旦异常无法及时处置。四条都是基本安全要求。"},{"id":934,"type":"multi","cat":"基础概念","stem":"无人机在以下哪些区域飞行属于高风险甚至违法违规行为？（）","A":"机场净空保护区","B":"军事管理区周边","C":"政府机关、核电站等敏感目标上空","D":"城市广场空旷区域","answer":"ABC","exp":"机场净空保护区危及民航起降安全，军事管理区周边涉及国防安全，政府机关、核电站等敏感目标上空未经批准绝对禁止飞行，均属高风险违法违规区域。城市广场等空旷区域只要遵守实名登记、真高与视距等一般规定即可合规飞行，不属于此类区域。"},{"id":935,"type":"multi","cat":"基础概念","stem":"无人机执行航拍任务时，下列做法正确的有（）。","A":"提前规划航线并设置返航点","B":"根据光照与风速调整拍摄参数","C":"注意避开障碍物、高压线和人群","D":"全程保持视距内或按超视距规定执飞","answer":"ABCD","exp":"A提前规划航线并设好返航点保证任务可控、失控可回；B光照与风速决定曝光参数和飞行稳定性；C障碍物、高压线和人群是航拍主要安全威胁，必须提前规避；D视距内或按超视距规定执飞是法规基本要求。四项均为规范航拍作业的正确做法。"},{"id":936,"type":"multi","cat":"基础概念","stem":"无人机在空中出现漂移现象，可能的原因有（）。","A":"GPS信号差或丢失","B":"磁罗盘受到干扰","C":"飞控未校准或振动过大","D":"风力过大","answer":"ABCD","exp":"GPS信号差或丢失使定点保持失效出现漂移；磁罗盘受钢铁构件、强电磁干扰会误判航向导致位置保持偏移；飞控未校准或机体振动过大会让姿态解算失准；自然风超过抗风能力时无人机也会被吹偏。这些都会表现为主观不动杆却发生漂移。"},{"id":937,"type":"multi","cat":"操纵与飞行技术","stem":"固定翼无人机着陆时，影响着陆距离的因素有（）。","A":"着陆重量","B":"逆风/顺风分量","C":"跑道或场地表面状况","D":"襟翼使用情况","answer":"ABCD","exp":"固定翼着陆距离由接地速度和减速能力决定：着陆重量越大，需要的空速越高，滑跑越长；逆风分量减小地速缩短距离，顺风反之；道面干燥坚硬摩擦力足，松软湿滑则延长滑跑；放下襟翼增升增阻，进近速度与滑跑距离均可缩短。四项均为影响因素。"},{"id":938,"type":"multi","cat":"航空气象","stem":"关于无人机云台与相机的使用，正确的有（）。","A":"起飞前应取下镜头保护罩","B":"应根据任务需要设置云台跟随或锁定模式","C":"航拍时应根据光线调整ISO、快门与光圈","D":"云台在飞行中可随意用手掰正","answer":"ABC","exp":"起飞前取下镜头保护罩避免遮挡成片并防止起飞震动甩落；按任务需要选择云台跟随或锁定模式控制构图方式；依据光线调整ISO、快门与光圈获得正确曝光。云台是精密稳定机构，飞行中用手掰正会打坏云台电机，属禁止操作。"},{"id":939,"type":"multi","cat":"领航与任务规划","stem":"无人机发生紧急状况必须立即降落或返航的情形包括（）。","A":"电量不足且距返航点距离较远","B":"电机或电调温度异常、桨叶受损","C":"图传中断或无法判断飞行状态","D":"遭遇强降雨、大风或能见度骤降","answer":"ABCD","exp":"电量不足以返回返航点时应立即返航或就近降落；电机电调温度异常、桨叶受损意味着动力随时可能失效；图传中断或无法判断飞行状态时后续控制没有保障；强降雨大风和能见度骤降已超出安全飞行条件。四种情形都应立即降落或返航。"},{"id":940,"type":"single","cat":"法规与空域","stem":"根据2024年修订的《无人驾驶航空器飞行管理暂行条例》，微型无人机在适飞空域内飞行时，下列哪项操作符合规定？","A":"夜间飞行时未开启位置灯","B":"在机场净空保护区域上空100米飞行","C":"携带总重量0.3kg的摄影设备","D":"在城市人口密集区上空真高60米飞行","answer":"C","exp":"微型无人机真高限制50米，机场净空保护区属管制空域禁飞，夜间飞行应开启位置灯，城市人口密集区上空真高60米既超高又未经批准；携带0.3kg摄影设备属于执行任务必需的任务载荷，在适飞空域内飞行符合规定。"},{"id":941,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在稳定悬停时，若出现顺时针旋转（俯视），最可能的原因是？","A":"1号电机（假设顺时针桨）转速偏高","B":"2号电机（逆时针桨）转速偏低","C":"3号电机（顺时针桨）转速偏低","D":"4号电机（逆时针桨）转速偏高","answer":"B","exp":"多旋翼悬停不偏航依靠正反桨的反扭矩相互抵消；俯视出现顺时针偏转说明该平衡被打破，逆时针桨一侧转速偏低、补偿扭矩不足是最可能的直接原因，顺时针桨一侧的转速变化引起的偏转方向与之相反。"},{"id":942,"type":"single","cat":"航空气象","stem":"下列哪类气象条件最可能导致无人机GPS信号异常？","A":"雷暴云团中的强电场","B":"低云（云底高200米）","C":"相对湿度90%的潮湿空气","D":"风速12m/s的侧风","answer":"A","exp":"雷暴云团内强电场与频繁放电会强烈干扰卫星导航接收和无线电链路，导致GPS定位跳变失锁，还可能损坏电子设备；低云、潮湿和侧风主要影响能见度、部件受潮与气动载荷，通常不会直接破坏GPS信号。"},{"id":943,"type":"single","cat":"法规与空域","stem":"视距内驾驶员执照（AOPA）持有人操作最大起飞重量12kg的无人机时，飞行高度限制为？","A":"真高100米","B":"真高120米","C":"真高500米","D":"真高不限（符合适飞空域）","answer":"B","exp":"视距内驾驶员操控12kg级无人机，仍须遵守统一的空域真高限制，在适飞空域内飞行真高不得超过120米，这与机型重量无关；500米等更高高度进入需要审批的空域使用范畴，且须具备相应等级资质。"},{"id":944,"type":"single","cat":"基础概念","stem":"无人机在600米高度飞行时，若遭遇突然断电，正确的应急措施是？","A":"立即切换手动模式进行迫降","B":"启用降落伞系统（若配备）","C":"尝试重启动力系统","D":"保持GPS模式等待重启","answer":"B","exp":"600米高度动力全部失效时，若配备降落伞系统应立即开伞，利用剩余高度大幅降低接地速度实现安全回收；此时电机已无动力，切手动模式无法控制姿态，重启动力和被动等待都可能错过最佳处置时机。"},{"id":945,"type":"multi","cat":"法规与空域","stem":"下列属于无人机适飞空域禁止行为的有？","A":"在军事管理区上空50米飞行","B":"携带易燃物品进行航空拍摄","C":"飞行中抛洒宣传物料","D":"夜间飞行时开启频闪灯","answer":"ABC","exp":"军事管理区上空未经批准无论高度均禁飞；携带易燃物品飞行既违反安全规定又放大坠机火灾风险；飞行中抛洒宣传物料属于未经批准投放物品，同样被禁止。夜间开启频闪灯反而利于被识别和避让，符合安全要求，不在禁止之列。"},{"id":946,"type":"multi","cat":"设备与维护","stem":"影响无人机电池续航的主要因素包括？","A":"环境温度（-10℃）","B":"飞行速度（15m/svs5m/s）","C":"起飞重量（10kgvs8kg）","D":"飞行高度（100米vs500米）","answer":"ABCD","exp":"零下十度低温使锂电池活性下降、可用容量明显缩水；15m/s高速飞行克服的阻力远大于5m/s，耗电成倍增加；起飞重量越大旋翼需维持更高转速输出更大拉力；高度升至500米时空气密度降低，且爬升本身消耗额外能量。四项都会明显缩短续航。"},{"id":947,"type":"multi","cat":"基础概念","stem":"无人机起飞前检查应包括？","A":"螺旋桨安装方向（正/反桨匹配）","B":"飞控校准（磁罗盘、加速度计）","C":"电池剩余电量（≥80%）","D":"周边50米内无人员聚集","answer":"ABCD","exp":"正反桨装反会导致无法起飞或立即翻覆，须核对螺旋桨安装方向；磁罗盘和加速度计校准保证定向与姿态基准准确；电池电量保持80%以上留足返航与抗风余量；周边50米内无人员聚集是失控坠落风险的基本隔离要求。四项均为起飞前应完成的检查。"},{"id":948,"type":"single","cat":"飞行原理","stem":"无人机飞行时放下襟翼，会使飞机（）。","A":"飞行速度增大","B":"飞行速度无明显变化","C":"飞行速度减小","D":"以上均不正确","answer":"C","exp":"放下襟翼增大机翼弯度和有效面积，升力提高的同时阻力也明显增大，同等推力下飞行速度减小，这正是着陆阶段用来缩短滑跑距离、降低接地速度的手段；它不会让速度增大，也不会保持速度基本不变。"},{"id":949,"type":"single","cat":"操纵与飞行技术","stem":"飞机的起飞和着陆，通常要求在（）条件下进行。","A":"逆风","B":"顺风","C":"上升气流","D":"下降气流","answer":"A","exp":"起飞着陆都要求逆风进行：逆风增大相对空速，同等地速下升力更大，滑跑距离更短、离地和接地速度更小，失速裕度充足；顺风则延长滑跑并增大冲出风险，上升下降气流都不能替代逆风带来的空速增益。"},{"id":950,"type":"single","cat":"设备与维护","stem":"为了解决大速度下空气压缩性的影响和噪音问题，可以对桨叶进行何种操作（）。","A":"把桨叶尖部作成后掠行","B":"采用矩形桨叶","C":"采用尖削桨叶","D":"以上均不正确","answer":"A","exp":"桨叶尖部在大速度下线速度很高，容易进入跨音速区产生激波，导致阻力剧增和噪音加大；把桨尖做成后掠形可推迟激波产生、削弱空气压缩性影响并降低噪音，思路与机翼后掠同理；矩形桨叶和尖削桨叶解决不了桨尖激波问题。"},{"id":951,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，关于顺风着陆描述正确的是（）。","A":"地速较大，平飘距离较长","B":"地速较小，平飘距离较短","C":"地速正常，平飘距离正常","D":"以上均不正确","answer":"A","exp":"顺风着陆时地速等于空速加风速，接地与滑跑速度更大，平飘距离明显拉长，操纵不慎容易飘远甚至冲出场地；逆风着陆则地速小、平飘短。因此正确的描述是地速较大、平飘距离较长。"},{"id":952,"type":"single","cat":"设备与维护","stem":"多旋翼无人机动力系统主要调试（）、动力电源、螺旋桨和调速系统等。","A":"机架","B":"动力电机","C":"定位系统","D":"避障系统","answer":"B","exp":"多旋翼动力系统的调试对象是动力电机、动力电源、螺旋桨和调速系统，即从能量输入到推力输出的整条链路，包括核对电机转向、拉力一致性与电调响应；机架属于结构件，定位与避障系统不属于动力系统范畴。"},{"id":953,"type":"single","cat":"基础概念","stem":"无人机驾驶员操作副翼时，飞行器将（）。","A":"横轴运动","B":"纵轴运动","C":"立轴运动","D":"以上均不正确","answer":"B","exp":"副翼安装在机翼后缘外侧，左右反向偏转产生滚转力矩，使飞机绕纵轴滚转实现横滚机动，纵轴即穿过机头机尾的轴线。升降舵控制绕横轴的俯仰，方向舵控制绕立轴的偏航，三者各司其职互不替代。"},{"id":954,"type":"single","cat":"操纵与飞行技术","stem":"无人机驾驶员操纵无人机着陆滑跑时，油门状态描述正确的是（）。","A":"飞机接地后，为保证安全一般将油门收为零","B":"飞机接地后，着陆滑跑一段距离再收油门","C":"飞机接地后，将油门保持大车状态，准备随时复飞","D":"以上均不正确","answer":"A","exp":"接地后应立即把油门收至零位，让螺旋桨停止提供拉力，依靠机轮摩擦和气动阻力减速滑跑；若接地后再收油门或保持大车状态，剩余拉力会让飞机重新飘起、延长滑跑甚至无意复飞，滑跑阶段不允许继续补油门。"},{"id":955,"type":"single","cat":"基础概念","stem":"当多旋翼无人机无法保持当前高度飞行时，应该检查（）。","A":"空速计","B":"陀螺仪","C":"气压计","D":"加速度计","answer":"C","exp":"多旋翼定高主要依赖气压计：它利用气压随高度变化的原理获取高度基准，气压计故障或受气流扰动时就会掉高、窜高，无法保持高度飞行。空速计用于固定翼测空速，陀螺仪和加速度计负责姿态测量而非高度。"},{"id":956,"type":"single","cat":"设备与维护","stem":"执行测量任务的传感器部件，如高度差传感器，送出姿态信号的惯性陀螺平台，实际上也都是一些（）系统。","A":"开放","B":"闭合","C":"闭环","D":"环路","answer":"C","exp":"高度差传感器、惯性陀螺平台这类测量部件必须持续把输出与基准比较并自动修正误差，构成检测、比较、反馈的闭合回路，本质上都是闭环控制系统；开环系统没有反馈通道，无法保证测量精度和抗干扰能力。"},{"id":957,"type":"single","cat":"飞行原理","stem":"直升机在前飞时桨叶在什么方位迎角最大？（）","A":"180°方位","B":"90°方位","C":"270°方位","D":"以上均不正确","answer":"C","exp":"前飞时前行桨叶相对气流速度大、升力趋于增大，自动倾斜器通过周期变距减小前行侧迎角，同时增大后退侧迎角，桨叶迎角在270°方位达到最大，90°方位前行侧最小，以此平衡两侧升力防止倾翻。"},{"id":958,"type":"single","cat":"基础概念","stem":"（）是无人驾驶航空器地面站的主要功能。","A":"数据采集处理","B":"飞行控制","C":"导航","D":"监控与任务规划","answer":"D","exp":"地面站的核心职能是监控与任务规划：实时显示位置、姿态与链路状态并支持人工介入，同时承担航线编辑、任务装订和载荷控制。数据采集处理、飞行控制、导航分别由任务终端、飞控子系统和导航子系统承担，地面站是管理与监视的枢纽。"},{"id":959,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机下滑中，估计到第四转弯时的高度将高于预定的高度（）。","A":"应及时地收小油门，必要时可收至20%，增大下滑角","B":"应适当地加大油门，减小下滑角","C":"转为平飞进行修正","D":"以上均不正确","answer":"A","exp":"第四转弯点高度偏高说明下滑剖面过平，应及时收小油门、必要时收至20%，通过增大下滑角加快消耗高度，回到预定下滑线；加大油门减小下滑角或转为平飞都会让高度进一步偏离，无法准确进入着陆点。"},{"id":960,"type":"single","cat":"设备与维护","stem":"为无人机选取机架时，如飞行器起飞重量大于4kg，建议电机臂碳管不小于（）mm或以上，机架碳板厚度达到5mm或以上。","A":"6","B":"16","C":"60","D":"160","answer":"B","exp":"经验做法是起飞重量大于4kg时，机臂碳管直径不小于16mm、机架碳板厚度达到5mm以上，以保证结构强度和抗弯刚度，承受相应起飞重量产生的拉力与振动；6mm碳管明显偏细，60mm、160mm则远超实际需要。"},{"id":961,"type":"single","cat":"飞行原理","stem":"民用无人机运行多处于低空低速环境下，主要受到的阻力有①摩擦阻力；②循环阻力；③干扰阻力；④激波阻力；⑤诱导阻力；⑥压差阻力。","A":"①②③④","B":"①③⑤⑥","C":"①②⑤⑥","D":"以上均不正确","answer":"B","exp":"低空低速运行时的气动阻力由摩擦阻力、压差阻力、诱导阻力和干扰阻力构成；激波阻力只有在接近声速出现激波时才产生，低速飞行可以忽略；循环阻力也不是标准的阻力分类。因此①③⑤⑥的组合是正确的。"},{"id":962,"type":"single","cat":"电力巡检","stem":"巡检作业时，若固定翼无人机出现失去动力等机械故障，应控制无人机（）。","A":"立即拉升爬高","B":"原地降落","C":"在安全区域紧急降落","D":"立即飞回","answer":"C","exp":"固定翼失去动力后仍具备滑翔能力，正确处置是控制飞机滑翔到预先选择的平坦安全区域实施迫降，最大限度保证地面和设备安全；立即拉升会耗尽仅存空速导致失速，原地降落和强行飞回都不符合当时的能量状态。"},{"id":963,"type":"multi","cat":"基础概念","stem":"常见小型多旋翼无人机常使用的动力装置不包括（）。","A":"燃气涡轮发动机","B":"四冲程活塞发动机","C":"电动机","D":"涡轮轴发动机","answer":"ABD","exp":"小型多旋翼普遍以电动机配锂电池为动力，结构简单、响应快、维护方便。燃气涡轮发动机与涡轮轴发动机功率大、成本高，主要用于中大型机型，四冲程活塞发动机多用于油动固定翼和直升机，均不是常见小型多旋翼的动力装置。"},{"id":964,"type":"multi","cat":"基础概念","stem":"起飞前应检查无人直升机动力系统的（）或（），确认满足飞行巡检航程要求。","A":"油量","B":"燃油","C":"电能储备","D":"电量储备","answer":"BC","exp":"起飞前应确认动力能源满足巡检航程要求：油动直升机核对燃油及其油量，电动平台核对电能储备是否充足，两者直接对应可飞行时间。单说油量或电量储备表述不完整，规程要求核对的是燃油或电能储备这两项内容。"},{"id":965,"type":"multi","cat":"基础概念","stem":"多轴飞行器在没有发生机械结构改变的前提下，如发生漂移，不能直线飞行时，需关注的是","A":"GPS定位","B":"指南针校准","C":"调整重心位置","D":"遥控天线","answer":"AB","exp":"GPS定位信号弱或丢失会让定点保持失效从而产生漂移；指南针未校准或受磁干扰会误判航向导致不能直线飞行，两者是无机械变动时首要关注对象。机械结构未变时重心一般无需调整，遥控天线只影响链路信号强弱，都不是漂移的直接原因。"},{"id":966,"type":"multi","cat":"基础概念","stem":"垂直起降固定翼无人机，又分为（）和（），指一种结合了多旋翼无人机和固定翼无人机优势的新型垂直起降飞行器。","A":"倾转旋翼无人机","B":"叠转旋翼无人机","C":"固定旋翼无人机","D":"复合翼无人机","answer":"AD","exp":"垂直起降固定翼结合多旋翼与固定翼优势，典型形态分两类：倾转旋翼无人机通过旋翼倾转在垂直起降与平飞之间转换；复合翼无人机用独立的多旋翼动力垂直起降、固定翼动力巡航。叠转旋翼、固定旋翼并不是通用的分类表述。"},{"id":967,"type":"multi","cat":"电力巡检","stem":"当无人机巡检系统主要组成部件进行了更换或升级后，运维单位应（）。","A":"立即使用","B":"组织试验检测","C":"组织评估","D":"确保无人机巡检系统满足相关标准要求","answer":"BD","exp":"巡检系统主要组成部件更换或升级后，功能与性能已发生变化，应组织试验检测加以验证，并确保无人机巡检系统满足相关标准要求后才能投入使用；未经检测立即使用存在失控与作业风险，检测和达标确认是规程要求的基本环节。"},{"id":968,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检作业安全工作规程》中，无人机巡检作业应严格按国家相关（）、等要求规范化使用空域。","A":"政策","B":"法规","C":"当地民航军管","D":"规程","answer":"ABC","exp":"规范化使用空域须遵循三个层面：国家相关政策提出总体要求，国家法规作出制度性规定，当地民航和军管部门掌握具体空域管制要求，三者共同构成空域使用的合规依据；内部作业规程不属于空域使用的外部规范要求。"},{"id":969,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统应具备（）功能","A":"一键返航功能","B":"链路中断返航功能","C":"飞行区域限制功能","D":"低电压报警功能","answer":"ABC","exp":"无人直升机巡检系统须具备一键返航功能便于应急撤离，链路中断时自动返航防止失联失控，飞行区域限制功能通过电子围栏防止误入禁飞区；低电压报警只是提示手段，安全功能应以能自动处置的返航与区域限制为主。"},{"id":970,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机自动驾驶状态下，安全下降速率应该是哪一个？（）","A":"2米/秒","B":"8米/秒","C":"5米/秒","D":"以上均不正确","answer":"A","exp":"多旋翼在自动驾驶状态下的安全下降速率一般控制在2米/秒左右：下降过快会接近甚至进入涡环状态导致升力骤降，低空接地冲击也过大；8米/秒和5米/秒都明显超出安全范围，容易引发危险。"},{"id":971,"type":"single","cat":"设备与维护","stem":"多旋翼电调与电机如何匹配？（）","A":"电调的额定电压要比电机的最大电流高","B":"电调的额定电流要比电机的最大电流底","C":"电调的额定电流要比电机的最大电流高","D":"以上均不正确","answer":"C","exp":"电调与电机按电流匹配：电调的额定电流必须高于电机的最大工作电流并留出裕量，满负荷运行时电调才不会过热烧毁；额定电压则应与所选电池电压体系一致，额定电流低于电机最大电流的电调必然过载损坏。"},{"id":972,"type":"single","cat":"操纵与飞行技术","stem":"无人机在室外作业时，没有按照指定位置悬停，而是不受控制自己飘走，应维修（）可以恢复其正常功能。","A":"陀螺仪","B":"飞控","C":"水平仪","D":"GPS模块","answer":"D","exp":"室外指定位置悬停依赖卫星定位：GPS模块故障或信号异常后，飞行器失去位置基准，就会不受控制地自行漂移。陀螺仪和飞控负责姿态稳定，水平仪参与调平校准，定点功能失效应首先检修GPS模块。"},{"id":973,"type":"single","cat":"设备与维护","stem":"多旋翼飞行器如果重新组装后，必须校准哪些传感器？（）","A":"磁罗盘，陀螺仪","B":"电调，GPS","C":"接收机，IMU","D":"以上均不正确","answer":"A","exp":"重新组装后机臂角度、走线布局和周边磁场环境都发生变化，必须重新校准磁罗盘以恢复准确的航向基准，并校准陀螺仪保证水平零位正确；电调、GPS、接收机不属于需校准的传感器，这是组装后的基本安全步骤。"},{"id":974,"type":"single","cat":"设备与维护","stem":"无人机飞行时收起起落架，会使飞机（）。","A":"全机阻力无明显变化","B":"全机阻力减小","C":"全机阻力增大","D":"以上均不正确","answer":"B","exp":"起落架是突出于机体之外的非承力部件，飞行中产生大量废阻力；收起后气动外形更干净，全机阻力减小，速度与航程性能随之改善，这正是可收放起落架的设计目的；放下状态才对应阻力增大，收起前后阻力不可能不变。"},{"id":975,"type":"single","cat":"基础概念","stem":"（）是无人机完成起飞、空中飞行、执行任务、返场回收等整个飞行过程的核心系统，对无人机实现全权控制与管理。","A":"飞控计算机","B":"飞控子系统","C":"导航子系统","D":"以上均不正确","answer":"B","exp":"飞控子系统是全权控制与管理的核心：它采集传感器数据完成姿态解算，对起飞、空中飞行、执行任务、返场回收全过程实施自动控制，并协调各子系统工作；飞控计算机只是其硬件载体，导航子系统仅提供位置信息。"},{"id":976,"type":"single","cat":"基础概念","stem":"多轴飞行器（）。","A":"无自转下滑能力","B":"有部分自传下滑能力","C":"有自转下滑能力","D":"以上均不正确","answer":"A","exp":"多轴飞行器桨叶与电机固定连接，没有直升机那种可变总距的旋翼和桨毂变距机构，动力失效后无法利用迎面气流维持旋翼转速，不具备自转下滑能力，只能依靠降落伞或动力冗余等手段实施应急。"},{"id":977,"type":"single","cat":"设备与维护","stem":"外转子无刷电机相对于内转子无刷的优势是（）。","A":"扭矩更高","B":"寿命更长","C":"功率更大","D":"转速更高","answer":"A","exp":"外转子无刷电机的外壳连同永磁体一起旋转，转动惯量大、磁极布置空间充足，相同功率下转速较低而输出扭矩更高，可直接驱动较大直径桨省去减速机构；寿命与功率取决于具体设计，内转子的优势才是转速更高。"},{"id":978,"type":"single","cat":"基础概念","stem":"以下是共轴双旋翼直升机的优点的是（）。","A":"操作结构简单","B":"自转下滑性能优异","C":"纵向尺寸小","D":"以上均不正确","answer":"C","exp":"共轴双旋翼上下两副桨反向旋转，反扭矩相互抵消，省去尾桨和长尾梁，机身纵向尺寸显著缩短、结构紧凑；其桨毂与操纵机构比较复杂，操作结构并不简单，上下桨间的气动干扰也使自转下滑性能受到限制。"},{"id":979,"type":"single","cat":"操纵与飞行技术","stem":"属于减升装置的辅助操纵面是（）。","A":"扰流扳","B":"副冀","C":"前缘缝翼","D":"以上均不正确","answer":"A","exp":"扰流板铰接在机翼上表面，打开后破坏上表面气流、急剧减小升力并增大阻力，属于减升装置；副翼用于差动滚转控制，前缘缝翼打开后延缓气流分离、提高升力，属于增升装置，两者用途与扰流板不同。"},{"id":980,"type":"single","cat":"基础概念","stem":"可进行夜间监视的无人机，作业时突然失去该夜视功能，此时可判断该现象产生的主要原因是（）出现故障。","A":"全球定位系统（GPS）模块","B":"前视红外仪","C":"摄像头","D":"电子调速器（电调）","answer":"B","exp":"夜间监视依靠前视红外热成像仪在黑暗中捕捉目标的热辐射成像，夜视功能突然丧失首先指向前视红外仪故障；GPS、电调关系到飞行控制与动力，普通可见光摄像头在夜间无光照条件下无法承担监视任务。"},{"id":981,"type":"multi","cat":"基础概念","stem":"安全保护功能应具备安全控制策略，包括（）和（）。","A":"返航策略","B":"自动躲避策略","C":"应急降落策略","D":"应急提升策略","answer":"AC","exp":"安全控制策略必须覆盖两类场景：出现异常或故障时执行返航策略，自动回到预设安全位置；无法继续维持安全飞行时执行应急降落策略，就地可控降落以减少损失。自动躲避、应急提升并非通用安全功能，规程强调的是返航与应急降落两项。"},{"id":982,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，无人机巡检区域处于（）等特殊区域时，巡检人员应根据无人机的性能及气象情况判断是否继续飞行。","A":"狭长地带","B":"大档距","C":"大落差","D":"微气象","answer":"ABCD","exp":"狭长地带限制避让与退飞空间，大档距跨越距离长、信号衰减和风险暴露大，大落差地形使相对高度难以把握，微气象区局地风突变难以预判。处于这些特殊区域时，须结合无人机性能与气象条件评估风险，再决定是否继续飞行。"},{"id":983,"type":"multi","cat":"设备与维护","stem":"固定翼无人机的舵角一般是一个三角形的固定件，安装在无人机副翼、尾翼的活动面上，通过连杆与舵机摇臂连接，其安装过程中的注意事项包括（）。","A":"同一舵面的各个铰链的中心线应该在一条直线上，并且位于舵面的中心","B":"舵脚的转动点应该与铰链的中心线在同一个垂直面上","C":"舵机摇臂应该与连杆垂直，调整摇臂使得键槽与键齿相配合，尽量不要使用遥控器的中立位置调整功能来调整舵机的中心位置","D":"使用高级的带轴承的连接附件和精密加工的铝制舵机摇臂，可以更好的完成设置","answer":"ABCD","exp":"同一舵面各铰链中心线须共线并位于舵面中心，保证舵面受力均匀不卡滞；舵脚转动点与铰链中心线应处于同一垂直面，避免运动干涉；舵机摇臂与连杆保持垂直并靠键槽键齿对中，尽量不用遥控器中立微调迁就；带轴承附件与精密铝摇臂能减小旷量、提高传动精度。四项均为安装要点。"},{"id":984,"type":"multi","cat":"基础概念","stem":"设备运维单位应提前掌握线路周边重要建筑和设施、人员活动密集区、（）、森林防火区和无人区等的分布情况。","A":"空中管制区","B":"无线电干扰区","C":"通讯阻隔区","D":"大风或切变风多发区","answer":"ABCD","exp":"线路运维前须提前掌握周边环境分布：空中管制区关系空域合法性，无线电干扰区影响导航与链路，通讯阻隔区会造成图传遥控中断，大风或切变风多发区直接威胁飞行稳定，连同重要建筑设施、人员密集区、森林防火区和无人区一并纳入风险预控。"},{"id":985,"type":"multi","cat":"电力巡检","stem":"在《架空输电线路无人机巡检技术》中，军用无人机可以分为（）。","A":"校靶机","B":"攻击机","C":"电子战无人机","D":"巡查/监视无人机","answer":"ABC","exp":"按用途划分，军用无人机主要包括校靶（靶标）机、攻击机、电子战无人机等服务于作战与武器试验的类型；巡查/监视无人机面向电力巡检等民用作业场景，不属于军用无人机的分类范畴，因此前三项正确。"},{"id":986,"type":"multi","cat":"操纵与飞行技术","stem":"直升机的空间有六个自由度，但实际上只需要四个操纵，这四个操纵分别是（）。","A":"总距操纵","B":"纵向操纵","C":"横向操纵","D":"航向操纵","answer":"ABCD","exp":"直升机六个空间自由度中，总距操纵控制旋翼总升力实现升降，纵向操纵使旋翼前后倾倒实现前飞后飞，横向操纵实现左右侧移，航向操纵借助尾桨推力或反扭矩差控制机头转向。上下、前后、左右、偏转四个操纵通道即可覆盖全部自由度。"},{"id":987,"type":"single","cat":"法规与空域","stem":"根据2025年修订的《无人驾驶航空器飞行管理暂行条例》实施细则，微型无人机（空机重量≤0.25kg）在适飞空域内飞行时，下列哪项操作符合规定？","A":"夜间飞行时未开启示位灯","B":"超视距飞行但保持与管制单位通信","C":"在机场净空保护区外100米高度飞行","D":"搭载总重量0.3kg的测绘设备","answer":"C","exp":"微型无人机在适飞空域内可超视距飞行，但需满足高度限制；夜间需示位灯，搭载重量不得超过空机重量，机场净空保护区外允许120米以下飞行"},{"id":988,"type":"single","cat":"航空气象","stem":"某多旋翼无人机在6m/s稳定风速中悬停，其电机输出功率与无风悬停相比：","A":"增加，因需抵消风阻","B":"减少，因风速提供部分升力","C":"不变，悬停功率仅与重力有关","D":"先增后减，取决于风向","answer":"A","exp":"稳定风场中，无人机需通过姿态调整产生水平推力抵消风阻，导致电机功率增加"},{"id":989,"type":"single","cat":"航空气象","stem":"以下哪种气象条件最可能引发无人机动力系统结冰？","A":"温度-5℃，相对湿度60%的晴天","B":"温度0℃，过冷水滴含量0.5g/m³的层云","C":"温度10℃，雷暴云砧下方","D":"温度-15℃，干燥的高空气流","answer":"B","exp":"结冰需满足过冷水滴存在、温度0℃至-10℃、水滴含量≥0.3g/m³，层云符合条件"},{"id":990,"type":"single","cat":"领航与任务规划","stem":"采用GPS+惯性导航（INS）组合导航的无人机，当GPS信号丢失时，导航误差主要来源于：","A":"气压高度计的温度漂移","B":"加速度计的零偏误差","C":"磁罗盘的磁干扰","D":"视觉定位的延迟","answer":"B","exp":"INS通过加速度计积分计算位移，其零偏误差会随时间累积，导致定位误差增大"},{"id":991,"type":"single","cat":"飞行原理","stem":"某4轴无人机（轴距450mm）使用1045桨（直径10英寸，螺距4.5英寸），若更换为1240桨，其他参数不变，最可能出现的现象是：","A":"悬停电流降低，最大升力增加","B":"悬停电流增加，最大升力降低","C":"悬停电流降低，最大升力降低","D":"悬停电流增加，最大升力增加","answer":"D","exp":"大直径桨叶在低转速下可产生更大升力，但需更大扭矩，导致悬停电流增加；螺距减小补偿转速需求，整体最大升力提升"},{"id":992,"type":"single","cat":"法规与空域","stem":"依据《民用无人驾驶航空器驾驶员执照管理规定》，申请视距内驾驶员执照（超视距等级）的申请人，需具备至少（）小时的超视距飞行训练经历？","A":"10","B":"15","C":"20","D":"25","answer":"B","exp":"2026年新规要求超视距等级需15小时专项训练，含5小时模拟机训练"},{"id":993,"type":"single","cat":"航空气象","stem":"无人机在500米高度飞行时，遇到中度颠簸，正确的应对措施是：","A":"立即降低高度至100米以下","B":"保持当前空速，调整俯仰角","C":"增大油门至最大，快速爬升","D":"切换至手动模式，稳定姿态","answer":"D","exp":"颠簸时需稳定姿态，手动模式可更精准控制；盲目增减油门或高度可能加剧不稳定"},{"id":994,"type":"single","cat":"设备与维护","stem":"以下哪种电池存储方式符合安全规范？","A":"锂电池充满电后，在25℃环境中密封保存","B":"镍氢电池放电至20%电量，在15℃干燥环境存放","C":"铅酸电池完全放电后，在0℃环境长期存储","D":"聚合物电池放电至50%电量，在35℃通风处堆叠存放","answer":"B","exp":"锂电池应存储在30%-50%电量，20-25℃；铅酸电池需保持部分电量防止硫化；聚合物电池需单颗隔离存放，避免堆叠"},{"id":995,"type":"single","cat":"设备与维护","stem":"某无人机飞控系统显示磁罗盘校准失败，可能的原因不包括：","A":"附近存在强电磁干扰（如高压电线）","B":"校准过程中无人机姿态变化过快","C":"飞控固件版本与磁罗盘型号不匹配","D":"螺旋桨旋转产生的振动导致传感器误差","answer":"D","exp":"磁罗盘校准失败主要因环境干扰、操作不当或软硬件不兼容；螺旋桨振动影响加速度计，不直接导致磁罗盘校准问题"},{"id":996,"type":"single","cat":"基础概念","stem":"关于无人机起降场地选择，错误的做法是：","A":"选择逆风方向起降，缩短滑跑距离","B":"多旋翼无人机在坡度15°的斜坡上垂直起降","C":"固定翼无人机在长度80米的草地跑道起飞","D":"避开通信基站、雷达站等电磁敏感区域","answer":"B","exp":"多旋翼垂直起降需场地水平，坡度超过10°可能导致起飞时姿态失控"},{"id":997,"type":"single","cat":"基础概念","stem":"下列哪项不属于无人机系统的感知与规避（SAA）功能？","A":"毫米波雷达探测前方障碍物","B":"视觉识别系统跟踪附近有人机","C":"自动调整航线避让禁飞区","D":"ADS-B接收机接收其他飞机位置信息","answer":"C","exp":"SAA特指对动态障碍物的实时感知与避让，禁飞区避让属于路径规划，非实时感知"},{"id":998,"type":"single","cat":"设备与维护","stem":"某六轴无人机（桨序1-6顺时针排列），若第2号电机（前右）停转，飞机会出现：","A":"机头向右偏转，右侧下沉","B":"机头向左偏转，左侧下沉","C":"机头向右偏转，左侧下沉","D":"机头向左偏转，右侧下沉","answer":"A","exp":"前右电机停转，该桨升力消失，右侧力矩不平衡导致右侧下沉；顺时针桨停转，反扭矩减少，机头向右转"},{"id":999,"type":"single","cat":"基础概念","stem":"气压高度表在高原地区（海拔3000米）使用时，若未修正基准气压，测得的高度会：","A":"高于实际高度（相对海平面）","B":"低于实际高度（相对海平面）","C":"准确反映相对地面高度","D":"误差随温度变化无规律","answer":"B","exp":"高原地区气压低于标准大气压，未修正时气压高度表会将低气压误判为更高高度，导致显示高度高于实际海拔，但相对地面高度需结合实时气压"},{"id":1000,"type":"single","cat":"领航与任务规划","stem":"无人机在执行测绘任务时，若需要地面分辨率达到5cm，飞行高度100米，应选择的相机焦距为（像元尺寸3.75μm）：","A":"15mm","B":"20mm","C":"25mm","D":"30mm","answer":"B","exp":"地面分辨率GSD=（像元尺寸×飞行高度"},{"id":1001,"type":"single","cat":"基础概念","stem":"依据《无人驾驶航空器运行风险等级划分》，以下哪类运行属于高风险？","A":"视距内农林喷洒（起飞重量25kg）","B":"超视距物流配送（起飞重量50kg，高度150米）","C":"视距内航空摄影（起飞重量1.5kg，人群上空50米）","D":"超视距电力巡检（起飞重量12kg，远离人群）","answer":"B","exp":"高风险运行包括超视距、起飞重量＞25kg、人口密集区上空等多重风险叠加"},{"id":1002,"type":"single","cat":"基础概念","stem":"无人机在飞行中出现动力不足报警，可能的原因不包括：","A":"电池内阻增大，放电能力下降","B":"电机KV值与桨叶匹配不当（KV值过高）","C":"飞控PID参数设置过软，响应延迟","D":"螺旋桨安装反角错误，产生负拉力","answer":"C","exp":"PID参数影响稳定性，不直接导致动力不足；动力问题多与动力系统效率相关"},{"id":1003,"type":"single","cat":"飞行原理","stem":"以下哪种飞行状态最容易诱发失速？","A":"固定翼无人机以1.2倍失速速度平飞","B":"多旋翼无人机以最大俯仰角（30°）俯冲","C":"固定翼无人机带20°坡度转弯，空速降低至失速速度","D":"多旋翼无人机在6级侧风中悬停","answer":"C","exp":"转弯时升力需分解为向心力，有效升力降低，空速接近失速速度时易失速"},{"id":1004,"type":"single","cat":"设备与维护","stem":"无人机数据链中断（信号丢失）时，优先执行的动作是：","A":"切换至手动模式，人工接管","B":"按预设航线继续飞行","C":"原地盘旋等待信号恢复","D":"自动返航至起飞点","answer":"D","exp":"多数飞控设计为信号丢失时优先返航，避免失控漂移；需根据飞控设置，但标准流程以返航为第一选择"},{"id":1005,"type":"single","cat":"设备与维护","stem":"关于无人机电池循环寿命，正确的描述是：","A":"循环次数指完全充放电（0-100%）的次数","B":"聚合物锂电池循环寿命通常＞1000次","C":"浅充浅放（20%-80%）会降低循环寿命","D":"镍镉电池无记忆效应，可任意充放电","answer":"A","exp":"循环寿命定义为完全充放电次数；聚合物锂电池循环约300-500次；浅充浅放可延长寿命；镍镉电池有记忆效应"},{"id":1006,"type":"single","cat":"设备与维护","stem":"某无人机飞控记录显示IMU校准失败，最可能的故障部件是：","A":"惯性测量单元（加速度计+陀螺仪）","B":"全球导航卫星系统（GNSS）模块","C":"气压高度传感器","D":"磁罗盘","answer":"A","exp":"IMU校准直接关联加速度计和陀螺仪，校准失败通常因传感器故障或环境振动过大"},{"id":1007,"type":"multi","cat":"法规与空域","stem":"以下哪些属于无人机适飞空域的管制空域？","A":"真高120米以上区域","B":"机场跑道中心线两侧各10公里、跑道端外20公里范围","C":"军事管理区上空","D":"人口密集区真高50米以下","answer":"ABC","exp":"管制空域包括高高度层、机场净空区、军事区等；人口密集区50米以下属加强管控区，非管制空域"},{"id":1008,"type":"multi","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停时，影响其稳定性的主要因素有：","A":"电机响应速度","B":"桨叶动平衡","C":"飞控PID参数","D":"电池放电倍率","answer":"ABCD","exp":"电机响应影响姿态调整速度；桨叶不平衡导致振动；PID参数决定控制精度；电池放电不足会导致动力中断"},{"id":1009,"type":"multi","cat":"航空气象","stem":"无人机在雷暴天气中飞行可能面临的风险包括：","A":"强电场引发电子设备故障","B":"上升/下沉气流导致失控","C":"冰雹撞击损坏机体","D":"湿度大导致电池短路","answer":"ABC","exp":"雷暴云内强电场、剧烈气流、冰雹是主要风险；密封良好的电池不易因湿度短路"},{"id":1010,"type":"multi","cat":"基础概念","stem":"固定翼无人机起飞滑跑距离过长，可能的原因有：","A":"起飞重量过大","B":"跑道表面摩擦系数过高","C":"迎角设置过小","D":"发动机推力不足","answer":"ACD","exp":"重量大、推力小、迎角小（升力不足"},{"id":1011,"type":"multi","cat":"基础概念","stem":"无人机维护时，需要检查的项目包括：","A":"螺旋桨是否有裂纹或变形","B":"飞控天线是否松动","C":"电池接口是否氧化","D":"电机轴是否有径向晃动","answer":"ABCD","exp":"螺旋桨结构、天线连接、电池接触、电机间隙均为关键检查项"},{"id":1012,"type":"single","cat":"法规与空域","stem":"根据《无人驾驶航空器飞行管理暂行条例》，我国对无人驾驶航空器实行（）制度。","A":"实名登记","B":"备案管理","C":"适航认证","D":"运营许可","answer":"A","exp":"《无人驾驶航空器飞行管理暂行条例》对民用无人驾驶航空器确立实名登记制度：所有者依法登记取得登记标志后方可飞行，便于追溯到人、落实安全责任；备案管理、适航认证、运营许可针对的是其他管理环节，不是对航空器所有者的基本制度。"},{"id":1013,"type":"single","cat":"法规与空域","stem":"轻型无人驾驶航空器在适飞空域内飞行的最大真高不得超过（）。","A":"50米","B":"120米","C":"500米","D":"1000米","answer":"B","exp":"轻型无人驾驶航空器在适飞空域内飞行的真高上限为120米，这是兼顾飞行活动需求与地面人员财产安全的统一高度红线，超过即进入需要审批的空域使用范畴；50米是微型机的限制，500米和1000米明显超出适飞空域的许可范围。"},{"id":1014,"type":"single","cat":"法规与空域","stem":"下列空域中，属于我国民用无人机适飞空域的是（）。","A":"机场净空保护区","B":"军事禁区上空","C":"真高120米以下的非管控空域","D":"政府机关驻地上空","answer":"C","exp":"适飞空域指真高120米以下、供微型轻型小型无人驾驶航空器使用的非管控空域，无需申请即可按规定飞行；机场净空保护区、军事禁区上空、政府机关驻地上空都属于管制或禁飞区域，未经批准不得进入。"},{"id":1015,"type":"single","cat":"法规与空域","stem":"CAAC颁发的民用无人机超视距驾驶员执照的理论考试合格分数线为（）。","A":"60分","B":"70分","C":"80分","D":"90分","answer":"C","exp":"CAAC超视距驾驶员执照理论考试满分100分，合格分数线为80分：超视距飞行涉及航线规划、链路管理与导航知识，考核要求更高，故分数线设定更高；60分、70分、90分都不是该等级规定的合格分数线。"},{"id":1016,"type":"single","cat":"操纵与飞行技术","stem":"视距内（VLOS）飞行是指驾驶员在目视范围内操纵无人机，其水平距离通常不超过（），相对高度不超过120米。","A":"200米","B":"500米","C":"1000米","D":"2000米","answer":"B","exp":"视距内飞行的本质是驾驶员以目视随时掌握飞行器位置姿态与状态，其水平距离通常不超过500米、真高不超过120米；超出目视范围后难以及时察觉异常，即进入超视距飞行，须具备相应资质和保障条件。"},{"id":1017,"type":"single","cat":"基础概念","stem":"无人机飞行中，应当避让的第一优先级目标是（）。","A":"其他无人机","B":"有人驾驶航空器","C":"地面建筑物","D":"地面人员","answer":"B","exp":"避让规则的最高优先级是有人驾驶航空器：客机、直升机上载有人员且速度快、机动受限，无人机必须无条件主动避让；其他无人机、地面建筑物和人员同样需要避让或隔离，但优先级均低于有人驾驶航空器。"},{"id":1018,"type":"single","cat":"法规与空域","stem":"从事经营性无人机飞行活动，应当取得（）颁发的经营许可证。","A":"民用航空管理部门","B":"公安机关","C":"交通运输部门","D":"应急管理部门","answer":"A","exp":"从事经营性无人机飞行活动以营利为目的，须取得民用航空管理部门颁发的经营许可证方可开展；公安机关负责公共安全管理和违法查处，交通运输、应急管理部门的职责范围都不包含这类飞行经营许可。"},{"id":1019,"type":"single","cat":"基础概念","stem":"下列哪种类型的无人机飞行，无需提前申请飞行计划（）。","A":"轻型无人机在适飞空域内飞行","B":"中型无人机在农村地区飞行","C":"植保无人机在管控空域内飞行","D":"测绘无人机在城市上空飞行","answer":"A","exp":"轻型无人驾驶航空器在适飞空域内飞行属于一般飞行活动，按规定无需提前申请飞行计划；中型机飞行、管控空域内的植保作业、城市上空测绘要么涉及更大机型、要么进入管控空域，均须提前提交飞行活动申请并获批准后实施。"},{"id":1020,"type":"single","cat":"法规与空域","stem":"无人机实名登记的信息不包括下列哪项（）。","A":"所有者姓名/单位名称","B":"无人机型号、序列号","C":"无人机购买价格","D":"联系方式","answer":"C","exp":"实名登记采集的是可用于追溯和识别航空器的信息：所有者姓名或单位名称、联系方式、无人机型号与序列号等；购买价格属于交易信息，与安全监管和责任追溯无关，不在实名登记要求的信息之列。"},{"id":1021,"type":"single","cat":"法规与空域","stem":"机场净空保护区通常是指机场跑道中心线两侧各（）、跑道端外各20公里的范围。","A":"5公里","B":"10公里","C":"20公里","D":"50公里","answer":"B","exp":"机场净空保护区域按标准划设，通常覆盖跑道中心线两侧各10公里、跑道端外各20公里的范围，将起降航径和低空进近区域纳入保护；5公里范围偏小，20公里对应的是跑道端外的距离，50公里则明显过大。"},{"id":1022,"type":"single","cat":"法规与空域","stem":"根据《民用无人机驾驶员管理规定》，无人机驾驶员执照的有效期为（）。","A":"2年","B":"3年","C":"6年","D":"长期有效","answer":"C","exp":"依据民用无人机驾驶员管理相关规定，CAAC颁发的驾驶员执照有效期为6年，期满需按规定办理换发并满足近期飞行经历要求；2年、3年都不是现行规定的执照有效期，执照也并非长期有效不用管理。"},{"id":1023,"type":"single","cat":"基础概念","stem":"超视距飞行任务中，对飞行安全负全面责任的是（）。","A":"无人机驾驶员","B":"任务载荷操作员","C":"无人机机长","D":"地面站观察员","answer":"C","exp":"超视距任务中驾驶员难以目视判断状态，机长对飞行安全负全面责任：统一组织实施任务、监控飞行进程、处置特殊情况并作出最终决策；任务载荷操作员只负责设备作业，地面站观察员提供辅助瞭望，均不承担全面责任。"},{"id":1024,"type":"single","cat":"法规与空域","stem":"下列区域中，属于无人机管控空域的是（）。","A":"真高100米的乡村农田上空","B":"真高80米的城市公园上空","C":"民用机场障碍物限制面以内的空域","D":"真高120米以下的无人区上空","answer":"C","exp":"民用机场障碍物限制面以内的空域属于管控空域，飞行须经空域管理部门批准；真高100米的乡村农田、80米的城市公园和120米以下的无人区上空都处于真高120米以下的适飞空域范畴，按规定飞行即可。"},{"id":1025,"type":"single","cat":"基础概念","stem":"无人机飞行活动的统一监督管理部门是（）。","A":"中国民用航空局","B":"国家发展和改革委员会","C":"工业和信息化部","D":"公安部","answer":"A","exp":"无人驾驶航空器飞行活动由国务院民用航空主管部门即中国民用航空局统一监督管理，涵盖登记、人员执照与运行标准等环节；发展改革、工业和信息化、公安等部门在各自职责范围内协同管理，不承担统一监督职能。"},{"id":1026,"type":"single","cat":"基础概念","stem":"多旋翼无人机的核心飞行控制部件是（）。","A":"电调","B":"飞控","C":"GPS模块","D":"接收机","answer":"B","exp":"飞控是飞行控制系统的核心，负责融合陀螺仪、加速度计等传感器数据，实时解算飞行姿态，并按操纵指令分配各电机转速，实现稳定飞行。电调只是按指令执行电机调速，接收机只传递遥控信号，核心解算与决策都由飞控完成。"},{"id":1027,"type":"single","cat":"设备与维护","stem":"多旋翼无人机中，用于调节电机转速的部件是（）。","A":"飞控","B":"电调","C":"电池","D":"接收机","answer":"B","exp":"电调即电子调速器，接收飞控输出的控制信号，通过调节电机电流来控制电机转速，从而改变拉力大小。飞控负责解算姿态并发出指令，但不直接驱动电机；电池只负责供电，接收机只负责接收遥控信号。"},{"id":1028,"type":"single","cat":"设备与维护","stem":"民用无人机常用的锂聚合物电池（LiPo）的单体额定电压是（）。","A":"1.2V","B":"3.7V","C":"4.2V","D":"5.0V","answer":"B","exp":"锂聚合物电池单体的标称（额定）电压为3.7V，单节充满电时约4.2V。1.2V是镍镉、镍氢电池单体的典型电压，4.2V是满电电压而非额定电压，满电值与额定值最容易混淆。"},{"id":1029,"type":"single","cat":"操纵与飞行技术","stem":"下列传感器中，用于测量无人机姿态角速度的是（）。","A":"加速度计","B":"陀螺仪","C":"磁力计","D":"气压计","answer":"B","exp":"陀螺仪测量机体绕滚转、俯仰、偏航三轴旋转的角速度，是飞控姿态闭环控制的关键反馈元件。加速度计感知线加速度与重力方向，磁力计提供航向，气压计测量高度，都不直接输出角速度。"},{"id":1030,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机实现悬停的基本原理是（）。","A":"升力大于重力","B":"升力等于重力","C":"升力小于重力","D":"推力等于阻力","answer":"B","exp":"悬停时多旋翼各旋翼产生的总升力恰好等于整机重力，合外力为零，高度和水平位置保持不变；升力大于重力飞机爬升，小于重力则下降。推力等于阻力描述的是水平方向力平衡，与悬停的升重关系无关。"},{"id":1031,"type":"single","cat":"飞行原理","stem":"固定翼无人机产生升力的主要部件是（）。","A":"机身","B":"机翼","C":"尾翼","D":"螺旋桨","answer":"B","exp":"固定翼无人机依靠机翼与空气的相对运动，气流流过翼型上下表面形成压差而产生升力，机翼面积最大、翼型最关键，是主要升力部件。尾翼用于稳定与操纵，机身用于装载连接，螺旋桨提供前飞拉力而非主要升力。"},{"id":1032,"type":"single","cat":"领航与任务规划","stem":"无人机GPS模块的主要作用是（）。","A":"测量飞行高度","B":"获取位置与速度信息","C":"测量飞行姿态","D":"接收地面控制信号","answer":"B","exp":"GPS模块接收卫星信号，解算出无人机的经纬度、高度等位置信息和运动速度，是定位导航、定点悬停与航线飞行的数据基础。测高主要由气压计完成，姿态由IMU解算，地面控制信号则由接收机接收。"},{"id":1033,"type":"single","cat":"设备与维护","stem":"多旋翼无人机的螺旋桨通常分为正桨和反桨，其主要作用是（）。","A":"提高飞行速度","B":"抵消反扭力","C":"增加升力","D":"降低阻力","answer":"B","exp":"电机带动螺旋桨旋转时，空气会对机体施加方向相反的反扭力，使机身朝反方向偏转；正桨与反桨旋转方向相反，反扭力相互抵消，机体才能保持航向稳定。其主要作用是平衡扭矩，与提高速度、增大升力无关。"},{"id":1034,"type":"single","cat":"设备与维护","stem":"下列不属于无人机飞控系统组成部分的是（）。","A":"惯性测量单元（IMU）","B":"GPS接收机","C":"任务载荷相机","D":"气压计","answer":"C","exp":"飞控系统由主控单元和IMU、GPS接收机、气压计等导航姿态传感器组成，负责姿态解算与飞行控制；任务载荷相机是为完成拍摄等任务挂载的设备，与飞行控制无关，因此不属于飞控系统的组成部分。"},{"id":1035,"type":"single","cat":"设备与维护","stem":"锂聚合物电池的安全储存电压通常为单体（）左右。","A":"3.7V","B":"3.85V","C":"4.2V","D":"3.2V","answer":"B","exp":"锂聚合物电池满电长期存放会加速老化甚至鼓包，深度放电又会损伤电芯，单体约3.85V（约半充状态）时电芯化学状态最稳定，是推荐的安全储存电压。3.7V是标称电压，4.2V是满电电压，均不宜作为长期存放状态。"},{"id":1036,"type":"single","cat":"基础概念","stem":"垂直起降固定翼无人机的优势是（）。","A":"续航时间比多旋翼短","B":"不需要跑道即可起降，且巡航速度快","C":"结构比多旋翼简单","D":"载重量比同级别多旋翼小","answer":"B","exp":"垂直起降固定翼兼具两类布局的优点：垂直起降阶段像多旋翼一样无需跑道，巡航阶段靠机翼升力高效飞行，速度快、航程远、续航长。其结构通常比多旋翼更复杂，优势集中在起降方式与巡航效率上。"},{"id":1037,"type":"single","cat":"设备与维护","stem":"无人机接收机的主要作用是（）。","A":"发送飞行状态数据到地面站","B":"接收遥控器的控制信号","C":"接收卫星定位信号","D":"处理飞行姿态数据","answer":"B","exp":"接收机安装在无人机上，用于接收地面遥控器发出的无线电控制信号，解码后送入飞控，实现对飞行器的实时操纵。向地面回传飞行数据是数传电台的任务，卫星定位信号由GPS模块接收，姿态数据由飞控处理。"},{"id":1038,"type":"single","cat":"设备与维护","stem":"下列哪种电池类型的能量密度最高（）。","A":"铅酸电池","B":"镍氢电池","C":"锂聚合物电池","D":"磷酸铁锂电池","answer":"C","exp":"常见电池中锂聚合物电池的能量密度最高，单位重量储存电能多、放电倍率大，成为无人机主流动力电源。铅酸、镍氢电池笨重且能量密度低；磷酸铁锂安全性好、循环寿命长，但能量密度低于锂聚合物。"},{"id":1039,"type":"single","cat":"基础概念","stem":"多旋翼无人机的三轴姿态指的是（）。","A":"滚转轴、俯仰轴、偏航轴","B":"X轴、Y轴、Z轴","C":"横轴、纵轴、竖轴","D":"速度轴、加速度轴、姿态轴","answer":"A","exp":"多旋翼的三轴姿态指机体绕三条相互垂直的机体轴的转动：绕纵轴的滚转、绕横轴的俯仰、绕竖轴的偏航，飞控对这三个通道闭环控制即可实现姿态调节。X、Y、Z只是坐标系表述，速度轴等说法并非姿态术语。"},{"id":1040,"type":"single","cat":"飞行原理","stem":"根据伯努利原理，流体流速越快，压强（）。","A":"越高","B":"越低","C":"不变","D":"不确定","answer":"B","exp":"伯努利原理指出，理想流体流速越大的位置压强越低。机翼上表面翼型弯曲、流管收缩、气流速度快，压强低于流速较慢的下表面，上下压差形成升力，这是固定翼升力的经典解释。"},{"id":1041,"type":"single","cat":"飞行原理","stem":"固定翼无人机的失速是指（）。","A":"飞行速度过低导致升力不足","B":"迎角超过临界迎角，升力急剧下降","C":"发动机失去动力","D":"舵面失效无法操纵","answer":"B","exp":"失速的本质是迎角超过临界迎角后，机翼上表面气流大面积分离，升力随迎角增大不增反降。它与发动机停车、舵面失效无关；速度过低只是诱发大迎角的因素之一，并非失速的定义本身。"},{"id":1042,"type":"single","cat":"飞行原理","stem":"下列哪种阻力属于诱导阻力（）。","A":"机身摩擦阻力","B":"螺旋桨阻力","C":"机翼升力产生的附加阻力","D":"起落架阻力","answer":"C","exp":"诱导阻力是伴随升力产生的附加阻力：下表面高压气流绕过翼尖流向低压的上表面，形成翼尖涡流，其能量损耗表现为阻力。机身摩擦阻力、起落架等附件阻力属于废阻力，与升力无直接关联，不是诱导阻力。"},{"id":1043,"type":"single","cat":"基础概念","stem":"多旋翼无人机向左偏航（机头左转）时，通常的操作逻辑是（）。","A":"左侧电机加速，右侧电机减速","B":"右侧电机加速，左侧电机减速","C":"顺时针旋转的桨加速，逆时针旋转的桨减速","D":"逆时针旋转的桨加速，顺时针旋转的桨减速","answer":"C","exp":"多旋翼靠电机反扭力差实现偏航：机头向左偏转时，飞控使顺时针旋转的桨加速、逆时针旋转的桨减速，反扭力差形成向左的偏航力矩。按左侧或右侧电机增减速描述的是滚转与俯仰控制逻辑，与偏航无关。"},{"id":1044,"type":"single","cat":"飞行原理","stem":"固定翼无人机的升阻比是指（）。","A":"升力与阻力的比值","B":"阻力与升力的比值","C":"升力与重力的比值","D":"推力与阻力的比值","answer":"A","exp":"升阻比是同一状态下升力与阻力的比值，反映机翼气动效率，升阻比越大，获得同样升力需克服的阻力越小，巡航越经济。它不是阻力与升力之比，也与重力、推力无直接比值关系。"},{"id":1045,"type":"single","cat":"设备与维护","stem":"下列关于重心位置的说法，正确的是（）。","A":"重心越靠前，无人机静稳定性越强","B":"重心越靠后，无人机静稳定性越强","C":"重心位置与稳定性无关","D":"重心在焦点之前，无人机是静不稳定的","answer":"A","exp":"重心位于焦点之前时，附加升力产生的俯仰力矩使飞机趋向恢复原姿态，具有静稳定性；重心越靠前恢复力矩力臂越长，静稳定性越强，但操纵变钝、配平负担增大。认为重心在焦点之前飞机反而静不稳定，正好说反了。"},{"id":1046,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机在爬升过程中，需要（）。","A":"所有电机同步加速","B":"所有电机同步减速","C":"前侧电机加速，后侧电机减速","D":"左侧电机加速，右侧电机减速","answer":"A","exp":"多旋翼爬升只需增大总拉力，各电机同步加速使总升力超过重力，机体保持姿态平稳上升；若只增减某一侧电机，会形成滚转或俯仰力矩使机体倾斜，那是姿态控制的手段，不是爬升的正确操作。"},{"id":1047,"type":"single","cat":"飞行原理","stem":"临界迎角是指（）。","A":"产生最大升力的迎角","B":"产生最小阻力的迎角","C":"产生最大升阻比的迎角","D":"失速后的迎角","answer":"A","exp":"迎角增大时升力系数随之增大，超过某一角度后上翼面气流大面积分离，升力骤降，该转折角度就是临界迎角，对应最大升力系数。最小阻力迎角、最大升阻比迎角是另外的气动特征点，与临界迎角不是一回事。"},{"id":1048,"type":"single","cat":"飞行原理","stem":"下列哪种飞行状态下，固定翼无人机的诱导阻力最大（）。","A":"高速巡航","B":"低速大迎角飞行","C":"下降阶段","D":"平飞加速","answer":"B","exp":"诱导阻力大致与升力系数的平方成正比、与飞行速度的平方成反比，低速飞行需用大迎角维持升力，升力大而速度小，诱导阻力达到最大；高速巡航时速度大、迎角小，诱导阻力占比很小。"},{"id":1049,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机实现机头低头的俯仰动作，需要（）。","A":"前侧电机加速，后侧电机减速","B":"前侧电机减速，后侧电机加速","C":"左侧电机加速，右侧电机减速","D":"左侧电机减速，右侧电机加速","answer":"B","exp":"机头低头是俯仰向下的姿态变化：前侧电机减速使前部拉力减小，后侧电机加速使后部拉力增大，形成低头力矩，机体绕横轴前倾。左右两侧电机的差动控制产生的是滚转动作，与俯仰无关。"},{"id":1050,"type":"single","cat":"飞行原理","stem":"空气密度对无人机升力的影响是（）。","A":"空气密度越大，升力越大","B":"空气密度越大，升力越小","C":"空气密度与升力无关","D":"仅影响固定翼，不影响多旋翼","answer":"A","exp":"升力与空气密度成正比，密度越大，单位时间内参与作用的空气质量越多，机翼或旋翼能产生的升力越大；高原、高温条件下空气稀薄，升力下降，需要提高转速或延长滑跑距离来补偿，对固定翼和多旋翼同样成立。"},{"id":1051,"type":"single","cat":"基础概念","stem":"对无人机飞行影响最大的大气层是（）。","A":"对流层","B":"平流层","C":"中间层","D":"散逸层","answer":"A","exp":"无人机飞行高度大多处于对流层内，该层集中了大气质量的绝大部分和几乎全部水汽与尘埃，云、雨、雾、风、雷暴等天气现象都发生在这里，对飞行影响最直接、最频繁，是飞行气象的重点层次。"},{"id":1052,"type":"single","cat":"航空气象","stem":"下列哪种云对飞行安全危害最大（）。","A":"卷云","B":"积雨云","C":"层云","D":"高积云","answer":"B","exp":"积雨云内部和周围存在强烈升降气流、雷电、冰雹和严重风切变，对飞行危害最大，必须绕开。卷云、高积云云体单薄、位于高空，层云主要带来低云幕和较差能见度，危害程度都远不及积雨云。"},{"id":1053,"type":"single","cat":"航空气象","stem":"风切变是指（）。","A":"风速的突然变化","B":"风向的突然变化","C":"风速或风向在短距离内的显著变化","D":"风力等级的变化","answer":"C","exp":"风切变指短距离内风速或风向发生显著变化的现象，可出现在水平方向或垂直方向，任一要素的突变都算风切变。起降阶段遭遇低空风切变，空速和升力骤变，极易导致失控，只提风速或只提风向都描述不完整。"},{"id":1054,"type":"single","cat":"航空气象","stem":"能见度是指（）。","A":"正常视力的人能看清最远目标的水平距离","B":"正常视力的人在当时天气条件下，能够从天空背景中看到和辨认出目标物的最大水平距离","C":"无人机摄像头能看清的最远距离","D":"雷达能探测的最远距离","answer":"B","exp":"能见度指在当时天气条件下，正常视力的人能够从天空背景中看到并辨认出目标物的最大水平距离，是衡量大气透明程度的要素。漏掉辨认目标物和天空背景这两个条件的说法不够严谨，与摄像头、雷达探测距离更无关系。"},{"id":1055,"type":"single","cat":"航空气象","stem":"低空风切变通常是指发生在（）以下的风切变，对无人机起降阶段威胁极大。","A":"100米","B":"500米","C":"1000米","D":"2000米","answer":"B","exp":"航空上通常把发生在离地500米以下的风切变称为低空风切变。这一高度正是无人机起降和低空飞行的主要活动范围，风切变引起空速突变、升力骤降，对起降阶段威胁极大，其余高度界定均不符合惯例。"},{"id":1056,"type":"single","cat":"操纵与飞行技术","stem":"下列哪种天气现象会导致无人机锂电池性能急剧下降（）。","A":"大风","B":"低温","C":"多云","D":"阴天","answer":"B","exp":"锂电池靠内部电化学反应放电，低温下电解液粘度增大、离子迁移变慢，内阻升高，可用容量和放电能力急剧下降，电压骤降甚至触发低压保护导致炸机，冬季飞行应给电池保温并预留电量余量。"},{"id":1057,"type":"single","cat":"航空气象","stem":"雷暴天气对无人机飞行的危害不包括（）。","A":"雷电损坏电子设备","B":"强阵风导致失控","C":"冰雹损坏机身结构","D":"能见度升高","answer":"D","exp":"雷暴的危害包括雷电击穿电子设备、强阵风使飞机失控、冰雹击伤机体结构，还常伴随暴雨使能见度降低，因此能见度升高不属于雷暴的危害，其余三项都是雷暴天气的典型风险源。"},{"id":1058,"type":"single","cat":"基础概念","stem":"大气中水汽凝结的条件不包括（）。","A":"水汽达到饱和","B":"有凝结核","C":"气温升高","D":"气温降低","answer":"C","exp":"水汽凝结需要两个基本条件：水汽达到饱和或过饱和状态，以及存在可供依附的凝结核；冷却降温是使空气达到饱和的主要途径。气温升高反而提高空气容纳水汽的能力，不利于凝结，不属于凝结条件。"},{"id":1059,"type":"single","cat":"航空气象","stem":"逆风飞行对多旋翼无人机的影响是（）。","A":"续航时间增加","B":"续航时间减少","C":"悬停稳定性提升","D":"相同油门下地速增大","answer":"B","exp":"逆风飞行时，无人机要克服迎面风分量，保持航迹需增大功率或迎角，地速减小使完成航线的时间拉长，单位距离能耗增加，续航时间减少。悬停在大风中还需持续修正姿态，同样更耗电。"},{"id":1060,"type":"single","cat":"航空气象","stem":"积冰对无人机飞行的影响是（）。","A":"增加重量，破坏气动外形","B":"仅影响固定翼，不影响多旋翼","C":"提高升力","D":"降低阻力","answer":"A","exp":"积冰附着在机翼和桨叶表面会破坏气动外形，升力下降、阻力增大，同时冰层增加机体重量，严重时诱发失速或动力不足。多旋翼桨叶同样会积冰，并非固定翼独有，积冰只降低气动性能，绝不会提高升力。"},{"id":1061,"type":"single","cat":"基础概念","stem":"下列关于气温垂直递减率的说法，正确的是（）。","A":"对流层内气温随高度升高而降低，平均每升高100米下降0.65​","B":"对流层内气温随高度升高而升高","C":"平流层内气温随高度升高而降低","D":"中间层内气温随高度升高而升高","answer":"A","exp":"对流层内气温总体随高度升高而降低，平均每上升100米约下降0.65℃，这就是气温垂直递减率。平流层因臭氧吸收紫外线增温，气温随高度升高而升高，与对流层趋势相反。"},{"id":1062,"type":"single","cat":"基础概念","stem":"无人机起飞前的检查项目不包括（）。","A":"电池电量","B":"螺旋桨安装是否牢固","C":"飞控校准状态","D":"无人机机身颜色","answer":"D","exp":"起飞前应检查电池电量、螺旋桨安装是否牢固、飞控与指南针校准状态、遥控链路通信等直接影响飞行安全的项目；机身颜色只是外观特征，不影响飞行性能与安全，不属于起飞前检查内容。"},{"id":1063,"type":"single","cat":"领航与任务规划","stem":"无人机航线规划时，返航高度应设置为（）。","A":"与飞行任务高度一致","B":"低于航线周边最高障碍物的高度","C":"高于航线周边最高障碍物至少30米","D":"越高越好","answer":"C","exp":"返航高度必须高于航线沿途最高障碍物并留出安全余量，通常要求至少高出30米，否则自动返航直线飞行途中可能撞上高楼、铁塔。返航高度与任务高度一致或低于障碍物都有撞机风险，设得过高则增加能耗和受风影响。"},{"id":1064,"type":"single","cat":"设备与维护","stem":"无人机飞行日志应当记录的内容不包括（）。","A":"飞行时间、地点","B":"飞行任务内容","C":"故障与异常情况","D":"驾驶员的饮食情况","answer":"D","exp":"飞行日志应记录飞行时间与地点、任务内容、设备状态、故障及异常情况和处置措施等，便于追溯飞行过程、分析安全隐患；驾驶员的饮食情况与飞行运行无直接关联，不属于日志记录内容。"},{"id":1065,"type":"single","cat":"领航与任务规划","stem":"下列关于无人机返航的说法，错误的是（）。","A":"低电量时应及时触发返航","B":"失联后无人机应自动返航","C":"返航时无需考虑周边障碍物","D":"返航前应确认返航点已正确记录","answer":"C","exp":"返航过程仍需规避障碍物：自动返航按记录高度直线飞行，返航高度低于沿途高楼、铁塔时照样会撞机，规划返航必须结合周边障碍情况；低电量及时返航、失联自动返航、确认返航点已记录都是正确做法，无需考虑障碍物的想法是错误的。"},{"id":1066,"type":"single","cat":"基础概念","stem":"超视距飞行时，地面站的主要作用不包括（）。","A":"实时监控飞行状态","B":"发送控制指令","C":"操纵遥控器目视飞行","D":"规划与调整航线","answer":"C","exp":"超视距飞行时人眼已看不到飞机，主要依靠地面站实时监控飞行状态、发送控制指令、规划和调整航线；操纵遥控器目视飞行属于视距内飞行方式，超视距下无法依靠目视操纵，不属于地面站的作用。"},{"id":1067,"type":"single","cat":"基础概念","stem":"无人机在人口稠密区上空飞行时，下列做法正确的是（）。","A":"尽量降低高度，拍摄更清晰的画面","B":"保持足够高度，确保故障时可滑翔至无人区","C":"飞越高楼顶部以获得更好的视野","D":"在人群正上方悬停","answer":"B","exp":"人口稠密区上空飞行必须保持足够高度余量，一旦动力失效或失控，飞机可利用高度和滑翔能力偏离人群坠落，最大限度降低地面伤亡风险。降低高度拍摄、贴楼顶飞行、在人群正上方悬停都会显著放大坠机伤人后果。"},{"id":1068,"type":"single","cat":"设备与维护","stem":"起飞前指南针（磁力计）校准的目的是（）。","A":"提高定位精度","B":"消除周围磁场干扰，保证航向准确","C":"测量飞行高度","D":"校准姿态","answer":"B","exp":"指南针通过感知地磁场确定航向，机体铁磁部件、通电线路及周围钢铁结构都会造成磁干扰，起飞前校准让磁力计建立准确的偏航基准，保证航向锁定和航线飞行方向正确。它不提高定位精度，定位由GPS完成。"},{"id":1069,"type":"single","cat":"基础概念","stem":"下列哪种情况可以进行无人机飞行（）。","A":"能见度不足100米的大雾天气","B":"风力6级的晴天（超出无人机抗风等级）","C":"夜间在开阔无人区进行视距内飞行（符合当地规定）","D":"雷雨天气","answer":"C","exp":"夜间在开阔无人区进行视距内飞行，符合当地规定并具备照明等条件时可以实施；大雾能见度不足、超出抗风等级的6级大风、雷雨天气都直接威胁飞行安全，不应冒险起飞。"},{"id":1070,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停时出现漂移，最不可能的原因是（）。","A":"GPS信号不良","B":"风速过大","C":"电池电量不足","D":"飞控未校准","answer":"C","exp":"悬停漂移多与定位和姿态控制相关：GPS信号不良使位置修正不准，风速过大机体被吹偏，飞控校准不当导致姿态解算偏差。电量不足影响续航时间和动力余量，不直接改变悬停控制回路的工作，是最不可能的原因。"},{"id":1071,"type":"single","cat":"领航与任务规划","stem":"任务规划时，下列哪项不是需要重点考虑的因素（）。","A":"空域限制","B":"地形与障碍物","C":"气象条件","D":"无人机的生产厂家","answer":"D","exp":"任务规划的重点是空域限制、地形与障碍物、气象条件等直接关系飞行安全和任务可行性的因素；生产厂家只是设备来源信息，与航线设计、风险控制没有直接关系，不属于规划重点。"},{"id":1072,"type":"single","cat":"操纵与飞行技术","stem":"无人机着陆时，下列做法正确的是（）。","A":"快速下降以节省时间","B":"选择平坦、开阔、无障碍物的场地","C":"在人员密集的地方降落","D":"无需检查降落场地，直接降落","answer":"B","exp":"着陆应选择平坦、开阔、无障碍物的场地，保证接地平稳并留出处置余量；快速下降易造成重着陆损伤结构，在人员密集处降落或不检查场地直接降落，都会放大坠机伤人毁物的风险。"},{"id":1073,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中失去GPS信号后，首先应（）。","A":"立即推杆降落","B":"切换至姿态模式，尝试目视飞回","C":"等待GPS信号恢复","D":"直接触发返航","answer":"B","exp":"失去GPS后定位定点功能失效，应尽快切换至姿态模式，依靠飞控姿态增稳并目视判断位置手动飞回，防止飞机漂移失控。无定位时等待信号或直接触发返航仍有撞障风险，盲目推杆降落更易摔机。"},{"id":1074,"type":"single","cat":"基础概念","stem":"无人机飞行中遇到有人驾驶航空器时，正确的处置方式是（）。","A":"保持原高度和航线飞行","B":"主动避让，下降高度或偏离航线","C":"拉升高度躲避","D":"原地悬停等待","answer":"B","exp":"无人机在重量、速度和防护能力上都远弱于有人驾驶航空器，相遇时必须主动避让，及时下降高度或偏离航线拉开间隔，让有人机优先通过；保持原航线、拉升抢高度或原地悬停都可能造成危险接近。"},{"id":1075,"type":"single","cat":"设备与维护","stem":"锂聚合物电池发生明火时，下列哪种处置方式是错误的（）。","A":"使用干粉灭火器扑灭明火","B":"用沙土覆盖隔绝氧气","C":"用水浇淋降温防止复燃","D":"直接用手拿起电池扔到室外","answer":"D","exp":"锂电池起火可用干粉灭火器扑灭明火，用沙土覆盖隔绝氧气，并持续浇水降温防止热失控复燃；直接用手拿起燃烧中的电池，喷射的火焰和高温电解液会造成严重灼伤，是绝对禁止的错误做法。"},{"id":1076,"type":"single","cat":"基础概念","stem":"无人机飞行中动力突然完全失效，正确的处置是（）。","A":"立即拉杆拉升","B":"选择合适的迫降场地，尽量减少人员与财产损失","C":"直接弃机逃跑","D":"继续飞行尝试恢复动力","answer":"B","exp":"动力完全失效后升力无法维持，应立即判断风向和地形，选择空旷、远离人群与建筑的场地迫降，并尽量调整姿态减小坠落冲击，把人员和财产损失降到最低；此时拉升已无动力支撑，继续飞行并不现实。"},{"id":1077,"type":"single","cat":"基础概念","stem":"无人机失联后，下列哪种做法是错误的（）。","A":"记录最后失联的位置与高度","B":"立即到失联区域正下方寻找","C":"在安全区域等待无人机自动返航","D":"必要时向空管部门报备","answer":"B","exp":"失联后飞机会按预设执行自动返航或悬停保护，跑到失联区域正下方寻找，等于站在坠落危险区之内，是错误做法。正确处置是记录失联位置与高度、在安全区域等待自动返航，必要时向空管部门报备。"},{"id":1078,"type":"single","cat":"设备与维护","stem":"飞行中发现无人机机身异常震动，首先应（）。","A":"继续飞行完成任务","B":"尽快降落检查","C":"拉升高度","D":"加速飞行","answer":"B","exp":"异常震动多源于桨叶破损变形、电机或轴承损坏、部件松动，继续飞行会加剧结构损伤甚至失控解体，正确做法是尽快安全降落并停机检查，排除故障后才能再次起飞；拉升或加速都会放大风险。"},{"id":1079,"type":"single","cat":"基础概念","stem":"无人机在人口稠密区发生故障即将坠机时，首要任务是（）。","A":"保护无人机设备","B":"保护地面人员安全","C":"保护任务载荷","D":"保护地面财产","answer":"B","exp":"无人机坠机最直接的危害是砸伤地面人员，处置的首要原则是人身安全优先，应尽力操纵飞机偏离人群坠向空旷处；设备、载荷和财产损失尚可弥补，人员伤亡无法挽回，故保护地面人员安全居首位。"},{"id":1080,"type":"single","cat":"基础概念","stem":"下列哪种行为属于无人机飞行安全违规行为（）。","A":"起飞前进行安全检查","B":"在适飞空域内按规定飞行","C":"酒后操纵无人机","D":"飞行前查看气象预报","answer":"C","exp":"酒后操纵会使反应速度、判断力和精细操纵能力明显下降，与酒后驾驶机动车性质相同，属于危害公共安全的违规行为；起飞前安全检查、在适飞空域按规定飞行、飞行前查看气象预报都是规范做法。"},{"id":1081,"type":"single","cat":"基础概念","stem":"无人机发生飞行安全事故造成人员伤亡或重大财产损失的，应当第一时间向（）报告。","A":"当地民用航空管理部门与公安机关","B":"无人机销售商","C":"无人机生产厂家","D":"当地街道办事处","answer":"A","exp":"造成人员伤亡或重大财产损失的飞行事故属于重大安全事件，应第一时间向当地民用航空管理部门和公安机关报告，由主管部门组织调查处理；销售商、厂家或街道办事处均不承担受理事故报告的职责。"},{"id":1082,"type":"multi","cat":"法规与空域","stem":"根据《无人驾驶航空器飞行管理暂行条例》，下列属于管控空域的有（）。","A":"民用机场障碍物限制面范围以内的空域","B":"真高120米以上的空域（除经批准的适飞空域外）","C":"军事禁区、军事管理区上空","D":"真高100米以下的乡村农田上空","answer":"ABC","exp":"民用机场障碍物限制面以内的空域划为管控空域，防止与起降的航空器冲突；未经批准，真高120米以上的空域属于管控空域，轻型无人机不得进入；军事禁区、军事管理区上空绝对禁止飞行。真高100米以下的乡村农田一般属于适飞空域，不属于管控空域。"},{"id":1083,"type":"multi","cat":"法规与空域","stem":"下列关于无人机驾驶员执照的说法，正确的有（）。","A":"视距内驾驶员执照理论考试合格线为70分","B":"超视距驾驶员执照理论考试合格线为80分","C":"执照有效期为6年","D":"执照到期后无需审验，自动延续","answer":"ABC","exp":"视距内驾驶员理论考试以70分为合格线，符合规定；超视距驾驶员要求更高，合格线为80分，同样正确；民用无人机驾驶员执照有效期为6年；执照到期并不会自动延续，须按规定申请换发并满足飞行经历等审验要求。"},{"id":1084,"type":"multi","cat":"基础概念","stem":"无人机飞行前，应当完成的准备工作包括（）。","A":"查看飞行空域的限制要求","B":"查询飞行时段的气象条件","C":"检查无人机设备状态","D":"确认飞行计划已获批（如需）","answer":"ABCD","exp":"飞行前应查看空域限制要求，避开禁飞区、限飞区和临时管制区；查询飞行时段的气象条件，确认风速、降水、能见度满足飞行标准；逐项检查无人机设备状态，保证电量、螺旋桨、链路正常；凡需要批准的飞行活动，还须确认飞行计划已获批。四项都是起飞前的必备准备工作。"},{"id":1085,"type":"multi","cat":"设备与维护","stem":"下列属于多旋翼无人机飞控系统核心传感器的有（）。","A":"陀螺仪","B":"加速度计","C":"磁力计","D":"气压计","answer":"ABCD","exp":"多旋翼飞控的姿态与导航解算依赖多传感器融合：陀螺仪测量三轴角速度，加速度计感知线加速度与重力方向，两者构成姿态估计的基础；磁力计提供航向基准，气压计辅助测量高度变化。四类传感器共同构成飞控核心传感器组合，缺一都会降低控制精度。"},{"id":1086,"type":"multi","cat":"设备与维护","stem":"锂聚合物电池的正确使用方法包括（）。","A":"避免过充过放","B":"低温环境下适当降低飞行强度","C":"满电状态长期储存","D":"发现鼓包后继续使用","answer":"AB","exp":"过充使单体电压超过上限、过放低于终止电压都会永久损伤电芯甚至引发起火，必须避免，正确；低温下锂电池放电能力骤降，应适当降低飞行强度并做好保温，也正确；满电长期存放会加速老化，应以单体约3.85V储存，错误；鼓包说明电芯内部已受损，继续使用有起火爆炸风险，必须立即停用，错误。"},{"id":1087,"type":"multi","cat":"基础概念","stem":"固定翼无人机的组成部分包括（）。","A":"机翼","B":"机身","C":"尾翼","D":"动力系统","answer":"ABCD","exp":"固定翼无人机的基本组成包括：机翼产生升力，机身装载设备并连接各部件，尾翼提供纵向与方向稳定性并承载俯仰、偏航操纵面，动力系统提供前飞拉力；此外还有起落装置和飞控舵机操纵系统等，四项均属于固定翼的组成部分。"},{"id":1088,"type":"multi","cat":"飞行原理","stem":"下列关于失速的说法，正确的有（）。","A":"失速是由于迎角超过临界迎角导致的","B":"失速仅发生在低速飞行时","C":"失速时升力会急剧下降","D":"高速飞行时不会发生失速","answer":"AC","exp":"失速的直接原因是迎角超过临界迎角后机翼上表面气流大面积分离，失速时升力急剧下降，这两点说法正确；失速本质是迎角问题而与速度大小无关，只要迎角超限，高速飞行同样可能失速，低速才会失速与高速不会失速的说法都不成立。"},{"id":1089,"type":"multi","cat":"基础概念","stem":"多旋翼无人机的三轴姿态控制包括（）。","A":"滚转控制","B":"俯仰控制","C":"偏航控制","D":"高度控制","answer":"ABC","exp":"多旋翼的姿态控制围绕三条机体轴进行：滚转控制使机体左右倾斜，俯仰控制使机头前俯后仰，偏航控制利用电机反扭力差实现机头转向，三者构成完整的三轴姿态控制。高度控制是升降通道的调节，不属于姿态控制范畴。"},{"id":1090,"type":"single","cat":"基础概念","stem":"固定翼无人机摩擦阻力产生的原因主要是（）。","A":"空气的粘性","B":"飞机表面与空气的接触面积","C":"飞机的总量","D":"飞机的型号","answer":"A","exp":"空气具有粘性，气流流过机体表面时形成附面层，粘性剪切作用在表面产生摩擦阻力，这是摩擦阻力的根本成因；机体表面积、光洁度只影响其大小，飞机重量与型号并非摩擦阻力的产生原因。"},{"id":1091,"type":"single","cat":"基础概念","stem":"无人机地面调试不包括（）。","A":"重心稳定度调试","B":"气动舵面调试","C":"动力系统调试","D":"抗风性测试","answer":"D","exp":"地面调试包括重心与稳定度调整、气动舵面行程和方向检查、动力系统转速与振动测试等可在地面完成的项目；抗风性取决于整机的气动响应与控制性能，必须在真实大风环境中飞行检验，地面无法模拟，不属于地面调试内容。"},{"id":1092,"type":"single","cat":"飞行原理","stem":"相同迎角，飞行速度增大一倍，阻力增加为原来的（）。","A":"一倍","B":"二倍","C":"四倍","D":"以上均不正确","answer":"C","exp":"气动阻力与飞行速度的平方成正比，速度增大一倍即变为原来的2倍时，阻力变为原来的4倍。按线性关系认为阻力只增加一倍，是忽略平方关系的典型错误。"},{"id":1093,"type":"single","cat":"操纵与飞行技术","stem":"遥控无人机着陆时，拉平低的修正方法是（）。","A":"发现有拉低的趋势，应适当地增大拉杆量","B":"发现有拉低的趋势，应停止拉杆或减小拉杆量","C":"发现有拉低的趋势，应推杆","D":"以上均不正确","answer":"A","exp":"拉平低说明接地前机头拉起不足、下沉速度偏大，发现拉低趋势时应适当增大拉杆量，继续抬起机头增大迎角、减小下沉率，使飞机柔和接地；停止拉杆、减小拉杆量或推杆都会加剧下沉，导致重着陆。"},{"id":1094,"type":"single","cat":"设备与维护","stem":"飞机场当地气温的变化，主要会影响以下哪种无人机的传感器。","A":"气压高度计","B":"磁罗盘","C":"速率陀螺","D":"以上均不正确","answer":"A","exp":"气压高度计依据大气压随高度变化的规律测高，而气压分布受气温影响，当地气温变化会使同一高度的气压基准偏移，造成气压示值误差，因此主要影响气压高度计；磁罗盘感测地磁、速率陀螺测角速度，与气温无直接关联。"},{"id":1095,"type":"single","cat":"领航与任务规划","stem":"地面站地图航迹显示系统可为无人机驾驶员提供飞行器（）等信息。","A":"飞行姿态","B":"位置","C":"飞控状态","D":"以上均不正确","answer":"B","exp":"地面站地图航迹显示系统将飞机定位数据叠加在电子地图上，实时提供飞行器的位置、航迹走向及其与地标的关系，便于驾驶员掌握飞机相对位置和航线偏差；飞行姿态由姿态仪表显示，飞控状态属于设备状态监控，均非地图航迹显示的内容。"},{"id":1097,"type":"single","cat":"设备与维护","stem":"四旋翼无人机，当逆时针的螺旋桨加速旋转，顺时针的螺旋桨减速旋转（）。","A":"飞机向左偏航","B":"飞机向右偏航","C":"飞机向右滚转","D":"飞机向上爬升","answer":"B","exp":"螺旋桨旋转时空气对机身施加反扭力：逆时针旋转的桨加速，其反扭力使机体获得顺时针方向的扭矩，顺时针旋转的桨减速使反向扭矩减小，合成力矩推动机头向右偏航。此时电机总拉力基本不变，不会引起爬升或滚转。"},{"id":1098,"type":"single","cat":"航空气象","stem":"遥控无人机着陆时，如果飞机处于逆侧风时（）。","A":"地速增大，收油门下滑和四转弯时机均应适当提前","B":"地速减小，收油门下滑和四转弯时机均应适当延后","C":"地速增大，收油门下滑和四转弯时机均应适当延后","D":"以上均不正确","answer":"B","exp":"逆侧风包含与航迹方向相反的风的分量，使地速减小，飞机下沉变缓、下滑距离拉长，因此收油门开始下滑和四转弯的时机都应适当延后；若按地速增大的思路提前操作，会偏离预定下滑点，造成偏差。"},{"id":1100,"type":"single","cat":"设备与维护","stem":"多旋翼无人机动平衡调试电机正反转平均值及（）。","A":"正反差值","B":"正差值","C":"反差值","D":"转速比","answer":"A","exp":"动平衡调试时先分别测出电机正转与反转的平均转速，再计算两者的差值，用以判断动力组安装是否对称、有无单边振动；正反平均值与正反差值结合起来，才能全面评估动力系统的动平衡状态。"},{"id":1101,"type":"single","cat":"设备与维护","stem":"电子调速器（电调）调参的方法有多种，使用遥控器的操作进行简单的设置、使用（）调参、使用电调调参软件调参等。","A":"飞行控制系统（自驾仪）","B":"编程卡","C":"电子调速器（电调）","D":"电机与飞行控制系统（自驾仪）","answer":"B","exp":"电调调参常用三种途径：通过遥控器的操作进行简单设置，使用专用编程卡逐项修改电调参数，或在电脑上用电调调参软件批量设定。编程卡携带方便、可现场快速读写参数，是介于遥控器设置和软件调参之间的常用工具。"},{"id":1102,"type":"single","cat":"基础概念","stem":"飞机的压力中心是（）。","A":"压力最低的点","B":"压力最高的点","C":"升力的着力点","D":"以上均不正确","answer":"C","exp":"压力中心是机翼上、下表面气动压力合力的作用点，即升力的着力点，其位置随迎角变化而前后移动，直接影响俯仰力矩与稳定性分析。把它当作压力最高或最低的点，混淆了合力作用点与个别点压强的概念。"},{"id":1103,"type":"single","cat":"操纵与飞行技术","stem":"自主飞行时，油门应该处于什么位置？（）","A":"中立位偏上","B":"中立位偏下","C":"中立位","D":"以上均不正确","answer":"C","exp":"自主飞行时高度与姿态由飞控闭环自动控制，油门杆保持在中立位置即可，升降由系统自动完成；人工偏置油门会与自动控制叠加，引起高度波动甚至冲突，无需也不应放在中立位偏上或偏下。"},{"id":1104,"type":"single","cat":"设备与维护","stem":"航测固定翼无人机在不同的大气环境下飞行测试必须校准（）传感器。","A":"气压计","B":"全球定位系统（GPS）","C":"磁罗盘","D":"角速度计","answer":"A","exp":"航测要求影像与高度数据精确对应，气压高度计在不同大气环境下的气压基准不同，每次飞行测试前必须校准气压计，使测高结果与当地实际气压匹配，保证航测成果的地理精度；GPS、磁罗盘和角速度计不受大气环境变化的直接影响。"},{"id":1106,"type":"single","cat":"基础概念","stem":"下面关于助手与飞手之间协作描述错误的是（）。","A":"助手可对B点一侧进行观察，保障无人机能够准确的完成航线","B":"助手可对速度进行观察，提醒飞手降速或增速","C":"助手可对横移宽度进行观察，提醒横移宽度是否合适","D":"助手可对无人机进行实时操控，纠正飞手的操控动作","answer":"D","exp":"助手的职责是观察与提醒：协助观察B点一侧保障航线准确完成、监视速度提示增减速、观察横移宽度是否合适，均属辅助配合；操纵权始终在飞手手中，助手无权实时操控无人机纠正飞手动作，否则互相干扰极易引发危险。"},{"id":1107,"type":"single","cat":"基础概念","stem":"遥控模型飞机具有一定的（），不要把它当做玩具。","A":"观赏性","B":"娱乐性","C":"危险性","D":"以上均不正确","answer":"C","exp":"遥控模型飞机带有高速旋转的桨叶，具有一定重量和飞行速度，失控坠落或触碰人体都会造成割伤、砸伤，具有一定危险性，必须遵守安全操作规范，在远离人群的场地飞行，绝不能把它当成玩具随意把玩。"},{"id":1108,"type":"multi","cat":"基础概念","stem":"电子地图插件应具备以下基本功能（）","A":"地面站所需要的永久图层和临时图层的创建","B":"地图属性设置，如图层设置、样式选择等","C":"对地图的一些基本操作，如拖动、放大、缩小等","D":"对地图图元的添加、删除、选定、移动等操作","answer":"ABCD","exp":"电子地图插件应支撑地面站的地图应用：创建地面站所需的永久图层和临时图层，提供图层设置、样式选择等地图属性配置，支持拖动、放大、缩小等基本浏览操作，并能对地图图元进行添加、删除、选定、移动等编辑管理，四项都是其应具备的基本功能。"},{"id":1109,"type":"multi","cat":"设备与维护","stem":"下面哪一项属于无刷电机的组成部分（）。","A":"电刷","B":"转轴","C":"漆包线","D":"轴承","answer":"BCD","exp":"无刷电机取消电刷、依靠控制器电子换相驱动定子绕组，结构上包括转轴、绕制定子绕组的漆包线和支撑转子的轴承等；电刷是有刷电机用来换向的部件，无刷电机中不存在，因此它不属于无刷电机的组成部分。"},{"id":1110,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆后应检查哪些方面？（）","A":"飞行器外观检查","B":"燃油动力飞行器需要称重检查","C":"各系统电量检查","D":"下载飞行参数并检查","answer":"ABCD","exp":"着陆后应检查飞行器外观有无损伤和变形，燃油动力的飞行器需称重检查以核对燃油消耗与是否漏油，检查各系统电量消耗情况，并下载飞行参数检查记录数据，为故障分析和下次飞行提供依据，四项都属于着陆后检查内容。"},{"id":1111,"type":"multi","cat":"电力巡检","stem":"在（）和其他特殊情况时，应及时对线路进行特殊巡视，以发现线路通道的异常现象及设备部件的缺陷及异常情况。","A":"气候剧烈变化","B":"自然灾害","C":"外力影响","D":"异常运行","answer":"ABCD","exp":"电力线路在气候剧烈变化、自然灾害、外力影响、异常运行及其他特殊情况时，应及时开展特殊巡视，以便发现线路通道的异常现象和设备部件的缺陷，防止缺陷发展成事故，四种情形都属于应启动特殊巡视的情况。"},{"id":1112,"type":"multi","cat":"基础概念","stem":"无人直升机出厂文件资料应至少包含：（）","A":"技术规格书","B":"操作手册","C":"出厂检验报告","D":"维护保养手册","answer":"ABCD","exp":"无人直升机出厂时应至少随附技术规格书、操作手册、出厂检验报告和维护保养手册，分别说明性能参数、操纵使用方法、质量检验结论和日常维护要求，保证用户能够正确验收、操作和保养设备，四项资料缺一不可。"},{"id":1114,"type":"single","cat":"基础概念","stem":"以下无冫机中，需要跑道起降的是（）？","A":"固定翼无冫机","B":"无冫直升机","C":"多旋翼无冫机","D":"六轴飞行器","answer":"A","exp":"固定翼无人机依靠机翼与空气的相对运动产生升力，必须在跑道上滑跑加速到离地速度才能起飞；无人直升机、多旋翼和六轴飞行器依靠旋翼直接产生升力，均可垂直起降，无需跑道。"},{"id":1115,"type":"single","cat":"基础概念","stem":"小型无人机，是指空机重量不超过（）千克或者最大起飞重量不超过（）千克的无人机，但不包括微型、轻型无人机。","A":"25，35","B":"15，35","C":"25，45","D":"15，25","answer":"D","exp":"按照《无人驾驶航空器飞行管理暂行条例》的分类，小型无人机指空机重量不超过15千克且最大起飞重量不超过25千克的无人驾驶航空器（微型、轻型除外），两个界限分别是15千克和25千克，其余数值组合均不符合该分类定义。"},{"id":1116,"type":"single","cat":"领航与任务规划","stem":"（）是指从航线上的任意点转入安全返航通道或从安全返航通道转向应急迫降点或机场。","A":"安全着陆策略","B":"航线转移策略","C":"安全返航策略","D":"以上均不正确","answer":"B","exp":"航线转移策略指飞机从航线上任意点转入安全返航通道，或从安全返航通道转向应急迫降点、机场的路径衔接方式，确保异常时沿预定安全路径离开任务航线；安全返航与安全着陆策略分别侧重返航决策和最终落地，与此定义不符。"},{"id":1117,"type":"single","cat":"领航与任务规划","stem":"电台、接收机、调速器、电池、GPS、电机（多旋翼无人机以下哪个组设备连接是正确的）？","A":"调速-电机-GPS-接收机","B":"接收机-调速器-电池-电台","C":"电池-调速器-电机","D":"以上均不正确","answer":"C","exp":"多旋翼动力回路的基本连接是电池为电调供电，电调按飞控指令调节输出、驱动电机，形成电池—电调—电机的供电控制链条；GPS和接收机是信息设备，接入飞控而非串入动力回路，把接收机串接在调速器与电池之间的连接明显错误。"},{"id":1118,"type":"single","cat":"基础概念","stem":"地面控制站飞行参数综合显示的内容包括（）。","A":"飞行与导航信息、数据链状态信息、设备状态信息、指令信息","B":"导航信息显示、航迹绘制显示以及地理信息的显示","C":"告警信息、地图航迹显示信息","D":"以上均不正确","answer":"A","exp":"地面控制站的飞行参数综合显示把飞行与导航信息、数据链路状态信息、设备状态信息和指令信息集中呈现在同一界面，使操作员全面掌握飞行状态；导航信息与航迹地图绘制、告警信息属于地面站其他显示功能模块，不在综合显示范畴之内。"},{"id":1119,"type":"single","cat":"操纵与飞行技术","stem":"（）主要包括起飞场地标注、着陆场地标注、应急场地标注，为操作员提供发射与回收以及应急迫降区域参考。","A":"场地标注","B":"任务区域标注","C":"警示标注","D":"以上均不正确","answer":"A","exp":"场地标注包括起飞场地标注、着陆场地标注和应急场地标注，在地图或现场为操作员标明发射、回收以及应急迫降区域的参考位置，便于异常情况下迅速选择备降地点；任务区域标注和警示标注分别对应任务范围与危险提示，不属于场地标注。"},{"id":1120,"type":"single","cat":"设备与维护","stem":"多轴飞行器飞控软件使用中要特别注意的事项，不包括（）。","A":"文件大小","B":"各通道正反逻辑设置","C":"版本","D":"以上均不正确","answer":"A","exp":"使用多轴飞控软件要特别注意各通道的正反逻辑设置，方向接反会直接导致操纵错误，还要关注软件与固件的版本是否匹配兼容；文件大小与飞控功能设置和飞行安全没有直接关系，不属于需要特别注意事项。"},{"id":1121,"type":"single","cat":"操纵与飞行技术","stem":"无人机在遥控下降时，驾驶员应注意（）。","A":"飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有右偏趋势，须抵住左舵","B":"飞机状态不会发生变化，不需做任何准备","C":"飞机下降时，油门收小，螺旋桨扭转气流减弱，飞机有左偏趋势，须抵住右舵","D":"以上均不正确","answer":"A","exp":"下降时收小油门，螺旋桨扭转气流（滑流）作用减弱，由此带来的左偏趋势相应减小，飞机呈现右偏趋势，需抵住左舵保持航向；认为下降中飞机状态不变或偏转方向相反的说法，都不符合螺旋桨滑流效应的规律。"},{"id":1122,"type":"multi","cat":"领航与任务规划","stem":"航线规划应远离（）、大风或切变风多发区，尽量避免跨越高速公路和铁路飞行。","A":"人口稠密区","B":"重要建筑和设施","C":"通讯阻隔区","D":"无线电干扰区","answer":"ABCD","exp":"航线规划应远离人口稠密区，降低坠机伤人风险；远离重要建筑和设施，避免撞击和次生危害；避开通讯阻隔区，防止链路中断失联；避开无线电干扰区，保证遥控与导航信号可靠；同时避开大风或切变风多发区，尽量避免跨越高速公路和铁路，防止坠落阻断交通。四项都应远离。"},{"id":1123,"type":"multi","cat":"基础概念","stem":"以下关于宽容度的描述，正确的是（）。","A":"宽容度高，能更完好地保留画面细节","B":"不同数码相机的宽容度是相同的","C":"宽容度有限，可能导致照片暗部细节无法展示","D":"宽容度有限，可能导致照片亮部细节无法展示","answer":"ACD","exp":"宽容度指相机能够记录的亮度范围能力：宽容度高，画面从暗部到亮部的细节能更完整保留，正确；不同数码相机的传感器与影像处理不同，宽容度并不相同，错误；宽容度有限时，超出记录范围的暗部或亮部细节都会丢失，照片可能出现死黑或死白，两种说法都正确。"},{"id":1124,"type":"multi","cat":"电力巡检","stem":"无人直升机进行输电线路巡检的主要巡检内容中对导地线可见光检测内容为（）。","A":"导地线断股","B":"锈蚀","C":"异物","D":"覆冰","answer":"ABCD","exp":"可见光检测依靠摄像拍照分辨导地线的外观异常：断股表现为线股断裂、松散翘起；锈蚀呈现表面变色和锈迹；异物指悬挂或缠绕在线上的飘挂物；覆冰可见冰层包裹线体。四类缺陷都通过外形、色泽变化表现出来，肉眼和可见光相机均可辨识，故全部属于导地线可见光检测内容。"},{"id":1125,"type":"multi","cat":"设备与维护","stem":"多旋翼无人机的动力电机调速可以采用（）的方法调速。","A":"电枢供电电压","B":"改变电机主磁通","C":"改变电枢回路总电阻","D":"改变外接电阻","answer":"ABC","exp":"直流电机的转速调节有三种基本途径：调节电枢供电电压实现平滑无级调速，是电调调速的主要方式；改变电机主磁通即弱磁调速；改变电枢回路总电阻，通过串入电阻调节电枢电流。单独改变外接电阻不属于规范的调速方法，还会增大损耗、降低效率，无人机动力系统不采用。"},{"id":1126,"type":"multi","cat":"电力巡检","stem":"无人直升机巡检系统的地面站系统包括（）、（）和（）等。","A":"硬件设备","B":"飞行控制软件","C":"检测软件","D":"通讯软件","answer":"ABC","exp":"无人直升机巡检系统的地面站由三部分组成：硬件设备如计算机、显示和数传设备，是系统运行载体；飞行控制软件负责航线规划、飞行监控与指令下发；检测软件处理巡检数据和影像。通讯功能由数传链路的硬件设备承担，不单独设通讯软件，故通讯软件不属于地面站组成部分。"},{"id":1127,"type":"single","cat":"基础概念","stem":"固定翼无人机电子调速器额定电流应与电动机的工作电流的关系是（）。","A":"大于","B":"小于","C":"等于","D":"不确定","answer":"C","exp":"电子调速器的额定电流应与电动机的工作电流相匹配，即等于工作电流，既能保证电调持续通过全部电流不过载，也不增加多余重量成本。最易误选大于：额定电流若小于工作电流，电调长期过载发热会烧毁，选型以匹配为准，而非盲目加大裕量。"},{"id":1128,"type":"single","cat":"设备与维护","stem":"某螺旋桨是正桨，是指（）。","A":"从多轴飞行器上方观察，该螺旋桨逆时针旋转","B":"从多轴飞行器上方观察，该螺旋桨顺时针旋转","C":"从多轴飞行器下方观察，该螺旋桨逆时针旋转","D":"以上均不正确","answer":"A","exp":"正桨与反桨按旋向区分：从多轴飞行器上方俯视，逆时针旋转的为正桨，顺时针旋转的为反桨，两者对角布置、反向旋转抵消反扭矩，机体才能保持航向稳定。易误选顺时针，那是反桨的定义；观察方位必须是上方俯视，从下方看感受恰好相反。"},{"id":1129,"type":"single","cat":"基础概念","stem":"可能需要处置的紧急情况不包括（）。","A":"控制站显示系统故障","B":"上行通讯链路故障","C":"飞控系统故障","D":"以上均不正确","answer":"C","exp":"需人工处置的紧急情况多发生在控制站和通讯链路环节，如显示系统故障使状态监视中断、上行链路故障使指令无法送达，都直接影响操纵，须按预案处置。飞控自身故障由机载保护逻辑和冗余设计处理，不在需人工处置的紧急情况之列。"},{"id":1130,"type":"single","cat":"设备与维护","stem":"调飞机遥控器的前四步是（）。","A":"新建模型、模型重命名、选择发射制式、失控保护","B":"新建模型、选择发射制式、定义开关、失控保护","C":"新建模型、选择发射制式、中立微调、行程量设置","D":"以上均不正确","answer":"B","exp":"遥控器调试先新建模型，开辟独立参数空间；再选择发射制式，确定调制方式和频点；然后定义开关，把通道功能分配到对应开关；最后设置失控保护，规定信号中断时舵面或电机的状态。中立微调与行程量设置是后续精细调整，不属于前四步。"},{"id":1131,"type":"single","cat":"设备与维护","stem":"一款无刷电机通电后电机卡顿，无法连续旋转，排查的项目不包括的是（）。","A":"检查电调信号线是否插紧","B":"电机引出线是否断线","C":"电调线与电调本体焊接是否松脱","D":"电机与电调线连接是否牢靠","answer":"A","exp":"无刷电机通电后卡顿、抖动不转，多为三相动力线接触不良：电机引出线断线、电机与电调连接松脱、电调线与本体焊接松脱都会造成换相紊乱。信号线只传输控制指令，插不紧表现为电机不启动、无响应，而不是卡顿，故不属于该项排查内容。"},{"id":1132,"type":"single","cat":"基础概念","stem":"一般不在（）的天气使用无人机，若无法避免，尽快使用完毕，断电擦干，风干或者放到防潮箱吸潮，确定湿气除净后再次使用。","A":"雨雪","B":"阴天","C":"晴朗","D":"多云","answer":"A","exp":"雨雪天水汽易侵入机体，引起电路板短路、接插件和电机锈蚀，低温还削弱电池放电能力，故一般不在雨雪天气使用无人机；若无法避免，用毕立即断电擦干、风干或放入防潮箱吸潮，确认湿气除净后再启用。阴天、多云无降水时可以正常飞行。"},{"id":1133,"type":"single","cat":"基础概念","stem":"真空速明显小于地速是什么原因？（）","A":"逆风","B":"顺风","C":"无风","D":"以上均不正确","answer":"B","exp":"地速等于真空速与风速沿航迹分量的矢量和。顺风时风从后方推动飞机，地速明显大于真空速，即真空速明显小于地速；逆风则相反，地速小于真空速。最易混淆的是逆风，那是空速大于地速的情形；无风时两者相等，故明显偏小对应顺风。"},{"id":1134,"type":"single","cat":"领航与任务规划","stem":"规划的航线遇有线路交叉跨越、临近边坡等情况，应保持足够的（）。","A":"净空距离","B":"安全距离","C":"飞行距离","D":"海拔高度","answer":"B","exp":"航线遇交叉跨越、临近边坡等复杂处，应与障碍物保持足够的安全距离，为阵风和定位误差留出裕量，防止碰撞或越界。易误选净空距离，它多指机场净空或线路电气间隙等专门概念；此处泛指飞行与障碍物间的间隔，规范表述为安全距离。"},{"id":1136,"type":"single","cat":"设备与维护","stem":"（）通常有刷电机的连续工作寿命在几百到1千多个小时，到达使用极限就需要更换碳刷，不然很容易造成轴承的磨损。","A":"无刷电机","B":"碳刷电机","C":"直流电机","D":"交流电机","answer":"B","exp":"有刷电机依靠碳刷与换向器接触实现换向，碳刷是易磨损件，连续工作寿命一般只有几百到一千多个小时，磨损到极限必须更换，否则碳粉与打火还会损伤轴承。无刷电机没有碳刷结构，寿命长得多，最易与这一描述混淆，故此处指的是碳刷电机。"},{"id":1138,"type":"single","cat":"基础概念","stem":"无人机（）配平主要考虑是沿纵轴的前后位置。","A":"气动焦点","B":"发动机","C":"重心","D":"机翼","answer":"C","exp":"配平主要调整重心沿机身纵轴的前后位置：重心过前或过后都会改变俯仰平衡，导致迎角失配、杆力异常，严重时影响稳定性与操纵性。气动焦点是升力增量的作用点，用于分析纵向静稳定性，最易与重心混淆，但配平调节的是载荷分布决定的重心。"},{"id":1139,"type":"multi","cat":"操纵与飞行技术","stem":"无人机着陆时，飞机（）都在随时发生变化。","A":"高度","B":"速度","C":"状态","D":"下降率","answer":"ABCD","exp":"着陆是高度、速度、状态、下降率同时变化的过程：随高度降低不断收油门、拉平，速度逐渐减小；俯仰姿态由下滑态转为拉平态再转为接地姿态；下降率从下滑值不断收小到轻接地。四者相互关联、同步变化，须动态协调控制，故全部正确。"},{"id":1140,"type":"multi","cat":"设备与维护","stem":"动力电池性能类检测包括（），具体检测方法参照QB/T2502相关规定。","A":"外观检测","B":"绝缘检测","C":"放电容量检测方法（蓄电池充电、20℃放电容量、-20℃放电容量、55℃放电容量）","D":"安全性能试验（过充电、短路、加热、挤压、针刺、振动）","answer":"ABCD","exp":"动力电池性能类检测包括：外观检测查看壳体有无变形破损；绝缘检测确认极柱与外壳间绝缘合格；放电容量检测按标准在20℃、-20℃、55℃等温度条件下充放电测定实际容量；安全性能试验做过充电、短路、加热、挤压、针刺、振动等项目验证安全边界，均参照QB/T 2502执行。"},{"id":1141,"type":"multi","cat":"基础概念","stem":"巡检飞行结束后，应及时做好（）等资料的归档。","A":"空域审批文件","B":"工作票（单）","C":"视频、影像资料","D":"航线信息库","answer":"ABD","exp":"巡检飞行结束后的资料归档针对飞行与组织过程资料：空域审批文件证明飞行手续合法齐全；工作票（单）记录作业组织与安全交底；航线信息库留存航线数据供复用管理。视频影像属于巡检成果数据，按成果流程单独移交处理，不列入飞行资料归档范围。"},{"id":1142,"type":"multi","cat":"领航与任务规划","stem":"航点类型指的是到达该航点时的动作类型，分为（）。","A":"起飞模式","B":"途径模式","C":"巡航模式","D":"着陆模式","answer":"BCD","exp":"航点类型指到达该航点时执行的动作：途径模式表示正常通过并转向下一航点；巡航模式按设定高度和速度巡航通过，常用于长直航线；着陆模式表示到达后执行降落程序。起飞由专门的起飞操作完成，不属于航点的动作类型，故不选。"},{"id":1143,"type":"multi","cat":"基础概念","stem":"无人机飞行前需要检查的项目有（）","A":"电池电量","B":"螺旋桨安装","C":"飞控系统","D":"遥控器信号","answer":"ABCD","exp":"起飞前检查围绕动力、结构、控制和链路展开：电池电量充足才有续航和返航余度；螺旋桨安装要牢固、方向正确、无裂纹；飞控系统自检确认传感器正常、参数无误；遥控器信号确认链路连通与强度足够。四项都直接关系飞行安全，缺一不可。"},{"id":1144,"type":"multi","cat":"航空气象","stem":"影响无人机飞行安全的气象因素有（）","A":"风速","B":"温度","C":"湿度","D":"能见度","answer":"ABCD","exp":"风速过大或阵风猛烈会超出抗风能力并加剧姿态波动；温度过高或过低影响电池放电、电机散热与器件工作范围；湿度过大易使设备受潮结露，雨雾中还可能引发短路；能见度差则影响视距内观察与避让。四项都直接关系飞行安全，均属应重点关注的气象因素。"},{"id":1145,"type":"multi","cat":"基础概念","stem":"多轴飞行器的优点包括（）","A":"垂直起降","B":"操作简单","C":"续航时间长","D":"可悬停","answer":"ABD","exp":"多轴飞行器靠多组旋翼差动实现升力与姿态控制：可垂直起降，无需跑道场地；操纵逻辑简单，易于学习和操控；能原地稳定悬停，适合航拍巡检等任务。其短板恰是续航：旋翼效率低、能耗大，多旋翼续航时间普遍较短，故续航时间长不属于其优点。"},{"id":1146,"type":"multi","cat":"基础概念","stem":"无人机在飞行中遇到的常见故障有（）","A":"电机故障","B":"电池故障","C":"信号丢失","D":"螺旋桨损坏","answer":"ABCD","exp":"飞行中的常见故障涵盖动力、能源、链路与结构四方面：电机故障如停转、异响导致推力失衡；电池故障如电压骤降、鼓包引发动力中断；信号丢失使遥控或图传中断，触发失控保护；螺旋桨损坏破坏升力平衡并引起剧烈振动。四类都是高发故障，检查和飞行中要重点防范。"},{"id":1147,"type":"multi","cat":"基础概念","stem":"无人机的应用领域包括（）","A":"物流配送","B":"测绘地理信息","C":"环境监测","D":"应急救援","answer":"ABCD","exp":"无人机应用已覆盖众多行业：物流配送利用其快速点对点运输能力；测绘地理信息通过航测获取影像并生成地图产品；环境监测对大气、水质、生态进行巡查取样；应急救援在灾情侦察、通信中继、物资投送中发挥机动优势。四个领域都是无人机当前广泛开展的应用方向。"},{"id":1148,"type":"multi","cat":"设备与维护","stem":"无人机的电池使用注意事项有（）","A":"避免过度放电","B":"避免高温存放","C":"定期充电保养","D":"不同容量电池混用","answer":"ABC","exp":"锂电池使用须避免过度放电，过放会造成容量永久损失甚至报废；避免高温存放，高温加速老化并有起火风险；长期存放应定期充电保养，将电量维持在储存电压附近。不同容量、新旧程度不同的电池混用充放电会因内阻和容量差异导致个别电芯过充过放，属禁止行为。"},{"id":1149,"type":"multi","cat":"基础概念","stem":"以下哪些情况会导致无人机信号干扰（）","A":"附近有高压电线","B":"周围有大量金属物体","C":"有其他无线设备工作","D":"飞行高度过高","answer":"ABC","exp":"高压电线附近存在强电磁场，会干扰罗盘和无线电链路；周围大量金属物体引起信号反射屏蔽，削弱链路并干扰磁航向；其他无线设备工作在同频段时造成同频或邻频干扰。飞行高度过高只会使信号因距离衰减变弱，本身并不构成干扰源，故不属于信号干扰的情形。"},{"id":1150,"type":"multi","cat":"基础概念","stem":"多轴飞行器的飞行模式有（）","A":"手动模式","B":"自动模式","C":"跟随模式","D":"返航模式","answer":"ABCD","exp":"多轴飞行器常见飞行模式包括：手动模式由飞手直接操纵各通道；自动模式按预设航线自主飞行；跟随模式使飞机自动跟随目标移动，多用于航拍跟拍；返航模式在触发失控保护或一键返航时自动返回起飞点。这些都是主流飞控固件提供的模式，故全部正确。"},{"id":1151,"type":"multi","cat":"基础概念","stem":"无人机飞行过程中，出现以下哪些情况需要立即降落（）","A":"电机冒烟","B":"电池过热","C":"信号持续丢失","D":"飞行姿态异常","answer":"ABCD","exp":"电机冒烟说明动力部件已过载或短路，随时可能失效；电池过热有鼓包甚至起火风险；信号持续丢失意味着失去有效控制；飞行姿态异常反映控制回路或气动状态失衡。这些情况都直接危及飞行安全，应立即降低高度、选择安全场地降落排查，故全部正确。"},{"id":1152,"type":"multi","cat":"设备与维护","stem":"无人机的飞控系统包含的主要部件有（）","A":"主控板","B":"传感器","C":"陀螺仪","D":"加速度计","answer":"ABCD","exp":"飞控系统以主控板为核心，运行姿态解算与控制算法；各类传感器负责感知飞行状态，其中陀螺仪测量机体角速率，用于阻尼和增稳；加速度计测量线加速度，参与姿态解算和水平修正。主控板与这些传感器共同构成飞控的基本硬件，四项均属其主要部件。"},{"id":1153,"type":"multi","cat":"操纵与飞行技术","stem":"无人机第四转弯后，有些情况下收油门的时机应当延迟，收油门的动作应适当减慢。它们是（）","A":"下滑点在预定下滑点的后面","B":"当时的高度低于预定高度","C":"速度小、下沉快","D":"逆风较大","answer":"ABCD","exp":"第四转弯后进入下滑着陆阶段，若下滑点落在预定下滑点之后，说明下滑角偏平、能量不足；当时高度低于预定高度、速度小而下沉快，同样表明能量储备不够；逆风较大时地速减小、下滑角变陡，下滑距离缩短。这些情形都应延迟并放缓收油门，保持推力补足能量，防止失速掉高度。"},{"id":1154,"type":"multi","cat":"基础概念","stem":"安装固定翼无人机时，以下（）说法是正确的。","A":"左右机翼安装角要一致","B":"水平尾翼和机翼的安装角要一致","C":"单垂尾飞机的垂直尾翼和水平尾翼夹角成90度","D":"左右垂起臂中心线应保证对称平行","answer":"ABCD","exp":"安装固定翼无人机时：左右机翼安装角必须一致，否则升力不对称引起滚转；水平尾翼与机翼的安装角按设计要求保持一致，保证纵向力矩平衡；单垂尾飞机的垂尾与水平尾翼夹角应成90度，确保安定面正交；左右垂起臂中心线对称平行，保证拉力线一致不产生偏航力矩。"},{"id":1155,"type":"multi","cat":"基础概念","stem":"无人机资质培训模拟器训练时，主要采取以下训练方法（）","A":"示范演练","B":"辅导训练","C":"小组训练","D":"个人训练","answer":"ABCD","exp":"模拟器训练采取四种方法：示范演练由教员演示标准操纵要领，学员观察模仿；辅导训练由教员在场指导，及时纠正操纵偏差；小组训练组织学员互相观摩讲评、交流经验；个人训练让学员独立反复练习、巩固技能。四种方法由看而练、循序渐进配合使用，故全部正确。"},{"id":1156,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统（飞控系统）的核心作用是？","A":"稳定无人机飞行姿态并控制飞行轨迹","B":"提供动力输出以驱动无人机前进","C":"接收并执行地面站的所有指令","D":"存储飞行过程中的所有传感器数据","answer":"A","exp":"本题考察无人机系统组成知识点，正确答案为A。飞控系统通过传感器（如陀螺仪、加速度计）实时感知无人机姿态，通过控制算法调整电机转速或舵面（如多旋翼调整各电机功率），实现姿态稳定（如悬停、俯仰、偏航）并执行预设飞行轨迹。选项B是动力系统（电机、电调）的功能；选项C是遥控器/地面站的功能；选项D是数据记录模块的功能，非飞控核心作用。"},{"id":1157,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，无人机在以下哪个区域飞行时，无需向空管部门申请空域许可？","A":"机场净空区外围5公里范围内","B":"城市人口密集区域上空","C":"国家重点文物保护单位上空","D":"海拔1000米以下的偏远山区（非军事、非管制区域）","answer":"D","exp":"根据民航法规，在非管制空域（如偏远山区、无人区等）飞行，若满足重量、高度等限制，无需申请空域许可。A、B、C选项均属于管制或限制飞行区域（机场净空区、人口密集区、重点文物区），需提前申请空域许可。D选项偏远山区（非军事、非管制区域）属于典型的低风险、非管制空域，符合条件。"},{"id":1158,"type":"single","cat":"基础概念","stem":"起飞前对无人机进行检查时，以下哪项是必须重点确认的？","A":"电池电压是否在安全范围内","B":"地面是否有无关人员停留","C":"遥控器天线是否完全展开","D":"无人机是否已完成实名登记注册","answer":"A","exp":"本题考察无人机飞行前检查的关键项目。起飞前必须确认电池电量充足（电压在安全范围），否则可能因电量不足导致飞行中失控。B选项属于环境安全检查（需确保周围无人员），但非设备本身检查项；C选项遥控器天线展开与否不影响核心功能；D选项实名登记为法规要求，与起飞前设备检查无关，因此A为正确答案。"},{"id":1159,"type":"single","cat":"设备与维护","stem":"起飞前对无人机电池进行检查时，以下哪项是必须重点关注的？","A":"电池外观是否有鼓包或漏液","B":"遥控器信号强度","C":"任务载荷是否安装牢固","D":"图传设备是否正常","answer":"A","exp":"本题考察无人机飞行前检查要点知识点。正确答案为A。分析：A选项电池外观是否有鼓包或漏液是电池检查的核心，鼓包或漏液可能导致电池短路、起火或爆炸，属于严重安全隐患；B选项遥控器信号强度属于飞行控制系统检查，与电池无关；C选项任务载荷是否安装牢固属于任务系统检查；D选项图传设备是否正常属于通信系统检查，均非电池检查重点。"},{"id":1160,"type":"single","cat":"飞行原理","stem":"无人机飞行时，旋翼产生升力的主要物理原理是基于哪个定律？","A":"伯努利原理","B":"牛顿第三定律","C":"万有引力定律","D":"楞次定律","answer":"A","exp":"本题考察旋翼升力产生的物理原理，正确答案为A。伯努利原理指出流体（空气）流速越快，压强越小。无人机旋翼高速旋转时，叶片上方空气流速快、压强低，下方流速慢、压强大，形成向上的压力差（升力）。选项B牛顿第三定律解释了旋翼对空气的作用力与反作用力，是升力的间接来源但非主要原理；选项C万有引力是重力来源，与升力无关；选项D楞次定律是电磁感应现象，与升力无关。"},{"id":1161,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照的有效期及签注要求是？","A":"6年，每2年进行签注","B":"5年，每年进行签注","C":"8年，每3年进行签注","D":"10年，无需签注","answer":"A","exp":"本题考察无人机驾驶员执照管理知识点。根据民航局规定，无人机驾驶员执照有效期为6年，需每2年进行签注（复训）以保持资质有效。选项B错误在于有效期5年及每年签注周期不符合规定；选项C错误为8年有效期及3年签注周期；选项D错误为10年有效期且无需签注，均不符合法规要求。"},{"id":1162,"type":"single","cat":"设备与维护","stem":"当无人机动力系统突发故障（如电机停止运转）时，正确的处置措施是？","A":"立即操控无人机迫降在人员密集区域以减少损失","B":"持续尝试反复开关遥控器重启动力系统","C":"保持飞行姿态，优先选择无障碍物的空旷区域迫降","D":"继续尝试通过地面站指令强制无人机升空脱离危险","answer":"C","exp":"本题考察应急处置原则知识点。动力故障时，首要原则是安全优先：A错误（人员密集区迫降易造成伤亡）；B错误（反复重启可能导致电池耗尽或二次故障）；D错误（动力失效无法强制升空）；C正确（利用剩余动能寻找安全区平稳迫降，避免失控风险）。"},{"id":1163,"type":"single","cat":"法规与空域","stem":"在以下哪种情况下，无人机驾驶员必须向空管部门申请飞行空域许可？","A":"在机场净空区5公里范围内飞行","B":"在人口密集的城市中心区飞行","C":"在自然保护区核心区上空飞行","D":"以上均不需要申请","answer":"A","exp":"本题考察无人机飞行空域申请要求。根据《民用无人驾驶航空器实名制登记管理规定》，机场净空区（通常机场周边5公里范围内）属于敏感空域，飞行前必须向空管部门申请许可。B选项城市中心区人口密集区域为禁飞区（除非特殊申请）；C选项自然保护区核心区禁止任何飞行活动；D选项与法规要求矛盾。因此正确答案为A。"},{"id":1164,"type":"single","cat":"领航与任务规划","stem":"当无人机GPS信号突然失灵时，以下哪种操作是正确的应急措施？","A":"立即执行返航操作","B":"切换至姿态模式并保持手动控制","C":"关闭无人机电源并迫降","D":"继续使用自动避障功能飞行","answer":"B","exp":"本题考察无人机GPS失灵时的应急处置知识点。GPS失灵后，无人机失去卫星定位，需切换至姿态模式（手动模式），依靠飞控系统的姿态传感器（陀螺仪、加速度计）保持稳定飞行，避免因失控导致坠机。A选项中GPS失灵时无法准确执行返航；C选项关闭电源会直接导致无人机坠落；D选项自动避障功能依赖GPS定位数据，失灵后无法正常工作。因此正确答案为B。"},{"id":1165,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行时，负责稳定飞行姿态、执行飞控指令（如悬停、转向）的核心系统是？","A":"飞控系统","B":"动力系统","C":"图传系统","D":"遥控系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（飞行控制系统）是无人机的核心控制系统，通过传感器实时监测姿态参数（如俯仰角、滚转角），并通过控制算法稳定飞行姿态、执行预设或遥控指令。选项B（动力系统）负责提供飞行动力，C（图传系统）用于传输航拍画面，D（遥控系统）仅负责地面指令传输，均不具备稳定飞行姿态的功能。"},{"id":1166,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，以下哪种无人机驾驶员必须持相应执照？","A":"最大起飞重量＞7千克","B":"最大起飞重量＞15千克","C":"最大起飞重量＞25千克","D":"最大起飞重量＞5千克","answer":"B","exp":"本题考察无人机驾驶员执照适用条件。根据民航局规定，最大起飞重量＞15千克的民用无人机（轻型或微型）需驾驶员持照；A选项7千克以下属于轻型无人机，通常无需执照；C、D选项数值不符合民航局明确规定的执照适用阈值，因此正确答案为B。"},{"id":1167,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项检查是确保飞行安全的首要步骤？","A":"检查螺旋桨是否安装牢固且无损坏","B":"检查无人机电池电量是否充足","C":"检查飞行场地是否有无关人员和障碍物","D":"检查遥控器与无人机的连接是否正常","answer":"B","exp":"本题考察无人机起飞前检查流程。电池电量不足（B）直接导致飞行中失电坠机，是最致命风险；A（螺旋桨）、C（场地）、D（连接）均为重要检查项，但电池电量是飞行动力的基础，无电则无法飞行。因此首要步骤为B。"},{"id":1168,"type":"single","cat":"领航与任务规划","stem":"当无人机在飞行中突然发生GPS信号丢失时，应优先采取的处置措施是？","A":"立即关闭电源迫降","B":"尝试切换至手动模式并执行返航操作","C":"继续保持自动模式并尝试悬停","D":"加大油门爬升以摆脱信号干扰","answer":"B","exp":"本题考察无人机应急处置知识点。GPS信号丢失后，飞控系统可能因定位失效导致失控风险。此时优先操作：①切换至手动模式（选项B，手动模式下可通过遥控器直接控制无人机姿态，避免自动模式的不可控性）；②执行返航操作（利用返航点记忆功能返回起飞点，确保安全）。选项A（关闭电源）会导致无人机无动力坠落，损坏设备；选项C（继续自动模式）可能因GPS失效引发剧烈晃动或直接坠机；选项D（加大油门爬升）会增加失控概率且无法解决信号问题。因此正确选项为B。"},{"id":1169,"type":"single","cat":"法规与空域","stem":"根据民航局规定，重量大于多少克的民用无人机需在实名登记系统中进行登记备案？","A":"250克","B":"200克","C":"500克","D":"1000克","answer":"A","exp":"本题考察无人机实名登记法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》，重量大于0.25千克（即250克）的民用无人机需在民航局无人机实名登记系统中进行实名登记，未登记不得飞行。选项B（200克）低于规定阈值，选项C（500克）和D（1000克）属于更大重量级别，均非法规规定的最低登记标准，故正确答案为A。"},{"id":1170,"type":"single","cat":"基础概念","stem":"在视距内飞行时，微型无人机的最大允许飞行高度通常不超过以下哪个数值？","A":"50米","B":"100米","C":"120米","D":"150米","answer":"C","exp":"本题考察无人机飞行高度限制知识点。根据《民用无人驾驶航空器实名制登记管理规定》及飞行安全标准，微型无人机在视距内飞行时，为避免与其他飞行器冲突，最大高度限制为120米。选项A（50米）和B（100米）过低，不符合实际操作标准；选项D（150米）超过视距内安全高度范围，可能导致空域冲突风险。"},{"id":1171,"type":"single","cat":"设备与维护","stem":"在无人机飞行过程中，若突然发生图传信号中断，应优先采取以下哪种措施？","A":"立即尝试手动操作无人机继续飞行","B":"执行紧急返航程序并远离人群","C":"增大油门使无人机快速爬升以恢复信号","D":"关闭遥控器电源后重新开机","answer":"B","exp":"本题考察飞行中突发故障的应急处置。图传信号中断可能意味着无人机失去控制或失联，此时优先执行紧急返航程序并远离人群，避免坠落在人员密集区域。A选项手动操作可能因失去信号无法控制；C选项加大油门可能加剧失控风险；D选项重启遥控器无法解决信号中断问题，因此B为正确答案。"},{"id":1172,"type":"single","cat":"基础概念","stem":"当无人机在飞行过程中突然与地面站失去通信连接时，驾驶员应优先采取的措施是？","A":"立即操作无人机执行返航指令","B":"尝试手动重新连接地面站","C":"启动紧急迫降程序（如迫降在安全区域）","D":"保持当前高度等待通信自动恢复","answer":"C","exp":"本题考察无人机失联应急处理。正确答案为C，失联时无人机可能因姿态失控或位置未知，无法执行返航指令（选项A）；手动重新连接需地面站支持，无法立即完成（选项B）；等待恢复可能导致无人机持续失控或坠机（选项D）。启动紧急迫降（如选择空旷安全区域迫降）是确保人员和设备安全的优先措施。"},{"id":1173,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统（飞控系统）的核心功能是？","A":"接收并执行遥控器指令","B":"稳定无人机姿态与飞行参数","C":"为动力系统提供电力","D":"记录飞行轨迹数据","answer":"B","exp":"正确答案为B，飞控系统通过传感器感知无人机姿态，通过PID算法稳定姿态、保持航向与高度；A选项是遥控器的功能；C选项为动力系统供电是电池模块的功能；D选项记录飞行数据通常由飞行数据记录器或地面站软件完成，非飞控核心功能。"},{"id":1174,"type":"single","cat":"航空气象","stem":"以下哪种气象条件下，无人机起飞前应暂停飞行计划？","A":"能见度300米","B":"风速10米/秒","C":"中度雾霾（能见度100-200米）","D":"温度15℃","answer":"C","exp":"本题考察无人机飞行环境知识点。A选项能见度300米在开放空域可满足目视飞行基本要求；B选项风速10米/秒（约5级风），多数消费级无人机抗风等级可达8-10米/秒，可尝试起飞；C选项中度雾霾（能见度100-200米）会严重降低无人机视觉避障系统的可靠性，增加碰撞风险，禁止起飞；D选项温度15℃属于常规环境，不影响飞行安全。正确答案为C。"},{"id":1175,"type":"single","cat":"基础概念","stem":"当无人机突然失控并可能坠向人群时，应优先采取的措施是？","A":"立即启动返航程序","B":"手动切断动力开关","C":"快速远离并远离人群","D":"尝试手动遥控修正姿态","answer":"C","exp":"本题考察无人机应急处置原则。安全优先原则下，失控无人机威胁人群安全时，首要任务是避免人员伤亡，应迅速远离危险区域。选项A（返航）可能因失控无法执行，B（切断动力）若直接坠落仍伤人，D（手动遥控）在失控状态下难以操作。因此正确答案为C。"},{"id":1176,"type":"single","cat":"基础概念","stem":"在下列哪种天气条件下，无人机应禁止起飞？","A":"风速达到6级（10.8-13.8m/s）","B":"能见度低于1000米","C":"有持续雷雨活动","D":"以上所有情况","answer":"D","exp":"本题考察无人机飞行的气象安全要求。A选项中，多数消费级无人机安全风速上限为5级（8.3-10.7m/s），6级风易导致无人机姿态失控；B选项能见度低于1000米时，目视避障和空域识别能力下降，存在碰撞风险；C选项雷雨天气伴随雷击、强气流和电磁干扰，会直接威胁设备安全和飞行稳定性。因此D选项以上所有情况均为禁止起飞的条件。"},{"id":1177,"type":"single","cat":"法规与空域","stem":"在机场净空保护区域内进行无人机飞行时，必须遵守的规定是？","A":"提前向当地空管部门申请并获得空域使用许可","B":"可在白天无需报备直接起飞","C":"仅需在夜间飞行前向机场塔台报备","D":"允许在无人看管的情况下进行飞行","answer":"A","exp":"本题考察无人机空域使用法规知识点。机场净空区属于受管制的空域，任何单位和个人进入该区域飞行均需提前向当地空管部门申请并获得空域使用许可（如飞行计划审批），因此A正确。B选项错误，因净空区禁止未经许可飞行；C选项错误，夜间飞行同样需要提前申请，且仅报备不足以获得合法飞行权限；D选项错误，无人看管飞行不符合安全操作规范，存在碰撞风险。"},{"id":1178,"type":"single","cat":"基础概念","stem":"以下哪项属于无人机明确禁止飞行的区域？","A":"军事管理区上空","B":"民用机场净空保护区域","C":"人口密集的城市中心区域","D":"以上均属于禁飞区","answer":"D","exp":"本题考察无人机禁飞区法规知识点。根据中国民航局及空域管理规定，军事管理区（A）、机场净空区（B）、人口密集区（C）均属于禁飞区或限制飞行区域，未经审批不得进入。因此A、B、C均为禁飞区，正确选项为D。"},{"id":1179,"type":"single","cat":"基础概念","stem":"起飞前检查中，必须重点确认的项目是？","A":"无人机电池剩余电量（≥80%）","B":"地面是否有无关人员停留","C":"起飞场地是否为硬质地面","D":"无人机GPS信号是否显示为红色","answer":"A","exp":"本题考察无人机飞行前检查要点。电池电量是飞行安全的基础，起飞前必须确保电池剩余电量≥80%（微型机可适当放宽至70%），否则可能因电量不足导致中途失压坠机。B选项地面无关人员属于场地安全检查，需在起飞前完成但非必须重点确认的核心项目；C选项硬质地面仅针对部分固定翼机型，且非普适性要求；D选项GPS信号红色通常表示信号弱或无定位，属于检查内容但优先级低于电池电量，故正确答案为A。"},{"id":1180,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中突发GPS信号丢失时，正确的处置措施是？","A":"立即切换至手动模式并快速拉升高度","B":"切换至姿态模式，保持悬停并寻找开阔区域","C":"继续使用GPS模式尝试返航","D":"直接关闭电源迫降","answer":"B","exp":"GPS丢失后，飞控系统会自动切换至姿态模式（依赖惯性测量单元IMU），此时应保持悬停并寻找开阔区域恢复信号或手动操作降落。A选项手动拉升高度可能因失去定位导致失控；C选项GPS模式已失效无法使用；D选项直接关闭电源易因惯性导致坠机，非安全处置。"},{"id":1181,"type":"single","cat":"基础概念","stem":"无人机飞行控制系统的核心组成部分是？","A":"飞控系统","B":"导航模块","C":"动力系统","D":"遥控系统","answer":"A","exp":"本题考察无人机系统结构。飞控系统（FlightControlSystem）是无人机飞行控制的核心，通过传感器采集数据、处理器计算姿态并输出指令，直接控制无人机飞行姿态和轨迹。B选项导航模块、C选项动力系统、D选项遥控系统均为无人机系统的子模块，非核心控制单元，因此正确答案为A。"},{"id":1182,"type":"single","cat":"设备与维护","stem":"无人机飞行中遭遇动力系统突发故障（如电机停转），以下哪种处置方式最安全？","A":"立即尝试重启发动机（螺旋桨）","B":"保持当前高度继续飞行至目的地","C":"迅速选择空旷无人员区域迫降","D":"立即切换至备用电池并返航","answer":"C","exp":"本题考察动力故障处置原则。A选项：若为螺旋桨断裂或电机卡死，重启无法实现，且盲目重启可能导致二次事故；B选项：持续飞行会因无动力急速坠落，增加风险；D选项：返航需动力维持，无动力时无法操作；C选项：优先确保安全，选择空旷区域迫降可避免人员和财产损失，符合安全第一原则。"},{"id":1183,"type":"single","cat":"设备与维护","stem":"多旋翼无人机飞行中突然出现单个电机停转，以下处置方式最合理的是？","A":"立即尝试切换至备用电池并迫降","B":"保持操控尝试手动降落至安全区域","C":"继续飞行至开阔地后紧急迫降","D":"重启飞控系统并继续执行任务","answer":"B","exp":"本题考察多旋翼无人机单电机故障应急处置。正确答案为B，多旋翼无人机单个电机停转后，机身会因力矩失衡倾斜，此时应立即手动操控剩余电机产生反扭矩，逐步降低高度并降落至安全区域。A选项切换备用电池适用于电池故障，与电机故障无关；C选项继续飞行会加剧失衡风险；D选项飞控系统重启无法解决电机硬件故障，且可能导致二次失控。"},{"id":1184,"type":"single","cat":"基础概念","stem":"无人机实现自主稳定飞行、姿态控制的核心系统是？","A":"飞控系统","B":"动力系统","C":"图传系统","D":"悬停系统","answer":"A","exp":"飞控系统（飞行控制系统）是无人机的大脑，通过传感器实时监测姿态、高度、速度等数据，自动调节电机输出实现稳定飞行和航线规划。B选项动力系统仅负责提供飞行动力；C选项图传系统用于传输航拍画面，不涉及飞行控制；D选项悬停是飞控系统实现的功能之一，非独立系统。"},{"id":1185,"type":"single","cat":"基础概念","stem":"起飞前无人机检查中，以下哪项属于必须确认的关键系统状态？","A":"电池剩余电量及电压","B":"飞控系统传感器校准状态","C":"遥控器与无人机的通讯信号强度","D":"以上均为必须确认项","answer":"D","exp":"本题考察无人机起飞前的系统检查要点。A选项电池状态直接决定飞行续航和稳定性，电量不足会导致突然失电；B选项飞控传感器（如GPS、IMU）校准失效会引发飞行姿态失控；C选项通讯信号弱或丢失会导致失联。三者均为起飞前必须确认的核心系统状态，缺一不可，故D正确。"},{"id":1186,"type":"single","cat":"法规与空域","stem":"以下哪种场景属于无人机法定禁飞区域？","A":"城市中心广场（非特殊活动时段）","B":"距离民用机场跑道入口5公里的空域","C":"国家测绘地理信息局划定的测绘作业区","D":"军事管理区外围1公里范围","answer":"B","exp":"本题考察无人机禁飞区法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》及《无人驾驶航空器经营性飞行活动管理办法》，民用机场净空区（通常为机场跑道两端及周边3-10公里范围内）属于法定禁飞区，选项B中距离跑道入口5公里符合净空区范围。选项A错误，城市中心广场可能受临时管制但非法定禁飞；选项C错误，测绘作业区通常需提前申请空域；选项D错误，军事管理区外围1公里无明确禁飞规定，因此正确答案为B。"},{"id":1187,"type":"single","cat":"航空气象","stem":"在视距内飞行时，小型多旋翼无人机起飞阶段的最大允许风速通常为？","A":"2级（≤1.6m/s）","B":"3级（3.4-5.4m/s）","C":"4级（5.5-7.9m/s）","D":"5级（8.0-10.7m/s）","answer":"B","exp":"本题考察无人机起飞风速限制知识点。小型多旋翼无人机起飞需避免强风干扰，3级风（风速3.4-5.4m/s）为安全范围。选项A（2级）过于保守；选项C（4级）和D（5级）风速过大，易导致无人机偏航、失控甚至坠毁，不符合安全规范。"},{"id":1188,"type":"single","cat":"基础概念","stem":"无人机起飞前，确保飞行安全的最重要基础检查环节是？","A":"检查遥控器与无人机的通讯连接是否正常","B":"检查无人机机身是否有明显损伤","C":"检查螺旋桨安装是否牢固且无变形","D":"检查地面是否有障碍物","answer":"C","exp":"本题考察无人机起飞前检查知识点。螺旋桨作为直接产生升力的部件，安装不牢固或变形会导致飞行中脱落、失衡甚至失控，是最基础且关键的安全隐患点；A（通讯检查）、B（机身损伤检查）、D（地面障碍物检查）均为重要检查项目，但螺旋桨安装质量直接决定飞行稳定性和安全性，是所有检查中最优先的基础环节，故正确答案为C。"},{"id":1189,"type":"single","cat":"基础概念","stem":"起飞前无人机检查中，以下哪项是必须检查的？","A":"螺旋桨叶片是否有裂纹或变形","B":"无人机内所有电子元件是否防水","C":"遥控器电池剩余电量是否充足","D":"飞行空域的实时天气情况","answer":"A","exp":"本题考察起飞前无人机检查要点。起飞前必须检查无人机硬件状态，螺旋桨作为动力传输关键部件，裂纹或变形会导致飞行失衡甚至坠机，属于必查项。选项B（防水检查非起飞前必查）、C（遥控器电量属于飞行准备阶段）、D（天气状况需提前查询而非起飞前检查无人机）均不符合检查要求。"},{"id":1190,"type":"single","cat":"航空气象","stem":"以下哪种气象条件下，无人机驾驶员应禁止起飞？","A":"能见度5公里（视距内标准）","B":"风速8m/s（多旋翼安全阈值内）","C":"轻度霾（能见度≥3公里）","D":"雷暴天气（伴随闪电、强风）","answer":"D","exp":"本题考察飞行气象条件知识点。雷暴天气伴随强对流、雷击及乱流，易导致无人机失控或坠机，属于绝对禁止起飞的气象条件。A/B/C项均为允许飞行的气象条件（能见度≥5公里满足视距标准，风速≤10m/s、轻度霾对飞行影响小）。因此正确答案为D。"},{"id":1191,"type":"single","cat":"基础概念","stem":"在进行无人机起飞和降落时，为确保安全，应与人群保持至少多少米的水平距离？","A":"5米","B":"10米","C":"15米","D":"20米","answer":"B","exp":"本题考察飞行安全操作规范。根据《民用无人驾驶航空器实名制登记管理规定》及飞行安全准则，起飞和降落阶段无人机操控难度较高，与人群需保持至少10米水平距离，以避免螺旋桨伤人或坠机风险。选项A距离过近，安全系数不足；C、D虽安全冗余更高，但法规标准中明确的基础安全距离为10米。故正确答案为B。"},{"id":1192,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统（飞控系统）的核心功能不包括以下哪项？","A":"稳定飞行姿态","B":"自主起飞与降落","C":"实时图像传输","D":"调整飞行参数","answer":"C","exp":"本题考察无人机系统组成知识点。飞控系统核心功能包括稳定飞行姿态（通过PID算法控制）、自主起飞/降落（预设控制逻辑）、调整飞行参数（如高度、速度）；而实时图像传输（FPV图传）属于独立的图传系统功能，由图传模块实现，非飞控系统范畴。因此正确答案为C。"},{"id":1193,"type":"single","cat":"领航与任务规划","stem":"当无人机在视距内飞行时突然发生GPS信号丢失且无法手动控制，最可能触发的安全机制是？","A":"无人机自动迫降在最近障碍物上","B":"无人机自动触发失控返航功能并悬停","C":"无人机立即切换至手动油门模式","D":"无人机持续向地面发送紧急求救信号","answer":"B","exp":"本题考察无人机失控处理机制。GPS丢失后，多数无人机默认触发失控返航（B），返回起飞点上空悬停等待指令，避免因失去定位导致坠机。A选项迫降非安全机制；C选项手动模式在GPS丢失后无法稳定控制；D选项无人机通常无独立求救信号发送功能，依赖地面站指令。"},{"id":1194,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，最大起飞重量在7千克至116千克之间的民用无人机属于哪一类？","A":"微型","B":"轻型","C":"小型","D":"大型","answer":"B","exp":"本题考察无人机分类知识点。中国民航局对民用无人机的分类标准为：微型无人机（最大起飞重量≤7千克）、轻型无人机（7千克＜最大起飞重量≤116千克）、小型无人机（116千克＜最大起飞重量≤5700千克）、大型无人机（最大起飞重量＞5700千克）。选项A（微型）重量范围错误；选项C（小型）重量下限错误；选项D（大型）重量范围远超题干描述。故正确答案为B。"},{"id":1195,"type":"single","cat":"法规与空域","stem":"在我国，以下哪种空域类型的无人机飞行通常需要提前向空管部门申请飞行计划？","A":"开放空域","B":"限制空域","C":"隔离空域","D":"通用空域","answer":"B","exp":"开放空域（如低空空域试点区域）无需申请飞行计划；限制空域（如机场净空区周边）需提前申请；隔离空域（军事禁区、禁飞区）严禁飞行。因此本题正确答案为B选项。"},{"id":1196,"type":"single","cat":"基础概念","stem":"起飞前对无人机进行检查时，以下哪项属于必须确认的关键内容？","A":"电池剩余电量及电压","B":"地面是否有无关人员","C":"无人机是否已完成注册登记","D":"图传设备是否连接正常","answer":"A","exp":"本题考察无人机起飞前的关键检查项目。电池是无人机动力来源，起飞前必须确认电池电压正常（如锂电池需达到额定电压，避免电量不足导致飞行中失控），故A为正确答案。B选项属于飞行空域安全确认，非无人机本身检查；C选项登记信息为静态备案，无需起飞前实时检查；D选项图传设备故障通常不影响起飞，仅影响作业时的图像传输。"},{"id":1197,"type":"single","cat":"基础概念","stem":"以下哪个区域属于无人机严格禁止飞行的区域？","A":"民用机场净空保护区域","B":"城市中心广场","C":"偏远山区无人区","D":"乡村农田上空","answer":"A","exp":"本题考察禁飞区法规。民用机场净空区（A）是民航安全的核心保障区域，根据《中华人民共和国民用航空法》，严禁任何无人机进入。城市中心广场（B）通常有临时禁飞规定，但优先级低于机场净空区；偏远山区（C）和乡村农田（D）在符合法规条件下可合法飞行。"},{"id":1198,"type":"single","cat":"基础概念","stem":"在城市人口密集区域飞行无人机时，应特别注意避开以下哪个区域？","A":"城市公园","B":"机场净空区","C":"军事管理区","D":"城市绿地","answer":"B","exp":"本题考察飞行空域安全知识点。机场净空区是为保障机场起降安全划定的严格禁飞区域，根据《民用机场管理条例》，任何单位或个人不得在机场净空区从事影响飞行安全的活动，因此必须避开。选项A城市公园、D城市绿地在符合条件下可飞行；选项C军事管理区属于禁飞区，但题目强调城市人口密集区域，军事管理区多位于非城市核心区，而机场净空区常分布于城市周边或内部，更需特别注意。故正确答案为B。"},{"id":1199,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，重量大于（）千克的民用无人机需要进行实名登记。","A":"0.25","B":"0.5","C":"1.0","D":"2.5","answer":"A","exp":"本题考察无人机实名登记的法规知识点，正确答案为A。根据规定，重量≥0.25千克（250克）的民用无人机必须进行实名登记，这是保障飞行安全和追溯管理的基础。选项B（0.5千克）通常是超视距飞行的重量限制标准，选项C（1.0千克）和D（2.5千克）均高于实名登记的法定阈值，因此错误。"},{"id":1200,"type":"single","cat":"基础概念","stem":"在以下哪种区域飞行时，无人机驾驶员必须提前向空管部门申请并获得飞行许可？","A":"城市中心广场","B":"机场净空区","C":"农村田野","D":"偏远山区","answer":"B","exp":"本题考察无人机禁飞区管理知识点。机场净空区属于受严格管制的空域，任何未经批准的无人机飞行都可能干扰机场正常运行，必须提前向空管部门申请并获得许可。选项A（城市中心广场）通常属于城市禁飞区，以限高/禁飞为主，无需单独申请；选项C（农村田野）和D（偏远山区）一般无需特殊申请，符合法规即可飞行。"},{"id":1201,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，以下哪项是最关键的安全检查内容？","A":"检查电池外观是否有鼓包或破损","B":"确认电池电压在标称电压±5%范围内","C":"仅需检查电池电量指示灯显示为绿色","D":"确保电池固定卡扣无松动","answer":"B","exp":"本题考察飞行前电池检查知识点。电池电压直接决定动力输出和续航能力，电压不足会导致飞行失控，是最核心的安全参数；外观检查（A）可辅助判断电池状态但非核心；电量指示灯可能受虚电影响，电压测量更准确；固定卡扣（D）属于机身结构检查，非电池安全检查的核心内容。"},{"id":1202,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中突然丢失GPS信号时，最安全的应急操作是？","A":"利用返航点记忆功能执行一键返航","B":"手动加大油门保持悬停","C":"尝试切换至‘姿态模式’手动控制","D":"立即关闭无人机电源迫降","answer":"A","exp":"本题考察无人机应急处置知识点。GPS丢失后，无人机可能进入失控或自稳模式，此时最安全的操作是利用预设的返航点（如起飞点）执行一键返航（通常由飞控系统自动完成，避免手动操作失误）。B选项手动加大油门可能因失去定位导致无人机失控；C选项姿态模式下无GPS辅助，手动控制难度极高，易碰撞；D选项立即迫降会造成设备损坏或人员风险。因此正确答案为A。"},{"id":1203,"type":"single","cat":"设备与维护","stem":"当无人机突然失控（如飞控系统故障）时，以下哪项操作是正确的应急处置措施？","A":"立即拉满油门使无人机快速爬升","B":"尝试通过遥控器执行手动返航程序","C":"切断无人机遥控器信号以停止飞行","D":"立即弃机远离人群，放弃无人机","answer":"B","exp":"本题考察无人机应急处置知识点。手动返航是失控时最直接的安全措施，可快速恢复无人机控制并返回安全区域；拉满油门（A）可能加剧失控或导致动力过载；切断遥控器信号（C）无效，无人机可能因惯性继续飞行；弃机（D）会造成设备损失，且未优先保障安全距离。"},{"id":1204,"type":"single","cat":"法规与空域","stem":"视距内驾驶员执照（驾驶员执照）的适用空域范围是？","A":"半径500米、高度120米以下的目视范围内空域","B":"任何空域（无需额外审批）","C":"仅允许在夜间飞行（需额外夜间资质）","D":"必须在有管制员指挥的空域飞行","answer":"A","exp":"本题考察无人机驾驶员执照分类知识点。视距内驾驶员执照（驾驶员执照）的核心要求是驾驶员需目视范围内（通常半径≤500米、高度≤120米）飞行，A选项描述符合规定。B选项错误，任何空域飞行需超视距执照或特殊审批；C选项错误，夜间飞行需额外夜间资质，与视距内执照无关；D选项错误，视距内飞行无需管制员指挥。"},{"id":1205,"type":"single","cat":"操纵与飞行技术","stem":"无人机在稳定悬停状态时，其主要受力平衡关系是？","A":"升力>重力，推力>阻力","B":"升力=重力，推力=阻力","C":"升力<重力，推力<阻力","D":"升力=重力，推力=0","answer":"B","exp":"悬停时无人机处于相对静止的平衡状态，竖直方向上升力与重力大小相等（F升=G），水平方向上（若考虑前进/后退）推力与阻力大小相等（F推=F阻）。A选项升力大于重力会导致上升，推力大于阻力会导致前进，不符合悬停；C选项升力小于重力会下降，推力小于阻力会减速，错误；D选项推力=0仅适用于完全无风的理想状态，实际微型无人机仍需微小推力平衡气流阻力，且推力为零无法维持悬停。"},{"id":1206,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，微型民用无人机的最大起飞重量限制为多少？","A":"7千克","B":"15千克","C":"116千克","D":"250千克","answer":"A","exp":"本题考察无人机重量分类知识点，正确答案为A。根据中国民航局相关规定，微型民用无人机（microUAV）定义为最大起飞重量≤7千克，轻型无人机（lightUAV）为＞7千克且≤116千克，小型无人机（smallUAV）通常指＞116千克且≤5700千克。选项B无明确对应标准；选项C是轻型无人机的上限；选项D超出了小型无人机的一般范围。"},{"id":1207,"type":"single","cat":"法规与空域","stem":"根据中国民航局相关规定，最大起飞重量超过以下哪个数值的民用无人机需要进行实名登记？","A":"250克","B":"2500克","C":"7000克","D":"15000克","answer":"B","exp":"本题考察无人机实名登记管理知识点。根据规定，最大起飞重量250克以下的民用无人机无需实名登记，250克至2500克的无人机需进行备案，超过2500克（即2.5千克）的无人机必须进行实名登记。选项A（250克）为无需登记的标准，选项C（7000克）和D（15000克）属于需实名登记的更大重量范围，但题目问的是超过多少需要登记，2500克是明确的登记门槛，故正确答案为B。"},{"id":1208,"type":"single","cat":"基础概念","stem":"根据中国民航局对民用无人驾驶航空器的分类标准，最大起飞重量≥25千克的民用无人机属于以下哪一类？","A":"微型无人机","B":"轻型无人机","C":"小型无人机","D":"中型无人机","answer":"C","exp":"本题考察无人机分类知识点。根据民航局规定，微型无人机最大起飞重量＜7千克，轻型无人机7千克≤最大起飞重量＜116千克，小型无人机116千克≤最大起飞重量＜5700千克，中型无人机≥5700千克。25千克属于轻型与小型的重叠区间，但题目中≥25千克更接近小型无人机范畴，故正确答案为C。A、B选项重量范围不符合，D选项重量超限。"},{"id":1209,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，在以下哪种区域飞行时，无人机驾驶员必须提前向当地空管部门申请并获得批准？","A":"城市中心公园","B":"民用机场净空区","C":"偏远山区","D":"军事管理区","answer":"B","exp":"本题考察无人机飞行空域管理知识点。A选项城市中心公园属于限制飞行区（需提前报备但非严格申请）；B选项民用机场净空区是严格管制区域，无人机飞行必须提前向空管部门申请并获批；C选项偏远山区通常属于低空空域开放区域，无需申请；D选项军事管理区属于禁飞区，禁止飞行而非申请。因此正确答案为B。"},{"id":1210,"type":"single","cat":"基础概念","stem":"根据中国民航局对民用无人机的分类标准，最大起飞重量大于7千克但不超过116千克的民用无人机属于以下哪一类？","A":"微型无人机","B":"轻型无人机","C":"小型无人机","D":"中型无人机","answer":"B","exp":"中国民航局对民用无人机的分类标准为：微型无人机（最大起飞重量≤7千克）、轻型无人机（7千克＜最大起飞重量≤116千克）、小型无人机（116千克＜最大起飞重量≤5700千克）、中型无人机（5700千克＜最大起飞重量≤57000千克）、大型无人机（＞57000千克）。因此，A选项（微型）因最大起飞重量≤7千克不符合，C选项（小型）因最大起飞重量＞116千克不符合，D选项（中型）因最大起飞重量＞5700千克不符合，正确答案为B。"},{"id":1211,"type":"single","cat":"基础概念","stem":"当无人机在飞行中出现动力系统故障且无法恢复控制时，应优先采取的措施是？","A":"立即切换至备用电池并尝试手动操控返航","B":"启动紧急迫降程序，选择远离人群、无障碍物的区域","C":"向地面指挥中心发送紧急失联信号后等待指令","D":"持续尝试增大油门使无人机重新升空","answer":"B","exp":"本题考察无人机应急动力故障处置知识点。动力系统故障时，无人机通常会失去升力或姿态控制，选项A切换备用电池可能因故障未排除导致二次失控；选项C等待指令会延误最佳处置时机，增加坠机风险；选项D增大油门可能因动力系统已失效而无效。正确原则是安全第一，立即启动迫降程序，选择开阔无人区域避免伤及他人或设备损坏。"},{"id":1212,"type":"single","cat":"飞行原理","stem":"无人机在静风中保持悬停状态时，其升力与重力的关系是？","A":"升力大于重力","B":"升力等于重力","C":"升力小于重力","D":"无法确定","answer":"B","exp":"本题考察无人机飞行原理。无人机悬停时处于垂直方向平衡状态，根据牛顿第一定律，合力为零。升力作为垂直向上的力，需与垂直向下的重力大小相等、方向相反，才能保持静止。选项A会导致无人机上升，C会导致下降，D不符合物理平衡原理，故正确答案为B。"},{"id":1213,"type":"single","cat":"设备与维护","stem":"当无人机飞行中突然信号丢失（图传中断）且处于失控状态时，最安全的处置措施是？","A":"立即启动返航程序","B":"尝试手动遥控器恢复控制","C":"继续尝试调整飞行参数","D":"保持当前高度等待信号恢复","answer":"A","exp":"本题考察应急处置措施。信号丢失且失控时，无人机无法自主稳定飞行，立即启动返航程序可引导无人机返回预设起飞点附近，避免迷失或坠落。B选项手动控制在失控状态下难度极大；C、D选项无法解决失控问题，可能导致无人机碰撞或坠机。故正确答案为A。"},{"id":1214,"type":"single","cat":"基础概念","stem":"在无人机飞行前，检查‘动力系统’时，需重点关注的是？","A":"电池电量及电机转速","B":"螺旋桨安装牢固性及电池电压","C":"飞控系统传感器校准状态","D":"地面站图传信号强度","answer":"B","exp":"本题考察无人机动力系统检查要点知识点。动力系统核心由电池、电机、螺旋桨组成，检查时需确认螺旋桨无变形/松动（避免飞行中脱落）、电池电压在安全范围（防止供电不足）。选项A（电机转速）需在飞行中监测，非起飞前重点；选项C（飞控传感器校准）属于飞控系统检查内容；选项D（图传信号）属于通信系统检查。因此正确答案为B。"},{"id":1215,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，不需要重点关注的是？","A":"电池接口是否有松动","B":"电池生产日期","C":"电池外观有无鼓包变形","D":"电池电压是否在正常范围内","answer":"B","exp":"本题考察飞行前电池检查要点。起飞前检查电池需重点关注：A选项电池接口松动可能导致接触不良引发断电；C选项电池鼓包变形存在短路或起火风险；D选项电压异常会导致动力不足或无法启动。而电池生产日期仅反映生产时间，不影响当前飞行安全，无需重点检查。因此正确答案为B。"},{"id":1216,"type":"single","cat":"飞行原理","stem":"在其他条件不变的情况下，无人机平飞时，若空速增大，其升力将如何变化？","A":"增大","B":"减小","C":"不变","D":"不确定","answer":"A","exp":"本题考察无人机升力产生原理。根据升力公式L=1/2ρv²SCL（ρ为空气密度，v为空速，S为机翼面积，CL为升力系数），在ρ、S、CL不变时，升力L与空速v的平方成正比。因此空速增大时，升力必然增大，A选项正确。B选项认为升力减小，违背公式关系；C选项认为不变，忽略了空速对升力的直接影响；D选项错误，因条件不变时空速与升力的关系明确。"},{"id":1217,"type":"single","cat":"基础概念","stem":"当无人机在飞行过程中失去控制信号或出现故障时，自动返回至起飞点附近并降落的功能称为？","A":"自主飞行模式","B":"自动返航功能","C":"失控保护模式","D":"失速恢复模式","answer":"B","exp":"本题考察无人机功能术语。自动返航功能（B）特指无人机在失控、低电量等情况下，按预设逻辑返回起飞点的功能；自主飞行（A）是指按预设航线自主完成任务的通用模式；失控保护（C）是更宽泛的故障应对机制，范围不限于返航；失速恢复（D）针对飞行速度过低的恢复措施，与题意无关。"},{"id":1218,"type":"single","cat":"基础概念","stem":"当无人机在飞行中突然与地面站失去通信连接（失联）时，正确的紧急处置方法是？","A":"立即上升高度至云层以上，扩大通信范围","B":"保持当前飞行姿态，等待无人机自动执行返航程序","C":"持续手动操控无人机，尝试重新锁定信号","D":"直接关闭遥控器电源，确保无人机平稳坠落","answer":"B","exp":"本题考察无人机应急处置流程知识点。根据《民用无人驾驶航空器飞行操作规范》，失联后无人机通常预设失联返航或自动降落程序，保持当前姿态等待指令是最安全的操作。选项A错误，上升高度可能进一步增加通信距离，导致信号更难恢复；选项C错误，手动操控在远距离失联时无法生效；选项D错误，直接关闭电源会导致无人机因惯性失控坠落，且不符合应急处置规范，因此正确答案为B。"},{"id":1219,"type":"single","cat":"领航与任务规划","stem":"当无人机GPS信号突然丢失时，以下哪项操作是最安全合理的？","A":"立即关闭无人机发动机并任其自由坠落","B":"切换至惯性导航模式并优先选择无人群区域安全降落","C":"持续尝试遥控器摇杆校准以恢复GPS信号","D":"继续保持当前航向飞行至预定降落点","answer":"B","exp":"本题考察无人机GPS失灵时的应急操作知识点。无人机通常配置多源导航系统（如GPS、北斗、惯性导航、气压计），当GPS信号丢失时，惯性导航（IMU）可短时维持定位和姿态控制，气压计辅助高度保持。选项A自由坠落可能造成设备损坏或人员伤害；选项C持续校准遥控器无法解决GPS硬件故障；选项D继续飞行至预定点可能因惯性导航误差导致撞障或失联。正确做法是切换至备用导航并优先降落。"},{"id":1220,"type":"single","cat":"基础概念","stem":"无人机起飞前，不需要重点检查的项目是？","A":"电池剩余电量","B":"GPS卫星信号强度","C":"螺旋桨安装是否牢固","D":"地面环境温度","answer":"D","exp":"本题考察起飞前检查要点。电池剩余电量（A）、GPS卫星信号强度（B）、螺旋桨安装牢固性（C）均为影响飞行安全的核心项目，必须严格检查。地面环境温度（D）一般不直接影响无人机起飞性能，属于非必要检查项。"},{"id":1221,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照的有效期一般为多少年？","A":"2年","B":"3年","C":"4年","D":"5年","answer":"B","exp":"本题考察无人机驾驶员执照有效期知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》及相关法规，无人机驾驶员执照（合格证）有效期通常为3年，到期前需完成签注或重新考核。选项A（2年）不符合常规有效期设定；选项C（4年）和D（5年）超出法规规定的常见有效期范围，因此正确答案为B。"},{"id":1222,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项属于必须确认的项目？","A":"电池剩余电量是否满足飞行需求","B":"GPS卫星信号是否正常","C":"螺旋桨安装是否牢固无松动","D":"以上都是","answer":"D","exp":"本题考察无人机飞行前检查流程。正确答案为D，起飞前需全面检查：电池电量不足会导致飞行中断；GPS信号异常会引发定位漂移或失控；螺旋桨松动可能在飞行中脱落，造成安全隐患。选项A、B、C均为起飞前关键检查项，缺一不可。"},{"id":1223,"type":"single","cat":"基础概念","stem":"根据中国民航局对民用无人机的分类标准，最大起飞重量大于7千克且小于等于116千克的无人机属于以下哪一类？","A":"微型","B":"轻型","C":"小型","D":"大型","answer":"B","exp":"根据中国民航局分类标准：微型无人机最大起飞重量≤7千克，轻型无人机为7千克以上且≤116千克（不含），小型无人机为116千克以上且≤5700千克，大型无人机重量更大。因此本题正确答案为B选项。"},{"id":1224,"type":"single","cat":"法规与空域","stem":"在我国，以下哪种情况的无人机飞行需要提前向空管部门申请飞行空域许可？","A":"视距内目视飞行","B":"超视距飞行","C":"起飞重量小于7千克","D":"白天在城市上空飞行","answer":"B","exp":"本题考察无人机空域申请法规知识点。超视距飞行（超出驾驶员目视范围）需向空管部门申请空域许可，因无法直接观察无人机状态，需空管协调保障安全；视距内飞行通常在开放空域内无需额外申请；起飞重量小于7千克的微型无人机一般无需空域申请；白天在城市上空飞行若未超视距且符合禁飞区规定，也无需专门申请空域许可。"},{"id":1225,"type":"single","cat":"法规与空域","stem":"在我国，无人机驾驶员在视距内飞行时，以下哪类空域无需向空管部门申请空域使用许可？","A":"开放类空域","B":"限制类空域","C":"管控类空域","D":"隔离类空域","answer":"A","exp":"本题考察无人机空域使用相关法规知识点。开放类空域（如低空空域开放区域）允许视距内飞行且无需申请空域使用许可；限制类空域（如部分机场周边）需提前申请并获得批准；管控类空域（如军事管制区）需严格审批；隔离类空域（如军事禁区）禁止民用无人机进入。因此正确答案为A。"},{"id":1226,"type":"single","cat":"基础概念","stem":"无人机起飞前，必须检查的项目是？","A":"遥控器摇杆是否居中","B":"螺旋桨是否安装牢固","C":"天气是否为晴天","D":"飞行器GPS是否有信号","answer":"B","exp":"本题考察起飞前设备检查知识点。正确答案为B，螺旋桨安装牢固是起飞前必须检查的核心项目，若安装不牢，起飞时可能因螺旋桨脱落导致无人机失控。A选项遥控器摇杆居中属于开机后操作检查，非起飞前必须项；C选项天气晴朗是理想飞行条件，非起飞前检查内容；D选项GPS信号需在飞行前开机自检时确认，非必须检查的基础物理状态项。"},{"id":1227,"type":"single","cat":"飞行原理","stem":"无人机飞行时，升力的主要产生原理是以下哪项？","A":"螺旋桨旋转产生的直接推力","B":"空气动力学中机翼上下表面的压力差（伯努利原理）","C":"发动机燃烧产生的热能转化","D":"机身与空气摩擦产生的反作用力","answer":"B","exp":"本题考察无人机升力的空气动力学原理。升力本质是机翼上下表面因气流速度差异产生的压力差（伯努利原理），即上表面气流速度快、压力低，下表面气流速度慢、压力高，形成向上的压力差。A选项螺旋桨推力是提供前进动力，而非升力；C选项热能转化是能量来源，不直接产生升力；D选项摩擦反作用力无法形成稳定升力，故B为正确答案。"},{"id":1228,"type":"single","cat":"法规与空域","stem":"根据民航及空域管理规定，以下哪些区域属于无人机禁飞区？","A":"机场净空保护区域","B":"军事管理区","C":"人口密集区域（如城市中心）","D":"A、B、C均属于","answer":"D","exp":"正确答案为D，机场净空区（A）禁止无人机飞行以保障航空器起降安全；军事管理区（B）属于敏感空域，禁止民用无人机进入；人口密集区域（C）因安全隐患（如坠机伤人）通常禁止飞行；因此A、B、C均为禁飞区，选D。"},{"id":1229,"type":"single","cat":"设备与维护","stem":"无人机飞行中突然出现电机停转故障，首要应急措施是？","A":"立即开启备用电源","B":"尝试重启故障电机","C":"迅速切换至手动降落模式","D":"保持悬停等待地面救援","answer":"C","exp":"本题考察无人机电机故障应急处理知识点。C选项迅速切换至手动降落模式是首要措施，可避免因失去动力导致无人机失控坠落。A选项备用电源通常未配置或容量有限；B选项重启电机需时间且成功率低；D选项无动力时无法悬停，必须立即迫降以保障安全。"},{"id":1230,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照的有效期是多久？","A":"1年","B":"2年","C":"3年","D":"5年","answer":"C","exp":"本题考察无人机法规知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，无人机驾驶员执照有效期为3年，持照人需在有效期内完成每年签注培训（含理论和实践考核），否则执照自动失效。选项A（1年）、B（2年）为错误有效期；选项D（5年）不符合民航局规定。故正确答案为C。"},{"id":1231,"type":"single","cat":"设备与维护","stem":"当无人机在飞行中突然出现失控（如遥控器信号丢失）时，应优先采取的措施是？","A":"立即手动关闭无人机电源开关","B":"尝试通过地面站执行紧急返航","C":"持续尝试遥控器操作使无人机撞向障碍物","D":"等待无人机自动降落至最近区域","answer":"B","exp":"本题考察无人机失控的应急处置。当无人机失控时，手动关闭电源（A）会导致无人机无动力坠落；持续操作撞向障碍物（C）会造成危险；等待自动降落（D）可能因电量耗尽或姿态失控导致坠机。正确做法是通过地面站或遥控器尝试执行紧急返航程序（B），利用GPS或预设航线返回安全区域，避免危险。"},{"id":1232,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪种飞行场景需要向空管部门报备飞行计划？","A":"起飞重量≤7kg的微型无人机在视距内飞行","B":"起飞重量＞7kg的轻型无人机在视距内飞行","C":"起飞重量＞7kg的轻型无人机在超视距飞行","D":"起飞重量＜25kg的轻型无人机在城市上空飞行","answer":"C","exp":"本题考察无人机法规与飞行管理知识点。民航局规定：①微型无人机（≤7kg）视距内飞行无需报备；②轻型无人机（7-116kg）超视距飞行需执照并报备；③轻型无人机视距内飞行仅需实名登记。A选项无需报备；B选项视距内无需报备；D选项城市上空飞行属于空域限制，与报备要求无关。正确答案为C。"},{"id":1233,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，以下哪类无人机属于轻型无人机？","A":"最大起飞重量5千克","B":"最大起飞重量100千克","C":"最大起飞重量7千克","D":"最大起飞重量150千克","answer":"B","exp":"本题考察无人机重量分类知识点。正确答案为B。分析：中国民航局规定，轻型无人机的最大起飞重量范围为7千克至116千克。A选项（5千克）和C选项（7千克）属于微型无人机（<7千克）；D选项（150千克）超过116千克，属于中型无人机；B选项（100千克）在7-116千克范围内，符合轻型无人机定义。"},{"id":1234,"type":"single","cat":"飞行原理","stem":"无人机飞行时，其升力主要由以下哪个因素产生？","A":"发动机推力","B":"螺旋桨旋转产生的下洗气流","C":"空气浮力","D":"机身结构产生的浮力","answer":"B","exp":"本题考察无人机升力原理。正确答案为B，无人机（多旋翼）的升力来源于螺旋桨高速旋转时，桨叶对空气施加向下的作用力（下洗气流），根据牛顿第三定律，空气对桨叶施加向上的反作用力，即升力。选项A发动机推力是提供无人机前进动力，而非升力；选项C空气浮力（如热气球原理）仅适用于密度远小于空气的飞行器，无人机因密度大于空气，升力远大于空气浮力；选项D机身浮力无此概念，故错误。"},{"id":1235,"type":"single","cat":"基础概念","stem":"根据中国民航局相关规定，轻型民用无人机的最大起飞重量通常不超过以下哪个数值？","A":"7千克","B":"116千克","C":"100千克","D":"200千克","answer":"B","exp":"本题考察轻型无人机的重量分类知识点。根据《民用无人驾驶航空器实名制登记管理规定》及飞行标准，轻型民用无人机指最大起飞重量大于7千克且不超过116千克的民用无人机，因此最大起飞重量上限为116千克。A选项7千克是微型无人机的典型最大起飞重量；C、D选项均超出轻型无人机的重量范围。"},{"id":1236,"type":"single","cat":"设备与维护","stem":"在无人机飞行前，检查电池状态时，以下哪项是最重要的？","A":"电池外观无鼓包变形","B":"电池电量是否充足","C":"电池接口是否清洁","D":"电池生产日期是否在保质期内","answer":"B","exp":"本题考察飞行前电池检查知识点。电池电量直接决定无人机能否完成飞行任务，电量不足会导致飞行中断或坠机风险。选项A（外观检查）可排除电池物理损坏风险，但非飞行前提；选项C（接口清洁）影响连接稳定性，但电量不足时仍无法起飞；选项D（保质期检查）属于长期存储要求，飞行前优先保障电量。"},{"id":1237,"type":"single","cat":"领航与任务规划","stem":"当无人机在飞行中突然失去GPS信号并出现姿态失控时，应优先采取的操作是？","A":"立即尝试手动返航（若有返航指令）","B":"继续保持当前航向飞行至安全区域","C":"快速拉升高度至云层以上脱离当前空域","D":"立即操控无人机迫降在最近平坦地面","answer":"A","exp":"本题考察无人机应急处置规范。失去GPS信号后，优先尝试手动返航（若飞控支持返航功能）是最安全的操作，可避免无人机因失控偏离航线或坠入危险区域，因此A正确。B选项继续飞行会加剧失控风险；C选项拉升高度可能进入更高风险空域（如高空风区）；D选项迫降需地面条件允许，且手动迫降易导致无人机损坏或造成人员/财产损失，故B、C、D错误。"},{"id":1238,"type":"single","cat":"领航与任务规划","stem":"无人机在自主飞行模式下，若GPS信号突然丢失，优先操作应为？","A":"立即触发‘失控返航’程序","B":"继续保持当前飞行姿态","C":"手动切换至手动模式并尝试迫降","D":"关闭遥控器电源后离开","answer":"A","exp":"本题考察无人机GPS信号丢失的应急处置知识点。当无人机自主飞行时，GPS信号丢失会导致定位失效，此时无人机通常会触发预设的‘失控返航’程序（基于最后已知位置和返航高度），确保安全返回起飞点。选项B（继续保持姿态）会导致无人机因无法定位而随机漂移，增加碰撞风险；选项C（手动迫降）需驾驶员具备极高操控能力，非优先操作；选项D（关闭电源）会导致无人机直接坠落，完全不可控。因此正确答案为A。"},{"id":1239,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中，负责稳定飞行姿态、实现悬停及航线规划的核心系统是？","A":"动力系统（提供升力）","B":"飞控系统（飞行控制系统）","C":"图传系统（传输视频数据）","D":"遥控系统（接收操控指令）","answer":"B","exp":"本题考察无人机核心系统功能。飞控系统（飞行控制系统）是无人机的大脑，负责稳定姿态、悬停、航线规划、故障预警等，B选项正确。A动力系统仅提供动力；C图传系统仅传输视频；D遥控系统仅接收指令，均非核心飞行控制功能。"},{"id":1240,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项属于必须检查的关键项目？","A":"遥控器电池电量","B":"螺旋桨是否有裂纹或变形","C":"地面是否有障碍物","D":"天气是否晴朗","answer":"B","exp":"本题考察无人机起飞前检查重点。螺旋桨作为动力传输核心部件，若有裂纹或变形会导致旋转不平衡，引发剧烈震动、动力失衡甚至空中解体，是起飞前必须检查的关键项目，故B正确。A选项遥控器电池属于地面设备，无人机自身起飞前检查重点是自身系统（如电池电量、螺旋桨、GPS等），遥控器电量通常由操作员自行负责；C、D选项属于飞行环境检查（障碍物、天气），并非无人机自身必须检查的关键项目。"},{"id":1241,"type":"single","cat":"基础概念","stem":"无人机的动力系统主要不包括以下哪个部件？","A":"电机","B":"螺旋桨","C":"电池","D":"GPS模块","answer":"D","exp":"本题考察无人机系统组成知识点。动力系统负责驱动无人机飞行，主要包括提供动力的电机、传递动力的螺旋桨、储存能量的电池。而GPS模块属于导航与定位系统，用于实现无人机位置感知、自主飞行控制，不属于动力系统范畴。故正确答案为D。"},{"id":1242,"type":"single","cat":"基础概念","stem":"起飞前对无人机进行检查时，以下哪项是最关键的检查项目？","A":"遥控器剩余电量","B":"无人机机身外观及螺旋桨安装情况","C":"地面站软件版本是否最新","D":"起飞区域的实时风速数据","answer":"B","exp":"本题考察无人机起飞前的安全检查重点。正确答案为B，起飞前必须检查无人机机身是否有结构损坏（如机架变形）、螺旋桨是否安装牢固且无裂纹/磨损，这些直接影响飞行安全；A选项遥控器电量是飞行前需确认的，但属于辅助检查；C选项地面站版本与飞行安全无直接关联；D选项风速是环境参数，需提前查询，不属于对无人机本身的检查项目。"},{"id":1243,"type":"single","cat":"法规与空域","stem":"根据民航局规定，以下哪类无人机飞行活动需驾驶员取得相应执照？","A":"起飞重量250克以下的微型无人机","B":"起飞重量大于7千克的轻型无人机","C":"起飞重量大于15千克的小型无人机","D":"起飞重量大于100千克的大型无人机","answer":"B","exp":"本题考察无人机执照适用范围。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，起飞重量＞7千克的轻型无人机（含轻型以上）在经营性飞行活动中需取得驾驶员执照；选项A（250克以下）属于微型无人机，法规规定无需执照；选项C（15千克以上）已超出轻型范畴，属于小型，需执照但选项B描述更精准；选项D（100千克以上）属于大型，需执照但题目选项中B更符合需执照的典型场景。故正确答案为B。"},{"id":1244,"type":"single","cat":"基础概念","stem":"当无人机突然失控并可能撞向人群时，最优先采取的应急措施是？","A":"立即切断动力并迫降（远离人群区域）","B":"尝试远程操控使其反向远离人群","C":"紧急返航至起飞点并途经人群上空","D":"继续观察等待无人机自动恢复稳定","answer":"A","exp":"本题考察无人机失控应急处置原则。失控撞向人群时，首要目标是避免人员伤亡，最优先措施是立即切断动力（如关闭电机或熄火），并选择无人区域迫降，防止进一步碰撞危险，故A正确。B选项远程操控可能因信号延迟或无人机完全失控无法实现；C选项紧急返航若途经人群上空，仍可能造成二次伤害；D选项等待自动恢复会错失最佳避险时机，加剧危险。"},{"id":1245,"type":"single","cat":"基础概念","stem":"起飞前检查无人机的关键步骤是？","A":"检查遥控器与无人机之间的信号强度","B":"检查GPS卫星数量是否≥4颗","C":"检查螺旋桨是否有明显磨损","D":"检查地面是否有人员围观","answer":"B","exp":"本题考察起飞前检查要点。选项A（信号强度）虽重要，但GPS定位是悬停和飞行稳定的核心前提；选项B（GPS卫星数量）直接关系到无人机定位精度和稳定性，起飞前必须确保GPS信号良好（通常需≥4颗卫星可见），否则易导致悬停漂移或失控；选项C（螺旋桨磨损）影响飞行安全性，但非起飞前关键检查的唯一核心项；选项D（地面人员）属于飞行安全距离要求，非检查内容。故正确答案为B。"},{"id":1246,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项不属于必须检查的项目？","A":"电池剩余电量","B":"GPS信号强度","C":"螺旋桨安装是否牢固","D":"地面障碍物分布","answer":"D","exp":"本题考察起飞前检查要点。起飞前需检查无人机自身状态：A（电池电量）、B（GPS信号确保定位）、C（螺旋桨安装影响飞行安全）均为必查项目。D选项地面障碍物分布属于飞行前环境规划内容，非无人机自身检查项目，故正确答案为D。"},{"id":1247,"type":"single","cat":"法规与空域","stem":"根据中国民航局《轻小无人机运行规定》，轻型民用无人机（起飞重量≥7千克）在开放空域视距内飞行时，最大允许飞行高度为？","A":"120米","B":"150米","C":"500米","D":"1000米","answer":"A","exp":"本题考察无人机飞行高度限制。轻型无人机（起飞重量≥7千克）在开放空域视距内飞行高度限制为120米（A正确），超视距飞行高度≤50米；500米、1000米属于超视距或特定空域（如限高区），不符合轻小无人机常规规定。"},{"id":1248,"type":"single","cat":"飞行原理","stem":"无人机在空中悬停时，其动力系统产生的升力主要平衡的力是？","A":"无人机自身重力","B":"空气流动产生的阻力","C":"螺旋桨旋转产生的离心力","D":"地面效应产生的托举力","answer":"A","exp":"本题考察无人机飞行力学基础知识点。悬停状态下，无人机处于受力平衡状态，动力系统产生的升力与无人机自身重力（包括载荷）完全相等，因此升力主要平衡重力。选项B错误，空气阻力在悬停时极小，不构成主要平衡对象；选项C错误，离心力是螺旋桨旋转的惯性力，升力与离心力方向相反但作用不同；选项D错误，地面效应仅在低空（距地面高度＜旋翼直径）时产生，非悬停升力的核心平衡对象，因此正确答案为A。"},{"id":1249,"type":"single","cat":"法规与空域","stem":"根据中国空域管理规定，以下哪类区域属于无人机禁飞区？","A":"机场净空区（半径10公里内）","B":"军事管理区","C":"人口密集区（如城市核心区）","D":"以上都是","answer":"D","exp":"本题考察无人机空域管理法规。正确答案为D，根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，机场净空区（防止干扰航班起降）、军事管理区（国家安全）、人口密集区（避免坠机风险）均属于禁飞区或限制飞行区域，未经批准不得飞入。选项A、B、C均符合禁飞区定义。"},{"id":1250,"type":"single","cat":"设备与维护","stem":"当无人机飞行中电池剩余电量显示为15%时，正确的操作是？","A":"继续飞行直到返回起飞点","B":"立即返航并优先保证安全降落","C":"继续拍摄直到电量耗尽","D":"切换至节能模式并快速爬升","answer":"B","exp":"本题考察低电量应急处置，正确答案为B。15%剩余电量已处于低电量警告状态，继续飞行（A）或拍摄（C）可能导致无人机在降落前完全断电，引发失控坠机；快速爬升（D）会增加动力负荷，加速电量消耗，加剧风险。立即返航并优先降落（B）是最安全的选择，确保无人机在可控状态下着陆，避免意外发生。"},{"id":1251,"type":"single","cat":"法规与空域","stem":"根据无人机飞行法规，起飞前必须完成的核心操作是？","A":"申请空域并获得批准","B":"调试地面站参数","C":"充电电池至100%","D":"检查螺旋桨安装牢固","answer":"A","exp":"本题考察无人机飞行前法规要求。正确答案为A，根据民航局及国际无人机法规，起飞前必须提前申请并获得空域使用许可（如视距内飞行需申请开放空域，超视距飞行需额外审批）。B选项调试地面站参数属于飞行前准备工作，但非法规强制前提；C选项充电电池至100%是设备维护要求，非法规强制的必须完成步骤；D选项检查螺旋桨安装属于飞行前机械检查，但属于操作前准备而非法规要求的核心操作。"},{"id":1252,"type":"single","cat":"飞行原理","stem":"无人机飞行时，产生升力的主要物理原理是？","A":"伯努利原理（机翼上下表面压力差）","B":"牛顿第三定律（作用力与反作用力）","C":"阿基米德原理（流体浮力）","D":"万有引力定律","answer":"A","exp":"本题考察无人机升力原理。无人机机翼设计基于伯努利原理：机翼上表面弧度大于下表面，气流流经时上表面流速更快，压强更低，下表面流速慢、压强大，形成上下表面压力差，从而产生向上的升力，故A正确。B选项牛顿第三定律主要解释螺旋桨推力（作用力与反作用力），但升力本质是压力差；C选项阿基米德原理适用于浮力（如船在水中），与无人机靠压力差产生升力无关；D选项万有引力是重力来源，与升力产生无直接关联。"},{"id":1253,"type":"single","cat":"基础概念","stem":"无人机飞行中突然失去动力，应优先采取以下哪种措施？","A":"立即返航","B":"尝试重启动力系统","C":"寻找最佳安全迫降区域","D":"继续保持高度盘旋等待救援","answer":"C","exp":"本题考察应急处置流程。失去动力后，无人机无法自主控制飞行，应优先选择空旷、无人员/障碍物的区域迫降（如农田、空地），避免坠机风险。A选项立即返航和D选项盘旋等待会因失去动力导致失控；B选项重启动力系统在动力完全失效时无法实现，因此正确答案为C。"},{"id":1254,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪种场景飞行前需向空管部门申请飞行计划？","A":"在城市居民区上空进行航拍作业","B":"在机场净空区边缘1公里外进行测绘飞行","C":"在国家测绘地理信息局划定的开放空域进行训练飞行","D":"在农村无人区域进行农业植保飞行","answer":"B","exp":"本题考察无人机飞行空域申请规范知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法》，机场净空区（含跑道端外3公里、侧方1公里）属于限制飞行区，需提前向当地空管部门（如民航局空管局）申请飞行计划；选项A居民区属于一般限制区，视距内飞行通常无需额外申请（但需遵守高度限制）；选项C开放空域按规定可直接飞行；选项D农村无人区属于开放空域，无需申请。因此答案为B。"},{"id":1255,"type":"single","cat":"设备与维护","stem":"无人机飞行控制系统中，负责稳定无人机姿态、执行飞控算法并确保飞行安全的核心组件是？","A":"飞控系统","B":"图传系统","C":"动力系统","D":"导航系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（飞行控制系统）是无人机的大脑，通过传感器感知姿态并执行飞控指令，稳定飞行姿态；B选项图传系统主要负责传输无人机实时影像，不参与姿态控制；C选项动力系统提供飞行动力，与姿态稳定无关；D选项导航系统负责定位和路径规划，不直接执行姿态稳定指令。因此正确答案为A。"},{"id":1256,"type":"single","cat":"基础概念","stem":"当无人机在飞行中突然失控并开始俯冲时，驾驶员应优先采取以下哪项措施？","A":"立即拉满油门使无人机快速爬升","B":"快速关闭遥控器油门通道（切断动力）","C":"迅速远离人群密集区域并尝试手动迫降","D":"立即切换至备用遥控器频率尝试控制","answer":"C","exp":"本题考察应急处置知识点。无人机俯冲失控时，首要原则是避免伤害他人，应优先远离人群（C项）。A项拉满油门可能加剧俯冲；B项切断动力可能导致突然坠落；D项切换频率需额外时间且成功率低。因此正确答案为C。"},{"id":1257,"type":"single","cat":"航空气象","stem":"在以下哪种气象条件下，根据中国民航相关规定，应当禁止无人机起飞？","A":"雷雨天气","B":"能见度良好（≥300米）","C":"风速≤5级（地面）","D":"无人机系统状态正常","answer":"A","exp":"本题考察无人机起飞的气象条件限制知识点。雷雨天气属于强对流气象条件，可能导致无人机雷击、失控或坠机风险，根据民航规定禁止起飞。B选项能见度良好是允许起飞的前提条件，C选项风速≤5级（地面）属于安全风速范围，D选项是无人机系统正常的基本要求，均非禁止起飞条件。因此正确答案为A。"},{"id":1258,"type":"single","cat":"飞行原理","stem":"多旋翼无人机升力产生的主要物理原理是基于以下哪项？","A":"伯努利原理","B":"牛顿第三定律（反作用力）","C":"阿基米德原理","D":"帕斯卡定律","answer":"B","exp":"本题考察无人机升力原理知识点。多旋翼无人机通过高速旋转的旋翼向下推动空气（作用力），根据牛顿第三定律，空气对旋翼产生向上的反作用力（反作用力），从而形成升力。选项A（伯努利原理）主要用于解释固定翼飞机机翼升力（上下表面流速差）；选项C（阿基米德原理）是浮力原理，适用于气球/飞艇；选项D（帕斯卡定律）是液体压强传递规律，与无人机升力无关。"},{"id":1259,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，以下哪种区域属于无人机驾驶员必须严格禁止飞行的区域？","A":"城市中心广场","B":"机场跑道外5公里净空区","C":"军事管理区边界线内","D":"自然保护区核心区","answer":"C","exp":"本题考察无人机禁飞区法规，正确答案为C。军事管理区（或军事禁区）属于国家重点安全管控区域，根据《无人驾驶航空器飞行管理暂行条例》，严禁任何未经批准的无人机进入。选项A城市中心广场需遵守限高但非绝对禁飞；选项B机场净空区通常指跑道两端及附近一定范围内（如10公里），但题目表述跑道外5公里不准确；选项D自然保护区核心区需谨慎飞行但非法定禁飞区。"},{"id":1260,"type":"single","cat":"操纵与飞行技术","stem":"无人机能够稳定悬停在空中的主要原理是？","A":"伯努利原理","B":"牛顿第三定律","C":"帕斯卡定律","D":"阿基米德原理","answer":"A","exp":"旋翼旋转使上下表面空气流速差形成压力差（伯努利原理），产生升力平衡重力；牛顿第三定律是辅助解释（反作用力），帕斯卡定律（液体压强）和阿基米德原理（浮力）与悬停无关。因此本题正确答案为A选项。"},{"id":1261,"type":"single","cat":"基础概念","stem":"在我国，轻型民用无人机在人口稠密区域上空飞行时，其最大允许飞行高度通常为？","A":"50米","B":"100米","C":"120米","D":"200米","answer":"C","exp":"本题考察轻型无人机飞行高度限制。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，轻型无人机在人口稠密区上空飞行高度不得超过120米。A选项50米可能适用于微型无人机或特定限制区域；B选项1"},{"id":1262,"type":"single","cat":"基础概念","stem":"以下哪项不属于无人机系统的组成部分？","A":"飞行器平台","B":"地面控制站","C":"卫星定位模块","D":"地面电源","answer":"D","exp":"本题考察无人机系统组成的知识点。无人机系统通常由飞行器平台（含动力、飞控等）、地面控制站（遥控站）、任务设备、数据链路等核心部分组成。C选项卫星定位模块（如GPS）是飞控系统的关键组成部分，用于定位和导航；A、B均为系统核心组成。而D选项地面电源仅用于地面设备（如地面站供电），并非无人机系统运行时的必要组成部分（无人机飞行依赖自身电池），因此正确答案为D。"},{"id":1263,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然出现GPS信号丢失（无GPS数据）时，最安全的应急操作是？","A":"立即切换至手动模式并尝试继续飞行","B":"保持当前航向，缓慢爬升以重新获取信号","C":"优先执行返航程序（若返航点有效且信号未丢失）","D":"继续操作无人机悬停，等待信号恢复","answer":"C","exp":"本题考察无人机GPS故障应急处理知识点。GPS丢失时，无人机通常触发失控保护或返航逻辑（若返航点有效），此时优先返航可避免因信号丢失导致的失控；A手动模式易因失去GPS辅助导致碰撞；B爬升可能加剧信号干扰；D悬停等待会因无人机惯性漂移或动力耗尽坠落。正确答案为C。"},{"id":1264,"type":"single","cat":"飞行原理","stem":"当无人机在地面悬停时，升力与重力的关系是？","A":"升力大于重力","B":"升力小于重力","C":"升力等于重力","D":"不确定，取决于风速","answer":"C","exp":"本题考察无人机飞行原理中升力与重力的平衡关系。悬停状态下，无人机相对地面静止（匀速直线运动的特殊形式），根据牛顿第一定律，合力为零，因此升力与重力大小相等、方向相反。A选项错误（升力过大将导致无人机上升），B选项错误（升力不足将导致无人机下降），D选项错误（风速不影响悬停时的升力-重力平衡）。"},{"id":1265,"type":"single","cat":"法规与空域","stem":"关于民用无人驾驶航空器驾驶员执照，以下说法正确的是？","A":"视距内驾驶员执照允许在目视气象条件下，高度≤120米、半径≤500米的空域飞行","B":"超视距驾驶员执照仅适用于夜间飞行场景","C":"轻型驾驶员执照允许起飞重量超过150千克的无人机飞行","D":"小型驾驶员执照无需通过理论考试即可申请 answer:","answer":"A","exp":"本题考察民用无人机驾驶员执照分类及适用范围。正确答案为A：视距内驾驶员执照（视距内驾驶员）的空域限制明确为目视气象条件下，高度≤120米、半径≤500米，符合中国民航局《民用无人驾驶航空器驾驶员管理暂行规定》。B错误：超视距驾驶员执照需通过额外考核（如超视距空域知识），且需遵守能见度、气象等条件，并非仅适用于夜间。C错误：轻型驾驶员执照对应的无人机最大起飞重量为7-116千克，而非超过150千克（后者属于小型或大型）。D错误：无论何种执照，均需通过理论考试（含法规、系统原理等）及实践考核，无豁免考试情况。"},{"id":1266,"type":"single","cat":"领航与任务规划","stem":"当无人机在飞行中突然失控（如GPS信号丢失），应首先采取以下哪项措施？","A":"立即拉回油门","B":"尝试手动紧急降落","C":"关闭遥控器电源","D":"启动返航程序","answer":"D","exp":"本题考察无人机安全操作知识点。A拉回油门可能因动力控制失效导致坠机；B手动紧急降落需精准操作，易因操作失误引发碰撞；C关闭遥控器电源会直接切断控制，导致无人机失控坠地。D启动返航程序（若飞控支持）可让无人机自动返回预设返航点，是最安全的应急措施，故正确答案为D。"},{"id":1267,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然出现GPS信号丢失（进入姿态模式），此时应优先采取以下哪项措施？","A":"立即关闭电源","B":"尝试手动返航（利用视觉定位和遥控器控制）","C":"继续保持原航向飞行","D":"尝试切换至备用电池","answer":"B","exp":"本题考察无人机应急处置流程。GPS丢失后，无人机进入姿态模式，需手动操作维持安全。B选项通过视觉定位（如地面标记）和遥控器手动控制，可优先确保无人机不坠机；A选项关闭电源会丢失飞行数据且无法应急；C选项无GPS时无法自动导航，继续飞行易失控；D选项备用电池与GPS丢失无关。因此正确答案为B。"},{"id":1268,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项检查是确保飞行安全的关键步骤？","A":"检查螺旋桨是否安装牢固","B":"检查地面是否有人员","C":"检查天气是否晴朗","D":"检查无人机外观是否有划痕","answer":"A","exp":"本题考察无人机起飞前安全检查知识点。A正确，螺旋桨安装不牢固会导致飞行中脱落，引发失控或碰撞风险，是核心安全检查项。B错误，地面人员需提前撤离至安全区，但属于飞行前观察而非关键检查；C错误，天气晴朗是飞行条件，非检查步骤；D错误，外观划痕不影响飞行性能，不属于安全检查范畴。"},{"id":1269,"type":"single","cat":"领航与任务规划","stem":"无人机在飞行中突然出现GPS信号丢失，此时应优先采取的措施是？","A":"继续手动操作无人机返回起飞点","B":"切换至姿态模式并执行自动返航（RTH）","C":"立即关闭电源迫降","D":"继续爬升以寻找卫星信号","answer":"B","exp":"本题考察无人机故障处理知识点。GPS信号丢失后，无人机主要依靠IMU（惯性测量单元）维持姿态，但无法定位。此时切换至姿态模式并执行RTH（自动返航）是最安全的措施，可利用预设返航点自动返回。选项A手动操作因无定位易失控，选项C强行关闭电源可能导致坠机，选项D爬升不一定恢复卫星信号。"},{"id":1270,"type":"single","cat":"飞行原理","stem":"多旋翼无人机产生升力的主要原理是？","A":"伯努利原理（旋翼上下表面压力差）","B":"牛顿第三定律（作用力与反作用力）","C":"阿基米德原理（浮力）","D":"万有引力","answer":"A","exp":"本题考察无人机升力产生原理知识点。A正确，多旋翼通过旋翼高速旋转使上下表面形成压力差（上表面流速快压力低，下表面流速慢压力高），根据伯努利原理产生升力。B错误，牛顿第三定律是螺旋桨反推原理（空气被下压产生反作用力），但非升力的核心原理；C错误，无人机升力与空气浮力无关（浮力针对密度差，升力针对相对运动）；D错误，万有引力是重力来源，与升力产生无关。"},{"id":1271,"type":"single","cat":"设备与维护","stem":"无人机飞控系统（FlightControlSystem）的核心功能是？","A":"接收并解析卫星定位信号，提供精确位置信息","B":"稳定无人机飞行姿态，实现自主控制与航线规划","C":"驱动电机旋转，提供无人机飞行所需的动力","D":"传输无人机实时状态数据至地面站","answer":"B","exp":"本题考察无人机飞控系统功能知识点。飞控系统的核心职责是通过传感器（如IMU惯性测量单元、GPS等）感知无人机姿态和位置，结合预设参数或地面指令，计算并输出控制指令，稳定飞行姿态（如悬停、转向）并实现自主控制（如航线规划）。选项A卫星定位信号解析是导航系统的功能，非飞控核心；选项C驱动电机旋转属于动力系统（电机、电调等）的职责；选项D数据传输由图传系统或数传模块完成，飞控系统不直接负责数据传输。因此正确答案为B。"},{"id":1272,"type":"single","cat":"基础概念","stem":"多旋翼无人机起飞前，以下哪项属于必须检查的关键项目？","A":"飞行空域是否已向空管部门申请","B":"电池电压是否在安全工作范围内","C":"地面站软件版本是否为最新","D":"无人机机身厂商售后服务电话","answer":"B","exp":"本题考察无人机起飞前检查要点知识点。起飞前必须检查的关键项目包括电池状态（电压、电量）、桨叶安装、GPS信号、遥控器连接等，其中电池电压是确保无人机动力系统正常运行的核心指标，因此正确答案为B。A选项空域申请属于飞行前准备阶段的行政流程，非起飞前直接检查项目；C选项地面站软件版本属于调试阶段，非起飞前关键检查项；D选项厂商售后电话与飞行安全无关。"},{"id":1273,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，视距内飞行的无人机最大飞行高度通常不超过多少米？","A":"50米","B":"120米","C":"200米","D":"500米","answer":"B","exp":"中国民航局明确视距内飞行标准：水平距离≤500米，高度≤120米（含120米）。A选项50米过低，C选项200米、D选项500米均超出规定高度限制。因此正确答案为B。"},{"id":1274,"type":"single","cat":"操纵与飞行技术","stem":"无人机飞行过程中，负责实时监测并自动修正无人机姿态（如倾斜、俯仰），确保飞行稳定性的核心系统是？","A":"飞控系统（飞行控制系统）","B":"遥控系统（地面站）","C":"动力系统（电机、电池）","D":"导航系统（GPS）","answer":"A","exp":"本题考察无人机系统组成及功能。飞控系统通过陀螺仪、加速度计等传感器实时感知无人机姿态，结合预设算法自动调节电机转速以修正姿态偏差，保障飞行稳定性。B遥控系统仅负责接收地面指令；C动力系统提供飞行动力但不控制姿态；D导航系统（GPS）提供位置信息和路径规划，不直接参与姿态稳定。"},{"id":1275,"type":"single","cat":"法规与空域","stem":"在未取得空域使用许可的情况下，微型无人机在视距内飞行的最大高度一般不超过多少米？","A":"80米","B":"100米","C":"120米","D":"150米","answer":"C","exp":"本题考察无人机飞行高度限制的法规知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》及空域管理规定，微型无人机在视距内飞行（无审批空域）的最大高度限制为120米。选项A（80米）和B（100米）低于常规视距内飞行高度上限，选项D（150米）通常适用于特定空域审批后的轻型无人机，未取得许可时不适用。因此正确答案为C。"},{"id":1276,"type":"single","cat":"基础概念","stem":"无人机的动力系统主要负责以下哪项核心功能？","A":"提供飞行动力","B":"处理飞行数据","C":"导航定位","D":"图像传输","answer":"A","exp":"本题考察无人机系统组成的动力系统功能知识点。动力系统（含电机、电池、螺旋桨等）的核心作用是通过电能转化为机械能，产生升力和推力以维持无人机飞行。选项B（处理飞行数据）属于飞控系统功能，选项C（导航定位）由GPS/IMU等导航模块实现，选项D（图像传输）属于图传系统功能。因此正确答案为A。19.无人机在飞行中突然与地面站失联，最不可能的原因是："},{"id":1277,"type":"single","cat":"基础概念","stem":"无人机在飞行中突然与地面站失联，最不可能的原因是：","A":"无人机飞控系统故障","B":"遥控器电池电量耗尽","C":"图传信号受到强电磁干扰","D":"无人机GPS卫星信号丢失","answer":"B","exp":"本题考察失联故障原因，正确答案为B。遥控器电池耗尽仅影响对无人机的控制操作，不会导致无人机与地面站失联；A（飞控故障）、C（信号干扰）、D（GPS丢失）均可能直接导致数据连接中断。"},{"id":1278,"type":"single","cat":"基础概念","stem":"当多旋翼无人机在飞行中突然失去动力时，以下哪项操作是正确的应急处置措施？","A":"立即关闭无人机电源并等待坠落","B":"尝试通过调整飞行摇杆控制无人机平稳迫降","C":"迅速拉升无人机高度并继续尝试操控","D":"立即切换至备用电池并继续飞行","answer":"B","exp":"失去动力时，立即关闭电源会导致完全失控坠落；拉升高度因无动力会迅速下降；备用电池切换无法解决动力缺失问题；正确做法是通过手动调整摇杆控制姿态，平稳迫降以减少损坏。因此正确答案为B。"},{"id":1279,"type":"single","cat":"操纵与飞行技术","stem":"四旋翼无人机悬停时，主要通过调节以下哪个参数平衡自身重力？","A":"电机转速","B":"扭矩","C":"升力大小","D":"推力方向","answer":"A","exp":"本题考察无人机飞行原理。四旋翼无人机通过改变每个电机的转速（A）来调整桨叶产生的升力，悬停时升力需与重力平衡。选项B（扭矩）是电机转动的力矩，不直接决定升力；选项C（升力大小）是结果而非调节参数；选项D（推力方向）为固定方向，无法平衡重力。因此正确答案为A。"},{"id":1280,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然失去GPS信号时，以下哪种操作是正确的应急措施？","A":"立即拉升至云层以上寻找信号","B":"切换至姿态模式保持基本控制","C":"强行执行返航程序","D":"关闭无人机电源避免失控","answer":"B","exp":"本题考察无人机故障应急处理知识点。GPS丢失后，无人机进入GPS模式失效状态，此时切换至姿态模式（B正确）可仅依赖惯性测量单元（IMU）维持基础飞行姿态，避免因失控坠落；A选项拉升至云层可能进入无信号区域加剧危险；C选项强行返航需GPS定位，无法执行；D选项关闭电源会导致无人机立即失控坠落，均错误。正确答案为B。"},{"id":1281,"type":"single","cat":"基础概念","stem":"无人机飞行前检查的核心项目不包括以下哪项？","A":"电池电压检查","B":"螺旋桨安装牢固性","C":"遥控器电量检查","D":"地面站软件版本检查","answer":"D","exp":"本题考察无人机飞行前检查的关键内容。飞行前需重点确认无人机硬件状态（如电池电压是否充足、螺旋桨安装是否牢固）及操控设备状态（遥控器电量是否满足飞行需求）。地面站软件版本属于任务规划阶段的配置，与实时飞行安全无关，因此无需在飞行前检查。"},{"id":1282,"type":"single","cat":"基础概念","stem":"根据中国民航局相关规定，视距内飞行的微型无人机，其最大飞行高度通常不超过多少米？","A":"50米","B":"120米","C":"500米","D":"1000米","answer":"B","exp":"本题考察无人机飞行高度法规知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，视距内飞行的微型无人机最大飞行高度限制为120米；轻型无人机视距内飞行高度不超过500米（超视距飞行需额外审批）。A选项50米为超小型无人机的低空限制，C选项500米为轻型无人机视距内高度上限，D选项1000米为超视距飞行高度上限（非视距内），故正确答案为B。"},{"id":1283,"type":"single","cat":"设备与维护","stem":"飞行中突然电机停转，正确的应急处置步骤是？","A":"立即切换至备用电池","B":"尝试手动操控无人机滑翔降落","C":"保持原飞行高度，等待地面指令","D":"快速拉升至安全高度后关闭电源","answer":"B","exp":"本题考察无人机动力失效应急处置知识点。正确答案为B。电机停转后无人机失去动力，应利用滑翔状态手动控制方向，尽快寻找安全区域迫降；A选项错误，切换电池需时间，可能已无法安全操作；C选项等待指令会加剧坠落风险；D选项拉升后关闭电源会直接导致无人机坠落，更危险。"},{"id":1284,"type":"single","cat":"飞行原理","stem":"当无人机飞行速度低于临界值，导致升力无法维持飞行高度时，这种现象称为？","A":"失速","B":"螺旋","C":"尾旋","D":"失控","answer":"A","exp":"本题考察无人机飞行术语中的失速概念知识点。失速的定义是飞行速度过低，机翼迎角超过临界值，导致升力急剧下降，无法维持高度或速度。选项B（螺旋）是无人机绕纵轴和横轴同时旋转的失控状态，选项C（尾旋）是螺旋的极端形式（绕垂直轴旋转），选项D（失控）是更宽泛的故障统称。三者均与速度过低导致升力不足的核心定义不符。因此正确答案为A。"},{"id":1285,"type":"single","cat":"基础概念","stem":"起飞前检查中，以下哪项属于必须确认的关键项目？","A":"螺旋桨安装是否牢固","B":"地面是否有手机信号","C":"天气是否为阴天","D":"无人机外观是否有划痕","answer":"A","exp":"本题考察起飞前检查要点。螺旋桨安装牢固是飞行安全的核心，若安装不牢，飞行中可能脱落导致事故，属于关键项目。选项B（手机信号）与飞行安全无关；选项C（天气）影响飞行但非必须检查的关键项目；选项D（外观划痕）不影响性能，无需检查。"},{"id":1286,"type":"single","cat":"法规与空域","stem":"申请民航局核发的民用无人驾驶航空器驾驶员执照，申请人的年龄应满足以下哪个条件？","A":"年满16周岁","B":"年满18周岁","C":"年满20周岁","D":"年满14周岁","answer":"A","exp":"本题考察无人机驾驶员执照申请的年龄要求知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》及民航局相关规定，申请驾驶员执照的申请人需年满16周岁，这是基础考证的法定年龄起点。选项B年满18周岁通常是经营性飞行人员或特定职业岗位的额外要求，非普遍基础条件；选项C年满20周岁不符合常规要求；选项D年满14周岁未达到法定最低年龄标准，因此正确答案为A。"},{"id":1287,"type":"single","cat":"设备与维护","stem":"无人机飞行中出现图传信号中断（画面/数据丢失），以下哪项不是可能的原因？","A":"遥控器与无人机间存在强电磁干扰","B":"无人机端图传模块硬件损坏","C":"无人机GPS信号丢失导致自动返航","D":"无人机电池电量耗尽","answer":"D","exp":"本题考察无人机图传中断故障原因。图传中断通常由信号链路问题或设备故障导致：A强电磁干扰会阻断无线信号传输，B图传模块损坏直接导致信号中断，CGPS丢失后无人机可能自动返航，但返航过程中仍可能因信号中断显示失联；D电池电量耗尽会导致无人机自动迫降，而非图传中断（电量耗尽前图传已中断）。故正确答案为D。"},{"id":1288,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机能够悬停的核心原理是？","A":"固定翼机翼上下表面压力差产生升力","B":"旋翼高速旋转产生的反作用力与重力平衡","C":"螺旋桨推力直接克服重力","D":"发动机动力通过传动系统转化为升力","answer":"B","exp":"本题考察多旋翼无人机悬停原理知识点。多旋翼无人机通过多个旋翼高速旋转，使旋翼下方空气流速加快、压力降低，上方空气流速慢、压力高，形成向上的反作用力（升力），当升力与无人机重力平衡时即可悬停，因此正确答案为B。A选项是固定翼无人机升力原理，与多旋翼无关；C选项错误，螺旋桨推力本质是反作用力，表述不准确；D选项错误，多旋翼无人机由电机驱动而非发动机，且推力表述混淆了升力与推力的概念。"},{"id":1289,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项是必须执行的关键步骤？","A":"检查电池电量≥80%","B":"确认螺旋桨安装牢固且无损伤","C":"测试遥控器摇杆行程是否正常","D":"以上都是","answer":"D","exp":"本题考察无人机起飞前安全检查知识点。起飞前需执行多维度检查：电池电量需充足（≥80%）以避免空中断电；螺旋桨需安装牢固且无裂纹/变形（防止旋转时脱落或失衡）；遥控器摇杆行程需正常（确保控制指令有效）。错误选项A、B、C均为起飞前检查的必要环节，单独任何一项缺失都可能导致飞行风险，因此正确答案为D。"},{"id":1290,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项属于必须检查的关键项目？","A":"螺旋桨安装是否牢固且方向正确","B":"无人机机身外观是否有明显变形","C":"地面是否有无关人员停留","D":"飞行空域是否已申请飞行计划","answer":"A","exp":"本题考察无人机起飞前检查要点。螺旋桨安装牢固和方向正确直接影响飞行平衡与动力输出，是飞行安全的核心保障。B选项外观变形若不影响结构安全则非必须检查；C、D属于场地和空域管理，非设备检查项目。故正确答案为A。"},{"id":1291,"type":"single","cat":"基础概念","stem":"无人机飞行前检查中，以下哪项属于必须确认的机械安全检查内容？","A":"遥控器电池剩余电量","B":"图传信号是否稳定","C":"螺旋桨是否安装牢固","D":"GPS卫星数量是否充足","answer":"C","exp":"本题考察飞行前检查要点。C选项螺旋桨安装牢固是机械连接安全的核心，若安装不牢，飞行中可能脱落导致失控或损坏，属于必须检查内容。A选项电池电量是能源检查，非机械安全检查。B选项图传信号稳定性需飞行中观察，非检查项目。D选项GPS卫星数量属于导航系统检查，与机械安全无关。"},{"id":1292,"type":"single","cat":"设备与维护","stem":"无人机遥控器校准过程中，必须执行的关键步骤是？","A":"校准指南针","B":"调整螺旋桨角度","C":"更换锂电池","D":"格式化SD卡","answer":"A","exp":"本题考察无人机设备操作的校准知识点。遥控器校准的核心是确保无人机与遥控器的信号匹配及姿态控制准确，其中校准指南针是关键步骤，可消除磁干扰对无人机方向的影响。选项B（调整螺旋桨角度）属于出厂设置或维护操作，非校准步骤；选项C（更换电池）仅为供电操作，与校准无关；选项D（格式化SD卡）用于数据存储管理，与校准无关。"},{"id":1293,"type":"single","cat":"领航与任务规划","stem":"无人机的核心控制系统，负责稳定飞行姿态、执行导航指令和故障处理的是？","A":"飞控系统","B":"动力系统","C":"遥控系统","D":"图传系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（FlightControlSystem）是无人机的核心，通过传感器实时监测姿态并执行控制算法，确保飞行稳定；B选项动力系统负责提供飞行动力；C选项遥控系统仅负责地面指令传输；D选项图传系统用于传输图像视频，不参与飞行控制。因此正确答案为A。"},{"id":1294,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，重量大于多少克的民用无人机需要进行实名登记？","A":"200克","B":"250克","C":"150克","D":"300克","answer":"B","exp":"本题考察无人机实名登记法规知识点。根据民航局《民用无人驾驶航空器实名制登记管理规定》，重量大于等于250克（含250克）的民用无人机需向民航局指定平台实名登记。A选项200克未达到规定阈值，C选项150克低于标准，D选项300克虽需登记但非规定的最低阈值，因此正确答案为B。37.无人机起飞前，地面检查的首要关键系统是____。"},{"id":1295,"type":"single","cat":"基础概念","stem":"无人机起飞前，地面检查的首要关键系统是____。","A":"图传系统信号强度","B":"动力系统（螺旋桨、电机、电池）安装牢固性","C":"飞控系统参数设置","D":"遥控器摇杆行程校准","answer":"B","exp":"本题考察无人机起飞前检查重点。动力系统（螺旋桨、电机、电池）是飞行安全的核心，起飞前必须确保螺旋桨安装牢固（防止脱落）、电机无异常、电池电量充足，否则可能引发空中失控或机械故障。A选项图传系统为辅助设备，C选项参数设置需在起飞前检查但非首要，D选项摇杆校准属于调试环节，因此正确答案为B。"},{"id":1296,"type":"single","cat":"基础概念","stem":"无人机飞行模式中，位置模式与高度模式的主要区别在于？","A":"位置模式可保持当前位置，高度模式仅控制高度","B":"位置模式需手动调整航向，高度模式自动调整","C":"位置模式依赖GPS，高度模式仅依赖气压计","D":"位置模式支持悬停，高度模式不支持悬停","answer":"A","exp":"本题考察无人机飞行模式参数控制知识点。位置模式（如GPS模式）下，无人机可保持当前经纬度位置（悬停时维持坐标不变），同时通过遥控器调整航向和高度；高度模式（如高度/姿态模式）下，无人机仅通过油门控制高度，位置需手动调整（如手动飞直线）。错误选项B描述反了两种模式的航向控制逻辑；C中两种模式均可能同时依赖GPS和气压计；D中高度模式也支持悬停（如保持固定高度），故排除。"},{"id":1297,"type":"single","cat":"航空气象","stem":"无人机起飞时，为获得最佳起飞性能，应尽量选择哪种风向？","A":"逆风","B":"顺风","C":"侧风","D":"无风","answer":"A","exp":"本题考察无人机起飞时的风向选择知识点。逆风起飞时，无人机相对空气的速度更快，机翼上下表面的气压差增大，升力显著提升，可缩短起飞滑跑距离、降低对发动机推力的依赖。顺风会降低相对空气速度，导致升力不足，需更长滑跑距离甚至可能因推力不足无法离地；侧风会增加起飞操控难度，无风则无额外升力增益。因此A选项正确。"},{"id":1298,"type":"single","cat":"基础概念","stem":"在进行视距内（VLOS）飞行时，根据中国民航局相关规定，民用无人机的最大飞行高度通常为？","A":"50米","B":"120米","C":"200米","D":"500米","answer":"B","exp":"本题考察视距内飞行高度限制知识点。中国民航局规定视距内飞行高度一般不超过120米，超视距飞行高度通常不超过500米。A选项50米过低，不符合实际操作；C选项200米超过视距内标准；D选项500米为超视距飞行高度上限，故正确答案为B。"},{"id":1299,"type":"single","cat":"领航与任务规划","stem":"飞行中GPS信号突然丢失时，应优先采取的操作是？","A":"立即切换至手动模式","B":"尝试重新搜索卫星信号","C":"启用返航功能（如有返航点）","D":"继续维持当前航向飞行","answer":"C","exp":"GPS丢失后无人机定位失效，继续飞行（D）易因失控坠毁；切换手动模式（A）需熟练操作且存在坠机风险；重新搜索卫星（B）无明确时间保障；启用返航功能（基于预设返航点）是最安全的应急措施，可快速返回安全区域，故正确答案为C。"},{"id":1300,"type":"single","cat":"法规与空域","stem":"未经批准在机场净空区进行无人机飞行，可能面临的法律后果不包括以下哪项？","A":"行政处罚（罚款）","B":"民事赔偿责任（如造成他人损失）","C":"刑事责任（如危害公共安全）","D":"仅需口头警告","answer":"D","exp":"本题考察禁飞区飞行法律后果。根据《无人驾驶航空器飞行管理暂行条例》，非法在机场净空区飞行属于违法行为，将面临罚款（A）、民事赔偿（B）甚至刑事处罚（C），仅口头警告（D）不符合法律规定。故正确答案为D。"},{"id":1301,"type":"single","cat":"领航与任务规划","stem":"无人机在飞行中突然失去GPS信号（无GPS模式），应优先采取以下哪种操作？","A":"立即执行返航操作（RTH）","B":"继续保持当前飞行姿态","C":"尝试手动调整油门和摇杆","D":"立即切换至紧急迫降模式","answer":"A","exp":"本题考察无人机故障应急处理流程。失去GPS信号后，无人机易因位置丢失失控，优先执行返航（RTH）可自动返回起飞点附近，避免盲目飞行导致坠机；B项继续飞行加剧危险；C项手动控制难度大且易误操作；D项紧急迫降需在安全环境下，非优先措施。因此正确答案为A。"},{"id":1302,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，以下哪项不属于必要检查内容？","A":"电池外观是否有鼓包、漏液","B":"电芯电压是否在正常范围内","C":"电池接口是否有松动或氧化","D":"电池生产日期及保质期","answer":"D","exp":"本题考察起飞前电池检查要点。起飞前需重点检查电池安全性（外观鼓包/漏液）、供电稳定性（电芯电压）、连接可靠性（接口状态）；电池生产日期及保质期仅影响长期存储寿命，与当前飞行安全无关。因此正确答案为D。"},{"id":1303,"type":"single","cat":"飞行原理","stem":"多旋翼无人机主要依靠什么原理产生升力？","A":"螺旋桨旋转产生的反作用力（升力）","B":"空气动力学伯努利效应（机翼上下表面压力差）","C":"发动机喷气推力","D":"机身与空气的相对运动产生的动压","answer":"A","exp":"本题考察无人机升力原理。多旋翼无人机通过多个螺旋桨高速旋转，对空气施加向下的作用力，根据牛顿第三定律，空气对螺旋桨产生向上的反作用力（即升力），因此A正确。B选项是固定翼无人机的升力原理；C选项是直升机或固定翼飞机发动机的推力来源，与多旋翼无关；D选项属于空气动力学基础概念，但多旋翼升力核心是螺旋桨反作用力，非单纯相对运动。"},{"id":1304,"type":"single","cat":"设备与维护","stem":"无人机飞控系统的核心功能是？","A":"稳定飞行姿态","B":"实时传输任务载荷数据","C":"控制动力系统输出","D":"显示地面站信息","answer":"A","exp":"飞控系统（FlightControlSystem）的核心职责是通过传感器采集姿态数据，计算并输出控制指令，实现无人机的稳定飞行（如保持高度、俯仰角、横滚角等）。选项B为任务载荷子系统功能，C为动力系统控制模块职责，D属于地面站数据显示范畴，均非飞控核心功能，故正确答案为A。"},{"id":1305,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照按运行环境（是否超出视线范围）分为以下哪两类？","A":"AOPA执照和民航局执照","B":"视距内驾驶员执照和超视距驾驶员执照","C":"固定翼执照和多旋翼执照","D":"民用执照和军用执照","answer":"B","exp":"本题考察无人机驾驶员执照分类知识点。无人机驾驶员执照根据运行环境分为视距内驾驶员执照（VLOS）和超视距驾驶员执照（BVLOS），前者适用于视线范围内飞行，后者需额外培训和资质。A选项是执照颁发机构，C选项是按无人机类型分类，D选项为执照用途分类，均不符合题意。"},{"id":1306,"type":"single","cat":"领航与任务规划","stem":"无人机在GPS模式飞行中突然失控，最可能的直接原因是？","A":"GPS卫星信号丢失","B":"螺旋桨被异物缠绕","C":"遥控器天线接触不良","D":"地面站软件故障","answer":"A","exp":"本题考察GPS模式飞行安全知识点。GPS模式依赖卫星定位数据，信号丢失会导致无人机失去自主悬停和位置控制能力，直接引发失控。B选项螺旋桨缠绕会导致动力失衡，通常表现为缓慢失控而非突然；C选项遥控器接触不良会导致控制信号中断，但不会直接引发失控状态；D选项地面站故障不影响飞行中无人机的实时控制。因此正确答案为A。"},{"id":1307,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，无人机驾驶员执照的有效期一般为多少年？","A":"1年","B":"3年","C":"5年","D":"7年","answer":"C","exp":"本题考察无人机驾驶员执照管理知识点。根据民航局规定，视距内驾驶员执照有效期为5年，故正确答案为C。A选项1年不符合实际，执照有效期不会如此短暂；B选项3年通常为其他短期证件的有效期，非执照有效期；D选项7年过长，超出常规执照管理周期。"},{"id":1308,"type":"single","cat":"法规与空域","stem":"以下哪个区域属于无人机飞行的严格禁飞区？","A":"城市公园","B":"机场净空区","C":"偏远山区","D":"乡村田野","answer":"B","exp":"本题考察无人机禁飞区安全规范。机场净空区是为保障机场运行安全划定的严格禁飞区域，根据《民用机场管理条例》，无人机在机场跑道端外3公里、跑道中心线两侧各10公里范围内禁止飞行。A、C、D选项均不属于禁飞区，城市公园、乡村田野等开放区域在遵守法规前提下可飞行，偏远山区虽无明确禁飞规定但需注意地形风险。因此正确答案为B。"},{"id":1309,"type":"single","cat":"基础概念","stem":"当无人机在空中突然与地面站失去连接（失联）时，最优先采取的应急措施是？","A":"立即关闭无人机电源","B":"尝试重新连接遥控器","C":"启动无人机的失控保护/返航程序","D":"手动操作无人机迫降","answer":"C","exp":"本题考察无人机故障应急处理知识点。无人机飞控系统通常预设失联保护或失控保护程序，当与地面站/遥控器失去连接时，系统会自动执行预设的安全动作（如返航、降落或悬停），优先保障飞行安全。选项A（关闭电源）会导致无人机突然坠落，可能引发安全事故；选项B（重新连接）成功率低且耗时，可能错过最佳处理时机；选项D（手动迫降）需依赖操作员手动控制，而失联后操作员无法实时接收无人机状态，易导致失控。因此正确答案为C。"},{"id":1310,"type":"single","cat":"操纵与飞行技术","stem":"无人机悬停时，主要依靠哪个部件产生的力平衡自身重力？","A":"推力","B":"升力","C":"阻力","D":"重力","answer":"B","exp":"本题考察无人机飞行原理。无人机悬停时，螺旋桨高速旋转推动空气向下，根据牛顿第三定律，空气对螺旋桨产生向上的反作用力即升力，升力与重力平衡使无人机保持悬停。选项A推力是螺旋桨提供的动力来源，非直接平衡重力的力；选项C阻力为空气阻碍运动的力，与悬停无关；选项D重力是被平衡的力而非平衡力，故正确答案为B。"},{"id":1311,"type":"single","cat":"基础概念","stem":"无人机飞行中突发低电量警告时，最优先的安全操作是？","A":"立即迫降","B":"执行返航程序","C":"继续飞行至目的地","D":"联系地面站","answer":"B","exp":"本题考察无人机应急处置规范。飞行中低电量时，无人机飞控系统会自动触发低电量返航程序（若未设置，驾驶员应手动执行），优先返回起飞点，避免因电量耗尽导致失控坠机。A选项迫降易造成设备损坏或人员伤害；C选项继续飞行会导致动力中断风险；D选项联系地面站无法解决电量不足问题，且可能延误操作时机。因此正确答案为B。"},{"id":1312,"type":"single","cat":"法规与空域","stem":"下列哪类无人机驾驶员执照适用于最大起飞重量25千克以上的民用无人机在视距内飞行？","A":"视距内驾驶员执照（25kg以下）","B":"超视距驾驶员执照（25kg以下）","C":"视距内驾驶员执照（25kg以上）","D":"超视距驾驶员执照（25kg以上）","answer":"C","exp":"本题考察无人机驾驶员执照分类知识点。中国民航局对无人机驾驶员执照分为视距内驾驶员执照（VTC）和超视距驾驶员执照（BVC），其中视距内驾驶员执照又根据最大起飞重量分为25千克以下和25千克以上两个等级。选项A适用于25kg以下无人机，选项B和D不符合超视距执照的重量限制，选项C正确描述了25kg以上视距内驾驶员执照的适用范围。"},{"id":1313,"type":"single","cat":"基础概念","stem":"根据中国民航局相关规定，微型民用无人机在视距内飞行时，最大允许飞行高度为？","A":"100米","B":"120米","C":"150米","D":"200米","answer":"B","exp":"本题考察无人机飞行空域高度限制知识点。根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，微型无人机在视距内飞行高度不得超过120米。A选项100米为早期非视距场景参考值，C（150米）和D（200米）均超出法规限制。"},{"id":1314,"type":"single","cat":"设备与维护","stem":"无人机飞控系统的核心功能不包括以下哪项？","A":"稳定飞行姿态","B":"自动避障决策","C":"控制电机转速","D":"调节飞行高度","answer":"B","exp":"本题考察无人机系统组成。飞控系统（FlightControlSystem）主要负责稳定无人机姿态（如横滚、俯仰、偏航）、控制电机转速以调节动力输出，以及通过PID算法自动调节飞行高度和速度。选项B自动避障决策属于无人机感知系统（如视觉避障、激光雷达）的功能，由外部传感器和独立算法完成，不属于飞控系统核心功能，故正确答案为B。"},{"id":1315,"type":"single","cat":"基础概念","stem":"根据《民用无人驾驶航空器经营性飞行活动管理办法》，无人机在人口密集区域上空飞行时，最低安全高度应为多少米？","A":"5米","B":"10米","C":"15米","D":"20米","answer":"B","exp":"本题考察空域安全操作规范。根据民航局规定，无人机在人口密集区域（如城市、广场、居民区）上空飞行时，需保持至少10米的安全高度，以避免碰撞风险；选项A（5米）过低、C（15米）和D（20米）过高，均不符合标准，故正确答案为B。"},{"id":1316,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然丢失GPS信号时，以下哪项是正确的应急操作？","A":"立即切换至手动模式并尝试返航","B":"继续操控无人机上升至云层上方","C":"关闭无人机电源以避免失控","D":"保持原航向继续飞行以节省电量","answer":"A","exp":"本题考察应急处理流程。GPS丢失时，手动模式可通过姿态控制实现返航/迫降，避免失控风险。上升至云层上方（B）无法解决信号问题且增加碰撞风险，关闭电源（C）会丢失飞行数据，保持原航向（D）易导致坠机或碰撞。"},{"id":1317,"type":"single","cat":"法规与空域","stem":"根据中国民航局相关规定，最大起飞重量在多少克以上的民用无人机需要进行实名登记？","A":"150克","B":"200克","C":"250克","D":"300克","answer":"C","exp":"本题考察无人机实名登记的重量标准知识点。根据《民用无人驾驶航空器实名制登记管理规定》，最大起飞重量≥250克的民用无人机（除微型航拍器等豁免情况外）需进行实名登记。选项A（150克）和B（200克）均低于规定阈值，选项D（300克）属于超轻型或轻型无人机的更高重量分类，并非登记的最低标准。因此正确答案为C。"},{"id":1318,"type":"single","cat":"设备与维护","stem":"当无人机飞行中发生单个电机突然停止工作时，正确的应急处置措施是？","A":"立即切换至备用电池并继续飞行","B":"尝试手动操作控制无人机平稳迫降","C":"保持当前飞行姿态直至电量耗尽","D":"强行拉升无人机高度以脱离故障区域","answer":"B","exp":"本题考察无人机故障应急处理。单电机故障会导致无人机失去平衡，此时强行拉升（D）或继续飞行（C）可能加剧失控；若无人机无备用电池（A），切换电池不现实。正确做法是手动操作无人机，利用剩余电机和舵面控制，选择无人区域平稳迫降，减少损失。"},{"id":1319,"type":"single","cat":"基础概念","stem":"根据中国民航局对轻型民用无人机（空机重量＜7千克）视距内飞行的规定，最大飞行高度限制为多少？","A":"50米","B":"120米","C":"500米","D":"1000米","answer":"B","exp":"本题考察无人机飞行高度法规。中国民航局规定，轻型民用无人机在视距内飞行时，最大高度限制为120米（含120米），以保障空域安全与避免空中冲突。A选项50米为低空飞行常见限制；C、D选项高度过高，超出轻型视距内飞行的安全范围（超视距飞行需额外资质且高度限制不同）。"},{"id":1320,"type":"single","cat":"基础概念","stem":"无人机系统（UAS）的核心组成部分不包括以下哪项？","A":"飞行器平台","B":"地面指挥控制站","C":"卫星定位系统","D":"任务载荷设备","answer":"C","exp":"本题考察无人机系统组成知识点。无人机系统核心由四部分构成：①飞行器平台（机体），②任务载荷设备（如相机、传感器），③地面指挥控制站（含地面站软件、遥控器），④遥控链路（含图传、数据链）。卫星定位系统（GPS/北斗）属于飞行器平台的子部件（飞控系统组成部分），并非独立核心组成，故C选项错误。A、B、D均为系统核心组成部分，正确答案为C。"},{"id":1321,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，无人机驾驶员执照主要依据以下哪项标准进行分类？","A":"按起飞重量分为15kg和25kg级","B":"按是否具备视距内飞行能力分为视距内驾驶员和超视距驾驶员","C":"按使用空域类型分为开放空域和限制空域驾驶员","D":"按电池容量分为高容量和低容量驾驶员","answer":"B","exp":"本题考察无人机驾驶员执照的分类标准知识点。中国民航局对无人机驾驶员执照的分类核心依据是飞行能力范围，即是否具备视距内（VLOS）飞行能力和超视距（BVLOS）飞行能力，因此正确答案为B。A选项错误，起飞重量是无人机类型划分（如微型、轻型、小型、大型）的标准，而非执照分类；C选项错误，空域类型是飞行任务的申请依据，并非执照分类标准；D选项错误，电池容量与执照分类无关。"},{"id":1322,"type":"single","cat":"领航与任务规划","stem":"当多旋翼无人机GPS信号突然丢失时，最安全的操作是？","A":"立即拉升高度至云层以上，重新搜索卫星信号","B":"保持当前高度和航向，等待GPS信号恢复","C":"切换至手动模式，尝试返航至起飞点","D":"立即关闭发动机，选择开阔地带紧急迫降","answer":"C","exp":"本题考察无人机GPS丢失后的应急处理。GPS丢失时，无人机可能因失去定位而进入失控状态（如漂移、坠落）。选项A盲目拉升可能因高度过高导致飞控无法恢复；选项B等待无法解决信号丢失问题；选项D紧急迫降易因失去定位导致撞击风险；选项C通过手动模式返航至起飞点，可避免失控风险，是最安全的操作。"},{"id":1323,"type":"single","cat":"设备与维护","stem":"多旋翼无人机遥控器中，通常用于控制飞行器升降（高度）的摇杆是？","A":"左摇杆","B":"右摇杆","C":"中摇杆","D":"无升降控制摇杆","answer":"A","exp":"本题考察无人机遥控器操作逻辑。主流多旋翼无人机遥控器布局中，左摇杆通常负责控制高度（油门）和偏航（旋转）：上下推动左摇杆可改变螺旋桨总升力大小，实现飞行器升降；左右推动左摇杆控制无人机绕竖轴旋转（偏航）。右摇杆一般控制俯仰（前后倾斜）和横滚（左右倾斜）。C、D选项不符合主流遥控器设计，因此正确答案为A。"},{"id":1324,"type":"single","cat":"设备与维护","stem":"无人机起飞后电机突然停转且无明显故障，最可能的原因是？","A":"螺旋桨卡滞","B":"电池电压过低","C":"飞控系统故障","D":"GPS信号丢失","answer":"B","exp":"本题考察无人机故障排除。电池电压过低会导致电机无法获得足够电能驱动，表现为突然停转且无机械卡滞（无异响）。选项A螺旋桨卡滞会伴随电机异响或剧烈震动；选项C飞控系统故障通常伴随飞行姿态异常（如倾斜、抖动）；选项DGPS信号丢失会导致失控但不会直接导致电机停转。因此，电池电压过低是最可能原因，正确答案为B。"},{"id":1325,"type":"single","cat":"设备与维护","stem":"在无人机飞行中，若发现电池电量不足，应如何操作？","A":"立即切换至低电量保护模式","B":"继续飞行至目的地后降落","C":"强行降落","D":"继续飞行至电量耗尽","answer":"A","exp":"本题考察无人机电池安全操作知识点。无人机低电量保护模式会自动启动，优先保障安全返航或迫降。选项B、C、D均因电量不足导致无人机失控坠落，存在设备损坏或安全隐患，而低电量保护模式是唯一安全操作方式。"},{"id":1326,"type":"single","cat":"领航与任务规划","stem":"当多旋翼无人机飞行过程中突然失去GPS信号时，最安全的应急处置措施是？","A":"继续手动操作无人机至安全地点","B":"立即启动自动返航程序","C":"强行继续飞行并尝试手动修正姿态","D":"直接关闭无人机电源并迫降","answer":"B","exp":"本题考察无人机应急处置知识点。GPS信号丢失后，无人机通常进入姿态模式，此时自动返航（RTF）是最安全的措施，可自动返回起飞点悬停，避免因手动操作失误导致坠机。错误选项中，A项手动操作难度高（无GPS定位易迷失方向）；C项强行飞行易因姿态失控坠落；D项直接断电会导致无人机失控坠落，无法保障安全。"},{"id":1327,"type":"single","cat":"法规与空域","stem":"根据中国民航局《民用无人驾驶航空器实名制登记管理规定》，以下哪种无人机需要进行实名登记？","A":"起飞重量≥250克的微型无人机","B":"起飞重量≥2000克的轻型无人机","C":"起飞重量≥1500克的小型无人机","D":"起飞重量≥1000克的轻型无人机","answer":"A","exp":"本题考察无人机实名登记法规知识点。根据民航局规定，起飞重量≥250克的微型无人机（属于民航局定义的‘轻型’以下类别）需进行实名登记，以加强监管。选项B、C、D的重量标准均不符合实名登记的具体阈值，因此正确答案为A。"},{"id":1328,"type":"single","cat":"航空气象","stem":"飞行中遭遇突发强风（风速超过安全阈值）时，最安全的处置措施是？","A":"立即关闭无人机电源","B":"果断返航降落","C":"继续保持原航向飞行","D":"增大油门提升高度","answer":"B","exp":"本题考察强风天气下的应急操作。强风可能导致无人机失控（如偏航、失速或坠机），此时应立即终止飞行并返航降落，避免因强风持续作用造成不可挽回的损失。A选项关闭电源会直接导致坠机；C选项强风下保持航向会加剧失控风险；D选项增大油门可能导致动力过载或姿态失衡。"},{"id":1329,"type":"single","cat":"基础概念","stem":"起飞前检查无人机时，以下哪项属于必须执行的安全检查项目？","A":"检查螺旋桨是否安装牢固","B":"确认遥控器电量充足","C":"检查GPS卫星信号强度是否正常","D":"以上都是","answer":"D","exp":"本题考察无人机起飞前的基础检查流程。起飞前需全面检查：A选项螺旋桨安装牢固可避免飞行中脱落导致事故；B选项遥控器电量不足会导致失控风险；C选项GPS信号弱或丢失会影响悬停稳定性与返航安全。因此A、B、C均为必须检查项目，正确答案为D。"},{"id":1330,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机悬停时，其能够保持在空中不坠落的主要原因是？","A":"螺旋桨产生的推力大于重力","B":"螺旋桨产生的升力等于重力","C":"空气对无人机的浮力平衡重力","D":"电池提供的电能维持高度","answer":"B","exp":"多旋翼无人机通过螺旋桨高速旋转产生向上的升力，悬停时升力与重力大小相等、方向相反，形成平衡。推力是螺旋桨反作用力的分量，并非直接平衡重力；浮力对悬停影响极小；电池仅提供动力，不直接平衡重力。因此正确答案为B。"},{"id":1331,"type":"single","cat":"飞行原理","stem":"无人机飞行时，机翼产生升力的主要物理原理是？","A":"伯努利原理（机翼上下表面流速差导致压力差）","B":"牛顿第三定律（螺旋桨反作用力）","C":"万有引力（地球引力提供升力）","D":"阿基米德原理（空气浮力）","answer":"A","exp":"本题考察无人机空气动力学基础。升力产生的核心是机翼上下表面的压力差：机翼上表面弯曲，气流流速快（根据伯努利原理，流速大则压力小），下表面相对平直，流速慢压力大，上下表面压力差形成升力。选项B中牛顿第三定律是螺旋桨推力的原理（作用力与反作用力）；选项C万有引力是重力来源，与升力无关；选项D阿基米德原理适用于液体浮力，空气浮力对升力贡献可忽略不计。"},{"id":1332,"type":"single","cat":"法规与空域","stem":"以下哪种场景属于中国民航局明确规定的无人机‘禁飞区’？","A":"城市居民区广场","B":"民用机场跑道外5公里","C":"军事管理区周边10公里","D":"偏远山区无人区","answer":"C","exp":"本题考察无人机禁飞区法规。正确答案为C，军事管理区属于国家安全管控区域，10公里内为严格禁飞区。A选项居民区广场若未明确禁飞（如公园广场）不属于禁飞区；B选项民用机场净空区通常为跑道外8-15公里，具体范围需精确划定；D选项偏远山区无人区为允许飞行区域。"},{"id":1333,"type":"single","cat":"基础概念","stem":"无人机起飞前，确保飞行安全的首要检查项目是？","A":"飞行器GPS卫星信号数量（≥8颗）","B":"遥控器电池剩余电量","C":"地面是否有无关人员","D":"天气是否为晴朗无云","answer":"A","exp":"本题考察飞行前关键检查。GPS信号是定位与稳定悬停的核心前提，卫星数量不足会导致失控。选项B（遥控器电量）影响操控但非首要；选项C（地面人员）为环境排查，非核心；选项D（天气）为宏观条件，非飞行安全直接前提。正确答案为A。"},{"id":1334,"type":"single","cat":"领航与任务规划","stem":"当无人机飞行中突然发生GPS信号丢失且无法手动遥控时，应优先采取的安全措施是？","A":"立即执行一键返航功能（若具备）","B":"快速关闭无人机电源以防止失控","C":"尝试手动切换至备用GPS卫星信号","D":"继续观察无人机姿态等待恢复信号 answer","answer":"A","exp":"本题考察失控应急处置流程。正确答案为A：若无人机具备一键返航功能，优先触发该功能，利用其内置的气压计、高度计及预存航线参数，在GPS丢失时尝试返回起飞点或安全迫降点。B错误：关闭电源会导致无人机立即坠落，无法执行任何安全操作。C错误：GPS信号丢失时，备用卫星信号切换无意义，且此时无人机可能因失去定位而进入随机漂移。D错误：等待信号恢复会导致无人机因动力耗尽或姿态失控坠毁，风险极高。"},{"id":1335,"type":"single","cat":"基础概念","stem":"当无人机在飞行中突然发生动力系统故障，最优先的处置措施是？","A":"立即切换至备用电池","B":"尝试手动迫降至空旷区域","C":"保持当前航向并继续飞行","D":"启动紧急返航程序","answer":"B","exp":"本题考察故障应急处置原则。动力系统故障时，无人机可能失去控制或急速坠落，首要任务是选择安全区域手动迫降（避免砸落伤人）。选项A（切换电池）需时间且未必能解决根本故障；C（继续飞行）会加剧风险；D（紧急返航）可能因动力不足无法执行。正确做法是优先确保地面人员安全，选择无人群区域迫降，故正确答案为B。"},{"id":1336,"type":"single","cat":"操纵与飞行技术","stem":"无人机悬停时，主要依靠哪个力与重力平衡？","A":"升力","B":"推力","C":"阻力","D":"重力","answer":"A","exp":"本题考察无人机飞行基本原理。悬停状态下，无人机的升力（由旋翼旋转产生的向上气流压力差）与重力大小相等、方向相反，实现平衡。选项B推力用于前进/加速，C阻力为空气阻碍运动的力，D重力是无人机自身重量，均无法直接平衡悬停时的重力，故正确答案为A。"},{"id":1337,"type":"single","cat":"基础概念","stem":"无人机的核心控制系统，负责稳定飞行姿态、执行飞行控制指令的是以下哪个系统？","A":"飞控系统（飞行控制系统）","B":"GPS定位系统","C":"图传系统","D":"动力系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统是无人机的大脑，通过传感器（如IMU惯性测量单元）实时感知飞行姿态，执行控制算法（如PID调节），确保无人机稳定悬停、巡航、转向等。选项B（GPS）仅负责定位，不直接控制飞行；选项C（图传）用于传输视频数据，不参与飞行控制；选项D（动力系统）负责提供动力，而非控制指令。因此正确答案为A。"},{"id":1338,"type":"single","cat":"法规与空域","stem":"申请民用无人驾驶航空器系统驾驶员执照的最低年龄要求是多少？","A":"16周岁","B":"17周岁","C":"18周岁","D":"20周岁","answer":"A","exp":"本题考察无人机驾驶员执照申请的法规知识点。根据中国民航局规定，申请驾驶员执照的最低年龄为16周岁。选项B（17周岁）、C（18周岁）、D（20周岁）均高于最低年龄要求，不符合最低条件，因此错误。"},{"id":1339,"type":"single","cat":"设备与维护","stem":"无人机飞控系统（FlightController）的核心功能是？","A":"直接控制电机转速","B":"处理传感器数据并自动控制无人机姿态和位置","C":"存储飞行日志数据","D":"实时传输航拍视频","answer":"B","exp":"本题考察无人机系统组成知识点。飞控系统的核心功能是通过处理陀螺仪、加速度计、GPS等传感器数据，计算并输出控制指令，实现无人机姿态稳定（如悬停、转向）和位置控制（如航线飞行）。选项A错误，飞控不直接控制电机，而是通过电调（ESC）控制；选项C是数据记录模块的功能；选项D是图传系统的功能，故正确答案为B。"},{"id":1340,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，视距内运行的民用无人驾驶航空器最大飞行高度为多少米？","A":"100","B":"120","C":"150","D":"200","answer":"B","exp":"本题考察无人机飞行高度限制知识点。根据《民用无人驾驶航空器实名制登记管理规定》及民航局相关细则，视距内运行（VLOS）的民用无人驾驶航空器最大飞行高度为120米，此高度限制旨在保障空域安全。错误选项中，100米为常见混淆值（非标准限制），150米和200米通常为超视距飞行或特定场景（如需审批的空域），不符合视距内的基本要求。"},{"id":1341,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，轻型无人机的起飞重量范围通常是？","A":"<0.25kg","B":"0.25kg-7kg","C":"7kg-116kg","D":">116kg","answer":"C","exp":"中国民航局对无人机的分类标准为：微型无人机（<7kg）、轻型无人机（7kg-116kg）、小型无人机（116kg-570kg）、大型无人机（>570kg）。选项A为微型无人机范围，B为过渡性分类，D为大型无人机范围，均不符合题意，故正确答案为C。"},{"id":1342,"type":"single","cat":"基础概念","stem":"无人机的核心控制系统，负责稳定飞行姿态、执行控制指令并实现自主飞行的是？","A":"飞控系统","B":"图传系统","C":"动力系统","D":"遥控系统","answer":"A","exp":"本题考察无人机系统组成知识点。飞控系统（飞行控制系统）是无人机的核心控制单元，通过传感器数据（如陀螺仪、加速度计）和GPS定位，执行姿态稳定算法（如PID控制），确保无人机按指令飞行（如悬停、航线规划）。B选项图传系统仅负责传输无人机实时视频信号；C选项动力系统提供飞行动力（如电机、电池）；D选项遥控系统是地面端向无人机发送操控指令的设备，而非核心控制组件。因此正确答案为A。"},{"id":1343,"type":"single","cat":"基础概念","stem":"轻型民用无人机的最大起飞重量范围通常是？","A":"≤7千克","B":"＞7千克且≤116千克","C":"＞116千克且≤5700千克","D":"＞5700千克","answer":"B","exp":"本题考察无人机分类知识点。正确答案为B，根据中国民航局分类标准，轻型无人机指最大起飞重量＞7千克且≤116千克的无人机。A选项为微型无人机（≤7千克），C选项为小型无人机（＞116千克且≤5700千克），D选项为大型无人机（＞5700千克）。"},{"id":1344,"type":"single","cat":"基础概念","stem":"在无人机飞行前，必须优先确认的关键信息是？","A":"飞行空域是否在禁飞区范围内","B":"无人机电池剩余电量是否充足","C":"遥控器与无人机的信号连接强度","D":"天气状况是否为晴朗无雨","answer":"A","exp":"本题考察无人机安全飞行操作规范。禁飞区（如机场净空区、军事管理区、政府机关等）是法律禁止飞行的区域，未经审批进入可能面临行政处罚甚至刑事责任，是飞行前必须首要确认的安全前提。选项B、C、D均为飞行前需检查的细节，但属于操作前准备而非必须确认的核心关键信息。"},{"id":1345,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪类无人机需要进行实名登记？","A":"所有起飞重量＞250克的无人机","B":"所有起飞重量＞150克的无人机","C":"所有空机重量＞250克的无人机","D":"所有起飞重量＞1000克的无人机","answer":"C","exp":"本题考察无人机实名登记规范知识点。民航局明确规定：空机重量＞250克的民用无人机（不含微型遥控模型飞机）需进行实名登记，以实现飞行数据可追溯。选项A混淆起飞重量与空机重量，选项B（150克）和D（1000克）均不符合规定标准。"},{"id":1346,"type":"single","cat":"基础概念","stem":"无人机飞行中突然失去动力，可能的直接原因是？","A":"电池电压过低","B":"电机控制器故障","C":"螺旋桨卡滞","D":"以上都是","answer":"D","exp":"本题考察无人机故障排除中动力系统失效原因知识点。A选项电池电压过低会导致电机无法获得足够功率（电压是电机输出功率的核心参数）；B选项电机控制器（ESC）故障会直接切断电机供电或驱动信号；C选项螺旋桨卡滞（如缠绕异物、电机卡死）会导致动力无法有效输出（旋翼无法转动产生升力）。三者均为动力中断的典型直接原因。因此正确答案为D。"},{"id":1347,"type":"single","cat":"基础概念","stem":"在视距内运行轻型民用无人机时，其最大飞行高度不得超过（）米。","A":"100","B":"120","C":"150","D":"200","answer":"B","exp":"本题考察无人机飞行高度的法规限制知识点。根据中国民航局相关规定，轻型民用无人机在视距内飞行时，最大飞行高度限制为120米；超视距飞行时，高度限制为500米。A选项100米低于规定下限，C选项150米和D选项200米均超过视距内轻型无人机的高度限制，因此正确答案为B。"},{"id":1348,"type":"single","cat":"法规与空域","stem":"根据中国民用无人驾驶航空器实名登记管理规定，起飞重量在250克至7千克之间的民用无人机，应当进行以下哪项操作？","A":"无需登记","B":"必须进行实名登记","C":"需向军方申请飞行许可","D":"仅需驾驶员执照即可飞行","answer":"B","exp":"中国民航局规定，250克（0.25千克）以下的民用无人机无需实名登记，250克以上、7千克以下的无人机必须进行实名登记，7千克以上的无人机也需登记。因此250克至7千克之间的无人机必须实名登记，正确答案为B。"},{"id":1349,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项属于必须完成的关键检查项目？","A":"遥控器电量与通道校准","B":"螺旋桨是否安装正确且无裂纹","C":"飞行器固件版本是否为最新","D":"以上所有均为关键检查项","answer":"D","exp":"本题考察无人机起飞前检查要点。A选项遥控器电量不足会导致失控，通道校准错误易引发操作失效；B选项螺旋桨安装错误（如反桨）或裂纹会导致失衡、动力中断甚至空中解体；C选项固件版本影响系统稳定性（如避障、传感器校准）。三者均为起飞前必须检查的关键环节，因此正确答案为D。"},{"id":1350,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，以下哪种类型的无人机需要向民航局指定平台进行实名登记？","A":"最大起飞重量≥250克的民用无人机","B":"最大起飞重量≥7千克的民用无人机","C":"所有民用无人机均需登记","D":"仅植保类无人机需登记","answer":"A","exp":"本题考察无人机实名登记管理知识点。正确答案为A。根据规定，最大起飞重量≥250克的民用无人机（包括微型、轻型等类型）需实名登记；B选项错误，7千克是轻型与小型无人机的分界标准，并非登记标准；C选项错误，并非所有无人机都需登记（如微型无人机≥250克才需登记）；D选项错误，非植保类无人机（如消费级、测绘类）也需按重量登记。"},{"id":1351,"type":"single","cat":"基础概念","stem":"根据中国民航局标准，以下哪种分类符合轻型民用无人驾驶航空器的定义？","A":"最大起飞重量≤7千克","B":"最大起飞重量7-116千克","C":"最大起飞重量116-5700千克","D":"最大起飞重量5700千克以上 answer","answer":"B","exp":"本题考察无人机重量分类标准。正确答案为B：根据《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，轻型无人机的最大起飞重量为7-116千克（含7千克，不含116千克）。A错误：≤7千克属于微型无人机。C错误：116-5700千克为小型无人机。D错误：＞5700千克为大型无人机。"},{"id":1352,"type":"single","cat":"法规与空域","stem":"以下哪项属于法定禁飞区？","A":"城市中心广场","B":"机场净空区","C":"偏远山区","D":"无人区","answer":"B","exp":"本题考察无人机空域管理知识点。正确答案为B（机场净空区），根据《民用机场管理条例》，机场净空区是法定禁飞区，任何无人机未经审批不得进入，否则将面临行政处罚。A选项城市中心广场多为限飞区（需提前申请）；C、D选项偏远山区和无人区通常允许合法飞行（需遵守空域申请规定），非法定禁飞区。"},{"id":1353,"type":"single","cat":"基础概念","stem":"根据中国民航局规定，微型无人机的最大起飞重量通常是？","A":"≤7千克","B":"7-116千克","C":"116-5700千克","D":"＞5700千克","answer":"A","exp":"本题考察无人机分类标准知识点。根据中国民航局规定，微型无人机的最大起飞重量通常≤7千克；7-116千克为轻型无人机（B选项），116-5700千克为小型无人机（C选项），＞5700千克为大型无人机（D选项）。因此正确答案为A。"},{"id":1354,"type":"single","cat":"基础概念","stem":"起飞前，对无人机进行检查时，以下哪项是必须确认的关键安全检查项？","A":"电池电量是否充足","B":"GPS卫星信号是否正常","C":"图传设备是否连接正常","D":"遥控器摇杆是否居中","answer":"B","exp":"本题考察无人机起飞前安全检查知识点。起飞前关键安全检查项包括：①GPS卫星信号是否正常（定位是飞行控制的基础，信号丢失会导致无人机失控）；②电池电量是否充足（防止空中断电）；③传感器校准状态（如IMU、磁罗盘）；④周围环境是否有障碍物。选项BGPS卫星信号是否正常是飞行控制的核心前提，直接决定无人机能否稳定悬停和自主导航；选项A（电池电量）是重要检查项，但题目问必须确认的关键安全项，GPS信号异常比电量不足更直接导致飞行失控；选项C（图传）不影响飞行控制；选项D（摇杆居中）属于调试环节，非起飞前核心安全检查。因此正确答案为B。"},{"id":1355,"type":"single","cat":"设备与维护","stem":"起飞前检查无人机电池时，首要关注的参数是？","A":"电池剩余容量（电压）","B":"电池生产厂商品牌","C":"电池单体温度","D":"电池总重量","answer":"A","exp":"本题考察飞行前检查要点。电池电压是起飞前最关键的检查参数，电压过低会导致动力不足、飞行失控甚至炸机，故A正确。选项B品牌不影响电池安全性；选项C温度需关注但非首要（极端高温/低温才需特别注意）；选项D总重量是起飞前整体检查内容，非电池单独检查重点。"},{"id":1356,"type":"single","cat":"法规与空域","stem":"根据中国民航局《民用无人驾驶航空器实名制登记管理规定》，重量超过多少克的微型无人机需要进行实名登记？","A":"150克","B":"250克","C":"300克","D":"500克","answer":"B","exp":"本题考察无人机法规知识点。根据民航局规定，重量超过250克的微型和轻型民用无人机需按要求实名登记，便于管理和事故追溯。选项A（150克）为未达阈值，无需登记；C（300克）和D（500克）为超轻型及以上级别，虽需登记但非微型范畴，故正确答案为B。"},{"id":1357,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，视距内运行的微型无人机在开放空域的最大飞行高度是多少？","A":"50米","B":"120米","C":"150米","D":"200米","answer":"B","exp":"本题考察无人机视距内运行的空域法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》及民航局相关细则，视距内运行的微型无人机在开放空域的最大飞行高度为120米。A选项50米低于法规最低标准；C、D选项150米和200米超出了视距内飞行的高度限制，可能引发空域冲突或违反法规。"},{"id":1358,"type":"single","cat":"基础概念","stem":"无人机起飞前，以下哪项不属于必须检查的核心内容？","A":"电池电量、GPS信号强度、桨叶安装牢固性","B":"手机APP版本、地面障碍物分布、电机品牌型号","C":"遥控器摇杆行程、图传信号稳定性、螺旋桨平衡度","D":"无人机固件版本、起飞场地风速、云台角度是否正确","answer":"B","exp":"本题考察无人机安全操作检查要点。起飞前检查需围绕飞行安全、设备功能展开，核心包括电池（电量）、传感器（GPS）、机械结构（桨叶安装）、控制链路（遥控器）等。选项B中手机APP版本（非硬件功能）和电机品牌型号（与安全无关）不属于核心检查项；地面障碍物分布虽重要但不属于选项A的错误描述，故错误选项为B。"},{"id":1359,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器实名制登记管理规定》，需要进行实名登记的无人机是？","A":"最大起飞重量≥1.0千克的无人机","B":"空机重量≥2.0千克的无人机","C":"起飞重量≥3.0千克的无人机","D":"所有类型的无人机","answer":"A","exp":"本题考察无人机实名登记法规知识点。正确答案为A，根据规定，最大起飞重量≥1.0千克的民用无人机需进行实名登记，小于1.0千克的无需登记。B选项重量标准错误（应为1.0千克而非2.0千克），C选项标准错误（应为最大起飞重量而非起飞重量），D选项所有类型错误（部分小型无人机无需登记）。"},{"id":1360,"type":"single","cat":"法规与空域","stem":"以下哪种区域属于法律明确规定的‘禁飞区’？","A":"民用机场净空区","B":"城市公园广场","C":"偏远山区","D":"无人海岛","answer":"A","exp":"本题考察无人机禁飞区的法规边界。正确答案为A，民用机场净空区是为保障民航飞机起降安全划定的严格禁飞区域，根据《中华人民共和国民用航空法》，未经批准严禁无人机进入。选项B城市广场属于限制飞行区域（人流密集区），但非法定禁飞区；C、D无特殊限制可依法飞行。"},{"id":1361,"type":"single","cat":"法规与空域","stem":"根据中国民航局相关规定，最大起飞重量250克以下的民用无人机在开放空域飞行时，通常是否需要驾驶员执照？","A":"需要","B":"不需要","C":"需要备案登记","D":"需要参加理论培训","answer":"B","exp":"本题考察无人机驾驶员执照法规要求。根据民航局规定，最大起飞重量小于7千克的轻型民用无人机，在开放空域个人使用时通常无需驾驶员执照（需符合其他安全规定）；250克以下属于超轻型范畴，飞行限制更宽松，因此无需执照。选项A错误，因法规豁免此类飞行执照要求；C备案登记针对250克以上，D培训非执照强制要求，故正确答案为B。"},{"id":1362,"type":"single","cat":"基础概念","stem":"飞行中发现无人机失控并急速下坠，正确的处置方式是？","A":"立即尝试手动拉回控制，强行保持高度","B":"立即关闭遥控器电源，任由无人机自由坠落","C":"迅速远离无人机可能坠落的区域，避免人员伤亡","D":"继续操作无人机，尝试返航迫降","answer":"C","exp":"本题考察无人机失控应急处置知识点。正确答案为C。首要原则是确保地面人员安全，应迅速撤离危险区域；A选项错误，强行拉回控制可能导致二次失控或损坏；B选项错误，关闭电源会加剧坠落风险；D选项错误，失控状态下无法继续操作，强行返航易引发事故。"},{"id":1363,"type":"single","cat":"法规与空域","stem":"根据中国民用航空安全管理规定，以下哪些区域属于无人机绝对禁飞或严格限制飞行的区域？","A":"机场跑道及净空保护区域","B":"军事管理区及周边空域","C":"人口密集的城市核心区（如CBD）","D":"以上所有区域均属于禁飞/限飞区","answer":"D","exp":"本题考察无人机禁飞区法规。根据《民用无人驾驶航空器实名制登记管理规定》及《民用航空法》，机场净空区（A）为绝对禁飞区，军事管理区（B）为严格管控区，城市核心区（C）因安全与空域使用冲突通常限制飞行。因此三者均属于禁飞/限飞范畴，正确答案为D。"},{"id":1364,"type":"single","cat":"操纵与飞行技术","stem":"多旋翼无人机起飞时，地面操作员应站立在无人机的哪个位置以避免螺旋桨伤害？","A":"正前方（10米内）","B":"侧后方（安全距离外）","C":"正下方（5米内）","D":"任意远离机身的位置","answer":"B","exp":"本题考察无人机起飞安全规范知识点。多旋翼螺旋桨高速旋转时，前方气流最强且存在反推效应，正前方（A）和正下方（C）易被螺旋桨气流/叶片击中；B侧后方是安全区域（气流分散且远离旋转平面）；D任意位置未明确安全距离，可能因距离过近仍有风险，因此正确答案为B。"},{"id":1365,"type":"single","cat":"基础概念","stem":"起飞前检查中，下列哪项是确保飞行安全的关键步骤？","A":"检查遥控器电量","B":"确认螺旋桨安装牢固","C":"验证地面站连接状态","D":"测试图传信号强度","answer":"B","exp":"本题考察无人机起飞前安全操作规范。螺旋桨安装牢固是基础安全检查项，若螺旋桨松动或安装错误，起飞时可能脱落导致失控或损坏。选项A（遥控器电量）、C（地面站连接）、D（图传信号）是飞行过程中的辅助检查，非起飞前必须的关键检查。正确答案为B。"},{"id":1366,"type":"single","cat":"法规与空域","stem":"根据中国民航局规定，起飞重量在多少千克以下的微型民用无人机飞行时无需驾驶员执照？","A":"7千克","B":"25千克","C":"116千克","D":"150千克","answer":"A","exp":"本题考察无人机驾驶员执照法规知识点。根据《民用无人驾驶航空器实名制登记管理规定》及《民用无人驾驶航空器经营性飞行活动管理办法（暂行）》，中国民航局将无人机分为微型（起飞重量＜7千克）、轻型（7-116千克）等类别，其中微型无人机飞行时无需驾驶员执照。选项B（25千克）、C（116千克）是轻型无人机的重量上限，D（150千克）为超轻型或其他分类，均需相应执照或审批。"},{"id":1367,"type":"single","cat":"领航与任务规划","stem":"当无人机GPS信号突然丢失且未开启‘失控返航’功能时，应优先采取的操作是？","A":"立即手动拉回无人机至手中","B":"尝试快速切换至‘返航模式’并锁定高度","C":"继续手动操作，观察无人机姿态变化","D":"重新启动无人机并搜索卫星信号","answer":"B","exp":"本题考察无人机失控应急操作。正确答案为B，GPS丢失后无人机进入姿态模式，无法自主定位，应优先锁定高度并返航至安全区域（如起飞点）。A选项手动拉回易导致无人机失控坠机；C选项继续操作缺乏定位，姿态模式下易因操控偏差失控；D选项重启耗时且无法解决当前信号丢失问题。"},{"id":1368,"type":"single","cat":"法规与空域","stem":"无人机驾驶员执照中，视距内驾驶员执照（VLOS）的适用范围是指无人机处于驾驶员目视范围内的水平距离和垂直高度限制，通常VLOS的水平距离和垂直高度限制分别是？","A":"500米，120米","B":"1000米，150米","C":"500米，150米","D":"1000米，120米","answer":"A","exp":"本题考察无人机法规中视距内驾驶员（VLOS）的飞行范围知识点。根据中国民航局相关规定，视距内驾驶员执照的VLOS标准为水平距离不超过500米，垂直高度不超过120米。B选项1000米和150米为超视距飞行（BVLOS）或特定场景下的放宽标准；C选项500米（水平）与150米（垂直）不符合VLOS定义；D选项1000米水平距离远超常规VLOS限制。因此正确答案为A。"},{"id":1369,"type":"single","cat":"法规与空域","stem":"根据《民用无人驾驶航空器系统驾驶员管理暂行规定》，在视距内运行的空机重量大于7千克且在25千克以下的无人机驾驶员，应当取得哪种资质？","A":"无需资质","B":"驾驶员合格证","C":"机长合格证","D":"教员合格证","answer":"B","exp":"按该规定，视距内运行且空机重量大于7千克、不超过25千克的无人机，驾驶员应取得驾驶员合格证；机长合格证适用于视距外运行等承担全权责任的情形，教员合格证面向教学培训。易误选机长：其条件是超视距等场景，与视距内中型机不同。"},{"id":1370,"type":"single","cat":"基础概念","stem":"无人机在飞行中，与地面指挥中心通信中断时，正确的处置方法是？","A":"继续按原航线飞行","B":"立即下降高度","C":"按预案自动返航或就近降落","D":"保持高度盘旋等待","answer":"C","exp":"与地面指挥中心通信中断后无法接收指令，继续原航线飞行积聚未知风险，盲目下降或盘旋等待缺乏保障。正确做法是执行预案：链路中断后按预设自动返航至起飞点，或在条件允许时就近选择安全场地降落。自主返航和就近降落是通用的处置原则。"},{"id":1371,"type":"single","cat":"法规与空域","stem":"民用无人机驾驶员执照理论考试的最低合格分数线是？","A":"60分","B":"70分","C":"80分","D":"90分","answer":"C","exp":"民用无人机驾驶员执照理论考试满分100分，最低合格分数线为80分，内容涵盖法规、气象、飞行原理和系统操作。60分、70分是其他类别考试常见的及格标准，容易误搬；无人机执照对理论掌握要求更高，未达到80分须重新参加考试。"},{"id":1372,"type":"single","cat":"法规与空域","stem":"无人机飞行前进行空域申请时，下列哪项不是必须提供的信息？","A":"飞行任务性质","B":"无人机驾驶员健康证明","C":"飞行空域范围","D":"飞行起止时间","answer":"B","exp":"空域申请需提供与空域使用直接相关的要素：飞行任务性质说明活动类别，飞行空域范围划定使用区域，飞行起止时间确定占用时段，审批方据此协调批准。驾驶员健康证明与人员资质管理相关，和空域使用无关，不属于必须提供的信息。"},{"id":1373,"type":"single","cat":"法规与空域","stem":"无人机在机场净空保护区内飞行，应当？","A":"经机场管理机构批准","B":"只要不在航线上即可","C":"提前向空管部门报备即可","D":"禁止飞行","answer":"A","exp":"机场净空保护区是保障航空器起降安全的核心区域，受法律严格保护。在保护区内飞行无人机必须事先取得机场管理机构的批准并按批准条件实施，防止与有人机冲突或侵入起降航迹。仅避开航线、提前报备都不满足要求，未经批准一律不得飞行。"},{"id":1374,"type":"single","cat":"航空气象","stem":"大气中导致无人机产生积冰的主要气象条件是？","A":"在含过冷水滴的云中飞行","B":"在干燥空气中飞行","C":"在高温高湿环境飞行","D":"在强对流天气下飞行","answer":"A","exp":"积冰的必要条件是机体接触过冷水滴：温度低于0℃的云中过冷水滴极不稳定，碰撞机体立即冻结，在机翼、桨叶和空速管上结冰，破坏气动外形、堵塞传感器。干燥空气没有液态水，高温环境不冻结，均不会积冰，关键是在含过冷水滴的云中飞行。"},{"id":1375,"type":"single","cat":"设备与维护","stem":"无人机常用锂电池的正常工作电压范围一般为？","A":"每节2.0~3.0V","B":"每节3.0~4.2V","C":"每节4.2~5.0V","D":"每节5.0~6.0V","answer":"B","exp":"锂电池单体满电4.2V，放电截止一般不低于3.0V，正常工作范围为每节3.0~4.2V。低于3.0V继续放电造成容量永久损失，高于4.2V充电有过热起火风险。其余范围不符合锂电池的电化学特性，易记混误选。"},{"id":1376,"type":"single","cat":"航空气象","stem":"无人机逆风起降时，通常应当选择哪种方式？","A":"逆风起飞，逆风降落","B":"逆风起飞，顺风降落","C":"顺风起飞，逆风降落","D":"顺风起飞，顺风降落","answer":"A","exp":"起降均应逆风进行：逆风起飞相对空速更大，较短滑跑即可获得足够升力；逆风降落接地速度小、操纵余量大，滑跑距离短且方向更可控。顺风起降会延长滑跑距离、减小相对空速，增加失速和冲出场地风险。故标准方式是逆风起飞、逆风降落。"},{"id":1377,"type":"single","cat":"飞行原理","stem":"无人机在水平飞行中，升力等于？","A":"重力与阻力之和","B":"重力","C":"重力沿垂直方向的分量","D":"重力沿飞行方向的分量","answer":"B","exp":"水平飞行指沿水平方向的稳定直线飞行，竖直方向不产生加速度，升力与重力构成一对平衡力，大小相等方向相反，推力与阻力沿水平方向平衡。重力垂直分量的说法在平飞中不成立，全部重力本就作用在竖直方向，无需再分解，故升力等于重力。"},{"id":1378,"type":"single","cat":"飞行原理","stem":"多旋翼无人机在空中悬停时，旋翼产生的升力大小？","A":"大于无人机重力","B":"等于无人机重力","C":"小于无人机重力","D":"与重力无关","answer":"B","exp":"悬停是相对地面位置和高度都不变化的平衡状态，旋翼产生的总升力与重力大小相等、方向相反，合力为零，机体才能既不上升也不下沉。升力大于重力会加速爬升，小于重力则加速下沉，只有精确等于重力才能维持悬停，故选等于无人机重力。"},{"id":1379,"type":"single","cat":"操纵与飞行技术","stem":"无人机最大平飞速度是指？","A":"一定高度上发动机最大推力下的平飞速度","B":"海平面上的平飞速度","C":"巡航状态下的平飞速度","D":"安全飞行允许的最大速度","answer":"A","exp":"最大平飞速度指一定高度上发动机以最大推力工作时能达到的稳定平飞速度，由可用推力与需用推力的平衡点决定，高度不同数值不同。易误选海平面数值，那只是一个高度点结果；巡航速度对应经济性，安全限制速度对应结构限制，均非此定义。"},{"id":1380,"type":"single","cat":"操纵与飞行技术","stem":"无人机自动驾驶仪中，负责感知姿态角速率并参与姿态稳定控制的传感器是？","A":"GPS接收机","B":"气压高度计","C":"角速率陀螺仪","D":"磁罗盘","answer":"C","exp":"姿态稳定控制需感知姿态变化速率，角速率陀螺仪实时测量机体绕三轴的角速率，反馈给飞控构成阻尼回路，抑制姿态振荡实现增稳。GPS提供位置速度，气压高度计测量高度，磁罗盘测定航向，都不感知角速率；误认GPS能稳定姿态最易混淆。"},{"id":1381,"type":"single","cat":"基础概念","stem":"无人机地面站的主要功能不包括？","A":"飞行数据实时显示","B":"飞行航线规划与上传","C":"无人机机体制造","D":"遥控指令发送","answer":"C","exp":"地面站承担飞行数据实时显示、航线规划与上传、遥控指令发送、状态监控报警等任务，是地面操作与人机交互的核心。无人机机体制造属于生产制造环节，与地面站功能毫无关联。其余三项都是地面站的典型功能，逐一对照即可确定不属于的一项。"},{"id":1382,"type":"single","cat":"设备与维护","stem":"当无人机出现单侧电机失效时，正确的应急处置原则是？","A":"立即加大油门，保持原姿态","B":"尽快降低高度，控制姿态并迫降","C":"立即切断所有动力","D":"立即满油门爬升","answer":"B","exp":"多旋翼一侧电机失效后推力失衡，强行保持原姿态或满油门爬升都会加剧失控翻滚。正确处置是尽快降低高度，同时控制姿态、稳住航向，在可控范围内选择安全场地迫降。切断所有动力会直接坠机，加大油门维持原姿态忽略失衡力矩，均不正确。"},{"id":1383,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，应当开启？","A":"搜索灯","B":"导航灯和防撞灯","C":"着陆灯","D":"闪光灯","answer":"B","exp":"夜间飞行必须开启导航灯和防撞灯：导航灯按左红右绿尾白的惯例布置，供他人判别航向和相对位置；防撞灯闪烁醒目，提高空中和地面的可见性。搜索灯用于照明搜索任务，着陆灯用于起降照明，闪光灯与夜航无关，都不是规定的灯光配置。"},{"id":1384,"type":"single","cat":"操纵与飞行技术","stem":"在标准大气条件下，海拔每升高1000米，气温大约下降？","A":"1.5℃","B":"6.5℃","C":"9.8℃","D":"12℃","answer":"B","exp":"标准大气对流层内气温随高度升高而降低，平均递减率约为每升高1000米下降6.5℃，是计算密度高度和判断积冰层的基本参数。1.5℃偏差过大；9.8℃是干空气绝热直减率，属气块升降的变化率，最易与气温平均递减率混淆。"},{"id":1385,"type":"single","cat":"操纵与飞行技术","stem":"无人机水平转弯时，倾斜角越大，则？","A":"转弯半径越大","B":"转弯半径越小","C":"转弯速度越快","D":"转弯速度越慢","answer":"B","exp":"水平转弯由升力的水平分量提供向心力，速度一定时倾斜角越大，水平分量越大，转弯半径越小、转弯角速度越大；但坡度增大还需增大总升力补偿竖直分量，否则掉高度甚至失速。易误选半径越大，那把向心力与半径的关系正好弄反了。"},{"id":1386,"type":"single","cat":"领航与任务规划","stem":"无人机使用GPS导航时，至少需要接收多少颗卫星才能实现三维定位？","A":"3颗","B":"4颗","C":"5颗","D":"6颗","answer":"B","exp":"GPS三维定位要解算三维坐标和接收机钟差共四个未知量，需同时接收至少4颗卫星信号才能建立方程完成定位，少于4颗只能得到部分结果或降级为二维定位。3颗仅能粗略二维定位，5颗以上只是提高精度和可靠性，并非最低要求，故选4颗。"},{"id":1387,"type":"single","cat":"基础概念","stem":"无人机机体上的空速管主要用于测量？","A":"气压高度","B":"升降速度","C":"空速","D":"地速","answer":"C","exp":"空速管即皮托管，通过感受迎面气流的全压与静压之差即动压，换算出飞行空速，是固定翼无人机感知速度的关键传感器，常带加热防冰以防堵塞失效。气压高度由气压高度计测量，升降速度由高度变化率解算，地速由GPS测得，均与空速管无关。"},{"id":1388,"type":"single","cat":"领航与任务规划","stem":"无人机在遥控链路丢失后，若未能收到返航指令，飞控系统通常默认执行？","A":"原地坠毁","B":"立即降落","C":"自动返航至起飞点","D":"按原航线继续飞行","answer":"C","exp":"链路丢失后若未收到返航指令，飞控触发失控保护，默认自动返航：爬升到预设返航高度，飞回起飞点上空并自动降落，这是通行的出厂设定。原地坠毁和立即降落都不是默认逻辑，按原航线继续飞行会在失联下积聚更大风险。"},{"id":1389,"type":"single","cat":"法规与空域","stem":"根据现行法规，从事无人机经营性飞行活动应当取得？","A":"通用航空经营许可","B":"民用机场使用许可证","C":"营业执照即可","D":"无需许可","answer":"A","exp":"从事经营性飞行活动，如航拍、测绘、喷洒等有偿服务，应按规定取得通用航空经营许可，这是经营性飞行活动的法定准入条件。营业执照只完成市场主体登记，机场使用许可针对机场运营，均不能替代；无许可经营属违规，必须持证经营。"},{"id":1390,"type":"single","cat":"设备与维护","stem":"无人机发动机空中停车后，活塞式无人机应首先采取的处置措施是？","A":"立即重新启动发动机","B":"操纵飞机进入最佳滑翔状态","C":"弃机跳伞","D":"加大油门","answer":"B","exp":"发动机空中停车后推力丧失，首要处置是操纵飞机进入最佳滑翔状态：保持有利速度，以最大升阻比下滑，为选择迫降场地和修正进场争取时间与高度。先重启会损失高度并分散注意力，加大油门已无意义，弃机跳伞更不现实，最佳滑翔是标准动作。"},{"id":1391,"type":"single","cat":"基础概念","stem":"无人机飞行时，空气密度减小会导致？","A":"升力增大，阻力减小","B":"升力减小，阻力减小","C":"升力增大，阻力增大","D":"升力减小，阻力增大","answer":"B","exp":"升力和阻力都与空气密度成正比：密度减小时，相同速度和迎角下升力减小，气动阻力也相应减小。高原高温正是密度减小的典型场景，起降需更长滑跑距离和更高真空速才能获得同样升力。升力增大的说法与变化方向相反，是最易误选的错误关系。"},{"id":1392,"type":"single","cat":"航空气象","stem":"无人机云台的主要作用是？","A":"增加飞行稳定性","B":"稳定相机姿态，隔离机体振动","C":"提高飞行速度","D":"扩展通信距离","answer":"B","exp":"云台是任务相机的稳定平台，通过三轴电机实时补偿机体俯仰、横滚、偏航抖动，并隔离旋翼和机身传来的高频振动，使相机稳定，画面清晰。它不改变飞机自身的飞行稳定性，与飞行速度、通信距离无关，增加飞行稳定性是最易误选的混淆项。"},{"id":1393,"type":"single","cat":"设备与维护","stem":"无人机在寒冷环境下飞行，电池性能会？","A":"放电能力增强","B":"放电能力下降","C":"容量增加","D":"内阻减小","answer":"B","exp":"锂电池依靠电化学反应放电，低温下电解液变粘、离子迁移变慢，内阻升高，可用容量、放电能力显著下降，电压平台降低、续航缩短，大电流放电还可能触发低压保护、损伤电芯。容量增加、内阻减小都与低温特性相反，放电增强更是错误认识。"},{"id":1394,"type":"single","cat":"基础概念","stem":"多旋翼无人机改变飞行方向是通过？","A":"改变旋翼总距","B":"差动改变各旋翼转速","C":"改变机体俯仰角","D":"改变旋翼倾转角度","answer":"B","exp":"多旋翼旋翼多为定距桨，没有总距和倾转机构，完全依靠飞控差动调节各旋翼转速：改变转速差产生力矩，使机体倾斜后升力出现水平分量实现移动，各旋翼反扭矩之差控制偏航。改变总距和倾转角度是直升机与倾转旋翼机的操纵原理，最易误选。"},{"id":1395,"type":"single","cat":"基础概念","stem":"无人机在超过视距运行（BVLOS）时，应满足的条件是？","A":"驾驶员必须目视观察","B":"必须使用电子围栏和感知避让系统","C":"只需保持通信链路","D":"必须在隔离空域内飞行","answer":"D","exp":"超视距运行时驾驶员无法目视航空器，风险显著增大，按管理要求应在隔离空域内飞行，与有人机航路隔开，配合可靠链路和应急预案实施。驾驶员必须目视观察与超视距的定义相矛盾，电子围栏和感知避让只是保障手段，均非运行的空间条件。"},{"id":1396,"type":"single","cat":"基础概念","stem":"无人机飞行记录中，通常要求保存至少？","A":"1个月","B":"3个月","C":"6个月","D":"12个月","answer":"D","exp":"飞行记录是事故调查、责任认定和运行追溯的重要依据，按管理要求通常应至少保存12个月，确保发生纠纷或事件时有完整数据可查。1个月、3个月、6个月的保存期都短于该要求，容易凭感觉估算而误选，实际运行中不少单位会保存更长时间。"},{"id":1397,"type":"single","cat":"设备与维护","stem":"无人机起飞前检查螺旋桨时，应重点确认？","A":"螺旋桨颜色","B":"螺旋桨安装方向正确且无裂纹","C":"螺旋桨数量","D":"螺旋桨材质","answer":"B","exp":"螺旋桨检查重点是安全关键项：安装方向必须正确，正反桨装反会失去升力平衡甚至无法正常起飞；桨叶有裂纹、缺口、变形，高速旋转中易断裂飞出造成事故。颜色、数量、材质装机时已确定，不是每次起飞的重点，检查始终围绕安装与完好性。"},{"id":1398,"type":"single","cat":"设备与维护","stem":"无人机使用遥控器时，应先开启哪个设备？","A":"先开无人机电源","B":"先开遥控器电源","C":"同时开启","D":"顺序无所谓","answer":"B","exp":"开机顺序应先开遥控器电源、后开无人机电源：遥控器先工作并持续发出有效信号，无人机上电后立即建立可靠链路，避免无指令输入时触发失控保护或电机意外启动。关机顺序相反，先断无人机电源再关遥控器，顺序颠倒易造成电机误转伤人。"},{"id":1399,"type":"single","cat":"航空气象","stem":"无人机在风切变环境中飞行，最危险的情况是？","A":"顺风切变","B":"逆风切变","C":"侧风切变","D":"下击暴流","answer":"D","exp":"下击暴流是强下沉气流冲近地面后向四周爆散：飞机先遇强逆风空速骤增，穿越核心后突转强顺风，空速骤减、升力锐减、掉高极快，起降阶段几乎无法及时改出，是风切变中最危险的情形。单纯顺风、逆风或侧风切变气流变化单一，危害相对较轻。"},{"id":1400,"type":"single","cat":"设备与维护","stem":"无人机电池充电时，正确的做法是？","A":"使用原装充电器并有人看守","B":"在密闭高温环境充电","C":"将电池充满后长时间不拔","D":"使用充电器时叠加充电","answer":"A","exp":"锂电池充电风险较高，正确做法是使用原装或匹配的充电器，按规定电压电流充电，并且全程有人看守，一旦鼓包、发热、异味可立即断电。密闭高温环境充电、充满后长时间不拔、叠加充电都会加速电芯劣化甚至引发起火，均属危险做法。"},{"id":1401,"type":"single","cat":"基础概念","stem":"无人机在雨中飞行可能导致？","A":"电子设备短路失效","B":"电机散热更好","C":"飞行速度增加","D":"电池续航增加","answer":"A","exp":"雨水渗入机体后在电路板和接插件间形成导电通路，引起短路漏电，导致飞控、电调等电子设备失效，还会造成电机轴承锈蚀、传感器失准，直接危及飞行安全。电机散热、飞行速度、续航都不会因下雨而改善，防水不足的无人机严禁雨中飞行。"},{"id":1402,"type":"single","cat":"基础概念","stem":"无人机在飞行中，机头朝北，正西风（风从西吹向东），无人机应向哪个方向偏航补偿？","A":"左偏","B":"右偏","C":"上偏","D":"下偏","answer":"A","exp":"机头朝北飞行，正西风从左侧吹来，把飞机吹向东侧即右方漂移，保持航迹必须向风来的方向修正，即向左偏航并带适当坡度抵消漂移。补偿方向永远朝上风向，若向右偏会被风吹得更偏离航线，上偏下偏在水平航向补偿中没有实际意义。"},{"id":1403,"type":"single","cat":"领航与任务规划","stem":"无人机执行测绘任务时，航线规划应优先考虑？","A":"风速与重叠率","B":"飞行高度固定","C":"地面控制点数量","D":"飞机颜色","answer":"A","exp":"测绘航线规划优先考虑风速与重叠率：大风影响飞行平稳和影像清晰度，需据此设计航高与航向；航向、旁向重叠率直接决定影像拼接与建模精度，是成图合格的前提。控制点属地面布设环节，飞机颜色与任务无关，故选风速与重叠率。"},{"id":1404,"type":"single","cat":"基础概念","stem":"无人机超视距飞行时，驾驶员应随时掌握？","A":"飞机位置和飞行状态","B":"飞机外观","C":"发动机温度","D":"机翼结冰情况","answer":"A","exp":"超视距飞行时肉眼看不到飞机，驾驶员须通过地面站随时掌握飞机位置和飞行状态，包括航迹、高度、速度、电量、链路与卫星状态，才能及时发现偏差、正确决策。飞机外观在视距外根本看不到，发动机温度、机翼结冰并非都具备监测手段。"},{"id":1405,"type":"single","cat":"基础概念","stem":"无人机在机场附近飞行，飞行高度不得超过？","A":"相对机场跑道高度的120米","B":"相对机场跑道高度的200米","C":"相对机场跑道高度的300米","D":"机场净空规定的限制高度","answer":"D","exp":"机场周边有严格的净空限制，障碍物限制面按跑道类别和位置规定允许的最大高度，无人机在该区域不得超过机场净空规定的限制高度，并须履行批准手续。固定的120米、200米、300米是通用限高或估算值，不能替代机场净空的具体规定。"},{"id":1406,"type":"single","cat":"设备与维护","stem":"无人机动力电池常见标示45C中的C表示？","A":"电池容量","B":"放电倍率","C":"充电倍率","D":"电池节数","answer":"B","exp":"电池标示的C表示放电倍率，45C指可用45倍容量数值的电流放电，如2200mAh电池对应约99A持续放电能力，C数越高大电流放电能力越强。它不是电池容量，也不表示充电倍率；节数用S标注，容量用mAh标注，注意区分。"},{"id":1407,"type":"single","cat":"基础概念","stem":"无人机在高温高原地区飞行时，主要影响是？","A":"空气密度减小，升力下降","B":"空气密度增大，升力增加","C":"发动机功率增大","D":"电池放电能力增强","answer":"A","exp":"高原海拔高、高温气温高，都使空气密度减小，相同速度和迎角下旋翼或机翼产生的升力下降，发动机功率输出也受影响，起降需要更大油门和更长距离，悬停和抗风余度减小。密度增大、功率增大、放电增强都与实际规律相反，属于方向性错误。"},{"id":1408,"type":"single","cat":"领航与任务规划","stem":"无人机飞行中，如果GPS信号丢失，正确的做法是？","A":"立即降落","B":"切换为姿态模式并人工操控","C":"继续等待GPS恢复","D":"关闭电源重启","answer":"B","exp":"GPS信号丢失后定点和航线功能失效，飞机可能漂移，正确做法是切换姿态模式，人工操控飞机保持平衡，目视或借助图传飞回安全区域降落。立即降落可能落在危险位置，原地等待恢复期间飞机持续漂移，关闭电源重启会中断链路，都不可取。"},{"id":1409,"type":"single","cat":"基础概念","stem":"无人机起飞前进行磁罗盘校准的目的是？","A":"校准空速管","B":"消除周围磁场干扰，保证航向准确","C":"校准电池电量","D":"校准遥控器","answer":"B","exp":"磁罗盘靠地磁场测定航向，机架、电机、电池及周围铁磁物体会叠加附加磁场造成偏差。起飞前校准用于消除干扰影响，保证航向解算准确，否则悬停会转圈漂移、自动航线跑偏。校准应在远离干扰的开阔场地进行，与空速管、电池、遥控器无关。"},{"id":1410,"type":"single","cat":"法规与空域","stem":"无人机在真高120米以下、隔离空域内飞行，需遵守？","A":"无需任何审批","B":"需向空管部门报备飞行计划","C":"必须获得飞行执照","D":"必须投保责任险","answer":"B","exp":"在真高120米以下隔离空域内飞行，仍须履行基本手续，按规定向空管部门报备飞行计划，使管制方掌握动态、协调冲突。无需任何审批的说法不成立；执照和保险属于人员资质与经营层面的要求，与报备飞行计划是两回事，不能相互替代。"},{"id":1411,"type":"single","cat":"飞行原理","stem":"无人机螺旋桨的螺距是指？","A":"螺旋桨直径","B":"螺旋桨旋转一周前进的理论距离","C":"螺旋桨叶片宽度","D":"螺旋桨安装角度","answer":"B","exp":"螺旋桨螺距指桨叶旋转一周理论上沿轴向前进的距离，如同螺栓旋进一圈的进给量，反映桨叶的做功能力，与直径配合决定拉力和所需功率。直径、叶片宽度、安装角都是另外的几何参数，最易与螺距混淆，定义对应旋转一周的理论前进距离。"},{"id":1412,"type":"single","cat":"领航与任务规划","stem":"无人机在地面站设置返航高度时，应高于返航路径上最高障碍物的？","A":"10米","B":"20米","C":"50米","D":"100米","answer":"C","exp":"返航高度应高于返航路径上最高障碍物并留出裕量，通常取50米左右，防止返航途中撞上楼宇、铁塔等障碍。裕量太小，叠加定位误差和气流波动仍有碰撞风险；过大则爬升耗电、延长返航时间。10米、20米裕量明显不足，故选50米。"},{"id":1413,"type":"single","cat":"航空气象","stem":"无人机起降时遭遇低空风切变，应当？","A":"加大油门强行起降","B":"立即中止起降，改到安全区域","C":"减小油门缓慢起降","D":"保持原操作不变","answer":"B","exp":"低空风切变使空速和升力短时间内剧烈变化，起降阶段高度余度极小、难以改出，最安全的处置是立即中止起降，改到气流稳定的安全区域或等待风切变消失。强行起降可能因升力骤失而失控，减小油门和保持原操作都会放大风险，中止是首选原则。"},{"id":1414,"type":"single","cat":"基础概念","stem":"无人机每次飞行结束后，应当？","A":"立即拆除所有部件","B":"检查机身、螺旋桨、电池等状态","C":"只保存飞行数据","D":"关闭遥控器电源即可","answer":"B","exp":"飞行结束后应例行检查：机身有无裂纹变形，螺旋桨有无磨损、裂纹、缺口，电池有无鼓包发热、电压是否正常，异常部件及时更换，为下次飞行做准备。只拆部件或只存数据都遗漏安全检查，仅关遥控器更不能代替，应全面检查状态。"},{"id":1415,"type":"single","cat":"设备与维护","stem":"无人机机载飞控系统的主要功能不包括？","A":"姿态稳定与控制","B":"导航与制导","C":"任务载荷投放","D":"应急保护与失效处理","answer":"C","exp":"机载飞控核心功能是姿态稳定与控制、导航与制导，以及失控返航、失效保护等应急处理，保障飞机按指令安全飞行。任务载荷投放属于任务设备的专门功能，由任务系统或人工控制完成，通常不列入飞控基本功能，其余三项都是飞控的典型职能。"},{"id":1416,"type":"single","cat":"法规与空域","stem":"无人机在禁飞区内飞行，可能导致？","A":"行政拘留","B":"罚款","C":"追究刑事责任","D":"以上均可能","answer":"D","exp":"违规在禁飞区飞行属违法行为，执法机关可按情节处以罚款，情节较重的可并处行政拘留，若造成重大事故、危害公共安全构成犯罪的，还追究刑事责任。具体承担何种责任取决于违规情节和后果轻重，三种后果都有可能发生，故选以上均可能。"},{"id":1417,"type":"single","cat":"基础概念","stem":"无人机在夜间飞行时，地面人员辨别无人机方向的依据是？","A":"机头灯颜色","B":"导航灯位置与颜色","C":"机身反光","D":"遥控器信号强度","answer":"B","exp":"夜间辨别无人机方向依靠导航灯的位置与颜色：按航空惯例左翼红灯、右翼绿灯、尾部白灯，根据灯光的相对位置和颜色组合即可判别机头朝向与飞行方向。单个机头灯颜色不足以定向，机身反光夜间微弱难辨，遥控器信号强度与方向辨识无关。"},{"id":1418,"type":"single","cat":"基础概念","stem":"无人机飞行前查看天气，重点关注？","A":"风速、风向、能见度、云底高","B":"气温、气压、湿度","C":"降水、雷电","D":"以上全部","answer":"D","exp":"飞行前查天气要综合评估：风速风向决定能否起飞和抗风余度，能见度、云底高影响目视观察与航高选择；气温气压湿度影响密度高度和电池性能；降水雷电直接威胁设备与飞行安全。各组都是重点关注内容，漏一项就可能留隐患，故以上全部。"},{"id":1419,"type":"multi","cat":"法规与空域","stem":"无人机驾驶员执照理论考试内容包括？","A":"航空法规","B":"气象学","C":"飞行原理","D":"无人机系统组成与操作","answer":"ABCD","exp":"执照理论考试覆盖四大基础：航空法规考查空域管理、飞行审批和驾驶员职责；气象学考查风、云、能见度等对飞行的影响及识别方法；飞行原理考查升力产生、稳定性与操纵规律；无人机系统组成与操作考查结构构成和设备使用。四部分都是考试大纲明确规定的内容，故全部正确。"},{"id":1420,"type":"multi","cat":"基础概念","stem":"无人机在飞行前必须进行的检查项目包括？","A":"螺旋桨安装牢固无裂纹","B":"电池电量充足","C":"遥控器与无人机通信正常","D":"GPS卫星颗数满足要求","answer":"ABCD","exp":"飞行前必须检查四项基础条件：螺旋桨安装牢固、无裂纹损伤，防止空中断裂飞脱；电池电量充足，保证续航和返航余度；遥控器与无人机通信正常，链路可靠才能有效操纵；GPS卫星颗数满足要求，定位精度才有保障。任何一项不合格都可能引发空中故障，故全部必查。"},{"id":1421,"type":"multi","cat":"基础概念","stem":"下列哪些属于无人机常见故障类型？","A":"电机停转","B":"飞控传感器漂移","C":"GPS丢失","D":"遥控链路中断","answer":"ABCD","exp":"常见故障覆盖动力、控制、定位和链路环节：电机停转使推力失衡、机体倾斜下坠；飞控传感器漂移导致姿态解算误差累积、悬停漂移；GPS丢失使定点和导航功能失效；遥控链路中断触发失控保护，驾驶员无法及时干预。四类都是高发故障，检查维护和飞行监控要重点关注。"},{"id":1422,"type":"multi","cat":"基础概念","stem":"无人机在山区飞行时，可能遇到的危险有？","A":"地形障碍碰撞","B":"山谷风切变","C":"上升气流影响高度","D":"磁罗盘受磁场干扰","answer":"ABC","exp":"山区飞行的主要危险来自地形和气流：山体、铁塔等地形障碍易造成碰撞；山谷地形易产生风切变，风向风速突变威胁低空安全；山坡上升气流会造成高度异常变化，影响航线精度和安全余度。磁罗盘干扰仅在强磁性矿体等特殊地段偶发，不属于山区飞行的普遍危险，故不选。"},{"id":1423,"type":"multi","cat":"设备与维护","stem":"无人机电池安全使用要求包括？","A":"使用专用充电器","B":"充电时远离易燃物","C":"电池鼓包后继续使用","D":"运输时保持短路保护","answer":"ABD","exp":"电池安全使用要求：使用专用充电器，保证电压电流匹配；充电时远离易燃物并有人看守，防止意外起火蔓延；运输时保持短路保护，避免极柱碰撞短路引发燃爆。电池鼓包说明电芯已受损变形，继续使用随时可能起火，必须停用报废，鼓包续用不属于安全要求。"},{"id":1424,"type":"multi","cat":"领航与任务规划","stem":"无人机执行应急测绘任务时，航线规划应考虑？","A":"禁飞区避让","B":"地形起伏与安全高度","C":"地面分辨率与重叠率","D":"飞机涂装颜色","answer":"ABC","exp":"应急测绘航线规划要考虑：避让禁飞区，确保飞行合法合规；结合地形起伏设定安全高度，防止山区碰撞；按任务要求确定地面分辨率和航向旁向重叠率，保证成图精度满足使用。飞机涂装颜色与影像质量和飞行安全均无关系，属于干扰项，故不选。"},{"id":1425,"type":"multi","cat":"基础概念","stem":"无人机在雨中飞行可能造成的后果有？","A":"电子设备短路","B":"镜头起雾影响成像","C":"机翼表面污染增加阻力","D":"电池续航增加","answer":"ABC","exp":"雨中飞行的危害：雨水侵入引起电子设备短路，飞控电调失效风险大；湿气使镜头起雾，成像质量下降；雨滴和污物附着在机翼表面破坏光滑外形，摩擦阻力增加。下雨只会让电量消耗更多，续航不可能增加，该说法违背常理，属于错误项，故不选。"},{"id":1426,"type":"multi","cat":"法规与空域","stem":"无人机在机场净空区域内飞行，应当避免？","A":"进入跑道中心线延长线","B":"在进近航线下方飞行","C":"在起飞爬升航迹下方飞行","D":"在停机坪上方低空飞行","answer":"ABC","exp":"净空避让的核心是有人机起降航迹：跑道中心线延长线是起飞着陆的主航迹方向，进近航线下方和起飞爬升航迹下方都是航空器低空经过的地带，侵入这些区域极易与航空器危险接近甚至相撞，必须严格避开。停机坪上方低空飞行属于对地面设施作业的干扰问题，不在净空航迹避让的内容之列。"},{"id":1427,"type":"multi","cat":"基础概念","stem":"无人机地面站软件应具备的基本功能包括？","A":"航线规划","B":"实时飞行数据显示","C":"飞行参数设置","D":"故障诊断与报警","answer":"ABCD","exp":"地面站软件的基本功能包括：航线规划，设计并上传航点任务；实时飞行数据显示，监视位置、高度、速度、电量等状态；飞行参数设置，调整飞控参数和任务配置；故障诊断与报警，发现链路、电压、传感器异常并及时提示。四项共同支撑地面监视与控制，故全部正确。"},{"id":1428,"type":"multi","cat":"基础概念","stem":"无人机驾驶员在飞行中应当遵守的原则有？","A":"保持视距内飞行","B":"避让有人驾驶航空器","C":"严禁酒后飞行","D":"任意跨越禁飞区","answer":"ABC","exp":"驾驶员飞行中须遵守基本原则：按规定保持视距内飞行，随时掌握飞机状态；遇有人驾驶航空器时无条件避让，有人机处于优先通行地位；严禁酒后飞行，饮酒削弱判断和反应能力，危害如同酒后驾车。任意跨越禁飞区是严重违法行为，与飞行原则根本相悖，故不选。"}];
